def _validate_authentication_user_interface_dispatch(arguments: dict[str, Any]) -> None:
    scope = arguments["scope"]
    if scope["type"] != "http" or scope["method"] != "GET" or scope["path"] != "/":
        raise ContractError("authentication user-interface dispatch must be GET /")
    if _authentication_user_interface_requirement(scope) is None:
        raise ContractError(
            "authentication user-interface dispatch needs absent or valid Basic credentials"
        )


def _validate_authentication_login_next_dispatch(arguments: dict[str, Any]) -> None:
    scope = arguments["scope"]
    query_string = base64.b64decode(scope["query_string_base64"], validate=True).decode("ascii")
    if (
        scope["type"] != "http"
        or scope["method"] != "POST"
        or scope["path"] != "/login"
        or _authentication_middleware_outcome(scope) != "valid"
        or not any(
            name == "next" and value
            for name, value in parse_qsl(query_string, keep_blank_values=True)
        )
    ):
        raise ContractError(
            "authentication login dispatch needs an authenticated POST with a nonempty next value"
        )


def _validate_authentication_required_route_dispatch(
    arguments: dict[str, Any], route: dict[str, Any]
) -> None:
    scope = arguments["scope"]
    if scope["type"] != "http" or scope["method"] != "GET" or scope["path"] != route["path"]:
        raise ContractError("authentication-required route dispatch differs from its source URL")
    outcome = _authentication_middleware_outcome(scope)
    if outcome == "invalid" and route["endpoint"]["form"] != "async":
        raise ContractError("malformed Basic credentials are sampled only on the async route")


def _validate_authentication_required_websocket_dispatch(
    arguments: dict[str, Any], app_arguments: dict[str, Any]
) -> None:
    route = app_arguments["routes"][0]
    scope = arguments["scope"]
    if scope.get("type") != "websocket" or scope.get("path") != route["path"]:
        raise ContractError(
            "authentication-required WebSocket dispatch differs from its source route"
        )
    _validate_websocket_exception_dispatch(app_arguments, arguments)


def _routes_have_local_middleware(routes: Any) -> bool:
    if not isinstance(routes, list):
        return False
    for route in routes:
        if not isinstance(route, dict):
            continue
        if "middleware" in route:
            return True
        if route.get("kind") == "mount":
            if _routes_have_local_middleware(route.get("routes")):
                return True
            app = route.get("app")
            if isinstance(app, dict) and _routes_have_local_middleware([app]):
                return True
    return False


def _is_route_middleware_workflow(case: Any) -> bool:
    if not isinstance(case, dict) or case.get("operation") != "__call__":
        return False
    steps = case.get("steps")
    if not isinstance(steps, list) or not steps or not isinstance(steps[0], dict):
        return False
    arguments = steps[0].get("arguments")
    if not isinstance(arguments, dict):
        return False
    routes = arguments.get("routes")
    if not isinstance(routes, dict) or routes.get("kind") != "literal":
        return False
    route_values = routes.get("value")
    return _routes_have_local_middleware(route_values) or (
        _route_middleware_topology(route_values) == "mounted_app_exception_propagation"
    )


def _validate_route_middleware_spec(spec: Any, context: str) -> dict[str, Any]:
    if not isinstance(spec, dict) or not isinstance(spec.get("kind"), str):
        raise ContractError(f"{context} must declare a middleware kind")
    if spec["kind"] == "append-response-header":
        spec = _exact(spec, {"kind", "name"}, context)
        name = _string(spec["name"], f"{context}.name")
        try:
            header_name = f"X-{name}".encode("ascii")
        except UnicodeEncodeError as exc:
            raise ContractError(f"{context}.name must produce an ASCII header name") from exc
        valid_token_characters = (
            "!#$%&'*+-.^_`|~0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"
        )
        if any(
            character not in valid_token_characters for character in header_name.decode("ascii")
        ):
            raise ContractError(f"{context}.name must produce a valid HTTP header token")
        return spec
    spec = _exact(spec, {"kind", "scope_key", "scope_value", "response_header"}, context)
    if spec["kind"] != "scope-and-response-header":
        raise ContractError(f"{context}.kind is unsupported")
    _string(spec["scope_key"], f"{context}.scope_key")
    if isinstance(spec["scope_value"], (dict, list)):
        raise ContractError(f"{context}.scope_value must be a JSON scalar")
    header = spec["response_header"]
    if (
        not isinstance(header, list)
        or len(header) != 2
        or any(not isinstance(value, str) or not value for value in header)
        or ":" in header[0]
        or any("\r" in value or "\n" in value for value in header)
    ):
        raise ContractError(f"{context}.response_header must be a valid [name, value] pair")
    try:
        header[0].encode("ascii")
        header[1].encode("latin-1")
    except UnicodeEncodeError as exc:
        raise ContractError(f"{context}.response_header must use ASGI-compatible bytes") from exc
    return spec


def _validate_route_middleware_node(node: Any, context: str) -> dict[str, Any]:
    if not isinstance(node, dict) or node.get("kind") not in {
        "http-route",
        "mount",
        "starlette-app",
    }:
        raise ContractError(f"{context} must be an HTTP route, Mount, or Starlette app input")
    if node["kind"] == "starlette-app":
        node = _exact(node, {"kind", "routes"}, context)
        if not isinstance(node["routes"], list) or not node["routes"]:
            raise ContractError(f"{context}.routes must be a non-empty array")
        for index, child in enumerate(node["routes"]):
            _validate_route_middleware_node(child, f"{context}.routes[{index}]")
        return node
    if node["kind"] == "http-route":
        allowed = {"kind", "path", "methods", "endpoint", "middleware", "name"}
        if node.keys() - allowed or not {"kind", "path", "methods", "endpoint"} <= node.keys():
            raise ContractError(f"{context} fields are invalid")
        path = _string(node["path"], f"{context}.path")
        if not path.startswith("/"):
            raise ContractError(f"{context}.path must be absolute")
        methods = node["methods"]
        if methods is not None and (
            not isinstance(methods, list)
            or not methods
            or any(not isinstance(method, str) or not method for method in methods)
            or len(methods) != len(set(methods))
        ):
            raise ContractError(f"{context}.methods must be a unique string array")
        if "name" in node and node["name"] is not None:
            _string(node["name"], f"{context}.name")
        endpoint = node["endpoint"]
        if not isinstance(endpoint, dict) or not isinstance(endpoint.get("kind"), str):
            raise ContractError(f"{context}.endpoint must declare an endpoint kind")
        if endpoint["kind"] == "plain-response":
            endpoint = _exact(endpoint, {"kind", "content", "media_type"}, f"{context}.endpoint")
            _string(endpoint["content"], f"{context}.endpoint.content")
            _string(endpoint["media_type"], f"{context}.endpoint.media_type")
        elif endpoint["kind"] == "scope-assert-empty-response":
            endpoint = _exact(
                endpoint,
                {"kind", "scope_key", "scope_value"},
                f"{context}.endpoint",
            )
            _string(endpoint["scope_key"], f"{context}.endpoint.scope_key")
            if type(endpoint["scope_value"]) is not bool:
                raise ContractError(f"{context}.endpoint.scope_value must be boolean")
        elif endpoint["kind"] == "sync-http-exception":
            endpoint = _exact(
                endpoint,
                {"kind", "status_code", "detail"},
                f"{context}.endpoint",
            )
            if endpoint["status_code"] != 403:
                raise ContractError(f"{context}.endpoint.status_code must be 403")
            if endpoint["detail"] != "auth":
                raise ContractError(f"{context}.endpoint.detail must match the source input")
        elif endpoint["kind"] == "raise-runtime-error":
            endpoint = _exact(
                endpoint,
                {"kind", "exception_type", "message"},
                f"{context}.endpoint",
            )
            if endpoint["exception_type"] != "Exception":
                raise ContractError(
                    f"{context}.endpoint.exception_type must match the source input"
                )
            _string(endpoint["message"], f"{context}.endpoint.message")
        else:
            raise ContractError(f"{context}.endpoint.kind is unsupported")
        if "middleware" in node:
            if not isinstance(node["middleware"], list):
                raise ContractError(f"{context}.middleware must be an array")
            for index, spec in enumerate(node["middleware"]):
                _validate_route_middleware_spec(spec, f"{context}.middleware[{index}]")
        return node

    if "app" in node:
        allowed = {"kind", "path", "app", "middleware"}
        if node.keys() - allowed:
            raise ContractError(f"{context} supplied-app fields are invalid")
        path = _string(node["path"], f"{context}.path")
        if not path.startswith("/"):
            raise ContractError(f"{context}.path must be absolute")
        _validate_route_middleware_node(node["app"], f"{context}.app")
    else:
        allowed = {"kind", "path", "routes", "middleware"}
        if node.keys() - allowed or not {"kind", "path", "routes"} <= node.keys():
            raise ContractError(f"{context} child-routes fields are invalid")
        path = _string(node["path"], f"{context}.path")
        if not path.startswith("/"):
            raise ContractError(f"{context}.path must be absolute")
        if not isinstance(node["routes"], list):
            raise ContractError(f"{context}.routes must be an array")
        for index, child in enumerate(node["routes"]):
            _validate_route_middleware_node(child, f"{context}.routes[{index}]")
    if "middleware" in node:
        if not isinstance(node["middleware"], list):
            raise ContractError(f"{context}.middleware must be an array")
        for index, spec in enumerate(node["middleware"]):
            _validate_route_middleware_spec(spec, f"{context}.middleware[{index}]")
    return node


def _route_middleware_topology(routes: list[dict[str, Any]]) -> str | None:
    if not isinstance(routes, list) or any(not isinstance(route, dict) for route in routes):
        return None
    if len(routes) == 1:
        mount = routes[0]
        app = mount.get("app")
        if (
            mount.get("kind") == "mount"
            and mount.get("path") == "/sub"
            and isinstance(app, dict)
            and app.get("kind") == "starlette-app"
            and app.get("routes")
            == [
                {
                    "kind": "http-route",
                    "path": "/",
                    "methods": None,
                    "endpoint": {
                        "kind": "raise-runtime-error",
                        "exception_type": "Exception",
                        "message": "Exc",
                    },
                }
            ]
        ):
            return "mounted_app_exception_propagation"
    if (
        len(routes) == 3
        and routes[0].get("kind") == "mount"
        and routes[0].get("path") == "/mount"
        and "routes" in routes[0]
        and isinstance(routes[0]["routes"], list)
        and len(routes[0]["routes"]) == 2
        and all(isinstance(route, dict) for route in routes[0]["routes"])
        and [route.get("path") for route in routes[0].get("routes", [])] == ["/err", "/home"]
        and [route.get("path") for route in routes[1:]] == ["/err", "/home"]
    ):
        return "mount_exception"
    if len(routes) != 2 or routes[1].get("path") != "/home":
        return None
    first = routes[0]
    if first.get("kind") == "http-route" and first.get("path") == "/http":
        return "route"
    if first.get("kind") != "mount" or first.get("path") != "/http":
        return None
    if "app" in first:
        return "mount_app"
    if "routes" in first:
        return "mount_routes"
    return None


def _validate_route_middleware_application(args: dict[str, Any]) -> None:
    if not isinstance(args["routes"], list) or not args["routes"]:
        raise ContractError("route middleware app requires a non-empty route tree")
    topology = _route_middleware_topology(args["routes"])
    if topology == "mount_exception":
        if not isinstance(args["middleware"], list) or len(args["middleware"]) != 1:
            raise ContractError("mounted exception workflow requires one app middleware")
        app_middleware = _validate_route_middleware_spec(
            args["middleware"][0], "application middleware[0]"
        )
        if app_middleware != {"kind": "append-response-header", "name": "Outer"}:
            raise ContractError("mounted exception workflow requires the source Outer middleware")
    elif args["middleware"] != []:
        raise ContractError("existing route middleware fixtures require no app middleware")
    if (
        args["debug"] is not False
        or args["exception_handlers"] != []
        or args["max_body_size"] is not None
        or _validate_lifespan_marker(args["lifespan"]) != "default"
    ):
        raise ContractError(
            "route middleware app constructor inputs differ from the source fixture"
        )
    for index, route in enumerate(args["routes"]):
        _validate_route_middleware_node(route, f"application routes[{index}]")


def _validate_route_middleware_workflow(case: dict[str, Any]) -> None:
    app_args = {
        key: descriptor["value"] for key, descriptor in case["steps"][0]["arguments"].items()
    }
    routes = app_args["routes"]
    topology = _route_middleware_topology(routes)
    expected_step_count = {
        "mount_exception": 5,
        "mounted_app_exception_propagation": 2,
    }.get(topology, 3)
    if topology is None or len(case["steps"]) != expected_step_count:
        raise ContractError("route middleware workflow must exercise one declared route topology")
    root = routes[0]
    if topology == "mounted_app_exception_propagation":
        step = case["steps"][1]
        if step["step_id"] != "dispatch-mounted-error":
            raise ContractError("mounted app exception workflow must select its dispatch")
        arguments = {key: item["value"] for key, item in step["arguments"].items()}
        scope = arguments["scope"]
        if scope["type"] != "http" or scope["method"] != "GET" or scope["path"] != "/sub/":
            raise ContractError("mounted app exception workflow must dispatch GET /sub/")
        return
    if topology == "mount_exception":
        mount_routes = root["routes"]
        expected_home = {
            "kind": "http-route",
            "path": "/home",
            "methods": None,
            "endpoint": {
                "kind": "plain-response",
                "content": "Hello, world",
                "media_type": "text/plain",
            },
        }
        expected_error = {
            "kind": "http-route",
            "path": "/err",
            "methods": None,
            "endpoint": {
                "kind": "sync-http-exception",
                "status_code": 403,
                "detail": "auth",
            },
        }
        expected_mount_middleware = [{"kind": "append-response-header", "name": "Mounted"}]
        if (
            mount_routes[0] != expected_error
            or mount_routes[1] != expected_home
            or root.get("middleware") != expected_mount_middleware
            or routes[1] != expected_error
            or routes[2] != expected_home
        ):
            raise ContractError("mounted exception route tree must match the pinned source order")
        expected_paths = ["/home", "/err", "/mount/home", "/mount/err"]
        expected_step_ids = [
            "dispatch-home",
            "dispatch-err",
            "dispatch-mounted-home",
            "dispatch-mounted-err",
        ]
        if [step["step_id"] for step in case["steps"][1:]] != expected_step_ids:
            raise ContractError("mounted exception dispatches must preserve source request order")
        app_middleware = app_args["middleware"]
        if app_middleware != [{"kind": "append-response-header", "name": "Outer"}]:
            raise ContractError("mounted exception workflow requires the source Outer middleware")
        if root["middleware"] != expected_mount_middleware:
            raise ContractError("mounted exception workflow requires the source Mounted middleware")
        for index, step in enumerate(case["steps"][1:]):
            arguments = {key: item["value"] for key, item in step["arguments"].items()}
            scope = arguments["scope"]
            if scope["type"] != "http" or scope["method"] != "GET":
                raise ContractError("mounted exception workflow requires HTTP GET dispatches")
            if scope["path"] != expected_paths[index]:
                raise ContractError("mounted exception requests must preserve source path order")
        return
    if routes[1] != {
        "kind": "http-route",
        "path": "/home",
        "methods": None,
        "endpoint": {
            "kind": "plain-response",
            "content": "Hello, world",
            "media_type": "text/plain",
        },
    }:
        raise ContractError("route middleware workflow must include the source homepage route")
    if topology == "route":
        wrapped_route = root
        middleware = root.get("middleware")
        expected_path = "/http"
    else:
        middleware = root.get("middleware")
        wrapped_route = root.get("app") if topology == "mount_app" else None
        if topology == "mount_routes":
            children = root.get("routes", [])
            wrapped_route = children[0] if len(children) == 1 else None
        expected_path = "/" if topology != "route" else "/http"
    expected_endpoint = {
        "kind": "scope-assert-empty-response",
        "scope_key": "add_headers_middleware",
        "scope_value": True,
    }
    if (
        not isinstance(wrapped_route, dict)
        or wrapped_route.get("kind") != "http-route"
        or wrapped_route.get("path") != expected_path
        or wrapped_route.get("methods") != ["GET"]
        or wrapped_route.get("endpoint") != expected_endpoint
        or (topology != "route" and "middleware" in wrapped_route)
        or middleware
        != [
            {
                "kind": "scope-and-response-header",
                "scope_key": "add_headers_middleware",
                "scope_value": True,
                "response_header": ["X-Test", "Set by middleware"],
            }
        ]
    ):
        raise ContractError("route middleware input differs from the source middleware behavior")
    dispatch_paths: list[str] = []
    for step in case["steps"][1:]:
        arguments = {key: item["value"] for key, item in step["arguments"].items()}
        scope = arguments["scope"]
        dispatch_paths.append(scope["path"])
        if scope["type"] != "http" or scope["method"] != "GET":
            raise ContractError("route middleware workflow requires HTTP GET dispatches")
    expected_wrapped_path = "/http" if topology == "route" else "/http/"
    if dispatch_paths != ["/home", expected_wrapped_path]:
        raise ContractError(
            "route middleware workflow must dispatch /home and the wrapped route in order"
        )


def _validate_application_stimulus(
    args: dict[str, Any], request_dispatch: bool, allow_lifespan_variants: bool = False
) -> None:
    if set(args) != {
        "debug",
        "routes",
        "middleware",
        "exception_handlers",
        "lifespan",
        "max_body_size",
    }:
        raise ContractError(
            "application inputs must explicitly encode each Starlette constructor input"
        )
    if _routes_have_local_middleware(args["routes"]) or (
        _route_middleware_topology(args["routes"]) == "mounted_app_exception_propagation"
    ):
        _validate_route_middleware_application(args)
        return
    if not request_dispatch and _is_authentication_user_interface_application(args):
        _validate_authentication_user_interface_application(args)
        return
    if not request_dispatch and _is_authentication_login_next_application(args):
        _validate_authentication_login_next_application(args)
        return
    if not request_dispatch and _is_authentication_required_route_application(args):
        _validate_authentication_required_route_application(args)
        return
    if not request_dispatch and _is_authentication_required_websocket_application(args):
        _validate_authentication_required_websocket_application(args)
        return
    if (
        not request_dispatch
        and isinstance(args["routes"], list)
        and len(args["routes"]) == 1
        and isinstance(args["routes"][0], dict)
        and args["routes"][0].get("kind") == "websocket-route"
    ):
        _validate_websocket_exception_application(args)
        return
    if not request_dispatch and _is_server_error_stimulus(args):
        _validate_server_error_application(args)
        return
    if _is_route_body_limit_application(args):
        _validate_route_body_limit_application(args)
        return
    if args["debug"] is not False or args["middleware"] != [] or args["max_body_size"] is not None:
        raise ContractError("GET /hello application inputs differ from the declared baseline")
    handlers = args["exception_handlers"]
    if handlers != []:
        _validate_exception_handler_registry(handlers)
    lifespan_kind = _validate_lifespan_marker(args["lifespan"])
    if lifespan_kind not in {"default", "async-context-manager"} and not allow_lifespan_variants:
        raise ContractError(
            "generator and special-method lifespan markers require lifecycle-only input"
        )
    if not isinstance(args["routes"], list) or len(args["routes"]) != 1:
        raise ContractError("application input must contain exactly one route")
    route = args["routes"][0]
    _exact(route, {"kind", "path", "methods", "endpoint"}, "route input")
    if request_dispatch:
        if handlers != []:
            raise ContractError("request-dispatch cases use the empty exception-handler registry")
        if not isinstance(route["path"], str):
            raise ContractError("Request route path must be a string")
        route_parameters = _route_template_parameters(route["path"])
        if (
            route["kind"] != "http-route"
            or not isinstance(route["path"], str)
            or not route["path"].startswith("/")
            or route["methods"] != ["GET"]
            or len(route_parameters) != 1
            or route_parameters[0][1] not in {"str", "int", "float", "uuid", "path"}
        ):
            raise ContractError(
                "Request workflow route must define one GET path parameter with a built-in converter"
            )
        endpoint = route["endpoint"]
        if isinstance(endpoint, dict) and endpoint.get("kind") == "request-observer":
            expected_observer = {
                **REQUEST_OBSERVER_ENDPOINT,
                "path_parameter": route_parameters[0][0],
            }
            if endpoint != expected_observer:
                raise ContractError(
                    "Request observer endpoint input differs from its declared values"
                )
            return
        if isinstance(endpoint, dict) and endpoint.get("kind") == "request-cookies-observer":
            _validate_request_cookies_observer(endpoint)
            if route["path"] != "/items/{item_id:int}":
                raise ContractError("Request cookies observer uses the int route boundary")
            return
        if isinstance(endpoint, dict) and endpoint.get("kind") == "async-request-callable-observer":
            fields = {"kind", "callable_kind", "path_parameter", "response_content"}
            if "error_message" in endpoint:
                fields.add("error_message")
            endpoint = _exact(
                endpoint,
                fields,
                "async request callable observer endpoint",
            )
            if (
                endpoint["callable_kind"] not in ASYNC_ENDPOINT_CALLABLE_KINDS
                or route["path"] != "/items/{item_id:int}"
                or endpoint["path_parameter"] != "item_id"
                or not isinstance(endpoint["response_content"], str)
                or ("error_message" in endpoint and not isinstance(endpoint["error_message"], str))
            ):
                raise ContractError(
                    "async endpoint callable input must use the declared int route and callable forms"
                )
            return
        if isinstance(endpoint, dict) and endpoint.get("kind") == "request-connection-property":
            endpoint = _exact(
                endpoint,
                {"kind", "property"},
                "request connection-property endpoint",
            )
            if endpoint["property"] not in REQUEST_CONNECTION_PROPERTY_REQUIREMENTS:
                raise ContractError(
                    "request connection-property endpoint uses an unsupported property"
                )
            return
        if isinstance(endpoint, dict) and endpoint.get("kind") == "request-state-observer":
            _validate_request_state_endpoint(endpoint)
            if route["path"] != "/items/{item_id:int}":
                raise ContractError("request state input uses the int route boundary")
            return
        if isinstance(endpoint, dict) and endpoint.get("kind") == "request-stream-observer":
            _validate_request_stream_endpoint(endpoint)
            return
        if isinstance(endpoint, dict) and endpoint.get("kind") == "sync-request-runtime-observer":
            _validate_sync_request_runtime_endpoint(endpoint)
            if route["path"] != "/items/{item_id:int}":
                raise ContractError("sync request runtime input uses the int route boundary")
            return
        if (
            isinstance(endpoint, dict)
            and endpoint.get("kind") == "sync-request-cancellation-observer"
        ):
            endpoint = _exact(
                endpoint,
                {"kind", "response_content"},
                "sync request cancellation observer endpoint",
            )
            if route["path"] != "/items/{item_id:int}" or not isinstance(
                endpoint["response_content"], str
            ):
                raise ContractError(
                    "sync request cancellation input must use the int route and text response"
                )
            return
        if endpoint == ASGI_CALLABLE_INSTANCE_ENDPOINT:
            if route["path"] != "/items/{item_id:int}":
                raise ContractError("ASGI callable-instance input uses the int route boundary")
            return
        if endpoint == ASYNC_CALL_BOUNDARY_ENDPOINT:
            if route["path"] != "/items/{item_id:int}":
                raise ContractError("async boundary input uses the int route boundary")
            return
        if isinstance(endpoint, dict) and endpoint.get("kind") == "asgi-callable-action-sequence":
            if route["path"] != "/items/{item_id:int}":
                raise ContractError("ASGI callable action input uses the int route boundary")
            _validate_asgi_callable_action_sequence(endpoint)
            return
        if not isinstance(endpoint, dict) or endpoint.get("kind") != "sync-request-observer":
            raise ContractError("Request endpoint must use a declared observer input shape")
        fields = {
            "kind",
            "callable_kind",
            "path_parameter",
            "context_var_name",
            "context_value",
            "response_content",
        }
        if "error_message" in endpoint:
            fields.add("error_message")
        _exact(
            endpoint,
            fields,
            "sync endpoint input",
        )
        if (
            endpoint["callable_kind"] not in {"function", "bound_method", "partial"}
            or route["path"] != "/items/{item_id:int}"
            or endpoint["path_parameter"] != "item_id"
            or endpoint["context_var_name"] != "request_context"
            or not isinstance(endpoint["context_value"], str)
            or not endpoint["context_value"]
            or endpoint["response_content"] != "sync ok"
            or ("error_message" in endpoint and not isinstance(endpoint["error_message"], str))
        ):
            raise ContractError("sync endpoint input must use the declared caller-context stimulus")
        return

    if (
        isinstance(route["endpoint"], dict)
        and route["endpoint"].get("kind") == "http-exception-after-body"
    ):
        _validate_body_reuse_application(route, handlers)
        return

    if isinstance(route["endpoint"], dict) and route["endpoint"].get("kind") == "http-exception":
        _validate_http_exception_application(route, handlers)
        return

    if handlers != []:
        _validate_status_precedence_application(route, handlers)
        return

    if (
        route["kind"] != "http-route"
        or not isinstance(route["path"], str)
        or not route["path"].startswith("/")
        or (
            route["methods"] is not None
            and (
                not isinstance(route["methods"], list)
                or not route["methods"]
                or any(
                    not isinstance(method, str) or not method or method != method.upper()
                    for method in route["methods"]
                )
                or len(route["methods"]) != len(set(route["methods"]))
            )
        )
    ):
        raise ContractError("route input must define a unique-method absolute HTTP route")
    endpoint_kind = route["endpoint"].get("kind") if isinstance(route["endpoint"], dict) else None
    if endpoint_kind == "sync-plain-text-response":
        endpoint = _exact(
            route["endpoint"],
            {"kind", "content"},
            "synchronous plain-text endpoint input",
        )
        if route["methods"] is not None:
            raise ContractError("synchronous plain-text route input must use default Route methods")
        _string(endpoint["content"], "synchronous plain-text endpoint content")
        return
    endpoint = _exact(
        route["endpoint"],
        {"kind", "content", "status_code", "media_type", "cookies"},
        "endpoint input",
    )
    if endpoint["kind"] != "plain-text-response":
        raise ContractError("endpoint input must define a plain-text response")
    if route["methods"] is None:
        raise ContractError(
            "only synchronous plain-text route inputs may use default Route methods"
        )
    _string(endpoint["content"], "plain-text endpoint content")
    if type(endpoint["status_code"]) is not int or not 100 <= endpoint["status_code"] <= 599:
        raise ContractError("plain-text endpoint status_code must be an HTTP status code")
    if endpoint["media_type"] is not None:
        _string(endpoint["media_type"], "plain-text endpoint media_type")
    cookies = endpoint["cookies"]
    if not isinstance(cookies, list):
        raise ContractError("plain-text endpoint cookies must be an ordered list")
    for index, cookie in enumerate(cookies):
        _exact(cookie, {"key", "value"}, f"cookie input[{index}]")
        _string(cookie["key"], f"cookie input[{index}].key")
        _string(cookie["value"], f"cookie input[{index}].value")


def _validate_starlette_add_route_registration(
    arguments: dict[str, Any], app_arguments: dict[str, Any]
) -> None:
    arguments = _exact(
        arguments,
        {"path", "route", "methods", "name", "include_in_schema"},
        "Starlette.add_route arguments",
    )
    path = _string(arguments["path"], "Starlette.add_route.path")
    route_reference = _exact(
        arguments["route"],
        {"kind", "route_index"},
        "Starlette.add_route route callable reference",
    )
    if route_reference != {"kind": "route-endpoint-reference", "route_index": 0}:
        raise ContractError("Starlette.add_route must use the input-defined first route endpoint")
    methods = arguments["methods"]
    if (
        not isinstance(methods, list)
        or not methods
        or any(
            not isinstance(method, str) or not method or method != method.upper()
            for method in methods
        )
        or len(methods) != len(set(methods))
    ):
        raise ContractError("Starlette.add_route.methods must be unique uppercase method strings")
    name = _string(arguments["name"], "Starlette.add_route.name")
    if type(arguments["include_in_schema"]) is not bool:
        raise ContractError("Starlette.add_route.include_in_schema must be boolean")
    if (
        not path.startswith("/")
        or "{" in path
        or "}" in path
        or path == app_arguments["routes"][0]["path"]
        or methods != ["GET"]
        or name != "registered"
    ):
        raise ContractError("Starlette.add_route input must add the declared static named route")


def _validate_starlette_add_route_workflow(case: dict[str, Any]) -> None:
    if case["target_profiles"] != ["python-package-cpython312"]:
        raise ContractError("Starlette.add_route workflow selects only the Python-package profile")
    if case["observations"] != ["dispatch-get", "dispatch-wrong-method"]:
        raise ContractError("Starlette.add_route workflow must observe both dispatch outcomes")
    if case["execution_schedule"] != [
        "route-registration",
        "dispatch-get",
        "dispatch-wrong-method",
    ]:
        raise ContractError(
            "Starlette.add_route schedule must preserve mutation and dispatch order"
        )
    route_step = case["steps"][1]
    route_arguments = {key: value["value"] for key, value in route_step["arguments"].items()}
    app_arguments = {key: value["value"] for key, value in case["steps"][0]["arguments"].items()}
    _validate_starlette_add_route_registration(route_arguments, app_arguments)
    route_path = route_arguments["path"]
    expected_methods = {"dispatch-get": "GET", "dispatch-wrong-method": "POST"}
    for step in case["steps"][2:]:
        arguments = {key: value["value"] for key, value in step["arguments"].items()}
        scope = arguments["scope"]
        _validate_dispatch_stimulus(arguments, request_dispatch=False)
        if scope["type"] != "http" or scope["path"] != route_path:
            raise ContractError("Starlette.add_route dispatch must request the registered path")
        if scope["method"] != expected_methods[step["step_id"]]:
            raise ContractError("Starlette.add_route dispatch methods must exercise GET and POST")


def _starlette_add_middleware_semantic_coverage(case: dict[str, Any]) -> set[str]:
    app_ids = [step["step_id"] for step in case["steps"] if step.get("operation") == "__init__"]
    registrations: dict[str, list[dict[str, Any]]] = {app_id: [] for app_id in app_ids}
    dispatches: dict[str, list[dict[str, Any]]] = {app_id: [] for app_id in app_ids}
    app_inputs: dict[str, dict[str, Any]] = {}
    dispatched: set[str] = set()
    after_start: list[dict[str, Any]] = []
    coverage: set[str] = set()

    def input_for(step: dict[str, Any]) -> dict[str, Any]:
        return {name: descriptor["value"] for name, descriptor in step["arguments"].items()}

    for step in case["steps"]:
        operation = step.get("operation")
        if operation == "__init__":
            app_inputs[step["step_id"]] = input_for(step)
            continue
        if operation not in {"add_middleware", "__call__"}:
            continue
        app_id = step["receiver"]["step_id"]
        if operation == "add_middleware":
            if app_id in dispatched:
                after_start.append(step)
            else:
                registrations[app_id].append(input_for(step))
        else:
            dispatches[app_id].append(step)
            dispatched.add(app_id)

    for app_id, definitions in registrations.items():
        dispatch_types = [
            step["arguments"]["scope"]["value"]["type"] for step in dispatches[app_id]
        ]
        app_input = app_inputs[app_id]
        route = app_input["routes"][0]
        boundary_dispatches = [input_for(step) for step in dispatches[app_id]]
        if (
            len(definitions) == 2
            and app_input["debug"] is False
            and app_input["exception_handlers"] == []
            and all(
                item["middleware_class"]["callable_kind"] == "class"
                and item["middleware_class"].get("boundary_trace") is True
                for item in definitions
            )
            and len({item["middleware_class"]["name"] for item in definitions}) == 2
            and route["kind"] == "http-route"
            and route["methods"] == ["GET"]
            and route["endpoint"].get("kind") == "raise-runtime-error"
            and len(boundary_dispatches) == 2
            and all(item["scope"]["type"] == "http" for item in boundary_dispatches)
            and [item["scope"]["method"] for item in boundary_dispatches] == ["POST", "GET"]
            and all(item["scope"]["path"] == route["path"] for item in boundary_dispatches)
        ):
            coverage.add(STARLETTE_ADD_MIDDLEWARE_REQUIREMENTS["boundary_order"])
        if (
            len(definitions) >= 2
            and all(item["middleware_class"]["callable_kind"] == "class" for item in definitions)
            and len({item["middleware_class"]["name"] for item in definitions}) == 1
            and all(item["args"] for item in definitions[:2])
            and definitions[0]["args"] != definitions[1]["args"]
            and dispatch_types[:2] == ["lifespan", "http"]
        ):
            coverage.add(STARLETTE_ADD_MIDDLEWARE_REQUIREMENTS["positional_order_and_cache"])
        if (
            len(definitions) >= 2
            and all(item["middleware_class"]["callable_kind"] == "factory" for item in definitions)
            and len({item["middleware_class"]["name"] for item in definitions}) == 1
            and any(item["args"] for item in definitions)
            and any(item["kwargs"] for item in definitions)
            and dispatch_types[:1] == ["lifespan"]
        ):
            coverage.add(STARLETTE_ADD_MIDDLEWARE_REQUIREMENTS["factory_keyword_arguments"])

    if after_start:
        coverage.add(STARLETTE_ADD_MIDDLEWARE_REQUIREMENTS["after_start_error"])

    if len(app_ids) >= 2:
        for first_app in app_ids:
            first_dispatches = dispatches[first_app]
            first_types = [step["arguments"]["scope"]["value"]["type"] for step in first_dispatches]
            first_class_names = {
                item["middleware_class"]["name"]
                for item in registrations[first_app]
                if item["middleware_class"]["callable_kind"] == "class"
            }
            if first_types[:2] != ["lifespan", "http"] or not first_class_names:
                continue
            for second_app in app_ids:
                if second_app == first_app or not dispatches[second_app]:
                    continue
                second_class_names = {
                    item["middleware_class"]["name"]
                    for item in registrations[second_app]
                    if item["middleware_class"]["callable_kind"] == "class"
                }
                if first_class_names & second_class_names:
                    coverage.add(
                        STARLETTE_ADD_MIDDLEWARE_REQUIREMENTS["per_application_stack_cache"]
                    )
                    break
            if STARLETTE_ADD_MIDDLEWARE_REQUIREMENTS["per_application_stack_cache"] in coverage:
                break
    return coverage


def _starlette_add_middleware_expected_schedule(case: dict[str, Any]) -> list[str]:
    schedule: list[str] = []
    registered: set[str] = set()
    dispatched: set[str] = set()
    for index, step in enumerate(case["steps"]):
        operation = step.get("operation")
        if operation == "__init__":
            if index:
                schedule.append("application-construction")
        elif operation == "add_middleware":
            app_id = step["receiver"]["step_id"]
            if app_id in dispatched:
                schedule.append("middleware-add-after-start")
            elif app_id not in registered:
                registered.add(app_id)
                schedule.append("middleware-registration")
        elif operation == "__call__":
            app_id = step["receiver"]["step_id"]
            arguments = {
                name: descriptor["value"] for name, descriptor in step["arguments"].items()
            }
            if arguments["scope"]["type"] == "lifespan":
                schedule.extend(["lifespan.startup", "lifespan.shutdown"])
            else:
                schedule.append("dispatch")
            dispatched.add(app_id)
    return schedule


def _validate_starlette_add_middleware_workflow(case: dict[str, Any]) -> None:
    steps = case["steps"]
    operations = [step.get("operation") for step in steps]
    if (
        case["target_profiles"] != ["python-package-cpython312"]
        or len(steps) < 4
        or operations[0] != "__init__"
        or operations.count("add_middleware") < 1
        or operations.count("__call__") < 1
        or any(
            operation not in {"__init__", "add_middleware", "__call__"} for operation in operations
        )
        or any(step.get("surface") != "starlette.applications.Starlette" for step in steps)
    ):
        raise ContractError("Starlette.add_middleware workflow has an invalid operation sequence")
    app_ids: set[str] = set()
    dispatched: set[str] = set()
    registered: set[str] = set()
    for step in steps:
        operation = step.get("operation")
        if operation == "__init__":
            app_ids.add(step["step_id"])
            app_arguments = {
                name: descriptor["value"] for name, descriptor in step["arguments"].items()
            }
            _validate_application_stimulus(app_arguments, request_dispatch=False)
            continue
        app_id = step["receiver"]["step_id"]
        if app_id not in app_ids:
            raise ContractError("Starlette.add_middleware must bind a previously constructed app")
        if operation == "__call__":
            dispatched.add(app_id)
            continue
        arguments = step.get("arguments")
        if not isinstance(arguments, dict) or set(arguments) != {
            "middleware_class",
            "args",
            "kwargs",
        }:
            raise ContractError(
                "Starlette.add_middleware requires callable, args, and kwargs inputs"
            )
        marker = arguments["middleware_class"].get("value")
        if (
            arguments["middleware_class"].get("kind") != "literal"
            or not isinstance(marker, dict)
            or set(marker) - {"kind", "callable_kind", "name", "boundary_trace"}
            or not {"kind", "callable_kind", "name"} <= set(marker)
            or marker["kind"] != "input-defined-middleware"
            or marker["callable_kind"] not in {"class", "factory"}
            or not isinstance(marker["name"], str)
            or not marker["name"]
            or ("boundary_trace" in marker and type(marker["boundary_trace"]) is not bool)
        ):
            raise ContractError(
                "middleware callable must use an input-defined class or factory marker"
            )
        args_descriptor = arguments["args"]
        kwargs_descriptor = arguments["kwargs"]
        if (
            args_descriptor.get("kind") != "literal"
            or not isinstance(args_descriptor.get("value"), list)
            or kwargs_descriptor.get("kind") != "literal"
            or not isinstance(kwargs_descriptor.get("value"), dict)
        ):
            raise ContractError("middleware variadic arguments must be literal arrays and objects")
        registered.add(app_id)
    if app_ids != registered or app_ids != dispatched:
        raise ContractError("each application must register middleware and receive an ASGI call")
    expected_schedule = _starlette_add_middleware_expected_schedule(case)
    if case["execution_schedule"] != expected_schedule:
        raise ContractError(
            "Starlette.add_middleware schedule must preserve registration and dispatch order"
        )
    exercised = _starlette_add_middleware_semantic_coverage(case)
    if not exercised or set(case["covers"]) != exercised:
        raise ContractError(
            "Starlette.add_middleware covers must exactly match the callable and dispatch inputs"
        )
    if case["observations"] != [step["step_id"] for step in steps[1:]]:
        raise ContractError(
            "Starlette.add_middleware must observe every registration and dispatch step"
        )


def _starlette_add_exception_handler_expected_schedule(case: dict[str, Any]) -> list[str]:
    schedule: list[str] = []
    for index, step in enumerate(case["steps"]):
        operation = step["operation"]
        if index and operation == "__init__":
            schedule.append("application-construction")
        elif operation == "add_exception_handler":
            schedule.append("handler-registration")
        elif operation == "request-dispatch":
            schedule.append("dispatch")
    return schedule


def _validate_starlette_add_exception_handler_handler(
    step: dict[str, Any], expected_key_kind: str
) -> None:
    arguments = {name: descriptor["value"] for name, descriptor in step["arguments"].items()}
    key = arguments["exc_class_or_status_code"]
    marker = arguments["handler"]
    if not isinstance(key, dict) or key.get("kind") != expected_key_kind:
        raise ContractError("exception handler registration must use its declared key kind")
    if expected_key_kind == "exception-class":
        _exact(key, {"kind", "name"}, "exception-class handler key")
        if key["name"] != "RuntimeError":
            raise ContractError("exception handler workflow must register RuntimeError")
    else:
        _exact(key, {"kind", "status_code"}, "status-code handler key")
        if key["status_code"] != 500:
            raise ContractError("status-code handler workflow must register status 500")
    marker = _exact(
        marker,
        {"kind", "callable_kind", "label", "status_code", "content"},
        "input-defined exception handler",
    )
    if (
        marker["kind"] != "input-defined-exception-handler"
        or marker["callable_kind"] not in {"sync", "async"}
        or not isinstance(marker["label"], str)
        or not marker["label"]
        or type(marker["status_code"]) is not int
        or not 100 <= marker["status_code"] <= 599
        or not isinstance(marker["content"], str)
    ):
        raise ContractError("exception-handler callable and response must be input-defined")


def _validate_starlette_add_exception_handler_workflow(case: dict[str, Any]) -> None:
    steps = case["steps"]
    operations = [step["operation"] for step in steps]
    late_registration = len(steps) == 7
    expected_operations = (
        [
            "__init__",
            "add_exception_handler",
            "request-dispatch",
            "__init__",
            "request-dispatch",
            "add_exception_handler",
            "request-dispatch",
        ]
        if late_registration
        else ["__init__", "add_exception_handler", "request-dispatch"]
    )
    expected_ids = (
        [
            "application-before",
            "register-before",
            "dispatch-before",
            "application-after",
            "dispatch-before-registration",
            "register-after",
            "dispatch-after-registration",
        ]
        if late_registration
        else ["application-status", "register-status-handler", "dispatch-status"]
    )
    key_kind = "exception-class" if late_registration else "status-code"
    if (
        case["target_profiles"] != ["python-package-cpython312"]
        or operations != expected_operations
        or [step["step_id"] for step in steps] != expected_ids
        or any(step["surface"] != "starlette.applications.Starlette" for step in steps)
    ):
        raise ContractError(
            "Starlette.add_exception_handler workflow has an invalid registration sequence"
        )

    applications: set[str] = set()
    for step in steps:
        operation = step["operation"]
        if operation == "__init__":
            applications.add(step["step_id"])
            arguments = {
                name: descriptor["value"] for name, descriptor in step["arguments"].items()
            }
            _validate_application_stimulus(arguments, request_dispatch=False)
            route = arguments["routes"][0]
            if (
                arguments["exception_handlers"] != []
                or route["kind"] != "http-route"
                or route["path"] != "/failure"
                or route["methods"] != ["GET"]
                or route["endpoint"].get("kind") != "raise-runtime-error"
            ):
                raise ContractError(
                    "exception-handler workflow applications must start with an uncaught GET failure"
                )
            continue

        receiver = step["receiver"]["step_id"]
        if receiver not in applications:
            raise ContractError(
                "Starlette.add_exception_handler must bind a previously constructed app"
            )
        if operation == "add_exception_handler":
            _validate_starlette_add_exception_handler_handler(step, key_kind)
            continue

        arguments = {name: descriptor["value"] for name, descriptor in step["arguments"].items()}
        _validate_dispatch_stimulus(arguments, request_dispatch=True)
        scope = arguments["scope"]
        if scope["type"] != "http" or scope["method"] != "GET" or scope["path"] != "/failure":
            raise ContractError(
                "exception-handler workflow dispatches must request the failing GET route"
            )

    if late_registration:
        registrations = [step for step in steps if step["operation"] == "add_exception_handler"]
        dispatches = [step for step in steps if step["operation"] == "request-dispatch"]
        if (
            registrations[0]["receiver"]["step_id"] != "application-before"
            or dispatches[0]["receiver"]["step_id"] != "application-before"
            or dispatches[1]["receiver"]["step_id"] != "application-after"
            or registrations[1]["receiver"]["step_id"] != "application-after"
            or dispatches[2]["receiver"]["step_id"] != "application-after"
            or registrations[0]["step_id"] != "register-before"
            or registrations[1]["step_id"] != "register-after"
            or dispatches[1]["step_id"] != "dispatch-before-registration"
        ):
            raise ContractError(
                "exception-class workflow must register before dispatch and after stack construction"
            )
    elif (
        steps[1]["receiver"]["step_id"] != "application-status"
        or steps[2]["receiver"]["step_id"] != "application-status"
    ):
        raise ContractError("status-code handler workflow must register before first dispatch")

    handler_steps = [step for step in steps if step["operation"] == "add_exception_handler"]
    if late_registration:
        if any(
            step["arguments"]["handler"]["value"]["callable_kind"] != "async"
            for step in handler_steps
        ):
            raise ContractError("exception-class workflow callbacks must be async callables")
    elif steps[1]["arguments"]["handler"]["value"]["callable_kind"] != "sync":
        raise ContractError("status-code workflow callback must be a synchronous callable")

    expected_schedule = _starlette_add_exception_handler_expected_schedule(case)
    if case["execution_schedule"] != expected_schedule:
        raise ContractError(
            "Starlette.add_exception_handler schedule must preserve registration and dispatch order"
        )
    if set(case["covers"]) != {STARLETTE_ADD_EXCEPTION_HANDLER_REQUIREMENT}:
        raise ContractError(
            "Starlette.add_exception_handler covers must name the registration and cache requirement"
        )
    if case["observations"] != [step["step_id"] for step in steps[1:]]:
        raise ContractError(
            "Starlette.add_exception_handler must observe every registration and dispatch step"
        )


def _starlette_add_exception_handler_semantic_coverage(case: dict[str, Any]) -> set[str]:
    return {STARLETTE_ADD_EXCEPTION_HANDLER_REQUIREMENT}


def _is_route_body_limit_workflow(case: Any) -> bool:
    if (
        not isinstance(case, dict)
        or case.get("surface") != "starlette.applications.Starlette"
        or case.get("operation") != "__call__"
        or not isinstance(case.get("steps"), list)
        or len(case["steps"]) != 2
    ):
        return False
    construction_arguments = case["steps"][0].get("arguments")
    if not isinstance(construction_arguments, dict):
        return False
    routes_input = construction_arguments.get("routes")
    limit_input = construction_arguments.get("max_body_size")
    if (
        not isinstance(routes_input, dict)
        or routes_input.get("kind") != "literal"
        or not isinstance(routes_input.get("value"), list)
        or len(routes_input["value"]) != 1
        or not isinstance(limit_input, dict)
        or limit_input.get("kind") != "literal"
        or type(limit_input.get("value")) is not int
    ):
        return False
    route = routes_input["value"][0]
    return (
        isinstance(route, dict)
        and route.get("kind") == "http-route"
        and "max_body_size" in route
        and _is_route_body_limit_endpoint(route.get("endpoint"))
    )


def _is_route_body_limit_application(arguments: Any) -> bool:
    if not isinstance(arguments, dict) or type(arguments.get("max_body_size")) is not int:
        return False
    routes = arguments.get("routes")
    if not isinstance(routes, list) or len(routes) != 1 or not isinstance(routes[0], dict):
        return False
    route = routes[0]
    return (
        route.get("kind") == "http-route"
        and "max_body_size" in route
        and _is_route_body_limit_endpoint(route.get("endpoint"))
    )


def _is_route_body_limit_endpoint(endpoint: Any) -> bool:
    return (
        endpoint == {"kind": "request-body-echo"}
        or (
            isinstance(endpoint, dict)
            and set(endpoint) == {"kind", "content", "status_code", "media_type", "cookies"}
            and endpoint.get("kind") == "plain-text-response"
            and isinstance(endpoint.get("content"), str)
            and type(endpoint.get("status_code")) is int
            and 100 <= endpoint["status_code"] <= 599
            and isinstance(endpoint.get("media_type"), str)
            and endpoint.get("cookies") == []
        )
        or (
            isinstance(endpoint, dict)
            and set(endpoint) == {"kind", "response_content"}
            and endpoint.get("kind") == "request-form-consumer"
            and isinstance(endpoint.get("response_content"), str)
        )
    )


def _validate_route_body_limit_application(arguments: dict[str, Any]) -> None:
    arguments = _exact(
        arguments,
        {"debug", "routes", "middleware", "exception_handlers", "lifespan", "max_body_size"},
        "route body-limit application input",
    )
    middleware = arguments["middleware"]
    if not isinstance(middleware, list):
        raise ContractError("route body-limit middleware must be an input-defined array")
    for index, middleware_spec in enumerate(middleware):
        spec = _exact(middleware_spec, {"kind"}, f"route body-limit middleware[{index}]")
        if spec["kind"] not in {
            "copy-scope",
            "read-before-application",
            "base-http-passthrough",
            "base-http-read-body",
        }:
            raise ContractError("route body-limit middleware uses an unsupported input action")
    if (
        arguments["debug"] is not False
        or arguments["exception_handlers"] != []
        or type(arguments["max_body_size"]) is not int
        or arguments["max_body_size"] < 0
        or _validate_lifespan_marker(arguments["lifespan"]) != "async-context-manager"
    ):
        raise ContractError("route body-limit application must use the declared bounded setup")
    routes = arguments["routes"]
    if not isinstance(routes, list) or len(routes) != 1:
        raise ContractError("route body-limit application must contain one HTTP route")
    route = _exact(
        routes[0],
        {"kind", "path", "methods", "endpoint", "max_body_size"},
        "route body-limit route input",
    )
    if (
        route["kind"] != "http-route"
        or not isinstance(route["path"], str)
        or not route["path"].startswith("/")
        or route["methods"] != ["POST"]
        or not _is_route_body_limit_endpoint(route["endpoint"])
        or (
            route["max_body_size"] is not None
            and (type(route["max_body_size"]) is not int or route["max_body_size"] < 0)
        )
    ):
        raise ContractError(
            "route body-limit route must use an input-defined response endpoint and optional limit"
        )


def _route_body_limit_requirement_from_input(case: dict[str, Any]) -> str | None:
    construction = {
        key: descriptor["value"] for key, descriptor in case["steps"][0]["arguments"].items()
    }
    dispatch = {
        key: descriptor["value"] for key, descriptor in case["steps"][1]["arguments"].items()
    }
    route = construction["routes"][0]
    app_limit = construction["max_body_size"]
    route_limit = route["max_body_size"]
    scope_copy_middleware = any(
        middleware_spec["kind"] == "copy-scope" for middleware_spec in construction["middleware"]
    )
    body_size = sum(
        len(base64.b64decode(message["body_base64"], validate=True))
        for message in dispatch["receive"]
    )
    if route_limit is None and body_size > app_limit:
        return ROUTE_BODY_LIMIT_WORKFLOW_REQUIREMENTS["application_default"]
    if route_limit is None:
        return None
    if scope_copy_middleware and app_limit < body_size <= route_limit and route_limit > app_limit:
        return ROUTE_BODY_LIMIT_WORKFLOW_REQUIREMENTS["raise_application_through_scope_copy"]
    if app_limit < body_size <= route_limit and route_limit > app_limit:
        return ROUTE_BODY_LIMIT_WORKFLOW_REQUIREMENTS["raise_application"]
    if route_limit < body_size <= app_limit and route_limit < app_limit:
        return ROUTE_BODY_LIMIT_WORKFLOW_REQUIREMENTS["lower_application"]
    return None


def _validate_route_body_limit_workflow(case: dict[str, Any]) -> None:
    if (
        case["target_profiles"] != ["python-package-cpython312"]
        or case["observations"] != ["dispatch"]
        or case["execution_schedule"] != ["dispatch"]
    ):
        raise ContractError("route body-limit dispatch selects one Python-package comparison")
    construction = {
        key: descriptor["value"] for key, descriptor in case["steps"][0]["arguments"].items()
    }
    route = construction["routes"][0]
    dispatch = {
        key: descriptor["value"] for key, descriptor in case["steps"][1]["arguments"].items()
    }
    scope = dispatch["scope"]
    if (
        scope.get("type") != "http"
        or scope.get("path") != route["path"]
        or scope.get("method") != "POST"
    ):
        raise ContractError("route body-limit dispatch must POST to its configured route")
    headers = [
        (
            base64.b64decode(name, validate=True).lower(),
            base64.b64decode(value, validate=True),
        )
        for name, value in scope["headers_base64_pairs"]
    ]
    content_lengths = [value for name, value in headers if name == b"content-length"]
    messages = dispatch["receive"]
    body_size = sum(
        len(base64.b64decode(message["body_base64"], validate=True)) for message in messages
    )
    if (
        len(content_lengths) > 1
        or (
            content_lengths
            and (not content_lengths[0].isdigit() or int(content_lengths[0]) != body_size)
        )
        or body_size == 0
    ):
        raise ContractError(
            "route body-limit request may omit Content-Length or declare its complete "
            "non-empty body length"
        )
    if route["endpoint"]["kind"] == "request-form-consumer":
        content_types = [value for name, value in headers if name == b"content-type"]
        if len(content_types) != 1:
            raise ContractError("request-form endpoint requires one multipart Content-Type")
        message_body = b"".join(
            base64.b64decode(message["body_base64"], validate=True) for message in messages
        )
        multipart_message = BytesParser(policy=email_policy.default).parsebytes(
            b"Content-Type: " + content_types[0] + b"\r\nMIME-Version: 1.0\r\n\r\n" + message_body
        )
        file_parts = (
            [
                part
                for part in multipart_message.iter_parts()
                if part.get_content_disposition() == "form-data" and part.get_filename() is not None
            ]
            if multipart_message.is_multipart()
            else []
        )
        if multipart_message.get_content_type() != "multipart/form-data" or len(file_parts) != 1:
            raise ContractError("request-form endpoint input must contain one multipart file part")
    requirement = _route_body_limit_requirement_from_input(case)
    if requirement is None or case["covers"] != [requirement]:
        raise ContractError("route body-limit case must cover its input-derived limit relationship")


def _validate_exception_handler_registry(value: Any) -> None:
    if not isinstance(value, list) or not value:
        raise ContractError("non-empty exception-handler registry must be an ordered entry array")
    seen: set[tuple[str, str | int]] = set()
    for index, raw_entry in enumerate(value):
        context = f"exception_handlers[{index}]"
        entry = _exact(raw_entry, {"key", "handler"}, context)
        key = entry["key"]
        if not isinstance(key, dict) or key.get("kind") not in {"status-code", "exception-class"}:
            raise ContractError(f"{context}.key must use a declared tagged handler key")
        if key["kind"] == "status-code":
            _exact(key, {"kind", "status_code"}, f"{context}.key")
            status_code = key["status_code"]
            if type(status_code) is not int or not 100 <= status_code <= 599:
                raise ContractError(f"{context}.key.status_code must be an HTTP status code")
            identity: tuple[str, str | int] = ("status-code", status_code)
        else:
            name = key.get("name")
            if name == "HTTPException":
                _exact(key, {"kind", "name"}, f"{context}.key")
            elif name == "WebSocketException":
                _exact(key, {"kind", "name"}, f"{context}.key")
            elif name == "Exception":
                _exact(key, {"kind", "name"}, f"{context}.key")
            elif name == "BodyReuseException":
                _exact(key, {"kind", "name", "base_class"}, f"{context}.key")
                if key["base_class"] != "HTTPException":
                    raise ContractError("BodyReuseException must derive from HTTPException")
            elif name == "CustomWSException":
                _exact(key, {"kind", "name", "base_class"}, f"{context}.key")
                if key["base_class"] != "Exception":
                    raise ContractError("CustomWSException must derive from Exception")
            else:
                raise ContractError(f"{context}.key names an unsupported exception class")
            identity = ("exception-class", name)
        if identity in seen:
            raise ContractError("exception-handler registry must not repeat a typed key")
        seen.add(identity)
        _validate_exception_handler_recipe(entry["handler"], f"{context}.handler")


def _validate_exception_handler_recipe(value: Any, context: str) -> None:
    if not isinstance(value, dict) or not isinstance(value.get("kind"), str):
        raise ContractError(f"{context} must use a declared handler recipe")
    kind = value["kind"]
    if kind == "json-exception-detail-response":
        _exact(value, {"kind", "status_from_exception"}, context)
        if value["status_from_exception"] is not True:
            raise ContractError(f"{context} must use the HTTPException status")
    elif kind == "json-exception-detail-headers-response":
        _exact(value, {"kind"}, context)
    elif kind == "json-literal-response":
        _exact(value, {"kind", "status_code", "content"}, context)
        if type(value["status_code"]) is not int or not 100 <= value["status_code"] <= 599:
            raise ContractError(f"{context}.status_code must be an HTTP status code")
        if not isinstance(value["content"], dict):
            raise ContractError(f"{context}.content must be a JSON object")
    elif kind == "request-body-json-response":
        _exact(value, {"kind", "body_field", "status_from_exception"}, context)
        _string(value["body_field"], f"{context}.body_field")
        if value["status_from_exception"] is not True:
            raise ContractError(f"{context} must use the HTTPException status")
    elif kind == "server-error-response":
        _exact(value, {"kind", "label", "status_code", "content"}, context)
        _string(value["label"], f"{context}.label")
        _string(value["content"], f"{context}.content")
        if value["status_code"] != 500:
            raise ContractError(f"{context}.status_code must be 500")
    elif kind == "record-sync-server-error-handler":
        _exact(value, {"kind", "label"}, context)
        _string(value["label"], f"{context}.label")
    elif kind == "websocket-close-handler":
        _exact(value, {"kind", "label", "callable_kind", "code"}, context)
        _string(value["label"], f"{context}.label")
        if value["callable_kind"] != "sync-from-thread":
            raise ContractError(f"{context}.callable_kind must preserve the source sync handler")
        if type(value["code"]) is not int or value["code"] < 0:
            raise ContractError(f"{context}.code must be a non-negative integer")
    elif kind == "websocket-exception-close-handler":
        _exact(value, {"kind", "code"}, context)
        if type(value["code"]) is not int or value["code"] < 0:
            raise ContractError(f"{context}.code must be a non-negative integer")
    else:
        raise ContractError(f"{context} uses an unsupported handler recipe: {kind!r}")


def _validate_websocket_exception_application(args: dict[str, Any]) -> None:
    if (
        args["debug"] is not False
        or args["middleware"] != []
        or args["max_body_size"] is not None
        or args["lifespan"]
        != {
            "kind": "async-context-manager",
            "record_entry": True,
            "record_exit": True,
        }
    ):
        raise ContractError("WebSocket exception application differs from the declared baseline")
    route = _exact(args["routes"][0], {"kind", "path", "endpoint"}, "WebSocket route input")
    if (
        route["kind"] != "websocket-route"
        or not isinstance(route["path"], str)
        or not route["path"].startswith("/")
    ):
        raise ContractError("WebSocket exception input requires one absolute WebSocket route")
    endpoint = route["endpoint"]
    if not isinstance(endpoint, dict) or not isinstance(endpoint.get("kind"), str):
        raise ContractError("WebSocket endpoint must use a declared exception stimulus")

    handlers = args["exception_handlers"]
    if endpoint["kind"] == "http-exception":
        endpoint = _exact(
            endpoint, {"kind", "status_code", "detail", "headers"}, "HTTPException endpoint"
        )
        if (
            type(endpoint["status_code"]) is not int
            or not 100 <= endpoint["status_code"] <= 599
            or (endpoint["detail"] is not None and not isinstance(endpoint["detail"], str))
            or endpoint["headers"] != []
        ):
            raise ContractError("WebSocket HTTPException input has invalid values")
        expected_handlers = [
            {
                "key": {"kind": "exception-class", "name": "HTTPException"},
                "handler": {
                    "kind": "json-exception-detail-response",
                    "status_from_exception": True,
                },
            }
        ]
        if handlers != expected_handlers:
            raise ContractError("WebSocket HTTPException must use the declared JSON detail handler")
        return

    endpoint = _exact(endpoint, {"kind", "actions"}, "WebSocket action-sequence endpoint")
    actions = endpoint["actions"]
    if (
        endpoint["kind"] != "websocket-action-sequence"
        or not isinstance(actions, list)
        or len(actions) != 2
    ):
        raise ContractError(
            "WebSocket exception endpoint must accept then raise one declared exception"
        )
    if actions[0] != {"action": "accept"}:
        raise ContractError("WebSocket exception sequence must accept before raising")
    raise_action = actions[1]
    if not isinstance(raise_action, dict) or raise_action.get("action") not in {
        "raise-websocket-exception",
        "raise-custom-exception",
    }:
        raise ContractError("WebSocket sequence must end by raising a declared WebSocket exception")
    if raise_action["action"] == "raise-websocket-exception":
        allowed = {"action", "code", "reason"}
        if set(raise_action) not in ({"action", "code"}, allowed):
            raise ContractError("WebSocketException action has invalid fields")
        if type(raise_action["code"]) is not int or raise_action["code"] < 0:
            raise ContractError("WebSocketException code must be a non-negative integer")
        if "reason" in raise_action and not isinstance(raise_action["reason"], str):
            raise ContractError("WebSocketException reason must be a string")
        if handlers:
            _validate_exception_handler_registry(handlers)
            if (
                len(handlers) != 1
                or handlers[0]["key"] != {"kind": "exception-class", "name": "WebSocketException"}
                or handlers[0]["handler"].get("kind") != "websocket-exception-close-handler"
            ):
                raise ContractError(
                    "custom WebSocketException handling requires its registered close handler"
                )
        return

    _exact(raise_action, {"action", "exception_class"}, "custom WebSocket exception action")
    if raise_action["exception_class"] != "CustomWSException":
        raise ContractError("custom WebSocket exception must name its declared class")
    _validate_exception_handler_registry(handlers)
    expected_key = {
        "kind": "exception-class",
        "name": "CustomWSException",
        "base_class": "Exception",
    }
    if (
        len(handlers) != 1
        or handlers[0]["key"] != expected_key
        or handlers[0]["handler"].get("kind") != "websocket-close-handler"
    ):
        raise ContractError("custom WebSocket exception must use its registered close handler")


def _validate_http_exception_application(route: dict[str, Any], handlers: Any) -> None:
    endpoint = _exact(
        route["endpoint"],
        {"kind", "status_code", "detail", "headers"},
        "HTTP exception endpoint input",
    )
    _string(route["path"], "HTTP exception route path")
    if (
        route["kind"] != "http-route"
        or not route["path"].startswith("/")
        or route["methods"] != ["GET"]
    ):
        raise ContractError("HTTP exception routes must select one absolute-path GET")
    if (
        type(endpoint["status_code"]) is not int
        or not 100 <= endpoint["status_code"] <= 599
        or (endpoint["detail"] is not None and not isinstance(endpoint["detail"], str))
        or not isinstance(endpoint["headers"], list)
    ):
        raise ContractError("HTTP exception stimulus has an invalid status, detail, or headers")
    for index, pair in enumerate(endpoint["headers"]):
        if (
            not isinstance(pair, list)
            or len(pair) != 2
            or any(not isinstance(value, str) for value in pair)
        ):
            raise ContractError(f"HTTP exception header input[{index}] must be a string pair")
    if handlers:
        if (
            len(handlers) != 1
            or handlers[0]["key"] != {"kind": "exception-class", "name": "HTTPException"}
            or handlers[0]["handler"].get("kind") != "json-exception-detail-headers-response"
            or not endpoint["headers"]
        ):
            raise ContractError(
                "HTTPException header forwarding requires its documented custom handler and headers"
            )


def _validate_status_precedence_application(route: dict[str, Any], handlers: Any) -> None:
    if (
        route["kind"] != "http-route"
        or not isinstance(route["path"], str)
        or not route["path"].startswith("/")
        or route["methods"] != ["GET"]
    ):
        raise ContractError("status-code precedence requires one absolute-path GET route")
    endpoint = route["endpoint"]
    if (
        not isinstance(endpoint, dict)
        or endpoint.get("kind") != "plain-text-response"
        or set(endpoint) != {"kind", "content", "status_code", "media_type", "cookies"}
        or not isinstance(endpoint["content"], str)
        or type(endpoint["status_code"]) is not int
        or endpoint["media_type"] != "text/plain"
        or endpoint["cookies"] != []
    ):
        raise ContractError("status-code precedence route must use a plain-text endpoint")
    if len(handlers) != 2:
        raise ContractError("status-code precedence must configure two ordered handlers")
    first, second = handlers
    if (
        first["key"] != {"kind": "exception-class", "name": "HTTPException"}
        or first["handler"]
        != {
            "kind": "json-exception-detail-response",
            "status_from_exception": True,
        }
        or second["key"] != {"kind": "status-code", "status_code": 405}
        or second["handler"].get("kind") != "json-literal-response"
        or second["handler"].get("status_code") != 405
    ):
        raise ContractError("status-code precedence must put the HTTPException class handler first")


def _validate_body_reuse_application(route: dict[str, Any], handlers: Any) -> None:
    endpoint = _exact(
        route["endpoint"],
        {"kind", "exception_class", "status_code", "detail"},
        "body-reuse endpoint",
    )
    if (
        route["kind"] != "http-route"
        or not isinstance(route["path"], str)
        or not route["path"].startswith("/")
        or route["methods"] != ["POST"]
        or endpoint["kind"] != "http-exception-after-body"
        or endpoint["exception_class"] != "BodyReuseException"
        or type(endpoint["status_code"]) is not int
        or not 100 <= endpoint["status_code"] <= 599
        or (endpoint["detail"] is not None and not isinstance(endpoint["detail"], str))
    ):
        raise ContractError(
            "body-reuse endpoint must read the request body then raise its declared subclass"
        )
    expected_key = {
        "kind": "exception-class",
        "name": "BodyReuseException",
        "base_class": "HTTPException",
    }
    if (
        len(handlers) != 1
        or handlers[0]["key"] != expected_key
        or handlers[0]["handler"].get("kind") != "request-body-json-response"
        or handlers[0]["handler"].get("body_field") != "body"
    ):
        raise ContractError("body-reuse requires the declared subclass handler to read cached body")


def _validate_dispatch_stimulus(
    args: dict[str, Any],
    request_dispatch: bool,
    allow_nonempty_body: bool = False,
    allow_body_stream: bool = False,
    allow_headers: bool = False,
    allow_root_path: bool = False,
    allow_query: bool = False,
    allow_oserror_send: bool = False,
    allow_host: bool = False,
    allow_client: bool = False,
    allow_lifespan_callback_failures: bool = False,
    allow_inherited_mount_scope: bool = False,
    allow_http_disconnect: bool = False,
    allow_pre_asgi24_disconnect: bool = False,
    allow_scope_app: bool = False,
) -> None:
    if set(args) != {"scope", "receive", "send"}:
        raise ContractError(
            "dispatch must explicitly supply the ASGI scope, receive messages, and send collector"
        )
    scope = args["scope"]
    if not isinstance(scope, dict):
        raise ContractError("scope input must be an object")
    if scope.get("type") == "lifespan":
        scope_fields = {"type", "asgi"}
        if allow_lifespan_callback_failures and "state" in scope:
            scope_fields.add("state")
        _exact(scope, scope_fields, "lifespan scope input")
        if scope["asgi"] != {"version": "3.0", "spec_version": "2.4"}:
            raise ContractError("lifespan scope must use the declared ASGI versions")
        if "state" in scope and not isinstance(scope["state"], dict):
            raise ContractError("lifespan scope state must be an object")
        if allow_lifespan_callback_failures:
            _validate_lifespan_receive_actions(args["receive"])
            _validate_lifespan_send_callback(args["send"])
        elif args["receive"] != [
            {"type": "lifespan.startup"},
            {"type": "lifespan.shutdown"},
        ]:
            raise ContractError("lifespan input must include startup followed by shutdown")
        elif args["send"] != {"kind": "capture-asgi-send"}:
            raise ContractError("send input must contain the fixed ASGI capture selector")
    elif scope.get("type") == "http":
        scope_fields = {
            "type",
            "asgi",
            "http_version",
            "method",
            "scheme",
            "path",
            "raw_path_base64",
            "query_string_base64",
            "root_path",
            "headers_base64_pairs",
            "client",
            "server",
        }
        if allow_inherited_mount_scope:
            scope_fields.update(key for key in ("app_root_path", "path_params") if key in scope)
        if allow_scope_app and "app" in scope:
            scope_fields.add("app")
        scope = _exact(scope, scope_fields, "HTTP scope input")
        if "app" in scope and scope["app"] is not True:
            raise ContractError("HTTP scope.app must be the true app-presence marker")
        if "app_root_path" in scope:
            _string(scope["app_root_path"], "HTTP scope.app_root_path")
        if "path_params" in scope:
            path_params = scope["path_params"]
            if not isinstance(path_params, dict) or any(
                not isinstance(name, str) or not name or type(value) not in (str, int, float)
                for name, value in path_params.items()
            ):
                raise ContractError(
                    "HTTP scope.path_params must map non-empty names to strings or numbers"
                )
        _string(scope["method"], "HTTP scope.method")
        path = _string(scope["path"], "HTTP scope.path")
        try:
            path_bytes = path.encode("utf-8")
        except UnicodeEncodeError as exc:
            raise ContractError("HTTP scope.path must be UTF-8 encodable") from exc
        try:
            raw_path = base64.b64decode(scope["raw_path_base64"], validate=True)
        except (ValueError, TypeError) as exc:
            raise ContractError("scope.raw_path_base64 is invalid base64") from exc
        raw_path_matches = raw_path == path_bytes
        if not raw_path_matches and raw_path.isascii():
            raw_path_matches = unquote_to_bytes(raw_path.decode("ascii")) == path_bytes
        if not raw_path_matches:
            raise ContractError("raw_path bytes must match the declared path")
        asgi_versions_match = scope["asgi"] == {"version": "3.0", "spec_version": "2.4"}
        if allow_pre_asgi24_disconnect:
            asgi = scope["asgi"]
            if isinstance(asgi, dict) and asgi.get("version") == "3.0":
                try:
                    spec_version = tuple(int(part) for part in asgi["spec_version"].split("."))
                except (AttributeError, KeyError, TypeError, ValueError):
                    spec_version = ()
                asgi_versions_match = (2, 0) <= spec_version < (2, 4)
            else:
                asgi_versions_match = False
        if not asgi_versions_match or scope["http_version"] != "1.1":
            raise ContractError("HTTP scope must use the declared ASGI and HTTP versions")
        if (
            scope["scheme"] not in ({"http", "https"} if allow_host else {"http"})
            or (not allow_root_path and scope["root_path"] != "")
            or not isinstance(scope["root_path"], str)
        ):
            raise ContractError("HTTP scope differs from the declared direct-ASGI baseline")
        if (not allow_client and scope["client"] != ["127.0.0.1", 12345]) or (
            not allow_host and scope["server"] != ["testserver", 80]
        ):
            raise ContractError("HTTP scope client/server differ from the declared baseline")
        if (
            allow_client
            and scope["client"] is not None
            and (
                not isinstance(scope["client"], list)
                or len(scope["client"]) != 2
                or not isinstance(scope["client"][0], str)
                or type(scope["client"][1]) is not int
                or not 0 <= scope["client"][1] <= 65535
            )
        ):
            raise ContractError("HTTP scope client is invalid for this dispatch")
        if allow_host and (
            not isinstance(scope["server"], list)
            or len(scope["server"]) != 2
            or not isinstance(scope["server"][0], str)
            or type(scope["server"][1]) is not int
            or not 1 <= scope["server"][1] <= 65535
        ):
            raise ContractError("HTTP scope server is invalid for Host route dispatch")
        if not request_dispatch and not allow_query and scope["query_string_base64"] != "":
            raise ContractError("HTTP scope query value differs from the declared baseline")
        if not request_dispatch and not allow_headers and scope["headers_base64_pairs"] != []:
            raise ContractError("HTTP scope header values differ from the declared baseline")
        for key in ("raw_path_base64", "query_string_base64"):
            try:
                base64.b64decode(scope[key], validate=True)
            except (ValueError, TypeError) as exc:
                raise ContractError(f"scope.{key} is invalid base64") from exc
        if not isinstance(scope["headers_base64_pairs"], list):
            raise ContractError("scope.headers_base64_pairs must be an array")
        for pair in scope["headers_base64_pairs"]:
            if not isinstance(pair, list) or len(pair) != 2:
                raise ContractError("each ASGI header input must be a two-item array")
            for value in pair:
                try:
                    base64.b64decode(value, validate=True)
                except (ValueError, TypeError) as exc:
                    raise ContractError("ASGI header input contains invalid base64") from exc
        if not isinstance(args["receive"], list):
            raise ContractError("HTTP request input must be a list of request events")
        for message in args["receive"]:
            if (
                allow_http_disconnect
                and isinstance(message, dict)
                and message.get("type") == "http.disconnect"
            ):
                _exact(message, {"type"}, "HTTP disconnect message")
                continue
            _exact(message, {"type", "body_base64", "more_body"}, "HTTP request message")
            if message["type"] != "http.request" or not isinstance(message["more_body"], bool):
                raise ContractError(
                    "HTTP request messages must be http.request records with a boolean more_body"
                )
            try:
                base64.b64decode(message["body_base64"], validate=True)
            except (ValueError, TypeError) as exc:
                raise ContractError("HTTP request body must be valid base64") from exc
        if (
            not request_dispatch
            and not allow_body_stream
            and not allow_nonempty_body
            and args["receive"] != [{"type": "http.request", "body_base64": "", "more_body": False}]
        ):
            raise ContractError("legacy HTTP inputs must contain one empty request event")
        if allow_body_stream:
            messages = args["receive"]
            if (
                not messages
                or any(message["more_body"] is False for message in messages[:-1])
                or messages[-1]["more_body"] is not False
            ):
                raise ContractError("HTTP request body stream must end with one final event")
        if allow_nonempty_body:
            messages = args["receive"]
            if (
                not messages
                or not all(message["more_body"] for message in messages[:-1])
                or messages[-1]["more_body"]
                or not b"".join(
                    base64.b64decode(message["body_base64"], validate=True) for message in messages
                )
            ):
                raise ContractError("input must contain a non-empty request body")
    elif scope.get("type") == "websocket":
        _validate_websocket_scope(scope)
        messages = args["receive"]
        if not isinstance(messages, list):
            raise ContractError("WebSocket receive input must be a message array")
        for index, message in enumerate(messages):
            _validate_websocket_message(message, f"WebSocket receive[{index}]", incoming=True)
    else:
        raise ContractError("scope type must be http, websocket, or lifespan")
    if args["send"] != {"kind": "capture-asgi-send"}:
        if allow_lifespan_callback_failures and scope.get("type") == "lifespan":
            return
        if not allow_oserror_send:
            raise ContractError("send input must contain the fixed ASGI capture selector")
        send = _exact(
            args["send"],
            {"kind", "event_index", "message"},
            "ASGI OSError send input",
        )
        if (
            send["kind"] != "capture-asgi-send-until-oserror"
            or type(send["event_index"]) is not int
            or send["event_index"] < 0
            or not isinstance(send["message"], str)
        ):
            raise ContractError("ASGI OSError send input is invalid")


def _validate_exception_handler_dispatch(
    app_arguments: dict[str, Any], dispatch_arguments: dict[str, Any]
) -> None:
    route = app_arguments["routes"][0]
    scope = dispatch_arguments["scope"]
    endpoint = route["endpoint"]
    if _is_router_miss_http_exception_handler_workflow(app_arguments, dispatch_arguments):
        return
    if scope.get("type") != "http" or _route_template_capture(route["path"], scope["path"]) is None:
        raise ContractError("exception-handler input must dispatch to its declared route path")
    if _is_server_error_stimulus(app_arguments):
        if scope["method"] != "GET" or route["methods"] != ["GET"]:
            raise ContractError("server-error inputs must dispatch their declared GET route")
        raw_headers = [
            (
                base64.b64decode(name, validate=True).lower(),
                base64.b64decode(value, validate=True),
            )
            for name, value in scope["headers_base64_pairs"]
        ]
        if app_arguments["debug"]:
            if len(raw_headers) != 1 or raw_headers[0][0] != b"accept":
                raise ContractError("debug traceback cases must declare one Accept header")
            if raw_headers[0][1] not in {b"application/json", b"text/html"}:
                raise ContractError(
                    "debug traceback Accept must select the declared text or HTML path"
                )
        elif raw_headers:
            raise ContractError("non-debug server-error cases must omit Accept headers")
        return
    if endpoint.get("kind") == "http-exception-after-body":
        if scope["method"] != "POST":
            raise ContractError("body-reuse input must dispatch a POST request")
    elif endpoint.get("kind") == "http-exception":
        if scope["method"] != "GET" or route["methods"] != ["GET"]:
            raise ContractError("HTTPException handler input must dispatch its declared GET route")
    elif scope["method"] != "POST" or route["methods"] != ["GET"]:
        raise ContractError("status-code precedence input must POST to its GET-only route")


def _is_router_miss_http_exception_handler_workflow(
    app_arguments: Any, dispatch_arguments: Any
) -> bool:
    if (
        not isinstance(app_arguments, dict)
        or not isinstance(dispatch_arguments, dict)
        or _is_server_error_stimulus(app_arguments)
    ):
        return False
    routes = app_arguments.get("routes")
    handlers = app_arguments.get("exception_handlers")
    scope = dispatch_arguments.get("scope")
    if (
        not isinstance(routes, list)
        or len(routes) != 1
        or not isinstance(routes[0], dict)
        or not isinstance(handlers, list)
        or not isinstance(scope, dict)
    ):
        return False
    route = routes[0]
    if (
        route.get("kind") != "http-route"
        or route.get("methods") != ["GET"]
        or not isinstance(route.get("path"), str)
        or scope.get("type") != "http"
        or scope.get("method") != "GET"
        or not isinstance(scope.get("path"), str)
        or _route_path_matches(route["path"], scope["path"])
    ):
        return False
    http_exception_handler = {
        "key": {"kind": "exception-class", "name": "HTTPException"},
        "handler": {
            "kind": "json-exception-detail-response",
            "status_from_exception": True,
        },
    }
    return http_exception_handler in handlers and not any(
        entry.get("key") == {"kind": "status-code", "status_code": 404}
        for entry in handlers
        if isinstance(entry, dict)
    )


def _validate_websocket_exception_dispatch(
    app_arguments: dict[str, Any], dispatch_arguments: dict[str, Any]
) -> None:
    route = app_arguments["routes"][0]
    scope = dispatch_arguments["scope"]
    if (
        route["kind"] != "websocket-route"
        or scope.get("type") != "websocket"
        or scope.get("path") != route["path"]
    ):
        raise ContractError("WebSocket exception input must dispatch to its declared route path")
    _validate_websocket_scope(scope)
    if dispatch_arguments["receive"] != [{"type": "websocket.connect", "subprotocols": []}]:
        raise ContractError("WebSocket exception input must supply one connection event")
    if dispatch_arguments["send"] != {"kind": "capture-asgi-send"}:
        raise ContractError("WebSocket exception input must use the ASGI event collector")
    if route["endpoint"]["kind"] == "http-exception":
        if scope.get("extensions") != {"websocket.http.response": {}}:
            raise ContractError(
                "WebSocket HTTPException input must expose the denial-response extension"
            )
    elif "extensions" in scope:
        raise ContractError("accepted WebSocket exception input does not declare extensions")


def _gzip_header_pairs(value: Any, context: str) -> list[tuple[bytes, bytes]]:
    if not isinstance(value, list):
        raise ContractError(f"{context} must be an array")
    decoded: list[tuple[bytes, bytes]] = []
    for index, pair in enumerate(value):
        if not isinstance(pair, list) or len(pair) != 2:
            raise ContractError(f"{context}[{index}] must be a two-item byte pair")
        try:
            name = base64.b64decode(pair[0], validate=True)
            header_value = base64.b64decode(pair[1], validate=True)
        except (ValueError, TypeError) as exc:
            raise ContractError(f"{context}[{index}] contains invalid base64") from exc
        if not name:
            raise ContractError(f"{context}[{index}] has an empty header name")
        decoded.append((name, header_value))
    return decoded


def _validate_body_limit_action_sequence(value: Any, context: str, depth: int = 0) -> None:
    if depth > 8:
        raise ContractError(f"{context} exceeds the declared nested middleware depth")
    if not isinstance(value, list) or not value:
        raise ContractError(f"{context} must be a non-empty action sequence")
    for index, raw_action in enumerate(value):
        action_context = f"{context}[{index}]"
        if not isinstance(raw_action, dict) or not isinstance(raw_action.get("action"), str):
            raise ContractError(f"{action_context} must declare an action")
        kind = raw_action["action"]
        if kind in {"receive", "observe-scope"}:
            _exact(raw_action, {"action"}, action_context)
        elif kind == "send":
            action = _exact(raw_action, {"action", "message"}, action_context)
            message = action["message"]
            if not isinstance(message, dict) or message.get("type") not in {
                "http.response.start",
                "http.response.body",
            }:
                raise ContractError(f"{action_context}.message has an unsupported ASGI type")
            if message["type"] == "http.response.start":
                message = _exact(
                    message,
                    {"type", "status", "headers_base64_pairs"},
                    f"{action_context}.message",
                )
                if type(message["status"]) is not int or not 100 <= message["status"] <= 599:
                    raise ContractError(f"{action_context}.message.status is invalid")
                _gzip_header_pairs(
                    message["headers_base64_pairs"], f"{action_context}.message.headers"
                )
            else:
                message = _exact(
                    message,
                    {"type", "body_base64", "more_body"},
                    f"{action_context}.message",
                )
                if not isinstance(message["more_body"], bool):
                    raise ContractError(f"{action_context}.message.more_body must be boolean")
                try:
                    base64.b64decode(message["body_base64"], validate=True)
                except (ValueError, TypeError) as exc:
                    raise ContractError(f"{action_context}.message.body_base64 is invalid") from exc
        elif kind == "raise-http-exception":
            action = _exact(
                raw_action,
                {"action", "status_code", "detail", "headers"},
                action_context,
            )
            if type(action["status_code"]) is not int or not 100 <= action["status_code"] <= 599:
                raise ContractError(f"{action_context}.status_code is invalid")
            if action["detail"] is not None and not isinstance(action["detail"], str):
                raise ContractError(f"{action_context}.detail must be a string or null")
            if action["headers"] is not None and not isinstance(action["headers"], list):
                raise ContractError(f"{action_context}.headers must be null or an array")
        elif kind == "raise-runtime-error":
            action = _exact(raw_action, {"action", "message"}, action_context)
            _string(action["message"], f"{action_context}.message")
        elif kind == "nested":
            action = _exact(
                raw_action,
                {"action", "max_body_size", "actions"},
                action_context,
            )
            limit = action["max_body_size"]
            if not isinstance(limit, int) or isinstance(limit, bool) or limit < 0:
                raise ContractError(f"{action_context}.max_body_size must be non-negative")
            _validate_body_limit_action_sequence(
                action["actions"], f"{action_context}.actions", depth + 1
            )
        else:
            raise ContractError(f"{action_context}.action is unsupported")


def _validate_default_receive_case(case: dict[str, Any]) -> None:
    if case["target_profiles"] != ["python-package-cpython312"]:
        raise ContractError("default receive parity currently targets the Python package profile")
    if case["assets"] != [] or case["observations"] != ["receive"]:
        raise ContractError("default receive cases must select receive without external assets")
    if not isinstance(case["scope"], dict):
        raise ContractError("default receive scope must be a record")
    _validate_dispatch_stimulus(
        {
            "scope": case["scope"],
            "receive": [],
            "send": {"kind": "capture-asgi-send"},
        },
        request_dispatch=True,
    )
    if case["scope"]["type"] != "http":
        raise ContractError("Request default-receive input must use an HTTP scope")
    if case["covers"] != ["starlette.request.default-empty-receive-runtime-error"]:
        raise ContractError("default receive case must cover its declared runtime-error behavior")


def _validate_request_client_case(case: dict[str, Any]) -> None:
    if case["target_profiles"] != ["python-package-cpython312"]:
        raise ContractError("Request.client parity currently targets the Python package profile")
    if case["assets"] != [] or case["observations"] != ["client-addresses"]:
        raise ContractError("Request.client cases select client-addresses without assets")
    if not case["case_id"].startswith("starlette.requests.Request.client."):
        raise ContractError("Request.client case ID must bind to the public client property")
    scope_cases = case["scope_cases"]
    if not isinstance(scope_cases, list) or not scope_cases:
        raise ContractError("Request.client scope_cases must be a non-empty array")
    scope_ids: set[str] = set()
    for index, value in enumerate(scope_cases):
        context = f"Request.client scope_cases[{index}]"
        scope_case = _exact(value, {"scope_id", "scope"}, context)
        scope_id = _string(scope_case["scope_id"], f"{context}.scope_id")
        if not scope_id or scope_id in scope_ids:
            raise ContractError("Request.client scope IDs must be non-empty and unique")
        scope_ids.add(scope_id)
        scope = scope_case["scope"]
        if not isinstance(scope, dict) or scope.get("type") != "http":
            raise ContractError(f"{context}.scope must be an HTTP scope record")
        if frozenset(scope) not in {frozenset({"type"}), frozenset({"type", "client"})}:
            raise ContractError(f"{context}.scope may supply only type and client")
        if "client" in scope:
            client = scope["client"]
            if client is not None and (
                not isinstance(client, list)
                or len(client) != 2
                or not isinstance(client[0], str)
                or type(client[1]) is not int
                or not 0 <= client[1] <= 65535
            ):
                raise ContractError(f"{context}.scope.client must be a host/port pair or null")
    if case["covers"] != [REQUEST_CLIENT_REQUIREMENT]:
        raise ContractError("Request.client case must cover the client-address requirement")


def _validate_request_scope_mapping_case(case: dict[str, Any]) -> None:
    if case["target_profiles"] != ["python-package-cpython312"]:
        raise ContractError("Request scope mapping parity targets the Python package profile")
    if case["assets"] != [] or case["observations"] != ["scope-mapping"]:
        raise ContractError("Request scope-mapping cases select scope-mapping without assets")
    if not case["case_id"].startswith("starlette.requests.Request.scope-mapping."):
        raise ContractError("Request scope-mapping case ID must bind to the mapping interface")
    expected_scope = {"type": "http", "method": "GET", "path": "/abc/"}
    if case["scope"] != expected_scope:
        raise ContractError("Request scope-mapping input must preserve the pinned minimal scope")
    if case["covers"] != [REQUEST_SCOPE_MAPPING_REQUIREMENT]:
        raise ContractError("Request scope-mapping case must cover its canonical requirement")


def _validate_websocket_scope_mapping_case(case: dict[str, Any]) -> None:
    if case["target_profiles"] != ["python-package-cpython312"]:
        raise ContractError("WebSocket scope mapping parity targets the Python package profile")
    if case["assets"] != [] or case["observations"] != ["scope-mapping"]:
        raise ContractError("WebSocket scope-mapping cases select scope-mapping without assets")
    if not case["case_id"].startswith("starlette.websockets.WebSocket.scope-mapping."):
        raise ContractError("WebSocket scope-mapping case ID must bind to the mapping interface")
    scope = case["scope"]
    if not isinstance(scope, dict) or scope.get("type") != "websocket":
        raise ContractError("WebSocket scope-mapping input must use a websocket scope")
    if not isinstance(scope.get("path"), str):
        raise ContractError("WebSocket scope-mapping input path must be a string")
    lookup_key = _string(case["lookup_key"], "WebSocket scope-mapping lookup_key")
    if lookup_key not in scope:
        raise ContractError("WebSocket scope-mapping lookup_key must exist in the supplied scope")
    header_lookup_keys = case["header_lookup_keys"]
    if not isinstance(header_lookup_keys, list) or any(
        not isinstance(key, str) or not key for key in header_lookup_keys
    ):
        raise ContractError("WebSocket header_lookup_keys must be an array of non-empty strings")
    assignment = _exact(
        case["header_assignment"],
        {"key", "value"},
        "WebSocket header_assignment",
    )
    assignment_key = _string(assignment["key"], "WebSocket header_assignment.key")
    _string(assignment["value"], "WebSocket header_assignment.value")

    if set(scope) == {"type", "path", "headers"}:
        if scope != {"type": "websocket", "path": "/abc/", "headers": []}:
            raise ContractError("WebSocket mapping input must preserve the declared minimal scope")
        if (
            case["covers"] != list(WEBSOCKET_SCOPE_MAPPING_REQUIREMENTS.values())
            or header_lookup_keys
        ):
            raise ContractError("minimal WebSocket mapping cases must cover scope and identity")
    elif set(scope) == {"type", "path", "headers_base64_pairs"}:
        headers = scope["headers_base64_pairs"]
        if not isinstance(headers, list):
            raise ContractError("WebSocket headers_base64_pairs must be an array")
        decoded_names: list[str] = []
        for pair in headers:
            if not isinstance(pair, list) or len(pair) != 2:
                raise ContractError("each WebSocket header pair must contain a name and value")
            try:
                name = base64.b64decode(pair[0], validate=True).decode("latin-1")
                base64.b64decode(pair[1], validate=True)
            except (ValueError, TypeError, UnicodeDecodeError) as error:
                raise ContractError("WebSocket header pair contains invalid base64") from error
            decoded_names.append(name)
        repeated_names = any(
            first.casefold() == second.casefold()
            for index, first in enumerate(decoded_names)
            for second in decoded_names[index + 1 :]
        )
        queried_case_variants = any(
            first.casefold() == second.casefold() and first != second
            for index, first in enumerate(header_lookup_keys)
            for second in header_lookup_keys[index + 1 :]
        )
        if (
            case["covers"] != [WEBSOCKET_HEADERS_REQUIREMENT]
            or not all(name.isascii() and name == name.lower() for name in decoded_names)
            or not repeated_names
            or not queried_case_variants
            or not any(name.casefold() == assignment_key.casefold() for name in decoded_names)
            or not any(
                name.casefold() == key.casefold()
                for name in decoded_names
                for key in header_lookup_keys
            )
        ):
            raise ContractError(
                "WebSocket header mapping coverage requires valid lowercase ASGI names, repeated "
                "headers, matching "
                "case-varied lookup inputs, and an assignment probe for a supplied header"
            )
    else:
        raise ContractError("WebSocket scope-mapping input has an unsupported scope shape")


def _validate_websocket_constructor_case(case: dict[str, Any]) -> None:
    if case["target_profiles"] != ["python-package-cpython312"]:
        raise ContractError("WebSocket constructor parity targets the Python package profile")
    if case["assets"] != [] or case["observations"] != ["constructor-contract"]:
        raise ContractError(
            "WebSocket constructor cases select constructor-contract without assets"
        )
    if not case["case_id"].startswith("starlette.websockets.WebSocket.constructor-contract."):
        raise ContractError("WebSocket constructor case ID must bind to the constructor interface")
    if case["scope"] != {"type": "websocket", "path": "/abc/", "headers": []}:
        raise ContractError("WebSocket constructor input must preserve the declared minimal scope")
    probes = case["constructor_probes"]
    if not isinstance(probes, list) or len(probes) != 2:
        raise ContractError("WebSocket constructor cases must provide both declared call forms")
    probe_ids: set[str] = set()
    argument_forms: set[tuple[str, ...]] = set()
    for index, raw_probe in enumerate(probes):
        context = f"WebSocket constructor probe[{index}]"
        probe = _exact(raw_probe, {"probe_id", "arguments"}, context)
        probe_id = _string(probe["probe_id"], f"{context}.probe_id")
        if not probe_id or probe_id in probe_ids:
            raise ContractError(f"{context}.probe_id must be non-empty and unique")
        probe_ids.add(probe_id)
        arguments = probe["arguments"]
        if (
            not isinstance(arguments, list)
            or any(
                not isinstance(argument, str) or argument not in {"scope", "receive", "send"}
                for argument in arguments
            )
            or len(arguments) != len(set(arguments))
        ):
            raise ContractError(f"{context}.arguments must select unique constructor inputs")
        argument_forms.add(tuple(arguments))
    if argument_forms != {("scope",), ("scope", "receive", "send")}:
        raise ContractError("WebSocket constructor probes must compare both documented call forms")
    if case["covers"] != [WEBSOCKET_CONSTRUCTOR_REQUIREMENT]:
        raise ContractError("WebSocket constructor case must cover its canonical requirement")


def _validate_send_push_promise_case(case: dict[str, Any]) -> None:
    if case["target_profiles"] != ["python-package-cpython312"]:
        raise ContractError("push-promise parity currently targets the Python package profile")
    if case["assets"] != [] or case["observations"] != ["send-push-promise"]:
        raise ContractError("push-promise cases must select one observation without assets")
    _string(case["path"], "Request.send_push_promise path")
    callback = _exact(
        case["send_callback"], {"kind"}, "Request.send_push_promise callback selector"
    )
    if callback["kind"] not in {"capture", "default"}:
        raise ContractError("push-promise callback must select capture or default")
    scope = case["scope"]
    if not isinstance(scope, dict) or "extensions" not in scope:
        raise ContractError("push-promise scope must explicitly declare its extensions")
    scope_without_extensions = {key: value for key, value in scope.items() if key != "extensions"}
    _validate_dispatch_stimulus(
        {
            "scope": scope_without_extensions,
            "receive": [],
            "send": {"kind": "capture-asgi-send"},
        },
        request_dispatch=True,
        allow_headers=True,
    )
    if scope["type"] != "http":
        raise ContractError("Request.send_push_promise requires an HTTP scope")
    extensions = scope["extensions"]
    if not isinstance(extensions, dict) or set(extensions) - {"http.response.push"}:
        raise ContractError("push-promise scope may declare only the HTTP response push extension")
    if "http.response.push" in extensions and extensions["http.response.push"] != {}:
        raise ContractError("HTTP response push extension configuration must be empty")
    if "http.response.push" not in extensions:
        expected = "starlette.request.send-push-promise.without-extension"
    elif callback["kind"] == "default":
        expected = "starlette.request.send-push-promise.missing-send"
    else:
        expected = "starlette.request.send-push-promise.extension-event"
    if case["covers"] != [expected]:
        raise ContractError("push-promise case must cover the behavior selected by its inputs")


def _validate_request_is_disconnected_case(case: dict[str, Any]) -> None:
    if case["target_profiles"] != ["python-package-cpython312"]:
        raise ContractError("Request.is_disconnected parity currently targets the Python package")
    if case["assets"] != [] or case["observations"] != ["is-disconnected"]:
        raise ContractError("disconnect cases must select one observation without external assets")
    _validate_dispatch_stimulus(
        {
            "scope": case["scope"],
            "receive": case["receive"],
            "send": {"kind": "capture-asgi-send"},
        },
        request_dispatch=True,
        allow_http_disconnect=True,
    )
    if case["scope"]["type"] != "http":
        raise ContractError("Request.is_disconnected requires an HTTP scope")
    message_types = [message["type"] for message in case["receive"]]
    checkpoints = case["receive_checkpoints"]
    if (
        not isinstance(checkpoints, list)
        or any(type(index) is not int or not 0 <= index < 3 for index in checkpoints)
        or len(set(checkpoints)) != len(checkpoints)
    ):
        raise ContractError("receive_checkpoints must contain unique callback indices from 0 to 2")
    if checkpoints == []:
        if message_types != ["http.request", "http.request", "http.disconnect"]:
            raise ContractError(
                "disconnect case must supply the request body, a non-disconnect poll result, "
                "then the client disconnect"
            )
    elif checkpoints == [1]:
        if message_types != ["http.request", "http.disconnect"]:
            raise ContractError(
                "canceled poll must leave the disconnect queued after the request body"
            )
    else:
        raise ContractError("disconnect parity supports a checkpoint on the first poll only")
    expected_covers = [
        "starlette.request.is-disconnected.detect-after-response",
        "starlette.request.is-disconnected.cache-observed-disconnect",
    ]
    if checkpoints:
        expected_covers.append("starlette.request.is-disconnected.cancel-pending-receive")
    if case["covers"] != expected_covers:
        raise ContractError("disconnect case must cover detection and cached disconnect state")


def _validate_request_body_stream_json_case(case: dict[str, Any]) -> None:
    if case["target_profiles"] != ["python-package-cpython312"]:
        raise ContractError("Request body/stream/json parity currently targets the Python package")
    if case["assets"] != [] or case["observations"] != ["request-consumption"]:
        raise ContractError("Request consumption cases select one observation without assets")
    scope_spec = case["scope"]
    scope_keys = {"type"}
    if isinstance(scope_spec, dict) and "headers_base64_pairs" in scope_spec:
        scope_keys.add("headers_base64_pairs")
    scope = _exact(scope_spec, scope_keys, "Request body/stream/json scope")
    if scope["type"] != "http":
        raise ContractError("Request body/stream/json requires an HTTP scope")
    scope_headers = (
        _validate_header_pairs(
            scope["headers_base64_pairs"], "Request body/stream/json scope headers_base64_pairs"
        )
        if "headers_base64_pairs" in scope
        else []
    )

    receive = case["receive"]
    if not isinstance(receive, list) or not receive:
        raise ContractError("Request body/stream/json receive tape must be non-empty")
    optional_receive_fields = False
    for index, raw_message in enumerate(receive):
        context = f"Request body/stream/json receive[{index}]"
        if not isinstance(raw_message, dict) or raw_message.get("type") not in {
            "http.request",
            "http.disconnect",
        }:
            raise ContractError(f"{context} must be an HTTP request or disconnect message")
        if raw_message["type"] == "http.request":
            allowed = {"type", "body_base64", "more_body"}
            if set(raw_message) - allowed:
                raise ContractError(f"{context} contains unsupported HTTP request fields")
            if "body_base64" in raw_message:
                try:
                    base64.b64decode(raw_message["body_base64"], validate=True)
                except (ValueError, TypeError, base64.binascii.Error) as exc:
                    raise ContractError(f"{context}.body_base64 is invalid") from exc
            else:
                optional_receive_fields = True
            if "more_body" in raw_message:
                if type(raw_message["more_body"]) is not bool:
                    raise ContractError(f"{context}.more_body must be boolean")
            else:
                optional_receive_fields = True
        elif set(raw_message) != {"type"}:
            raise ContractError(f"{context} disconnect message has unsupported fields")

    blocked_receive_calls = case["blocked_receive_calls"]
    if (
        not isinstance(blocked_receive_calls, list)
        or any(
            type(index) is not int or index < 0 or index >= len(receive)
            for index in blocked_receive_calls
        )
        or len(blocked_receive_calls) != len(set(blocked_receive_calls))
    ):
        raise ContractError("blocked_receive_calls must select unique messages in the receive tape")

    actions = case["actions"]
    if not isinstance(actions, list) or not actions:
        raise ContractError("Request body/stream/json actions must be a non-empty sequence")
    started_tasks: set[str] = set()
    awaited_tasks: set[str] = set()
    released_calls: set[int] = set()
    stream_ids: list[str] = []
    action_operations: list[str] = []
    for index, action in enumerate(actions):
        context = f"Request body/stream/json action[{index}]"
        if not isinstance(action, dict) or not isinstance(action.get("operation"), str):
            raise ContractError(f"{context} must be an operation record")
        operation = action["operation"]
        action_operations.append(operation)
        if operation in {"body", "form", "json"}:
            _exact(action, {"operation"}, context)
        elif operation == "stream-next":
            _exact(action, {"operation", "stream_id"}, context)
            stream_ids.append(_string(action["stream_id"], f"{context}.stream_id"))
        elif operation == "start-body":
            _exact(action, {"operation", "task_id"}, context)
            task_id = _string(action["task_id"], f"{context}.task_id")
            if task_id in started_tasks:
                raise ContractError(f"{context}.task_id must be unique")
            started_tasks.add(task_id)
        elif operation == "await-body":
            _exact(action, {"operation", "task_id"}, context)
            task_id = _string(action["task_id"], f"{context}.task_id")
            if task_id not in started_tasks or task_id in awaited_tasks:
                raise ContractError(f"{context}.task_id must name one earlier unawaited body task")
            awaited_tasks.add(task_id)
        elif operation == "release-receive":
            _exact(action, {"operation", "receive_call"}, context)
            receive_call = action["receive_call"]
            if type(receive_call) is not int or receive_call not in blocked_receive_calls:
                raise ContractError(f"{context}.receive_call must select a blocked callback")
            if receive_call in released_calls:
                raise ContractError(f"{context}.receive_call cannot be released twice")
            released_calls.add(receive_call)
        else:
            raise ContractError(f"{context}.operation is unsupported")
    if started_tasks != awaited_tasks:
        raise ContractError("every started body task must be awaited exactly once")
    if released_calls != set(blocked_receive_calls):
        raise ContractError("every blocked receive callback must be released exactly once")

    expected_covers: set[str] = set()
    body_positions = [
        index
        for index, operation in enumerate(action_operations)
        if operation in {"body", "await-body"}
    ]
    direct_body_positions = [
        index for index, operation in enumerate(action_operations) if operation == "body"
    ]
    json_positions = [
        index for index, operation in enumerate(action_operations) if operation == "json"
    ]
    form_positions = [
        index for index, operation in enumerate(action_operations) if operation == "form"
    ]
    stream_positions = [
        index for index, operation in enumerate(action_operations) if operation == "stream-next"
    ]
    if optional_receive_fields:
        expected_covers.add(REQUEST_CONSUMPTION_REQUIREMENTS["optional_receive_fields"])
    if len(direct_body_positions) > 1:
        expected_covers.add(REQUEST_CONSUMPTION_REQUIREMENTS["body_cache"])
    request_messages = [message for message in receive if message["type"] == "http.request"]
    if (
        body_positions
        and not blocked_receive_calls
        and len(request_messages) > 1
        and all(message.get("more_body", False) for message in request_messages[:-1])
        and not request_messages[-1].get("more_body", False)
        and all(message["type"] == "http.request" for message in receive)
    ):
        expected_covers.add(REQUEST_CONSUMPTION_REQUIREMENTS["body_chunks"])
    if (
        direct_body_positions
        and stream_positions
        and direct_body_positions[0] < stream_positions[0]
    ):
        expected_covers.add(REQUEST_CONSUMPTION_REQUIREMENTS["body_stream_replay"])
    if (
        direct_body_positions
        and stream_positions
        and stream_positions[0] < direct_body_positions[0]
    ):
        expected_covers.add(REQUEST_CONSUMPTION_REQUIREMENTS["stream_body_consumed"])
    if stream_positions and form_positions and stream_positions[0] < form_positions[0]:
        if not any(
            name.lower() == b"content-type"
            and value.lower().startswith(b"application/x-www-form-urlencoded")
            for name, value in scope_headers
        ):
            raise ContractError(
                "Request.form after stream consumption requires a URL-encoded content type"
            )
        expected_covers.add(REQUEST_CONSUMPTION_REQUIREMENTS["stream_form_consumed"])
    if stream_positions and json_positions and stream_positions[0] < json_positions[0]:
        expected_covers.add(REQUEST_CONSUMPTION_REQUIREMENTS["stream_json_consumed"])
    if len(json_positions) > 1:
        expected_covers.add(REQUEST_CONSUMPTION_REQUIREMENTS["json_cache"])
        payload = b"".join(
            base64.b64decode(message.get("body_base64", ""), validate=True)
            for message in request_messages
        )
        try:
            json.loads(payload)
        except (json.JSONDecodeError, UnicodeDecodeError):
            expected_covers.add(REQUEST_CONSUMPTION_REQUIREMENTS["json_decode_error"])
    if len(set(stream_ids)) > 1:
        expected_covers.add(REQUEST_CONSUMPTION_REQUIREMENTS["stream_interleaving"])
    if (stream_positions or direct_body_positions) and any(
        message["type"] == "http.disconnect" for message in receive
    ):
        expected_covers.add(REQUEST_CONSUMPTION_REQUIREMENTS["stream_client_disconnect"])
    if (
        0 in blocked_receive_calls
        and "start-body" in action_operations
        and "stream-next" in action_operations
        and "release-receive" in action_operations
        and "await-body" in action_operations
        and action_operations.index("start-body")
        < action_operations.index("stream-next")
        < action_operations.index("release-receive")
        < action_operations.index("await-body")
    ):
        expected_covers.add(REQUEST_CONSUMPTION_REQUIREMENTS["body_stream_overlap"])
    if set(case["covers"]) != expected_covers:
        raise ContractError(
            "Request body/stream/json covers must match the declared action and receive inputs: "
            f"expected={sorted(expected_covers)}, actual={sorted(case['covers'])}"
        )


def _request_form_limits_exceeded(body: bytes, form_options: dict[str, Any]) -> bool:
    fields = parse_qsl(body.decode("latin-1"), keep_blank_values=True)
    max_fields = form_options.get("max_fields", 1000)
    if len(fields) > max_fields:
        return True

    max_part_size = form_options.get("max_part_size", 1024 * 1024)
    for field in body.split(b"&"):
        name, separator, value = field.partition(b"=")
        if not separator:
            value = b""
        if len(name) + len(value) > max_part_size:
            return True
    return False


def _first_multipart_text_part(content_type: str, body: bytes) -> bytes | None:
    text_parts = _multipart_text_parts(content_type, body)
    return text_parts[0] if text_parts else None


def _multipart_parts(content_type: str, body: bytes) -> list[Any]:
    envelope = f"Content-Type: {content_type}\r\nMIME-Version: 1.0\r\n\r\n".encode("latin-1") + body
    message = BytesParser(policy=email_policy.default).parsebytes(envelope)
    parts = message.get_payload()
    return parts if message.is_multipart() and isinstance(parts, list) else []


def _multipart_text_parts(content_type: str, body: bytes) -> list[bytes]:
    result = []
    for part in _multipart_parts(content_type, body):
        if part.get_filename() is not None:
            continue
        payload = part.get_payload(decode=True)
        if isinstance(payload, bytes):
            result.append(payload)
    return result


def _multipart_part_counts(content_type: str, body: bytes) -> tuple[int, int]:
    fields = 0
    files = 0
    for part in _multipart_parts(content_type, body):
        if part.get_filename() is None:
            fields += 1
        else:
            files += 1
    return fields, files


def _multipart_has_missing_name(content_type: str, body: bytes) -> bool:
    return any(
        part.get("Content-Disposition") is not None
        and part.get_param("name", header="content-disposition") is None
        for part in _multipart_parts(content_type, body)
    )


def _multipart_filelike_fields_without_filename(content_type: str, body: bytes) -> list[str]:
    return [
        name
        for part in _multipart_parts(content_type, body)
        if part.get("Content-Type") is not None
        and part.get_filename() is None
        and (name := part.get_param("name", header="content-disposition")) is not None
    ]


def _multipart_count_limit_exceeded(
    content_type: str, body: bytes, form_options: dict[str, Any]
) -> bool:
    fields, files = _multipart_part_counts(content_type, body)
    return fields > form_options.get("max_fields", 1000) or files > form_options.get(
        "max_files", 1000
    )


def _multipart_count_limit_boundary(
    content_type: str, body: bytes, form_options: dict[str, Any]
) -> bool:
    fields, files = _multipart_part_counts(content_type, body)
    return ("max_fields" in form_options and fields >= form_options["max_fields"]) or (
        "max_files" in form_options and files >= form_options["max_files"]
    )


def _multipart_part_limit_exceeded(
    content_type: str, body: bytes, form_options: dict[str, Any]
) -> bool:
    max_part_size = form_options.get("max_part_size", 1024 * 1024)
    return any(len(part) > max_part_size for part in _multipart_text_parts(content_type, body))


def _multipart_boundary(content_type: str) -> bytes | None:
    match = re.search(
        r'(?:^|;)\s*boundary\s*=\s*(?:"([^"]+)"|([^;\s]+))',
        content_type,
        re.IGNORECASE,
    )
    if match is None:
        return None
    value = match.group(1) or match.group(2)
    return value.encode("latin-1")


def _first_multipart_file_data_range(content_type: str, body: bytes) -> tuple[int, int] | None:
    boundary = _multipart_boundary(content_type)
    if boundary is None:
        return None
    marker = b"--" + boundary
    part_start = body.find(marker)
    while part_start >= 0:
        header_start = body.find(b"\r\n", part_start)
        if header_start < 0:
            return None
        header_end = body.find(b"\r\n\r\n", header_start)
        if header_end < 0:
            return None
        headers = body[header_start + 2 : header_end].lower()
        if b"content-disposition:" in headers and b"filename=" in headers:
            data_start = header_end + 4
            data_end = body.find(b"\r\n" + marker, data_start)
            if data_end < 0:
                return None
            return data_start, data_end
        part_start = body.find(marker, header_end + 4)
    return None


def _expand_request_form_messages(messages: Any) -> list[dict[str, Any]]:
    if not isinstance(messages, list):
        raise ContractError("Request.form receive input must be a list")
    expanded: list[dict[str, Any]] = []
    for index, message in enumerate(messages):
        if isinstance(message, dict) and "body_segments" in message:
            _exact(
                message,
                {"type", "body_segments", "more_body"},
                f"Request.form receive[{index}]",
            )
            if message["type"] != "http.request" or type(message["more_body"]) is not bool:
                raise ContractError("segmented Request.form bodies must be HTTP request messages")
            segments = message["body_segments"]
            if not isinstance(segments, list) or not segments:
                raise ContractError("Request.form body_segments must be a non-empty array")
            body_parts = []
            body_length = 0
            for segment_index, segment in enumerate(segments):
                context = f"Request.form receive[{index}].body_segments[{segment_index}]"
                if not isinstance(segment, dict) or not isinstance(segment.get("kind"), str):
                    raise ContractError(f"{context} must declare a segment kind")
                if segment["kind"] == "literal":
                    _exact(segment, {"kind", "bytes_base64"}, context)
                    try:
                        part = base64.b64decode(segment["bytes_base64"], validate=True)
                    except (ValueError, TypeError) as exc:
                        raise ContractError(f"{context}.bytes_base64 is invalid") from exc
                elif segment["kind"] == "repeat":
                    repeat = _exact(
                        segment,
                        {"kind", "pattern_base64", "count"},
                        context,
                    )
                    try:
                        pattern = base64.b64decode(repeat["pattern_base64"], validate=True)
                    except (ValueError, TypeError) as exc:
                        raise ContractError(f"{context}.pattern_base64 is invalid") from exc
                    count = repeat["count"]
                    if not pattern or type(count) is not int or count < 1:
                        raise ContractError(
                            f"{context} repeat must have a non-empty pattern and positive count"
                        )
                    part = pattern * count
                elif segment["kind"] == "indexed_repeat":
                    repeat = _exact(
                        segment,
                        {"kind", "template_base64", "count"},
                        context,
                    )
                    try:
                        template = base64.b64decode(repeat["template_base64"], validate=True)
                    except (ValueError, TypeError) as exc:
                        raise ContractError(f"{context}.template_base64 is invalid") from exc
                    count = repeat["count"]
                    placeholder = b"{{index}}"
                    if (
                        not template
                        or placeholder not in template
                        or type(count) is not int
                        or not 1 <= count <= 20000
                        or len(template) * count > 8 * 1024 * 1024
                    ):
                        raise ContractError(
                            f"{context} indexed repeat requires an index template and count from 1 through 20000"
                        )
                    part = b"".join(
                        template.replace(placeholder, str(item_index).encode("ascii"))
                        for item_index in range(count)
                    )
                else:
                    raise ContractError(
                        f"{context}.kind must be literal, repeat, or indexed_repeat"
                    )
                body_length += len(part)
                if body_length > 8 * 1024 * 1024:
                    raise ContractError(
                        f"Request.form receive[{index}].body_segments must expand to 1 through 8 MiB"
                    )
                body_parts.append(part)
            if body_length == 0:
                raise ContractError(
                    f"Request.form receive[{index}].body_segments must expand to 1 through 8 MiB"
                )
            expanded.append(
                {
                    "type": message["type"],
                    "body_base64": base64.b64encode(b"".join(body_parts)).decode("ascii"),
                    "more_body": message["more_body"],
                }
            )
            continue
        if not isinstance(message, dict) or "body_repeat" not in message:
            expanded.append(message)
            continue
        _exact(
            message,
            {"type", "body_repeat", "more_body"},
            f"Request.form receive[{index}]",
        )
        if message["type"] != "http.request" or type(message["more_body"]) is not bool:
            raise ContractError("repeated Request.form bodies must be HTTP request messages")
        repeat = _exact(
            message["body_repeat"],
            {"pattern_base64", "count"},
            f"Request.form receive[{index}].body_repeat",
        )
        try:
            pattern = base64.b64decode(repeat["pattern_base64"], validate=True)
        except (ValueError, TypeError) as exc:
            raise ContractError(
                f"Request.form receive[{index}].body_repeat.pattern_base64 is invalid"
            ) from exc
        count = repeat["count"]
        if (
            not pattern
            or type(count) is not int
            or count < 1
            or len(pattern) * count > 8 * 1024 * 1024
        ):
            raise ContractError(
                f"Request.form receive[{index}].body_repeat must expand to 1 through 8 MiB"
            )
        expanded.append(
            {
                "type": message["type"],
                "body_base64": base64.b64encode(pattern * count).decode("ascii"),
                "more_body": message["more_body"],
            }
        )
    return expanded


def _validate_request_form_case(case: dict[str, Any]) -> None:
    if case["target_profiles"] != ["python-package-cpython312"]:
        raise ContractError("Request.form parity currently targets the Python package profile")
    if case["assets"] != [] or case["observations"] != ["form"]:
        raise ContractError("Request.form cases must select one form observation without assets")
    messages = _expand_request_form_messages(case["receive"])
    _validate_dispatch_stimulus(
        {
            "scope": case["scope"],
            "receive": messages,
            "send": {"kind": "capture-asgi-send"},
        },
        request_dispatch=True,
        allow_headers=True,
        allow_scope_app=True,
    )
    if case["scope"]["type"] != "http":
        raise ContractError("Request.form requires an HTTP scope")

    if (
        not messages
        or any(not message["more_body"] for message in messages[:-1])
        or messages[-1]["more_body"]
    ):
        raise ContractError(
            "Request.form receive input must contain body chunks ending with one final request message"
        )

    probe_keys = case["form_probe_keys"]
    if not isinstance(probe_keys, list) or any(not isinstance(key, str) for key in probe_keys):
        raise ContractError("Request.form form_probe_keys must be an array of strings")

    form_file_probe_keys = case.get("form_file_probe_keys", [])
    if (
        not isinstance(form_file_probe_keys, list)
        or any(not isinstance(key, str) for key in form_file_probe_keys)
        or len(form_file_probe_keys) != len(set(form_file_probe_keys))
        or not set(form_file_probe_keys) <= set(probe_keys)
    ):
        raise ContractError("Request.form form_file_probe_keys must be unique form_probe_keys")
    form_type_probe_keys = case.get("form_type_probe_keys", [])
    if (
        not isinstance(form_type_probe_keys, list)
        or any(not isinstance(key, str) for key in form_type_probe_keys)
        or len(form_type_probe_keys) != len(set(form_type_probe_keys))
        or not set(form_type_probe_keys) <= set(probe_keys)
    ):
        raise ContractError("Request.form form_type_probe_keys must be unique form_probe_keys")
    form_file_probe_all = case.get("form_file_probe_all", False)
    if type(form_file_probe_all) is not bool:
        raise ContractError("Request.form form_file_probe_all must be a boolean")
    if form_file_probe_all and form_file_probe_keys:
        raise ContractError(
            "Request.form all-file probes cannot be combined with named file probes"
        )
    has_file_probes = bool(form_file_probe_keys) or form_file_probe_all
    if has_file_probes and type(case.get("form_file_read_size")) is not int:
        raise ContractError("Request.form file probes require an integer form_file_read_size")
    if has_file_probes and case["form_file_read_size"] < -1:
        raise ContractError("Request.form form_file_read_size must be -1 or non-negative")
    if "form_file_read_size" in case and not has_file_probes:
        raise ContractError("Request.form form_file_read_size requires file probes")
    if "form_file_write_base64" in case:
        if not has_file_probes or not isinstance(case["form_file_write_base64"], str):
            raise ContractError(
                "Request.form form_file_write_base64 requires file probes and a base64 string"
            )
        try:
            base64.b64decode(case["form_file_write_base64"], validate=True)
        except (ValueError, base64.binascii.Error) as exc:
            raise ContractError("Request.form form_file_write_base64 must be valid base64") from exc
    if "form_close" in case and type(case["form_close"]) is not bool:
        raise ContractError("Request.form form_close must be a boolean")
    if case.get("form_close", False) and not has_file_probes and case.get("form_app") is None:
        raise ContractError("Request.form form_close without file probes requires an ASGI app")
    if has_file_probes and not (
        case.get("form_close", False) or case.get("form_access", "await") == "context-manager"
    ):
        raise ContractError(
            "Request.form file probes must exercise FormData's file-close lifecycle"
        )
    if "form_io_trace" in case and type(case["form_io_trace"]) is not bool:
        raise ContractError("Request.form form_io_trace must be a boolean")
    receive_error = case.get("receive_error")
    file_write_error = case.get("file_write_error")
    if receive_error is not None and file_write_error is not None:
        raise ContractError("Request.form cannot select receive and file-write errors together")
    if receive_error is not None:
        _exact(receive_error, {"at_call", "message"}, "Request.form receive_error")
        if (
            type(receive_error["at_call"]) is not int
            or receive_error["at_call"] < 1
            or receive_error["at_call"] >= len(messages)
            or not isinstance(receive_error["message"], str)
            or not receive_error["message"]
            or not case.get("form_io_trace", False)
        ):
            raise ContractError(
                "Request.form receive_error must fail after a traced multipart chunk"
            )
    if file_write_error is not None:
        _exact(file_write_error, {"at_call", "message"}, "Request.form file_write_error")
        if (
            type(file_write_error["at_call"]) is not int
            or file_write_error["at_call"] != 0
            or not isinstance(file_write_error["message"], str)
            or not file_write_error["message"]
            or not case.get("form_io_trace", False)
        ):
            raise ContractError("Request.form file_write_error must fail the first traced write")

    form_options = case.get("form_options", {})
    if not isinstance(form_options, dict) or set(form_options) - {
        "max_files",
        "max_fields",
        "max_part_size",
    }:
        raise ContractError("Request.form form_options contains unsupported public arguments")
    for name, value in form_options.items():
        if name == "max_part_size":
            if type(value) is not int:
                raise ContractError("Request.form max_part_size must be an integer")
        elif type(value) not in (int, float) or not math.isfinite(value):
            raise ContractError(f"Request.form {name} must be a finite number")

    form_access = case.get("form_access", "await")
    if form_access not in {"await", "context-manager"}:
        raise ContractError("Request.form form_access must be await or context-manager")
    form_app = case.get("form_app")
    if form_app is not None and form_app not in {"direct", "mount"}:
        raise ContractError("Request.form form_app must be direct or mount")
    if form_app is not None and form_access != "await":
        raise ContractError("Request.form ASGI application cases use await access")
    if "form_read_body" in case and type(case["form_read_body"]) is not bool:
        raise ContractError("Request.form form_read_body must be a boolean")
    if case.get("form_read_body", False) and form_app is None:
        raise ContractError("Request.form form_read_body requires an ASGI application case")

    content_type = None
    content_type_header = None
    for encoded_name, encoded_value in case["scope"]["headers_base64_pairs"]:
        name = base64.b64decode(encoded_name, validate=True).decode("latin-1").lower()
        if name == "content-type":
            content_type_header = base64.b64decode(encoded_value, validate=True).decode("latin-1")
            content_type = content_type_header.split(";", 1)[0].strip().lower().encode("latin-1")
            break
    body = b"".join(base64.b64decode(message["body_base64"], validate=True) for message in messages)
    if (
        case.get("form_close", False)
        and not has_file_probes
        and (
            content_type != b"multipart/form-data"
            or _first_multipart_file_data_range(content_type_header or "", body) is None
        )
    ):
        raise ContractError("Request.form form_close without file probes requires a multipart file")
    if content_type == b"application/x-www-form-urlencoded" and body:
        if _request_form_limits_exceeded(body, form_options):
            expected_covers = ["starlette.request.form.parser-limits"]
        else:
            expected_covers = [
                "starlette.request.form.urlencoded-fields",
                "starlette.datastructures.FormData.multidict-lookups",
            ]
            if form_access == "context-manager":
                expected_covers.append("starlette.request.form.context-manager-lifecycle")
    elif (
        content_type == b"multipart/form-data"
        and body
        and (
            _multipart_boundary(content_type_header or "") is None
            or _multipart_has_missing_name(content_type_header or "", body)
        )
    ):
        if form_options or has_file_probes or form_access != "await":
            raise ContractError("multipart framing-error cases only observe the parser error")
        expected_covers = ["starlette.request.form.multipart-input-errors"]
    elif (
        content_type == b"multipart/form-data"
        and body
        and _multipart_part_limit_exceeded(content_type_header or "", body, form_options)
    ):
        if set(form_options) - {"max_part_size"}:
            raise ContractError("multipart part-limit cases select max_part_size alone")
        if len(messages) < 2 or has_file_probes or form_access != "await":
            raise ContractError(
                "multipart part-limit cases must stop before a later receive and cannot probe files"
            )
        oversized_parts = [
            part
            for part in _multipart_text_parts(content_type_header or "", body)
            if len(part) > form_options.get("max_part_size", 1024 * 1024)
        ]
        first_chunk = base64.b64decode(messages[0]["body_base64"], validate=True)
        if (
            not oversized_parts
            or not any(part and part in first_chunk for part in oversized_parts)
            or any(
                base64.b64decode(message["body_base64"], validate=True) == b""
                for message in messages
            )
        ):
            raise ContractError(
                "multipart part-limit input must put oversized text bytes in the first chunk"
            )
        expected_covers = ["starlette.request.form.multipart-incremental-part-limits"]
    elif (
        content_type == b"multipart/form-data"
        and body
        and _multipart_count_limit_exceeded(content_type_header or "", body, form_options)
    ):
        if set(form_options) - {"max_files", "max_fields"}:
            raise ContractError("multipart count-limit cases select max_files or max_fields")
        if has_file_probes or form_access != "await":
            raise ContractError("multipart count-limit errors cannot inspect or close form values")
        expected_covers = ["starlette.request.form.multipart-count-limits"]
    elif content_type == b"multipart/form-data" and body:
        if not case["scope"]["headers_base64_pairs"]:
            raise ContractError("Request.form multipart cases require Content-Type")
        if file_write_error is not None:
            if form_options or has_file_probes or form_access != "await":
                raise ContractError(
                    "Request.form file-write-error cleanup cases cannot include options or probes"
                )
            file_data_range = _first_multipart_file_data_range(content_type_header or "", body)
            first_chunk = base64.b64decode(messages[0]["body_base64"], validate=True)
            if (
                file_data_range is None
                or file_data_range[1] <= file_data_range[0]
                or len(first_chunk) <= file_data_range[0]
                or not messages[0]["more_body"]
            ):
                raise ContractError(
                    "Request.form file-write-error cases must attempt a write before a later receive"
                )
            expected_covers = ["starlette.request.form.multipart-error-file-cleanup"]
        elif receive_error is not None:
            if form_options or has_file_probes or form_access != "await":
                raise ContractError(
                    "Request.form receive-error cleanup cases cannot include form options or probes"
                )
            file_data_range = _first_multipart_file_data_range(content_type_header or "", body)
            prior_body = b"".join(
                base64.b64decode(message["body_base64"], validate=True)
                for message in messages[: receive_error["at_call"]]
            )
            if (
                file_data_range is None
                or len(prior_body) <= file_data_range[0]
                or not all(message["more_body"] for message in messages[: receive_error["at_call"]])
            ):
                raise ContractError(
                    "Request.form receive-error cleanup cases must fail after file bytes arrive"
                )
            expected_covers = ["starlette.request.form.multipart-error-file-cleanup"]
        else:
            if set(form_options) - {"max_fields", "max_files"}:
                raise ContractError("multipart success cases select only file/field limits")
            if form_options and not _multipart_count_limit_boundary(
                content_type_header or "", body, form_options
            ):
                raise ContractError("multipart count-limit options must reach the supplied limit")
            expected_covers = [
                "starlette.request.form.multipart-form-data",
                "starlette.datastructures.FormData.multidict-lookups",
            ]
            filelike_fields_without_filename = _multipart_filelike_fields_without_filename(
                content_type_header or "", body
            )
            if filelike_fields_without_filename:
                if not set(filelike_fields_without_filename) <= set(form_type_probe_keys):
                    raise ContractError(
                        "multipart parts with Content-Type but no filename require a value-type probe"
                    )
                expected_covers.append("starlette.request.form.multipart-no-filename")
            if form_options:
                expected_covers.append("starlette.request.form.multipart-count-limits")
            if re.search(r"(?:^|;)\s*charset\s*=", content_type_header or "", re.IGNORECASE) or any(
                value > 127 for value in body
            ):
                expected_covers.append("starlette.request.form.multipart-charset-decoding")
            if has_file_probes:
                expected_covers.extend(
                    [
                        "starlette.datastructures.FormData.file-values",
                        "starlette.datastructures.UploadFile.file-operations",
                    ]
                )
            if case.get("form_close", False) or form_access == "context-manager":
                expected_covers.append("starlette.datastructures.FormData.close")
            if form_access == "context-manager":
                expected_covers.append("starlette.request.form.context-manager-lifecycle")
            if case.get("form_io_trace", False):
                file_data_range = _first_multipart_file_data_range(content_type_header or "", body)
                first_chunk_length = len(
                    base64.b64decode(messages[0]["body_base64"], validate=True)
                )
                if (
                    len(messages) < 2
                    or file_data_range is None
                    or not file_data_range[0] < first_chunk_length < file_data_range[1]
                ):
                    raise ContractError(
                        "Request.form file streaming traces must split file bytes across receives"
                    )
                expected_covers.append("starlette.request.form.multipart-file-streaming")
            if any("body_repeat" in message for message in case["receive"]):
                file_data_range = _first_multipart_file_data_range(content_type_header or "", body)
                if (
                    not case.get("form_io_trace", False)
                    or file_data_range is None
                    or file_data_range[1] - file_data_range[0] <= 1024 * 1024
                    or has_file_probes
                    or form_app is None
                ):
                    raise ContractError(
                        "Request.form repeated-body cases must trace a file larger than the spool threshold"
                    )
                expected_covers.append(
                    "starlette.request.form.multipart-large-file-rollover-worker"
                )
    elif content_type is None and not body:
        expected_covers = ["starlette.request.form.empty"]
    else:
        raise ContractError(
            "Request.form supports non-empty URL-encoded forms, bounded valid multipart forms, or an empty body without Content-Type"
        )
    if case["covers"] != expected_covers:
        raise ContractError("Request.form coverage must match its media type and body input")


def _validate_status_symbols_case(case: dict[str, Any]) -> None:
    if case["target_profiles"] != ["python-package-cpython312"]:
        raise ContractError("status module parity currently targets the Python package profile")
    if case["assets"] != []:
        raise ContractError("status module parity does not use external assets")
    observations = [
        "public_names",
        "public_values",
        "deprecated_values_and_warnings",
        "directory",
        "missing_attribute",
    ]
    if case["observations"] != observations:
        raise ContractError("status module parity must select every declared observation")
    public_names = case["public_names"]
    deprecated_names = case["deprecated_names"]
    missing_names = case["missing_names"]
    for label, names in (
        ("public_names", public_names),
        ("deprecated_names", deprecated_names),
        ("missing_names", missing_names),
    ):
        if (
            not isinstance(names, list)
            or any(not isinstance(name, str) or not name.isidentifier() for name in names)
            or len(names) != len(set(names))
        ):
            raise ContractError(f"status {label} must be a unique array of identifiers")
    if not public_names:
        raise ContractError("status module parity must request public names")
    if type(case["observe_directory"]) is not bool:
        raise ContractError("status observe_directory must be boolean")
    exercised = {"starlette.status.module-symbol-sequence.public-integer-constants"}
    if deprecated_names:
        exercised.add("starlette.status.module-symbol-sequence.deprecated-aliases")
    if missing_names:
        exercised.add("starlette.status.module-symbol-sequence.unknown-attribute")
    if case["observe_directory"]:
        exercised.add("starlette.status.module-symbol-sequence.directory-listing")
    if set(case["covers"]) != exercised:
        raise ContractError("status module coverage must match the requested input behaviors")


def _wsgi_build_environ_semantic_coverage(case: dict[str, Any]) -> set[str]:
    scope = case["scope"]
    probes = {probe["key"]: probe["kind"] for probe in case["environ_probes"]}
    covered: set[str] = set()
    core_fields = {
        "REQUEST_METHOD",
        "SCRIPT_NAME",
        "PATH_INFO",
        "QUERY_STRING",
        "SERVER_PROTOCOL",
        "wsgi.url_scheme",
        "wsgi.version",
    }
    if core_fields <= set(probes):
        covered.add(WSGI_BOUNDARY_REQUIREMENTS["scope-projection"])
    headers = [
        (
            base64.b64decode(name, validate=True).decode("latin-1").lower(),
            base64.b64decode(value, validate=True).decode("latin-1"),
        )
        for name, value in scope.get("headers_base64_pairs", [])
    ]
    if headers and any(
        key.startswith("HTTP_") or key in {"CONTENT_LENGTH", "CONTENT_TYPE"} for key in probes
    ):
        covered.add(WSGI_BOUNDARY_REQUIREMENTS["header-projection"])
    header_names = [name for name, _ in headers]
    if len(header_names) != len(set(header_names)) and any(
        key.startswith("HTTP_") for key in probes
    ):
        covered.add(WSGI_BOUNDARY_REQUIREMENTS["duplicate-header-joining"])
    path = scope["path"]
    root_path = scope.get("root_path", "")
    if root_path and path.startswith(root_path) and {"SCRIPT_NAME", "PATH_INFO"} <= set(probes):
        covered.add(WSGI_BOUNDARY_REQUIREMENTS["root-path-stripping"])
    if probes.get("wsgi.input") == "read-bytes":
        covered.add(WSGI_BOUNDARY_REQUIREMENTS["input-stream"])
    if any(ord(character) > 127 for character in path + root_path) and {
        "SCRIPT_NAME",
        "PATH_INFO",
    } <= set(probes):
        covered.add(WSGI_BOUNDARY_REQUIREMENTS["latin1-path-encoding"])
    if not scope.get("server") and {"SERVER_NAME", "SERVER_PORT"} <= set(probes):
        covered.add(WSGI_BOUNDARY_REQUIREMENTS["server-default"])
    if "scheme" not in scope and "wsgi.url_scheme" in probes:
        covered.add(WSGI_BOUNDARY_REQUIREMENTS["scheme-default"])
    if "client" not in scope and probes.get("REMOTE_ADDR") == "presence":
        covered.add(WSGI_BOUNDARY_REQUIREMENTS["client-omission"])
    return covered


def _validate_wsgi_boundary_case(case: dict[str, Any]) -> None:
    if case["target_profiles"] != ["python-package-cpython312"]:
        raise ContractError("WSGI helper and import parity cases select the Python package profile")
    if case["assets"] != []:
        raise ContractError("WSGI helper and import parity cases do not use external assets")
    operation = (case["surface"], case["operation"])
    if operation == WSGI_BUILD_ENVIRON_OPERATION:
        if case["observations"] != ["environ-results"]:
            raise ContractError("build_environ cases must select environ-results")
        scope = _exact(
            case["scope"],
            {
                "type",
                "http_version",
                "method",
                "scheme",
                "path",
                "root_path",
                "query_string_base64",
                "headers_base64_pairs",
                "client",
                "server",
            }
            & set(case["scope"])
            | {"http_version", "method", "path", "query_string_base64"},
            "build_environ scope",
        )
        if "type" in scope and scope["type"] != "http":
            raise ContractError("build_environ scope type must be HTTP when supplied")
        for name in ("http_version", "method", "path"):
            _string(scope[name], f"build_environ scope.{name}")
        if "scheme" in scope:
            _string(scope["scheme"], "build_environ scope.scheme")
        if "root_path" in scope:
            _string(scope["root_path"], "build_environ scope.root_path")
        try:
            base64.b64decode(scope["query_string_base64"], validate=True).decode("ascii")
            base64.b64decode(case["body_base64"], validate=True)
        except (ValueError, TypeError, UnicodeDecodeError) as exc:
            raise ContractError(
                "build_environ body and query must be valid ASCII/base64 input"
            ) from exc
        raw_headers = scope.get("headers_base64_pairs", [])
        if not isinstance(raw_headers, list):
            raise ContractError("build_environ scope headers must be an array")
        for index, pair in enumerate(raw_headers):
            if (
                not isinstance(pair, list)
                or len(pair) != 2
                or any(not isinstance(value, str) for value in pair)
            ):
                raise ContractError(f"build_environ scope header[{index}] must be a base64 pair")
            try:
                base64.b64decode(pair[0], validate=True)
                base64.b64decode(pair[1], validate=True)
            except (ValueError, TypeError) as exc:
                raise ContractError(
                    f"build_environ scope header[{index}] is invalid base64"
                ) from exc
        for name in ("server", "client"):
            value = scope.get(name)
            if value is not None and (
                not isinstance(value, list)
                or len(value) != 2
                or not isinstance(value[0], str)
                or type(value[1]) is not int
            ):
                raise ContractError(f"build_environ scope.{name} must be null or a two-item tuple")
        probes = case["environ_probes"]
        if not isinstance(probes, list) or not probes:
            raise ContractError("build_environ requires at least one environ probe")
        seen_keys: set[str] = set()
        for index, raw_probe in enumerate(probes):
            probe = _exact(raw_probe, {"key", "kind"}, f"build_environ probe[{index}]")
            key = _string(probe["key"], f"build_environ probe[{index}].key")
            if key in seen_keys:
                raise ContractError("build_environ probe keys must be unique")
            seen_keys.add(key)
            if probe["kind"] not in {"value", "read-bytes", "is-stdout", "presence"}:
                raise ContractError(f"build_environ probe[{index}].kind is unsupported")
            if probe["kind"] == "read-bytes" and key != "wsgi.input":
                raise ContractError("only wsgi.input probes may read bytes")
            if probe["kind"] == "is-stdout" and key != "wsgi.errors":
                raise ContractError("only wsgi.errors probes may compare stdout identity")
            if key == "wsgi.input" and probe["kind"] != "read-bytes":
                raise ContractError("wsgi.input must use the read-bytes probe")
            if key == "wsgi.errors" and probe["kind"] != "is-stdout":
                raise ContractError("wsgi.errors must use the is-stdout probe")
        exercised = _wsgi_build_environ_semantic_coverage(case)
    elif operation == WSGI_MODULE_IMPORT_OPERATION:
        if case["observations"] != ["import-results"]:
            raise ContractError("WSGI module import must select import-results")
        if case["module_name"] != "starlette.middleware.wsgi":
            raise ContractError("WSGI import input must name the declared compatibility module")
        exercised = {WSGI_BOUNDARY_REQUIREMENTS["module-import-warning"]}
    else:
        raise ContractError("unsupported WSGI boundary operation")
    if set(case["covers"]) != exercised:
        raise ContractError(
            "WSGI boundary covers must match the scope probes or module import input: "
            f"expected={sorted(exercised)}, actual={sorted(case['covers'])}"
        )


def _validate_config_case(case: dict[str, Any]) -> None:
    if case["target_profiles"] != ["python-package-cpython312"]:
        raise ContractError("configuration parity currently targets the Python package profile")
    if case["assets"] != []:
        raise ContractError("configuration parity does not use external assets")

    operation = (case["surface"], case["operation"])
    if operation == ("starlette.config.Config", "value-resolution"):
        if case["observations"] != ["lookup-results"]:
            raise ContractError("Config value resolution must select lookup-results")
        config = _exact(case["config"], {"env_prefix", "environ", "env_file_lines"}, "Config input")
        if not isinstance(config["env_prefix"], str):
            raise ContractError("Config env_prefix must be a string")
        if "encoding" in case:
            _string(case["encoding"], "Config encoding")
        environ = config["environ"]
        if not isinstance(environ, dict) or any(
            not isinstance(key, str) or not isinstance(value, str) for key, value in environ.items()
        ):
            raise ContractError("Config environ must be a string mapping")
        lines = config["env_file_lines"]
        if not isinstance(lines, list) or any(not isinstance(line, str) for line in lines):
            raise ContractError("Config env_file_lines must be a string array")
        lookups = case["lookups"]
        if not isinstance(lookups, list) or not lookups:
            raise ContractError("Config lookups must be a non-empty array")
        file_values = {}
        has_embedded_equals = False
        for line in lines:
            stripped = line.strip()
            if "=" in stripped and not stripped.startswith("#"):
                key, value = stripped.split("=", 1)
                file_values[key.strip()] = value.strip().strip("\"'")
                has_embedded_equals = has_embedded_equals or "=" in value
        selected: set[str] = set()
        if has_embedded_equals:
            selected.add("starlette.config.Config.env-file-first-equals")
        if "encoding" in case:
            selected.add("starlette.config.Config.explicit-encoding")
        for index, raw in enumerate(lookups):
            if not isinstance(raw, dict):
                raise ContractError(f"Config lookups[{index}] must be an object")
            lookup_keys = {"key"}
            lookup_keys.update(field for field in ("cast", "default", "inspect") if field in raw)
            lookup = _exact(raw, lookup_keys, f"Config lookups[{index}]")
            key = _string(lookup["key"], f"Config lookups[{index}].key")
            cast = lookup.get("cast")
            public_class: str | None = None
            if isinstance(cast, str):
                if cast not in {"str", "bool", "int"}:
                    raise ContractError(f"Config lookups[{index}].cast is unsupported")
                cast_operation = cast
            elif isinstance(cast, dict):
                kind = cast.get("kind")
                if kind == "python-callable":
                    cast_spec = _exact(
                        cast,
                        {"kind", "name", "converter"},
                        f"Config lookups[{index}].cast",
                    )
                    name = _string(cast_spec["name"], f"Config lookups[{index}].cast.name")
                    if not name.isidentifier() or keyword.iskeyword(name):
                        raise ContractError(
                            f"Config lookups[{index}].cast.name must be a Python identifier"
                        )
                    cast_operation = _string(
                        cast_spec["converter"], f"Config lookups[{index}].cast.converter"
                    )
                    if cast_operation not in {"str", "bool", "int"}:
                        raise ContractError(
                            f"Config lookups[{index}].cast.converter is unsupported"
                        )
                elif kind == "starlette-public-class":
                    cast_spec = _exact(
                        cast,
                        {"kind", "symbol"},
                        f"Config lookups[{index}].cast",
                    )
                    symbol = _string(cast_spec["symbol"], f"Config lookups[{index}].cast.symbol")
                    if symbol not in {
                        "starlette.datastructures.URL",
                        "starlette.datastructures.Secret",
                    }:
                        raise ContractError(
                            f"Config lookups[{index}].cast.symbol is unsupported: {symbol}"
                        )
                    public_class = symbol.rsplit(".", maxsplit=1)[-1]
                    cast_operation = public_class
                    selected.add("starlette.config.Config.custom-cast-callback-boundary")
                    selected.add(
                        "starlette.config.Config.cast-url-class"
                        if public_class == "URL"
                        else "starlette.config.Config.cast-secret-class"
                    )
                else:
                    raise ContractError(f"Config lookups[{index}].cast.kind is unsupported: {kind}")
                if kind == "python-callable":
                    selected.add("starlette.config.Config.custom-cast-callback-boundary")
            elif cast is None:
                cast_operation = None
            else:
                raise ContractError(f"Config lookups[{index}].cast is unsupported")
            inspect = lookup.get("inspect", [])
            if (
                not isinstance(inspect, list)
                or any(not isinstance(selector, str) for selector in inspect)
                or len(inspect) != len(set(inspect))
            ):
                raise ContractError(
                    f"Config lookups[{index}].inspect must be a unique string array"
                )
            inspectable = {
                "URL": {
                    "scheme",
                    "netloc",
                    "path",
                    "query",
                    "fragment",
                    "username",
                    "password",
                    "hostname",
                    "port",
                    "is_secure",
                },
                "Secret": {"repr", "truthiness"},
            }
            if inspect and (public_class is None or not set(inspect) <= inspectable[public_class]):
                raise ContractError(
                    f"Config lookups[{index}].inspect selectors do not match its public cast class"
                )
            prefixed = config["env_prefix"] + key
            has_default = "default" in lookup
            if cast is not None and has_default and lookup["default"] is None:
                selected.add("starlette.config.Config.cast-skips-null-default")
            if (
                config["env_prefix"]
                and key in environ
                and prefixed not in environ
                and prefixed not in file_values
            ):
                selected.add("starlette.config.Config.prefix-ignores-unprefixed-value")
            if prefixed in environ and prefixed in file_values:
                selected.add("starlette.config.Config.environment-precedence")
            if prefixed in file_values:
                selected.add("starlette.config.Config.file-precedence")
            if has_default:
                selected.add("starlette.config.Config.default-values")
            elif prefixed not in environ and prefixed not in file_values:
                selected.add("starlette.config.Config.missing-key-error")
            if config["env_prefix"]:
                selected.add("starlette.config.Config.env-prefix")
            raw_value = environ.get(prefixed, file_values.get(prefixed))
            cast_value = raw_value if raw_value is not None else lookup.get("default")
            if cast_operation == "bool" and isinstance(cast_value, str):
                selected.add("starlette.config.Config.bool-cast")
                if cast_value.lower() not in {"true", "1", "false", "0"}:
                    selected.add("starlette.config.Config.invalid-bool-error")
            if cast_operation == "int" and cast_value is not None:
                try:
                    int(cast_value)
                except ValueError:
                    selected.add("starlette.config.Config.cast-error")
        if set(case["covers"]) != selected:
            raise ContractError("Config value-resolution coverage must match its input lookups")
        return

    if operation == ("starlette.config.Config", "constructor-warning"):
        if case["observations"] != ["warning-results"]:
            raise ContractError("Config constructor must select warning-results")
        env_file = _exact(case["env_file"], {"kind", "file_name"}, "Config env_file")
        if env_file["kind"] != "missing-temporary-file":
            raise ContractError("Config warning input must identify a missing temporary file")
        _string(env_file["file_name"], "Config env_file.file_name")
        if case["covers"] != ["starlette.config.Config.missing-file-warning"]:
            raise ContractError("Config constructor coverage must match its warning input")
        return

    is_module_environ = operation == ("starlette.config", "environ")
    if operation != ("starlette.config.Environ", "mapping-sequence") and not is_module_environ:
        raise ContractError("configuration case uses an undeclared operation")
    if case["observations"] != ["action-results"]:
        raise ContractError("Environ inputs must select action-results")
    initial = case["initial_environ"]
    if not isinstance(initial, dict) or any(
        not isinstance(key, str) or not isinstance(value, str) for key, value in initial.items()
    ):
        raise ContractError("Environ initial_environ must be a string mapping")
    mapping_source = (
        "module-global" if is_module_environ else case.get("mapping_source", "explicit")
    )
    if mapping_source not in {"explicit", "os-environ", "module-global"}:
        raise ContractError("Environ mapping_source must be explicit or os-environ")
    actions = case["actions"]
    if not isinstance(actions, list) or not actions:
        raise ContractError("Environ actions must be a non-empty array")
    selected = set()
    if mapping_source == "os-environ":
        selected.add("starlette.config.Environ.default-os-environ-mapping")
    module_global_mutations_before_read: set[str] = set()
    module_config_reads: dict[str, str] = {}
    module_late_mutations: dict[str, set[str]] = {}
    read_keys: set[str] = set()
    present_keys = set(initial)
    process_comparisons: set[str] = set()
    for index, raw in enumerate(actions):
        context = f"Environ actions[{index}]"
        if not isinstance(raw, dict) or not isinstance(raw.get("action"), str):
            raise ContractError(f"{context} must be an action object")
        action = raw["action"]
        if action in {"set", "delete", "get", "contains"}:
            expected = {"action", "key", "value"} if action == "set" else {"action", "key"}
            item = _exact(raw, expected, context)
            key = _string(item["key"], f"{context}.key")
            if action == "set":
                if not isinstance(item["value"], str):
                    raise ContractError(f"{context}.value must be a string")
                if is_module_environ and key not in read_keys:
                    module_global_mutations_before_read.add(action)
                    present_keys.add(key)
                elif is_module_environ:
                    module_late_mutations.setdefault(key, set()).add(action)
                elif key not in read_keys:
                    selected.add("starlette.config.Environ.set-before-read")
                    present_keys.add(key)
                else:
                    selected.add("starlette.config.Environ.read-freezes-set")
            elif action == "delete":
                if is_module_environ and key not in read_keys:
                    module_global_mutations_before_read.add(action)
                    present_keys.discard(key)
                elif is_module_environ:
                    module_late_mutations.setdefault(key, set()).add(action)
                elif key not in read_keys:
                    selected.add("starlette.config.Environ.delete-before-read")
                    present_keys.discard(key)
                else:
                    selected.add("starlette.config.Environ.read-freezes-delete")
            else:
                if action == "get":
                    selected.add("starlette.config.Environ.read-value")
                elif key not in present_keys:
                    selected.add("starlette.config.Environ.missing-key-membership-freezes-key")
                read_keys.add(key)
        elif action == "config-get":
            if not is_module_environ:
                raise ContractError(
                    "Config reads are only allowed through the module environ operation"
                )
            item = _exact(
                raw,
                {"action", "key", "default"} if "default" in raw else {"action", "key"},
                context,
            )
            key = _string(item["key"], f"{context}.key")
            if key in present_keys:
                module_config_reads[key] = "present"
            elif "default" in item:
                _string(item["default"], f"{context}.default")
                module_config_reads[key] = "missing-default"
            else:
                raise ContractError(
                    "module environ Config reads require a present key or input default"
                )
            read_keys.add(key)
        elif action == "iterate":
            item = _exact(
                raw,
                {"action", "compare_to"} if "compare_to" in raw else {"action"},
                context,
            )
            if mapping_source in {"os-environ", "module-global"}:
                if item.get("compare_to") != "underlying-os-environ":
                    raise ContractError(f"{context} must compare with underlying os.environ")
                process_comparisons.add(action)
            elif "compare_to" in item:
                raise ContractError(f"{context}.compare_to requires os-environ mapping_source")
            selected.add("starlette.config.Environ.iteration")
        elif action == "length":
            item = _exact(
                raw,
                {"action", "compare_to"} if "compare_to" in raw else {"action"},
                context,
            )
            if mapping_source in {"os-environ", "module-global"}:
                if item.get("compare_to") != "underlying-os-environ":
                    raise ContractError(f"{context} must compare with underlying os.environ")
                process_comparisons.add(action)
            elif "compare_to" in item:
                raise ContractError(f"{context}.compare_to requires os-environ mapping_source")
            selected.add("starlette.config.Environ.length")
        else:
            raise ContractError(f"{context}.action is unsupported")
    if mapping_source in {"os-environ", "module-global"} and process_comparisons != {
        "iterate",
        "length",
    }:
        raise ContractError("Environ os-environ mapping must observe iteration and length equality")
    if is_module_environ:
        if process_comparisons == {"iterate", "length"}:
            selected.add("starlette.config.environ.module-global-os-environ")
        if {"set", "delete"} <= module_global_mutations_before_read:
            selected.add("starlette.config.environ.mutable-before-read")
        for key, read_kind in module_config_reads.items():
            if {"set", "delete"} <= module_late_mutations.get(key, set()):
                selected.add(
                    "starlette.config.environ.config-read-freezes-present-key-mutations"
                    if read_kind == "present"
                    else "starlette.config.environ.config-default-freezes-absent-key"
                )
    if set(case["covers"]) != selected:
        raise ContractError("Environ mapping coverage must match its action sequence")


def _validate_schema_route_input(
    route: Any, context: str, *, allow_schema_endpoint: bool = False
) -> tuple[set[str], bool]:
    if not isinstance(route, dict) or not isinstance(route.get("kind"), str):
        raise ContractError(f"{context} must be a route object")
    kind = route["kind"]
    if kind in {"route", "websocket-route"}:
        allowed = {"kind", "path", "endpoint"}
        if kind == "route":
            allowed |= {key for key in ("methods", "include_in_schema") if key in route}
        item = _exact(route, allowed, context)
        _string(item["path"], f"{context}.path")
        endpoint = item["endpoint"]
        endpoint_kinds = {"function", "class"}
        if allow_schema_endpoint and kind == "route":
            endpoint_kinds.add("schema-response")
        if not isinstance(endpoint, dict) or endpoint.get("kind") not in endpoint_kinds:
            raise ContractError(f"{context}.endpoint must describe a function or class")
        if endpoint["kind"] == "schema-response":
            _exact(endpoint, {"kind"}, f"{context}.endpoint")
            handler_count = 1
        elif endpoint["kind"] == "function":
            endpoint = _exact(endpoint, {"kind", "docstring"}, f"{context}.endpoint")
            if endpoint["docstring"] is not None:
                _string(endpoint["docstring"], f"{context}.endpoint.docstring")
            handler_count = 1
        else:
            endpoint = _exact(endpoint, {"kind", "handlers"}, f"{context}.endpoint")
            handlers = endpoint["handlers"]
            if (
                not isinstance(handlers, dict)
                or not handlers
                or any(
                    not isinstance(name, str)
                    or not name.isidentifier()
                    or (docstring is not None and not isinstance(docstring, str))
                    for name, docstring in handlers.items()
                )
            ):
                raise ContractError(f"{context}.endpoint.handlers must map names to docstrings")
            handler_count = len(handlers)
        if kind == "route":
            if "methods" in item and (
                not isinstance(item["methods"], list)
                or any(not isinstance(method, str) for method in item["methods"])
            ):
                raise ContractError(f"{context}.methods must be a string array")
            if "include_in_schema" in item and type(item["include_in_schema"]) is not bool:
                raise ContractError(f"{context}.include_in_schema must be boolean")
        selected: set[str] = set()
        if kind == "route":
            selected.add("starlette.schemas.BaseSchemaGenerator.get_endpoints")
            if item.get("include_in_schema", True):
                selected.add("starlette.schemas.BaseSchemaGenerator.parse_docstring")
            if ":" in item["path"]:
                selected.add("starlette.schemas.BaseSchemaGenerator._remove_converter")
        return selected, handler_count > 0
    if kind in {"mount", "host"}:
        allowed = {"kind", "routes", "path" if kind == "mount" else "host"}
        item = _exact(route, allowed, context)
        _string(item["path" if kind == "mount" else "host"], f"{context}.{kind}")
        nested_routes = item["routes"]
        if not isinstance(nested_routes, list):
            raise ContractError(f"{context}.routes must be an array")
        selected: set[str] = {"starlette.schemas.BaseSchemaGenerator.get_endpoints"}
        has_child = False
        for index, child in enumerate(nested_routes):
            child_selected, child_present = _validate_schema_route_input(
                child,
                f"{context}.routes[{index}]",
                allow_schema_endpoint=allow_schema_endpoint,
            )
            selected |= child_selected
            has_child |= child_present
        if kind == "mount":
            selected.add("starlette.schemas.BaseSchemaGenerator._remove_converter")
        return selected, has_child
    raise ContractError(f"{context}.kind is unsupported")


def _validate_application_route_endpoint(endpoint: Any, context: str) -> None:
    if not isinstance(endpoint, dict) or endpoint.get("kind") not in {"function", "class"}:
        raise ContractError(f"{context} must describe a function or class")
    if endpoint["kind"] == "function":
        endpoint = _exact(endpoint, {"kind", "name", "async"}, context)
        _string(endpoint["name"], f"{context}.name")
        if type(endpoint["async"]) is not bool:
            raise ContractError(f"{context}.async must be boolean")
    else:
        endpoint = _exact(endpoint, {"kind", "name"}, context)
        _string(endpoint["name"], f"{context}.name")


def _validate_application_route_input(route: Any, context: str) -> None:
    if not isinstance(route, dict) or not isinstance(route.get("kind"), str):
        raise ContractError(f"{context} must be an application route record")
    kind = route["kind"]
    if kind in {"route", "websocket-route"}:
        required = {"kind", "path", "endpoint"}
        allowed = required | {"route_name"}
        if kind == "route":
            allowed |= {"methods"}
        if not required <= route.keys() or route.keys() - allowed:
            raise ContractError(f"{context} fields are invalid")
        item = route
        path = _string(item["path"], f"{context}.path")
        if not path.startswith("/"):
            raise ContractError(f"{context}.path must be an absolute route path")
        if "route_name" in item and item["route_name"] is not None:
            _string(item["route_name"], f"{context}.route_name")
        if "methods" in item and (
            not isinstance(item["methods"], list)
            or not item["methods"]
            or any(not isinstance(method, str) or not method for method in item["methods"])
            or len(item["methods"]) != len(set(item["methods"]))
        ):
            raise ContractError(f"{context}.methods must be a unique string array")
        _validate_application_route_endpoint(item["endpoint"], f"{context}.endpoint")
        return
    if kind in {"mount", "host"}:
        path_field = "path" if kind == "mount" else "host"
        required = {"kind", path_field, "routes"}
        allowed = required | {"route_name"}
        if not required <= route.keys() or route.keys() - allowed:
            raise ContractError(f"{context} fields are invalid")
        item = route
        path = _string(item[path_field], f"{context}.{path_field}")
        if kind == "mount" and path and not path.startswith("/"):
            raise ContractError(f"{context}.path must be empty or absolute")
        if kind == "host" and path.startswith("/"):
            raise ContractError(f"{context}.host must not start with a slash")
        if "route_name" in item and item["route_name"] is not None:
            _string(item["route_name"], f"{context}.route_name")
        if not isinstance(item["routes"], list):
            raise ContractError(f"{context}.routes must be an array")
        for index, child in enumerate(item["routes"]):
            _validate_application_route_input(child, f"{context}.routes[{index}]")
        return
    raise ContractError(f"{context}.kind is unsupported")


def _validate_application_routes_property_case(case: dict[str, Any]) -> None:
    if case["observations"] != ["route-inventory"]:
        raise ContractError("Starlette.routes cases must select route-inventory")
    if case["target_profiles"] != ["python-package-cpython312"]:
        raise ContractError("Starlette.routes cases select only the Python-package profile")
    if not isinstance(case["routes"], list) or not case["routes"]:
        raise ContractError("Starlette.routes cases require a non-empty input route list")
    for index, route in enumerate(case["routes"]):
        _validate_application_route_input(route, f"Starlette.routes[{index}]")


def _validate_schema_case(case: dict[str, Any]) -> None:
    if case["target_profiles"] != ["python-package-cpython312"]:
        raise ContractError("schema parity currently targets the Python package profile")
    if case["assets"] != []:
        raise ContractError("schema parity does not use external assets")

    operation = (case["surface"], case["operation"])
    if operation == ("starlette.schemas.SchemaGenerator", "schema-generation"):
        if case["observations"] != ["endpoints", "schema"]:
            raise ContractError("SchemaGenerator must select endpoints and schema")
        if not isinstance(case["base_schema"], dict) or not isinstance(case["routes"], list):
            raise ContractError("SchemaGenerator base_schema and routes must be records and arrays")
        selected: set[str] = {"starlette.schemas.SchemaGenerator.get_schema"}
        has_route = False
        has_converter = False
        has_mount = False
        has_host = False
        has_head = False
        has_excluded = False
        has_class_endpoint = False
        for index, route in enumerate(case["routes"]):
            route_selected, route_present = _validate_schema_route_input(
                route, f"SchemaGenerator routes[{index}]"
            )
            selected |= route_selected
            has_route |= route_present
            has_mount |= route.get("kind") == "mount"
            has_host |= route.get("kind") == "host"
            if route.get("kind") == "route":
                has_head |= "HEAD" in route.get("methods", [])
                has_excluded |= route.get("include_in_schema") is False
                endpoint = route.get("endpoint", {})
                has_class_endpoint |= endpoint.get("kind") == "class"
                has_converter |= ":" in route.get("path", "")
        required = {
            "starlette.schemas.SchemaGenerator.get_schema",
            "starlette.schemas.BaseSchemaGenerator.get_endpoints",
            "starlette.schemas.BaseSchemaGenerator._remove_converter",
            "starlette.schemas.BaseSchemaGenerator.parse_docstring",
        }
        if selected != required or not all(
            [
                has_route,
                has_converter,
                has_mount,
                has_host,
                has_head,
                has_excluded,
                has_class_endpoint,
            ]
        ):
            raise ContractError("SchemaGenerator input does not exercise its declared route rules")
        expected = {"starlette.schemas.SchemaGenerator.get_schema"}
        expected |= {
            "starlette.schemas.BaseSchemaGenerator.get_endpoints",
            "starlette.schemas.BaseSchemaGenerator._remove_converter",
            "starlette.schemas.BaseSchemaGenerator.parse_docstring.mapping",
            "starlette.schemas.BaseSchemaGenerator.parse_docstring.delimited-section",
        }
        if set(case["covers"]) != expected:
            raise ContractError("SchemaGenerator coverage must match its route input")
        return

    if operation == ("starlette.schemas.BaseSchemaGenerator", "schema-docstring-parsing"):
        if case["observations"] != ["parsed-docstrings", "exception"]:
            raise ContractError("docstring parsing must select parsed-docstrings and exception")
        docstrings = case["docstrings"]
        if (
            not isinstance(docstrings, list)
            or not docstrings
            or any(not isinstance(docstring, str) for docstring in docstrings)
        ):
            raise ContractError("docstring parsing input must be a non-empty string array")
        malformed = any("[unterminated" in docstring for docstring in docstrings)
        if malformed:
            if len(docstrings) != 1 or case["covers"] != [
                "starlette.schemas.BaseSchemaGenerator.parse_docstring.malformed-yaml"
            ]:
                raise ContractError("malformed YAML input must isolate its parser error")
        else:
            if not any("responses:" in docstring for docstring in docstrings):
                raise ContractError("docstring parsing input must include a YAML mapping")
            if not any("---" in docstring for docstring in docstrings):
                raise ContractError("docstring parsing input must include a schema delimiter")
            if not any(not docstring.strip() for docstring in docstrings):
                raise ContractError("docstring parsing input must include empty prose")
            if not any(
                docstring.startswith("-") or docstring.strip() == "null" for docstring in docstrings
            ):
                raise ContractError("docstring parsing input must include a non-mapping YAML value")
            if set(case["covers"]) != {
                "starlette.schemas.BaseSchemaGenerator.parse_docstring.mapping",
                "starlette.schemas.BaseSchemaGenerator.parse_docstring.delimited-section",
                "starlette.schemas.BaseSchemaGenerator.parse_docstring.non-mapping-filter",
            }:
                raise ContractError("docstring parsing coverage must match its input examples")
        return

    if operation == ("starlette.schemas.OpenAPIResponse", "schema-endpoint-asgi-call"):
        observations = [
            "response-status",
            "content-type",
            "ordered-repeated-headers",
            "response-bytes",
            "asgi-event-order",
            "asgi-events",
        ]
        if case["observations"] != observations:
            raise ContractError("schema endpoint must select its HTTP response and ASGI events")
        if not isinstance(case["base_schema"], dict) or not isinstance(case["routes"], list):
            raise ContractError("schema endpoint base_schema and routes must be records and arrays")
        scope = _exact(
            case["scope"],
            {
                "type",
                "asgi",
                "http_version",
                "method",
                "scheme",
                "path",
                "raw_path_base64",
                "query_string_base64",
                "root_path",
                "headers_base64_pairs",
                "client",
                "server",
            },
            "OpenAPIResponse schema endpoint HTTP scope",
        )
        if (
            scope["type"] != "http"
            or scope["asgi"] != {"version": "3.0", "spec_version": "2.4"}
            or scope["method"] != "GET"
            or scope["scheme"] != "http"
        ):
            raise ContractError("schema endpoint must use an ASGI 3.0 HTTP GET scope")
        for key in ("http_version", "path"):
            _string(scope[key], f"schema endpoint scope.{key}")
        if not isinstance(scope["root_path"], str):
            raise ContractError("schema endpoint scope.root_path must be a string")
        try:
            expected_raw_path = base64.b64encode(scope["path"].encode("ascii")).decode("ascii")
        except UnicodeEncodeError as exc:
            raise ContractError("schema endpoint scope.path must be ASCII") from exc
        if scope["raw_path_base64"] != expected_raw_path:
            raise ContractError("schema endpoint raw_path must match its input path")
        for key in ("raw_path_base64", "query_string_base64"):
            if not isinstance(scope[key], str):
                raise ContractError(f"schema endpoint scope.{key} must be base64 text")
            try:
                base64.b64decode(scope[key], validate=True)
            except (ValueError, TypeError) as exc:
                raise ContractError(f"schema endpoint scope.{key} is invalid base64") from exc
        headers = scope["headers_base64_pairs"]
        if not isinstance(headers, list):
            raise ContractError("schema endpoint scope headers must be an array")
        for index, pair in enumerate(headers):
            if not isinstance(pair, list) or len(pair) != 2:
                raise ContractError(f"schema endpoint scope header[{index}] must be a pair")
            for value in pair:
                if not isinstance(value, str):
                    raise ContractError(
                        f"schema endpoint scope header[{index}] values must be base64 text"
                    )
                try:
                    base64.b64decode(value, validate=True)
                except (ValueError, TypeError) as exc:
                    raise ContractError(
                        f"schema endpoint scope header[{index}] is invalid base64"
                    ) from exc
        for key in ("client", "server"):
            address = scope[key]
            if (
                not isinstance(address, list)
                or len(address) != 2
                or not isinstance(address[0], str)
                or not isinstance(address[1], int)
                or isinstance(address[1], bool)
            ):
                raise ContractError(f"schema endpoint scope.{key} must be a host/port pair")

        incoming = case["incoming"]
        if not isinstance(incoming, list) or len(incoming) != 1:
            raise ContractError("schema endpoint must provide one complete HTTP request message")
        request_message = _exact(
            incoming[0],
            {"type", "body_base64", "more_body"},
            "schema endpoint request message",
        )
        if request_message["type"] != "http.request" or request_message["more_body"] is not False:
            raise ContractError("schema endpoint request must be a terminal http.request message")
        if not isinstance(request_message["body_base64"], str):
            raise ContractError("schema endpoint request body must be base64 text")
        try:
            request_body = base64.b64decode(request_message["body_base64"], validate=True)
        except (ValueError, TypeError) as exc:
            raise ContractError("schema endpoint request body must be base64") from exc
        if request_body:
            raise ContractError("schema endpoint request body must be empty")

        if not case["routes"]:
            raise ContractError("schema endpoint requires the pinned application route graph")
        selected: set[str] = set()
        schema_routes = []
        for index, route in enumerate(case["routes"]):
            route_selected, _ = _validate_schema_route_input(
                route,
                f"OpenAPIResponse schema endpoint routes[{index}]",
                allow_schema_endpoint=True,
            )
            selected |= route_selected
            if (
                isinstance(route, dict)
                and route.get("kind") == "route"
                and isinstance(route.get("endpoint"), dict)
                and route["endpoint"].get("kind") == "schema-response"
            ):
                schema_routes.append(route)
        if (
            len(schema_routes) != 1
            or schema_routes[0].get("methods") != ["GET"]
            or schema_routes[0].get("include_in_schema") is not False
            or schema_routes[0].get("path") != scope["path"]
        ):
            raise ContractError(
                "schema endpoint must be one hidden GET route selected by its HTTP scope"
            )
        if not selected:
            raise ContractError("schema endpoint route graph must contain HTTP routes")
        if set(case["covers"]) != {
            "starlette.schemas.SchemaGenerator.OpenAPIResponse.endpoint-generation",
            "starlette.schemas.OpenAPIResponse.asgi-response-call",
        }:
            raise ContractError("schema endpoint coverage must match generation and ASGI response")
        return

    if operation != ("starlette.schemas.OpenAPIResponse", "openapi-response-render"):
        raise ContractError("schema case uses an undeclared operation")
    if case["observations"] != ["media-type", "rendered-bytes"]:
        raise ContractError("OpenAPIResponse must select media-type and rendered-bytes")
    if not isinstance(case["content"], dict):
        raise ContractError("OpenAPIResponse content must be a mapping")
    if set(case["covers"]) != {
        "starlette.schemas.OpenAPIResponse.render",
        "starlette.schemas.BaseSchemaGenerator.OpenAPIResponse",
    }:
        raise ContractError("OpenAPIResponse coverage must match render and generator response")


def _validate_templating_case(case: dict[str, Any]) -> None:
    if case["target_profiles"] != ["python-package-cpython312"]:
        raise ContractError("Jinja2Templates parity currently targets the Python package profile")
    if case["assets"] != [] or case["observations"] != ["template-response"]:
        raise ContractError(
            "Jinja2Templates cases use inline templates and select template-response"
        )
    if set(case["covers"]) != TEMPLATING_REQUIREMENTS:
        raise ContractError(
            "Jinja2Templates coverage must select the complete declared template workflow"
        )

    template_files = case["template_files"]
    if not isinstance(template_files, list) or not template_files:
        raise ContractError("Jinja2Templates template_files must be a non-empty array")
    source_by_path: dict[str, str] = {}
    for index, item in enumerate(template_files):
        item = _exact(item, {"path", "text"}, f"Jinja2Templates template_files[{index}]")
        path = _string(item["path"], f"Jinja2Templates template_files[{index}].path")
        components = path.split("/")
        if (
            path.startswith("/")
            or "\\" in path
            or any(component in {"", ".", ".."} for component in components)
        ):
            raise ContractError("Jinja2Templates file paths must be safe relative POSIX paths")
        if path in source_by_path:
            raise ContractError(f"Jinja2Templates template path is duplicated: {path!r}")
        source_by_path[path] = _string(
            item["text"], f"Jinja2Templates template_files[{index}].text"
        )

    template_name = _string(case["template_name"], "Jinja2Templates template_name")
    if template_name not in source_by_path:
        raise ContractError("Jinja2Templates template_name must select a supplied template file")
    if not template_name.lower().endswith((".html", ".htm", ".xml")):
        raise ContractError(
            "Jinja2Templates autoescape input must use a documented HTML/XML suffix"
        )

    route = _exact(case["route"], {"path", "name"}, "Jinja2Templates route")
    route_path = _string(route["path"], "Jinja2Templates route.path")
    route_name = _string(route["name"], "Jinja2Templates route.name")
    if "{" not in route_path or "}" not in route_path:
        raise ContractError("Jinja2Templates url_for input must contain a route parameter")

    context = case["context"]
    if not isinstance(context, dict) or not context:
        raise ContractError("Jinja2Templates context must be a non-empty record")
    template_text = source_by_path[template_name]
    if "url_for" not in template_text or route_name not in template_text:
        raise ContractError("Jinja2Templates template must call the configured url_for route")
    if not all(key in template_text for key in context):
        raise ContractError("Jinja2Templates template must render every supplied context key")

    additions = case["processor_additions"]
    if (
        not isinstance(additions, list)
        or not additions
        or any(not isinstance(item, dict) or not item for item in additions)
    ):
        raise ContractError("Jinja2Templates processor_additions must be non-empty records")
    if not any(key in template_text for processor in additions for key in processor):
        raise ContractError("Jinja2Templates template must render a context-processor value")

    scope = _exact(
        case["scope"],
        {
            "type",
            "asgi",
            "http_version",
            "scheme",
            "path",
            "raw_path_base64",
            "query_string_base64",
            "root_path",
            "headers_base64_pairs",
            "client",
            "server",
            "method",
            "extensions",
        },
        "Jinja2Templates ASGI scope",
    )
    if scope["type"] != "http":
        raise ContractError("Jinja2Templates ASGI scope.type must be http")
    asgi = _exact(scope["asgi"], {"version", "spec_version"}, "Jinja2Templates ASGI scope.asgi")
    if asgi != {"version": "3.0", "spec_version": "2.4"}:
        raise ContractError("Jinja2Templates scope must use ASGI 3.0 with spec version 2.4")
    for key in ("http_version", "scheme", "path", "method"):
        _string(scope[key], f"Jinja2Templates ASGI scope.{key}")
    if not isinstance(scope["root_path"], str):
        raise ContractError("Jinja2Templates ASGI scope.root_path must be a string")
    try:
        expected_raw_path = base64.b64encode(scope["path"].encode("ascii")).decode("ascii")
    except UnicodeEncodeError as exc:
        raise ContractError("Jinja2Templates ASGI scope.path must be ASCII") from exc
    if scope["raw_path_base64"] != expected_raw_path:
        raise ContractError("Jinja2Templates raw_path bytes must match the declared ASCII path")
    for key in ("raw_path_base64", "query_string_base64"):
        try:
            base64.b64decode(scope[key], validate=True)
        except (ValueError, TypeError) as exc:
            raise ContractError(f"Jinja2Templates ASGI scope.{key} is invalid base64") from exc
    scope_headers = scope["headers_base64_pairs"]
    if not isinstance(scope_headers, list):
        raise ContractError("Jinja2Templates scope headers must be an array")
    for index, pair in enumerate(scope_headers):
        if not isinstance(pair, list) or len(pair) != 2:
            raise ContractError(f"Jinja2Templates scope headers[{index}] must be a pair")
        for value in pair:
            try:
                base64.b64decode(value, validate=True)
            except (ValueError, TypeError) as exc:
                raise ContractError(
                    f"Jinja2Templates scope headers[{index}] is invalid base64"
                ) from exc
    for key in ("client", "server"):
        address = scope[key]
        if (
            not isinstance(address, list)
            or len(address) != 2
            or not isinstance(address[0], str)
            or not isinstance(address[1], int)
            or isinstance(address[1], bool)
        ):
            raise ContractError(f"Jinja2Templates ASGI scope.{key} must be a host/port pair")
    extensions = scope["extensions"]
    if not isinstance(extensions, dict) or "http.response.debug" not in extensions:
        raise ContractError("Jinja2Templates scope must request the debug response extension")

    status_code = case["status_code"]
    if not isinstance(status_code, int) or isinstance(status_code, bool):
        raise ContractError("Jinja2Templates status_code must be an integer")
    headers = case["headers"]
    if not isinstance(headers, dict) or any(
        not isinstance(name, str) or not isinstance(value, str) for name, value in headers.items()
    ):
        raise ContractError("Jinja2Templates headers must be a string mapping")
    if case["media_type"] is not None and not isinstance(case["media_type"], str):
        raise ContractError("Jinja2Templates media_type must be a string or null")


def _validate_url_query_case(case: dict[str, Any]) -> None:
    if case["target_profiles"] != ["python-package-cpython312"]:
        raise ContractError("URL query parity currently targets the Python package profile")
    if case["assets"] != [] or case["observations"] != ["action-results"]:
        raise ContractError("URL query cases use no assets and select action-results")
    _string(case["url"], "URL query input URL")
    actions = case["actions"]
    if not isinstance(actions, list) or not actions:
        raise ContractError("URL query actions must be a non-empty array")

    methods: set[str] = set()
    for index, action in enumerate(actions):
        context = f"URL query actions[{index}]"
        if not isinstance(action, dict) or not isinstance(action.get("method"), str):
            raise ContractError(f"{context} must select a public URL method")
        method = action["method"]
        if method in {"include_query_params", "replace_query_params"}:
            action = _exact(action, {"method", "kwargs"}, context)
            kwargs = action["kwargs"]
            if not isinstance(kwargs, dict) or any(not isinstance(key, str) for key in kwargs):
                raise ContractError(f"{context}.kwargs must be a string-keyed mapping")
        elif method == "remove_query_params":
            action = _exact(action, {"method", "args"}, context)
            args = action["args"]
            if not isinstance(args, list) or len(args) != 1:
                raise ContractError(f"{context}.args must contain the keys argument")
            keys = args[0]
            if not isinstance(keys, str) and not (
                isinstance(keys, list) and all(isinstance(key, str) for key in keys)
            ):
                raise ContractError(f"{context}.args[0] must be a string or string array")
        else:
            raise ContractError(f"{context}.method is outside the declared URL query operations")
        methods.add(method)

    expected_methods = {"include_query_params", "replace_query_params", "remove_query_params"}
    expected_covers = {
        "starlette.datastructures.URL.include_query_params",
        "starlette.datastructures.URL.replace_query_params",
        "starlette.datastructures.URL.remove_query_params",
    }
    if methods != expected_methods or set(case["covers"]) != expected_covers:
        raise ContractError("URL query actions and coverage must include all declared methods")


def _validate_url_components_case(case: dict[str, Any]) -> None:
    if case["target_profiles"] != ["python-package-cpython312"]:
        raise ContractError("URL component parity currently targets the Python package profile")
    if case["assets"] != []:
        raise ContractError("URL component cases do not use external assets")
    _string(case["url"], "URL component input URL")
    actions = case["actions"]
    if not isinstance(actions, list):
        raise ContractError("URL component actions must be an array")
    observations = case["observations"]
    allowed_observations = {"url-record", "action-results"}
    if (
        not isinstance(observations, list)
        or not observations
        or any(
            not isinstance(item, str) or item not in allowed_observations for item in observations
        )
        or len(observations) != len(set(observations))
    ):
        raise ContractError("URL component observations must select unique declared results")

    replacements = False
    allowed_components = {
        "scheme",
        "netloc",
        "path",
        "query",
        "fragment",
        "username",
        "password",
        "hostname",
        "port",
    }
    for index, action in enumerate(actions):
        context = f"URL component actions[{index}]"
        action = _exact(action, {"method", "kwargs"}, context)
        if action["method"] != "replace":
            raise ContractError(f"{context}.method must be replace")
        kwargs = action["kwargs"]
        if (
            not isinstance(kwargs, dict)
            or not kwargs
            or any(not isinstance(key, str) or key not in allowed_components for key in kwargs)
        ):
            raise ContractError(f"{context}.kwargs must name URL replacement components")
        for key, value in kwargs.items():
            if value is not None and not isinstance(value, (str, int)):
                raise ContractError(f"{context}.kwargs[{key!r}] must be a string, integer, or null")
            if isinstance(value, bool):
                raise ContractError(f"{context}.kwargs[{key!r}] must not be boolean")
        replacements = True

    exercised = {"starlette.datastructures.URL.component-construction"}
    if "url-record" in observations:
        exercised.add("starlette.datastructures.URL.component-access")
        exercised.add("starlette.datastructures.URL.password-redaction")
    if replacements:
        exercised.add("starlette.datastructures.URL.component-replacement")
    unexercised = set(case["covers"]) - exercised
    if unexercised:
        raise ContractError(
            "URL component case claims requirements not exercised by its input: "
            f"{sorted(unexercised)}"
        )


def _validate_urlpath_absolute_case(case: dict[str, Any]) -> None:
    if case["target_profiles"] != ["python-package-cpython312"]:
        raise ContractError("URLPath absolute-URL parity currently targets the Python package")
    if case["assets"] != [] or case["observations"] != ["absolute-url-results"]:
        raise ContractError(
            "URLPath absolute-URL cases use no assets and select absolute-url-results"
        )

    graph = _validate_reverse_route_node(
        case["route_graph"], "URLPath route_graph", {}, allow_observer=False
    )
    lookups = case["lookups"]
    if not isinstance(lookups, list) or not lookups:
        raise ContractError("URLPath lookups must be a non-empty array")
    profiles: list[tuple[str, bool]] = []
    for index, raw_lookup in enumerate(lookups):
        context = f"URLPath lookups[{index}]"
        lookup = _exact(raw_lookup, {"name", "path_params"}, context)
        _string(lookup["name"], f"{context}.name")
        path_params = lookup["path_params"]
        if not isinstance(path_params, dict):
            raise ContractError(f"{context}.path_params must be an object")
        for name, value in path_params.items():
            _string(name, f"{context}.path parameter name")
            if isinstance(value, (dict, list)):
                raise ContractError(f"{context}.path parameter values must be JSON scalars")
        candidates = _urlpath_route_profiles(graph, lookup["name"], path_params, {})
        if not candidates:
            raise ContractError(f"{context} must resolve through the supplied route graph")
        profiles.append(candidates[0])

    raw_base_urls = case["base_urls"]
    if not isinstance(raw_base_urls, list) or not raw_base_urls:
        raise ContractError("URLPath base_urls must be a non-empty array")
    base_urls = []
    for index, raw_base_url in enumerate(raw_base_urls):
        context = f"URLPath base_urls[{index}]"
        base_url = _exact(raw_base_url, {"kind", "value"}, context)
        if base_url["kind"] not in {"string", "url"}:
            raise ContractError(f"{context}.kind must be string or url")
        value = _string(base_url["value"], f"{context}.value")
        try:
            parsed = urlsplit(value)
        except ValueError as exc:
            raise ContractError(f"{context}.value must be a valid absolute URL") from exc
        if parsed.scheme not in {"http", "https"} or not parsed.netloc:
            raise ContractError(f"{context}.value must have an HTTP(S) scheme and authority")
        base_urls.append((base_url["kind"], parsed))

    schemes = {base.scheme for _kind, base in base_urls}
    protocols = {protocol for protocol, _host in profiles}
    has_host_override = any(host for _protocol, host in profiles)
    has_base_authority_fallback = any(
        not host and any(base.netloc for _kind, base in base_urls) for _protocol, host in profiles
    )
    base_paths = {base.path for _kind, base in base_urls}
    base_types = {kind for kind, _base in base_urls}
    derived: set[str] = set()
    if {"http-route", "websocket-route"} <= protocols and {"http", "https"} <= schemes:
        derived.add(URLPATH_ABSOLUTE_REQUIREMENTS["scheme"])
    if "" in protocols and {"http", "https"} <= schemes:
        derived.add(URLPATH_ABSOLUTE_REQUIREMENTS["base_scheme"])
    if has_host_override:
        derived.add(URLPATH_ABSOLUTE_REQUIREMENTS["host_override"])
    if has_base_authority_fallback:
        derived.add(URLPATH_ABSOLUTE_REQUIREMENTS["base_authority"])
    if any(path not in {"", "/"} for path in base_paths):
        derived.add(URLPATH_ABSOLUTE_REQUIREMENTS["base_path"])
    if base_types == {"string", "url"}:
        derived.add(URLPATH_ABSOLUTE_REQUIREMENTS["base_types"])
    if any(base.query and base.fragment for _kind, base in base_urls):
        derived.add(URLPATH_ABSOLUTE_REQUIREMENTS["query_fragment"])
    if set(case["covers"]) != derived:
        raise ContractError(
            "URLPath absolute-URL coverage must be derived from route and base URL inputs: "
            f"expected {sorted(derived)}"
        )


def _validate_header_pairs(value: Any, context: str) -> list[tuple[bytes, bytes]]:
    if not isinstance(value, list):
        raise ContractError(f"{context} must be an array")
    pairs: list[tuple[bytes, bytes]] = []
    for index, pair in enumerate(value):
        if not isinstance(pair, list) or len(pair) != 2:
            raise ContractError(f"{context}[{index}] must be a two-item array")
        decoded: list[bytes] = []
        for item in pair:
            if not isinstance(item, str):
                raise ContractError(f"{context}[{index}] entries must be base64 strings")
            try:
                decoded.append(base64.b64decode(item, validate=True))
            except (ValueError, TypeError) as exc:
                raise ContractError(f"{context}[{index}] contains invalid base64") from exc
        pairs.append((decoded[0], decoded[1]))
    return pairs


def _validate_header_constructor(
    constructor: Any,
    context: str,
    *,
    mutable: bool,
    exercised: set[str],
) -> tuple[bool, list[tuple[bytes, bytes]]]:
    if not isinstance(constructor, dict) or not isinstance(constructor.get("kind"), str):
        raise ContractError(f"{context} must select a declared header constructor")
    kind = constructor["kind"]
    if kind == "raw":
        source = _exact(constructor, {"kind", "headers_base64_pairs"}, context)
        pairs = _validate_header_pairs(
            source["headers_base64_pairs"], f"{context}.headers_base64_pairs"
        )
        exercised.add(
            "starlette.datastructures.MutableHeaders.constructor"
            if mutable
            else "starlette.datastructures.Headers.constructor.raw"
        )
    elif kind == "mapping":
        source = _exact(constructor, {"kind", "items"}, context)
        items = source["items"]
        if not isinstance(items, list):
            raise ContractError(f"{context}.items must be an array")
        keys: set[str] = set()
        for index, pair in enumerate(items):
            if (
                not isinstance(pair, list)
                or len(pair) != 2
                or not isinstance(pair[0], str)
                or not isinstance(pair[1], str)
            ):
                raise ContractError(f"{context}.items[{index}] must be a two-string pair")
            if pair[0] in keys:
                raise ContractError(f"{context}.items contains duplicate mapping key {pair[0]!r}")
            keys.add(pair[0])
        try:
            pairs = [
                (key.lower().encode("latin-1"), value.encode("latin-1")) for key, value in items
            ]
        except UnicodeEncodeError as exc:
            raise ContractError(f"{context}.items must be Latin-1 encodable") from exc
        exercised.add(
            "starlette.datastructures.MutableHeaders.constructor"
            if mutable
            else "starlette.datastructures.Headers.constructor.mapping"
        )
    elif kind == "scope":
        source = _exact(
            constructor,
            {"kind", "scope_headers_container", "headers_base64_pairs"},
            context,
        )
        container = source["scope_headers_container"]
        if not isinstance(container, str) or container not in {"list", "tuple"}:
            raise ContractError(f"{context}.scope_headers_container must be list or tuple")
        pairs = _validate_header_pairs(
            source["headers_base64_pairs"], f"{context}.headers_base64_pairs"
        )
        if mutable:
            if container == "tuple":
                exercised.add(
                    "starlette.datastructures.MutableHeaders.constructor.scope-list-coercion"
                )
        else:
            exercised.add("starlette.datastructures.Headers.constructor.scope-container-conversion")
    elif kind == "empty":
        _exact(constructor, {"kind"}, context)
        pairs = []
        if mutable:
            exercised.add("starlette.datastructures.MutableHeaders.constructor")
    else:
        raise ContractError(f"{context}.kind is outside the declared header constructors")
    return kind == "scope", pairs


def _validate_header_argument(value: Any, instance_ids: set[str], context: str) -> str | None:
    if isinstance(value, dict):
        if set(value) == {"instance_id"}:
            instance_id = _string(value["instance_id"], f"{context}.instance_id")
            if instance_id not in instance_ids:
                raise ContractError(f"{context} references an unknown header instance")
            return "headers"
        if set(value) == {"kind", "items"}:
            kind = value["kind"]
            items = value["items"]
            if kind == "mapping":
                if not isinstance(items, list):
                    raise ContractError(f"{context}.items must be an array")
                seen: set[str] = set()
                for index, pair in enumerate(items):
                    if (
                        not isinstance(pair, list)
                        or len(pair) != 2
                        or not isinstance(pair[0], str)
                        or not isinstance(pair[1], str)
                    ):
                        raise ContractError(f"{context}.items[{index}] must be a two-string pair")
                    if pair[0] in seen:
                        raise ContractError(
                            f"{context}.items has duplicate mapping key {pair[0]!r}"
                        )
                    seen.add(pair[0])
                return "mapping"
            if kind == "set":
                if not isinstance(items, list) or any(not isinstance(item, str) for item in items):
                    raise ContractError(f"{context}.items must be an array of strings")
                if len(items) != len(set(items)):
                    raise ContractError(f"{context}.items must not repeat set values")
                return "nonmapping"
        raise ContractError(f"{context} must use a declared header argument descriptor")
    if isinstance(value, list):
        for index, item in enumerate(value):
            if isinstance(item, (list, str, int, float, bool)) or item is None:
                _validate_header_argument(item, instance_ids, f"{context}[{index}]")
            else:
                raise ContractError(f"{context}[{index}] is not JSON-compatible")
        return "sequence"
    if isinstance(value, (str, int, float, bool)) or value is None:
        return None
    raise ContractError(f"{context} is not a declared header argument value")


def _validate_state_case(case: dict[str, Any]) -> None:
    if case["target_profiles"] != ["python-package-cpython312"]:
        raise ContractError("State consumer-sequence parity targets the Python package profile")
    if case["assets"] != []:
        raise ContractError("State consumer-sequence cases do not use external assets")
    if case["observations"] != ["consumer-sequence"]:
        raise ContractError("State observations must select consumer-sequence")

    instances = case["instances"]
    if not isinstance(instances, list) or not instances:
        raise ContractError("State instances must be a non-empty array")
    instance_ids: set[str] = set()
    current_keys: dict[str, list[str]] = {}
    provided_mapping: dict[str, bool] = {}
    empty_instances: set[str] = set()
    for index, instance_value in enumerate(instances):
        context = f"State instances[{index}]"
        instance = _exact(instance_value, {"instance_id", "initial_state"}, context)
        instance_id = _string(instance["instance_id"], f"{context}.instance_id")
        if not instance_id or instance_id in instance_ids:
            raise ContractError(f"{context}.instance_id must be non-empty and unique")
        instance_ids.add(instance_id)
        initial_state = instance["initial_state"]
        if initial_state is None:
            current_keys[instance_id] = []
            provided_mapping[instance_id] = False
            empty_instances.add(instance_id)
        elif isinstance(initial_state, dict):
            _validate_threadpool_json(initial_state, f"{context}.initial_state")
            if any(not isinstance(key, str) for key in initial_state):
                raise ContractError(f"{context}.initial_state keys must be strings")
            current_keys[instance_id] = list(initial_state)
            provided_mapping[instance_id] = True
        else:
            raise ContractError(f"{context}.initial_state must be a mapping or null")

    actions = case["actions"]
    if not isinstance(actions, list) or not actions:
        raise ContractError("State actions must be a non-empty array")
    action_ids: set[str] = set()
    attribute_set_keys: dict[str, set[str]] = {instance_id: set() for instance_id in instance_ids}
    attribute_get_keys: dict[str, set[str]] = {instance_id: set() for instance_id in instance_ids}
    attribute_delete_keys: dict[str, set[str]] = {
        instance_id: set() for instance_id in instance_ids
    }
    item_set_keys: dict[str, set[str]] = {instance_id: set() for instance_id in instance_ids}
    item_get_keys: dict[str, set[str]] = {instance_id: set() for instance_id in instance_ids}
    item_delete_keys: dict[str, set[str]] = {instance_id: set() for instance_id in instance_ids}
    missing_attributes: set[str] = set()
    missing_items: set[str] = set()
    iterated: set[str] = set()
    measured_length: set[str] = set()
    inspected_instances: set[str] = set()
    mutated_provided_mappings: set[str] = set()
    written_instances: set[str] = set()
    read_missing_instances: set[str] = set()

    for index, action_value in enumerate(actions):
        context = f"State actions[{index}]"
        action = _exact(action_value, {"action_id", "receiver", "call", "arguments"}, context)
        action_id = _string(action["action_id"], f"{context}.action_id")
        receiver = _string(action["receiver"], f"{context}.receiver")
        call = _string(action["call"], f"{context}.call")
        arguments = action["arguments"]
        if not action_id or action_id in action_ids:
            raise ContractError(f"{context}.action_id must be non-empty and unique")
        action_ids.add(action_id)
        if receiver not in instance_ids:
            raise ContractError(f"{context}.receiver must refer to a declared instance")
        if call not in STATE_ACTIONS or not isinstance(arguments, list):
            raise ContractError(f"{context} must use a declared State action and argument array")
        expected_arity = (
            {2}
            if call in {"set-attribute", "set-item"}
            else {1}
            if call in {"get-attribute", "delete-attribute", "get-item", "delete-item"}
            else {0}
        )
        if len(arguments) not in expected_arity:
            raise ContractError(f"{context}.arguments has invalid arity for {call}")
        for argument_index, argument in enumerate(arguments):
            _validate_threadpool_json(argument, f"{context}.arguments[{argument_index}]")
        if call in {
            "set-attribute",
            "get-attribute",
            "delete-attribute",
            "set-item",
            "get-item",
            "delete-item",
        } and not isinstance(arguments[0], str):
            raise ContractError(f"{context}.arguments[0] must be a string key")

        if call in {"set-attribute", "set-item"}:
            key = arguments[0]
            keys = current_keys[receiver]
            if key not in keys:
                keys.append(key)
            if call == "set-attribute":
                attribute_set_keys[receiver].add(key)
            else:
                item_set_keys[receiver].add(key)
            written_instances.add(receiver)
            if provided_mapping[receiver]:
                mutated_provided_mappings.add(receiver)
        elif call in {"get-attribute", "get-item"}:
            key = arguments[0]
            if key in current_keys[receiver]:
                if call == "get-attribute":
                    attribute_get_keys[receiver].add(key)
                else:
                    item_get_keys[receiver].add(key)
            elif call == "get-attribute":
                missing_attributes.add(receiver)
            else:
                missing_items.add(receiver)
                read_missing_instances.add(receiver)
        elif call in {"delete-attribute", "delete-item"}:
            key = arguments[0]
            keys = current_keys[receiver]
            if key in keys:
                keys.remove(key)
                if call == "delete-attribute":
                    attribute_delete_keys[receiver].add(key)
                else:
                    item_delete_keys[receiver].add(key)
                if provided_mapping[receiver]:
                    mutated_provided_mappings.add(receiver)
            elif call == "delete-item":
                missing_items.add(receiver)
        elif call == "iterate":
            iterated.add(receiver)
        elif call == "length":
            measured_length.add(receiver)
        elif call == "vars":
            inspected_instances.add(receiver)

    exercised: set[str] = set()
    if mutated_provided_mappings:
        exercised.add(STATE_REQUIREMENTS["constructor_mapping"])
    if any(attribute_set_keys[item] & attribute_get_keys[item] for item in instance_ids):
        exercised.add(STATE_REQUIREMENTS["attribute_set_get"])
    if any(attribute_set_keys[item] & attribute_delete_keys[item] for item in instance_ids):
        exercised.add(STATE_REQUIREMENTS["attribute_delete"])
    if missing_attributes:
        exercised.add(STATE_REQUIREMENTS["missing_attribute"])
    if any(item_set_keys[item] & item_get_keys[item] for item in instance_ids):
        exercised.add(STATE_REQUIREMENTS["item_set_get"])
    if any(item_set_keys[item] & attribute_get_keys[item] for item in instance_ids):
        exercised.add(STATE_REQUIREMENTS["item_alias"])
    if any(item_set_keys[item] & item_delete_keys[item] for item in instance_ids):
        exercised.add(STATE_REQUIREMENTS["item_delete"])
    if missing_items:
        exercised.add(STATE_REQUIREMENTS["missing_item"])
    if any(iterated & measured_length):
        exercised.add(STATE_REQUIREMENTS["iteration_length"])
    if inspected_instances:
        exercised.add(STATE_REQUIREMENTS["instance_dict"])
    default_state_write_and_independent_read = any(
        written != missing
        for written in written_instances & empty_instances
        for missing in read_missing_instances & empty_instances
    )
    if (
        len(empty_instances) >= 2
        and default_state_write_and_independent_read
        and empty_instances & iterated & measured_length
    ):
        exercised.add(STATE_REQUIREMENTS["default_isolation"])

    if set(case["covers"]) != exercised:
        raise ContractError(
            "State case covers must match its input-defined constructors and actions; "
            f"expected {sorted(exercised)}"
        )


def _upload_file_semantic_coverage(case: dict[str, Any]) -> set[str]:
    scenarios = case.get("scenarios")
    if not isinstance(scenarios, list) or len(scenarios) < 2:
        return set()

    rollover_states: set[bool] = set()
    shared_actions: list[dict[str, Any]] | None = None
    exercised_calls: set[str] = set()
    probed_roll_states: dict[str, set[bool]] = {}
    injected_read_error = False
    for scenario in scenarios:
        max_size = scenario["max_size"]
        position = 0
        file_size = 0
        rolled = False
        actions = scenario["actions"]
        if shared_actions is None:
            shared_actions = actions
        elif actions != shared_actions:
            return set()
        for action in actions:
            call = action["call"]
            exercised_calls.add(call)
            if scenario.get("thread_probe") is not None:
                probed_roll_states.setdefault(call, set()).add(rolled)
            injected_read_error |= call == "read" and "injected_error" in action
            if call == "read":
                size = action["size"]
                remaining = max(file_size - position, 0)
                position += remaining if size == -1 else min(size, remaining)
            elif call == "seek":
                position = action["offset"]
            elif call == "write":
                data = base64.b64decode(action["data_base64"], validate=True)
                position += len(data)
                file_size = max(file_size, position)
                if max_size and position > max_size:
                    rolled = True
        rollover_states.add(rolled)

    if (
        rollover_states == {False, True}
        and {
            "read",
            "write",
            "seek",
            "close",
        }
        <= exercised_calls
    ):
        exercised = {UPLOAD_FILE_ROLLOVER_REQUIREMENT}
    else:
        exercised = set()

    file_operations = {"read", "write", "seek", "close"}
    if (
        all(probed_roll_states.get(call) == {False, True} for call in file_operations)
        and injected_read_error
    ):
        exercised.add(UPLOAD_FILE_THREADPOOL_GAP)

    constructor_probes = case.get("constructor_probes", [])
    required_file_calls = {"read", "write", "seek"}
    has_sized_file_input = any(
        probe["size"] is not None
        and required_file_calls <= {action["call"] for action in probe["actions"]}
        for probe in constructor_probes
    )
    has_unsized_file_input = any(
        probe["size"] is None
        and required_file_calls <= {action["call"] for action in probe["actions"]}
        for probe in constructor_probes
    )
    has_default_headers = any(probe["headers"] is None for probe in constructor_probes)
    has_explicit_headers = any(bool(probe["headers"]) for probe in constructor_probes)
    if (
        has_sized_file_input
        and has_unsized_file_input
        and has_default_headers
        and has_explicit_headers
    ):
        exercised.add(UPLOAD_FILE_CONSTRUCTOR_GAP)
    return exercised


def _validate_upload_file_constructor_probes(probes: Any) -> None:
    if not isinstance(probes, list) or len(probes) < 3:
        raise ContractError("UploadFile constructor inputs must cover size and header variants")
    probe_ids: set[str] = set()
    for index, probe_value in enumerate(probes):
        context = f"UploadFile constructor_probes[{index}]"
        probe = _exact(
            probe_value,
            {"probe_id", "data_base64", "filename", "size", "headers", "actions"},
            context,
        )
        probe_id = _string(probe["probe_id"], f"{context}.probe_id")
        if not probe_id or probe_id in probe_ids:
            raise ContractError(f"{context}.probe_id must be non-empty and unique")
        probe_ids.add(probe_id)
        data_base64 = _string(probe["data_base64"], f"{context}.data_base64")
        try:
            base64.b64decode(data_base64, validate=True)
        except (ValueError, TypeError) as exc:
            raise ContractError(f"{context}.data_base64 must be valid base64") from exc
        if probe["filename"] is not None:
            _string(probe["filename"], f"{context}.filename")
        size = probe["size"]
        if size is not None and (type(size) is not int or size < 0):
            raise ContractError(f"{context}.size must be null or a non-negative integer")
        headers = probe["headers"]
        if headers is not None:
            if not isinstance(headers, list):
                raise ContractError(f"{context}.headers must be null or a header-pair array")
            for header_index, header_value in enumerate(headers):
                header_context = f"{context}.headers[{header_index}]"
                header = _exact(header_value, {"name", "value"}, header_context)
                _string(header["name"], f"{header_context}.name")
                _string(header["value"], f"{header_context}.value")
        actions = probe["actions"]
        if not isinstance(actions, list):
            raise ContractError(f"{context}.actions must be an array")
        action_ids: set[str] = set()
        for action_index, action_value in enumerate(actions):
            action_context = f"{context}.actions[{action_index}]"
            if not isinstance(action_value, dict) or not isinstance(action_value.get("call"), str):
                raise ContractError(f"{action_context} must declare a call")
            call = action_value["call"]
            action_fields = {
                "read": {"action_id", "call", "size"},
                "write": {"action_id", "call", "data_base64"},
                "seek": {"action_id", "call", "offset"},
            }.get(call)
            if action_fields is None:
                raise ContractError(f"{action_context}.call must be read, write, or seek")
            action = _exact(action_value, action_fields, action_context)
            action_id = _string(action["action_id"], f"{action_context}.action_id")
            if not action_id or action_id in action_ids:
                raise ContractError(f"{action_context}.action_id must be non-empty and unique")
            action_ids.add(action_id)
            if call == "read":
                if type(action["size"]) is not int or action["size"] < -1:
                    raise ContractError(f"{action_context}.size must be -1 or non-negative")
            elif call == "write":
                data = _string(action["data_base64"], f"{action_context}.data_base64")
                try:
                    base64.b64decode(data, validate=True)
                except (ValueError, TypeError) as exc:
                    raise ContractError(
                        f"{action_context}.data_base64 must be valid base64"
                    ) from exc
            elif type(action["offset"]) is not int or action["offset"] < 0:
                raise ContractError(f"{action_context}.offset must be non-negative")


def _validate_upload_file_case(case: dict[str, Any]) -> None:
    if case["target_profiles"] != ["python-package-cpython312"]:
        raise ContractError("UploadFile cases select only the Python-package profile")
    if case["assets"] != []:
        raise ContractError("UploadFile cases do not use external assets")
    if case["observations"] != ["file-operations"]:
        raise ContractError("UploadFile cases must select file-operations")

    _validate_upload_file_constructor_probes(case["constructor_probes"])

    scenarios = case["scenarios"]
    if not isinstance(scenarios, list) or len(scenarios) < 2:
        raise ContractError("UploadFile scenarios must cover at least two spool thresholds")
    scenario_ids: set[str] = set()
    shared_filename: str | None = None
    shared_initial_size: int | None = None
    shared_actions: list[dict[str, Any]] | None = None
    shared_thread_probe: dict[str, int] | None = None
    injected_error_count = 0
    for index, scenario_value in enumerate(scenarios):
        context = f"UploadFile scenarios[{index}]"
        scenario = _exact(
            scenario_value,
            {
                "scenario_id",
                "max_size",
                "filename",
                "initial_size",
                "actions",
                "thread_probe",
            },
            context,
        )
        scenario_id = _string(scenario["scenario_id"], f"{context}.scenario_id")
        if not scenario_id or scenario_id in scenario_ids:
            raise ContractError(f"{context}.scenario_id must be non-empty and unique")
        scenario_ids.add(scenario_id)
        max_size = scenario["max_size"]
        initial_size = scenario["initial_size"]
        if type(max_size) is not int or max_size < 0:
            raise ContractError(f"{context}.max_size must be a non-negative integer")
        if type(initial_size) is not int or initial_size < 0:
            raise ContractError(f"{context}.initial_size must be a non-negative integer")
        filename = _string(scenario["filename"], f"{context}.filename")
        if shared_filename is None:
            shared_filename = filename
            shared_initial_size = initial_size
        elif filename != shared_filename or initial_size != shared_initial_size:
            raise ContractError(
                "UploadFile threshold scenarios must share metadata and initial size"
            )
        thread_probe = _exact(
            scenario["thread_probe"],
            {"event_loop_release_delay_ms", "watchdog_release_delay_ms"},
            f"{context}.thread_probe",
        )
        loop_delay = thread_probe["event_loop_release_delay_ms"]
        watchdog_delay = thread_probe["watchdog_release_delay_ms"]
        if type(loop_delay) is not int or not 1 <= loop_delay <= 1000:
            raise ContractError(
                f"{context}.thread_probe.event_loop_release_delay_ms must be 1..1000"
            )
        if type(watchdog_delay) is not int or not loop_delay < watchdog_delay <= 5000:
            raise ContractError(
                f"{context}.thread_probe.watchdog_release_delay_ms must exceed the loop "
                "delay and be at most 5000"
            )
        if shared_thread_probe is None:
            shared_thread_probe = thread_probe
        elif thread_probe != shared_thread_probe:
            raise ContractError("UploadFile threshold scenarios must share thread probe settings")
        actions = scenario["actions"]
        if not isinstance(actions, list) or not actions:
            raise ContractError(f"{context}.actions must be a non-empty array")
        action_ids: set[str] = set()
        validated_actions: list[dict[str, Any]] = []
        for action_index, action_value in enumerate(actions):
            action_context = f"{context}.actions[{action_index}]"
            if not isinstance(action_value, dict) or not isinstance(action_value.get("call"), str):
                raise ContractError(f"{action_context} must declare a call")
            call = action_value["call"]
            action_fields = {
                "read": {"action_id", "call", "size"},
                "write": {"action_id", "call", "data_base64"},
                "seek": {"action_id", "call", "offset"},
                "close": {"action_id", "call"},
            }.get(call)
            if action_fields is None:
                raise ContractError(f"{action_context}.call is unsupported")
            if "injected_error" in action_value:
                if call != "read":
                    raise ContractError(
                        f"{action_context}.injected_error is supported only for read"
                    )
                action_fields = action_fields | {"injected_error"}
            action = _exact(action_value, action_fields, action_context)
            action_id = _string(action["action_id"], f"{action_context}.action_id")
            if not action_id or action_id in action_ids:
                raise ContractError(f"{action_context}.action_id must be non-empty and unique")
            action_ids.add(action_id)
            if call == "read":
                size = action["size"]
                if type(size) is not int or size < -1:
                    raise ContractError(f"{action_context}.size must be -1 or non-negative")
                if "injected_error" in action:
                    injected_error = _exact(
                        action["injected_error"],
                        {"class", "message"},
                        f"{action_context}.injected_error",
                    )
                    if injected_error["class"] != "OSError":
                        raise ContractError(
                            f"{action_context}.injected_error.class must be OSError"
                        )
                    _string(
                        injected_error["message"],
                        f"{action_context}.injected_error.message",
                    )
                    injected_error_count += 1
            elif call == "write":
                data_base64 = _string(action["data_base64"], f"{action_context}.data_base64")
                try:
                    base64.b64decode(data_base64, validate=True)
                except (ValueError, TypeError) as exc:
                    raise ContractError(
                        f"{action_context}.data_base64 must be valid base64"
                    ) from exc
            elif call == "seek":
                offset = action["offset"]
                if type(offset) is not int or offset < 0:
                    raise ContractError(f"{action_context}.offset must be non-negative")
            if call == "close" and action_index != len(actions) - 1:
                raise ContractError(f"{action_context} must be the final action")
            validated_actions.append(action)
        if (
            validated_actions[-1]["call"] != "close"
            or sum(action["call"] == "close" for action in validated_actions) != 1
        ):
            raise ContractError(f"{context} must close exactly once as its final action")
        if shared_actions is None:
            shared_actions = validated_actions
        elif validated_actions != shared_actions:
            raise ContractError("UploadFile threshold scenarios must run the same action sequence")

    if injected_error_count != 2:
        raise ContractError(
            "UploadFile threadpool boundary input must inject the same read failure "
            "for both spool thresholds"
        )

    exercised = _upload_file_semantic_coverage(case)
    if set(case["covers"]) != exercised:
        raise ContractError(
            "UploadFile covers must match its input-defined read/write/seek/close workflow "
            f"across rolled and unrolled thresholds; expected {sorted(exercised)}"
        )


def _validate_headers_case(case: dict[str, Any]) -> None:
    mutable = case["surface"] == MUTABLE_HEADERS_SURFACE
    if case["target_profiles"] != ["python-package-cpython312"]:
        raise ContractError("Headers parity currently targets the Python package profile")
    if case["assets"] != []:
        raise ContractError("Headers cases do not use external assets")
    observations = case["observations"]
    if (
        not isinstance(observations, list)
        or not observations
        or any(
            not isinstance(item, str) or item not in HEADERS_OBSERVATIONS for item in observations
        )
        or len(observations) != len(set(observations))
    ):
        raise ContractError("Headers observations must select unique declared results")
    instances = case["instances"]
    if not isinstance(instances, list) or not instances:
        raise ContractError("Headers instances must be a non-empty array")

    exercised: set[str] = set()
    instance_ids: set[str] = set()
    instance_mutability: dict[str, bool] = {}
    instance_pairs: dict[str, list[tuple[bytes, bytes]]] = {}
    instance_raw_constructor: dict[str, bool] = {}
    scope_ids: set[str] = set()
    for index, instance in enumerate(instances):
        context = f"Headers instances[{index}]"
        instance = _exact(instance, {"instance_id", "constructor"}, context)
        instance_id = _string(instance["instance_id"], f"{context}.instance_id")
        if not instance_id or instance_id in instance_ids:
            raise ContractError(f"{context}.instance_id must be non-empty and unique")
        instance_ids.add(instance_id)
        instance_mutability[instance_id] = mutable
        is_scope, raw_pairs = _validate_header_constructor(
            instance["constructor"],
            f"{context}.constructor",
            mutable=mutable,
            exercised=exercised,
        )
        instance_pairs[instance_id] = raw_pairs
        instance_raw_constructor[instance_id] = (
            isinstance(instance["constructor"], dict)
            and instance["constructor"].get("kind") == "raw"
        )
        if is_scope:
            scope_ids.add(instance_id)

    actions = case.get("actions", [])
    if not isinstance(actions, list):
        raise ContractError("Headers actions must be an array")
    action_ids: set[str] = set()
    needs_case_insensitive_lookup = False
    equality_header_operand = False
    equality_non_header_operand = False
    equality_reordered_operand = False
    union_operand_kinds: dict[str, set[str]] = {"__or__": set(), "__ior__": set()}
    nonmapping_union_methods: set[str] = set()
    mutablecopy_bindings: set[str] = set()
    mutated_mutablecopy_bindings: set[str] = set()
    has_scope_mutation = False
    raw_input_append_instances: set[str] = set()
    raw_view_append_instances: set[str] = set()
    no_op_mutations_with_identity: set[str] = set()
    for index, action in enumerate(actions):
        context = f"Headers actions[{index}]"
        if not isinstance(action, dict):
            raise ContractError(f"{context} must be an object")
        action_fields = {"action_id", "receiver", "call", "arguments"}
        if "bind_instance_id" in action:
            action_fields.add("bind_instance_id")
        if "identity_indices" in action:
            action_fields.add("identity_indices")
        action = _exact(action, action_fields, context)
        action_id = _string(action["action_id"], f"{context}.action_id")
        receiver = _string(action["receiver"], f"{context}.receiver")
        call = _string(action["call"], f"{context}.call")
        arguments = action["arguments"]
        if not action_id or action_id in action_ids:
            raise ContractError(f"{context}.action_id must be non-empty and unique")
        action_ids.add(action_id)
        if receiver not in instance_ids:
            raise ContractError(f"{context}.receiver must refer to a preceding instance")
        if call not in HEADERS_ACTIONS or not isinstance(arguments, list):
            raise ContractError(f"{context} must use a declared action and argument array")
        if "identity_indices" in action:
            identity_indices = action["identity_indices"]
            if (
                not isinstance(identity_indices, list)
                or any(
                    type(raw_index) is not int or raw_index < 0 for raw_index in identity_indices
                )
                or len(identity_indices) != len(set(identity_indices))
            ):
                raise ContractError(
                    f"{context}.identity_indices must be unique non-negative integers"
                )
        if call in {
            "iterate",
            "len",
            "dict",
            "repr",
            "raw",
            "keys",
            "values",
            "items",
            "mutablecopy",
        }:
            expected_arity = {0}
        elif call == "get":
            expected_arity = {1, 2}
        elif call == "__setitem__" or call == "setdefault" or call == "append":
            expected_arity = {2}
        elif call in {"raw-input-append", "raw-view-append"}:
            expected_arity = {1}
        elif call == "update" or call in {"__or__", "__ior__", "__eq__"}:
            expected_arity = {1}
        else:
            expected_arity = {1}
        if len(arguments) not in expected_arity:
            raise ContractError(f"{context}.arguments has invalid arity for {call}")
        argument_kinds = [
            _validate_header_argument(value, instance_ids, f"{context}.arguments[{arg_index}]")
            for arg_index, value in enumerate(arguments)
        ]
        if call in {"raw-input-append", "raw-view-append"}:
            if call == "raw-input-append" and not instance_raw_constructor[receiver]:
                raise ContractError(f"{context} requires a raw-list constructor")
            added_pairs = _validate_header_pairs(arguments[0], f"{context}.arguments[0]")
            if len(added_pairs) != 1:
                raise ContractError(f"{context}.arguments[0] must contain exactly one raw pair")
            if call == "raw-input-append":
                raw_input_append_instances.add(receiver)
                instance_pairs[receiver].extend(added_pairs)
            else:
                raw_view_append_instances.add(receiver)
                if mutable:
                    instance_pairs[receiver].extend(added_pairs)
        if call in {"__contains__", "__getitem__", "get", "getlist"} and arguments:
            key = arguments[0]
            if not isinstance(key, str):
                raise ContractError(f"{context}.arguments[0] must be a string header name")
            if key.lower() != key:
                needs_case_insensitive_lookup = True
        if call in {"getlist", "keys", "values", "items", "iterate", "len", "dict"}:
            exercised.add(
                "starlette.datastructures.Headers.duplicate-order-getlist-and-mapping-views"
            )
        if call == "__eq__":
            if argument_kinds[0] == "headers":
                equality_header_operand = True
                other_id = arguments[0]["instance_id"]
                left_pairs = instance_pairs.get(receiver, [])
                right_pairs = instance_pairs.get(other_id, [])
                equality_reordered_operand = left_pairs != right_pairs and sorted(
                    left_pairs
                ) == sorted(right_pairs)
            else:
                equality_non_header_operand = True
        if call == "repr":
            exercised.add("starlette.datastructures.Headers.representation")
        if call == "__setitem__" and instance_mutability[receiver]:
            exercised.add(
                "starlette.datastructures.MutableHeaders.set-replaces-and-collapses-duplicates-in-place"
            )
        elif call == "setdefault" and instance_mutability[receiver]:
            exercised.add(
                "starlette.datastructures.MutableHeaders.setdefault-preserves-existing-and-appends-new"
            )
        elif call == "__delitem__" and instance_mutability[receiver]:
            exercised.add("starlette.datastructures.MutableHeaders.delete-removes-all-matches")
        elif call == "update" and instance_mutability[receiver]:
            exercised.add("starlette.datastructures.MutableHeaders.update-uses-set-semantics")
        elif call == "append" and instance_mutability[receiver]:
            exercised.add(
                "starlette.datastructures.MutableHeaders.append-preserves-duplicates-and-order"
            )
        elif call in {"__or__", "__ior__"} and instance_mutability[receiver]:
            union_operand_kinds[call].add(argument_kinds[0] or "scalar")
            if argument_kinds[0] == "nonmapping":
                nonmapping_union_methods.add(call)

        if instance_mutability[receiver] and "identity_indices" in action:
            tracked_indices = action["identity_indices"]
            tracks_all_pairs = tracked_indices == list(range(len(instance_pairs[receiver])))
            if tracks_all_pairs and call == "__delitem__" and isinstance(arguments[0], str):
                key = arguments[0].lower().encode("latin-1")
                if all(raw_key != key for raw_key, _ in instance_pairs[receiver]):
                    no_op_mutations_with_identity.add("delete-absent")
            elif tracks_all_pairs and call == "setdefault" and isinstance(arguments[0], str):
                key = arguments[0].lower().encode("latin-1")
                if any(raw_key == key for raw_key, _ in instance_pairs[receiver]):
                    no_op_mutations_with_identity.add("setdefault-existing")
            elif (
                tracks_all_pairs
                and call == "update"
                and argument_kinds[0] == "mapping"
                and arguments[0]["items"] == []
            ):
                no_op_mutations_with_identity.add("empty-update")

        if receiver in scope_ids and call in {
            "__setitem__",
            "__delitem__",
            "setdefault",
            "update",
            "append",
            "__ior__",
        }:
            has_scope_mutation = True
        if receiver in mutablecopy_bindings and call in {
            "__setitem__",
            "__delitem__",
            "setdefault",
            "update",
            "append",
        }:
            mutated_mutablecopy_bindings.add(receiver)
        if "bind_instance_id" in action:
            binding = _string(action["bind_instance_id"], f"{context}.bind_instance_id")
            if not binding or binding in instance_ids:
                raise ContractError(f"{context}.bind_instance_id must be new and non-empty")
            instance_ids.add(binding)
            if call == "mutablecopy":
                mutablecopy_bindings.add(binding)
            instance_mutability[binding] = (
                True if call in {"mutablecopy", "__or__"} else instance_mutability[receiver]
            )
            instance_pairs[binding] = list(instance_pairs.get(receiver, []))
            instance_raw_constructor[binding] = False
            if call == "mutablecopy":
                instance_mutability[binding] = True
    if needs_case_insensitive_lookup:
        exercised.add("starlette.datastructures.Headers.case-insensitive-lookup")
    if equality_header_operand and equality_non_header_operand and equality_reordered_operand:
        exercised.add("starlette.datastructures.Headers.equality-order-and-type")
    if union_operand_kinds["__or__"] >= {"mapping", "headers"}:
        exercised.add("starlette.datastructures.MutableHeaders.union.mapping-and-header-operands")
    if union_operand_kinds["__ior__"] >= {"mapping", "headers"}:
        exercised.add(
            "starlette.datastructures.MutableHeaders.inplace-union.mapping-and-header-operands"
        )
    if nonmapping_union_methods == {"__or__", "__ior__"}:
        exercised.add(
            "starlette.datastructures.MutableHeaders.union-and-inplace-union-nonmapping-error"
        )
    if mutablecopy_bindings & mutated_mutablecopy_bindings and "instance-snapshots" in observations:
        exercised.add(
            "starlette.datastructures.Headers.mutablecopy-independent-duplicate-preserving-copy"
        )
    if scope_ids and "scope-snapshots" in observations and has_scope_mutation:
        exercised.add("starlette.datastructures.MutableHeaders.scope-aliasing")
    if raw_input_append_instances & raw_view_append_instances and {
        "action-trace",
        "instance-snapshots",
    } <= set(observations):
        exercised.add(
            "starlette.datastructures.MutableHeaders.raw-list-input-and-view-aliasing"
            if mutable
            else "starlette.datastructures.Headers.raw-list-input-alias-and-copy-view"
        )
    if no_op_mutations_with_identity >= {
        "delete-absent",
        "setdefault-existing",
        "empty-update",
    }:
        exercised.add(
            "starlette.datastructures.MutableHeaders.no-op-mutation-preserves-raw-pair-identities"
        )
    if (
        mutablecopy_bindings
        and any(
            isinstance(action, dict)
            and action.get("call") == "mutablecopy"
            and "identity_indices" in action
            and "bind_instance_id" in action
            for action in actions
        )
        and {"action-trace", "instance-snapshots"} <= set(observations)
    ):
        exercised.add("starlette.datastructures.Headers.mutablecopy-retains-pair-tuple-identities")
    unexercised = set(case["covers"]) - exercised
    if unexercised:
        raise ContractError(
            f"Headers case claims requirements not exercised by its input: {sorted(unexercised)}"
        )


def _url_scope_value(value: Any) -> dict[str, Any]:
    allowed = {"scheme", "server", "path", "query_string_base64", "headers_base64_pairs"}
    required = {"path", "headers_base64_pairs"}
    if not isinstance(value, dict) or required - set(value) or set(value) - allowed:
        raise ContractError("URL scope input must contain only the declared scope fields")
    scope: dict[str, Any] = {"path": _string(value["path"], "URL scope path")}
    if "scheme" in value:
        scope["scheme"] = _string(value["scheme"], "URL scope scheme")
    if "server" in value:
        server = value["server"]
        if (
            not isinstance(server, list)
            or len(server) != 2
            or not isinstance(server[0], str)
            or not isinstance(server[1], int)
            or isinstance(server[1], bool)
            or not 0 <= server[1] <= 65535
        ):
            raise ContractError("URL scope server must be a host and valid port pair")
        scope["server"] = (server[0], server[1])
    if "query_string_base64" in value:
        try:
            query_string = base64.b64decode(value["query_string_base64"], validate=True)
            query_string.decode("utf-8")
        except (ValueError, TypeError, UnicodeDecodeError) as exc:
            raise ContractError(
                "URL scope query string must be valid base64-encoded UTF-8"
            ) from exc
        scope["query_string"] = query_string
    else:
        scope["query_string"] = b""
    headers = value["headers_base64_pairs"]
    if not isinstance(headers, list):
        raise ContractError("URL scope headers must be a base64 pair array")
    decoded_headers = []
    for index, pair in enumerate(headers):
        if not isinstance(pair, list) or len(pair) != 2:
            raise ContractError(f"URL scope headers[{index}] must contain name and value")
        try:
            decoded_headers.append(
                (
                    base64.b64decode(pair[0], validate=True),
                    base64.b64decode(pair[1], validate=True),
                )
            )
        except (ValueError, TypeError) as exc:
            raise ContractError(f"URL scope headers[{index}] must be valid base64") from exc
    scope["headers"] = decoded_headers
    return scope


def _url_scope_semantic_coverage(scope: dict[str, Any]) -> set[str]:
    coverage = {URL_SCOPE_REQUIREMENTS["from-scope"]}
    host_header = next(
        (value.decode("latin-1") for name, value in scope["headers"] if name == b"host"),
        None,
    )
    valid_host = (
        host_header is not None
        and re.fullmatch(
            r"([a-z0-9.-]+|\[[a-f0-9]*:[a-f0-9.:]+\])(?::[0-9]+)?",
            host_header,
            re.IGNORECASE,
        )
        is not None
    )
    if host_header is not None and not valid_host and scope.get("server") is not None:
        coverage.add(URL_SCOPE_REQUIREMENTS["invalid-host-fallback"])

    path = scope["path"]
    path_contains_authority = (
        path.startswith("//")
        or "@" in path
        or re.match(r"^[a-z][a-z0-9+.-]*://", path, re.IGNORECASE) is not None
    )
    if path_contains_authority and (valid_host or scope.get("server") is not None):
        coverage.add(URL_SCOPE_REQUIREMENTS["authority-in-path-containment"])
    return coverage


def _validate_url_scope_case(case: dict[str, Any]) -> None:
    if case["target_profiles"] != ["python-package-cpython312"]:
        raise ContractError("URL scope parity currently targets the Python package profile")
    if case["assets"] != [] or case["observations"] != ["url-record"]:
        raise ContractError("URL scope cases use no assets and select url-record")
    scope = _url_scope_value(case["scope"])
    if set(case["covers"]) != _url_scope_semantic_coverage(scope):
        raise ContractError("URL scope coverage must be derived from the supplied scope")


def _validate_query_params_source(value: Any, context: str) -> dict[str, Any]:
    if not isinstance(value, dict) or not isinstance(value.get("kind"), str):
        raise ContractError(f"{context} must select a QueryParams constructor input")
    kind = value["kind"]
    if kind == "string":
        source = _exact(value, {"kind", "value"}, context)
        if not isinstance(source["value"], str):
            raise ContractError(f"{context}.value must be a string")
        return source
    if kind == "bytes":
        source = _exact(value, {"kind", "value_base64"}, context)
        if not isinstance(source["value_base64"], str):
            raise ContractError(f"{context}.value_base64 must be a string")
        try:
            base64.b64decode(source["value_base64"], validate=True)
        except (ValueError, TypeError) as exc:
            raise ContractError(f"{context}.value_base64 is invalid base64") from exc
        return source
    if kind == "empty":
        return _exact(value, {"kind"}, context)
    if kind in {"pairs", "mapping", "copy"}:
        source = _exact(
            value,
            {"kind", "items", "kwargs"} if kind == "pairs" else {"kind", "items"},
            context,
        )
        items = source["items"]
        if not isinstance(items, list):
            raise ContractError(f"{context}.items must be an array")
        seen: set[str] = set()
        for index, pair in enumerate(items):
            if not isinstance(pair, list) or len(pair) != 2:
                raise ContractError(f"{context}.items[{index}] must be a two-item array")
            key, item = pair
            if kind == "mapping":
                if not isinstance(key, str):
                    raise ContractError(f"{context}.items[{index}][0] must be a string")
                if key in seen:
                    raise ContractError(f"{context}.items has duplicate mapping key {key!r}")
                seen.add(key)
            if not isinstance(key, (str, int, float, bool)) and key is not None:
                raise ContractError(f"{context}.items[{index}][0] must be a scalar")
            if not isinstance(item, (str, int, float, bool)) and item is not None:
                raise ContractError(f"{context}.items[{index}][1] must be a scalar")
        if kind == "pairs":
            kwargs = source["kwargs"]
            if not isinstance(kwargs, list):
                raise ContractError(f"{context}.kwargs must be an array")
            kwarg_names: set[str] = set()
            for index, pair in enumerate(kwargs):
                if not isinstance(pair, list) or len(pair) != 2:
                    raise ContractError(f"{context}.kwargs[{index}] must be a two-item array")
                key, item = pair
                if not isinstance(key, str):
                    raise ContractError(f"{context}.kwargs[{index}][0] must be a string")
                if key in kwarg_names:
                    raise ContractError(f"{context}.kwargs has duplicate key {key!r}")
                kwarg_names.add(key)
                if not isinstance(item, (str, int, float, bool)) and item is not None:
                    raise ContractError(f"{context}.kwargs[{index}][1] must be a scalar")
        return source
    raise ContractError(f"{context}.kind is outside the declared QueryParams constructors")


def _validate_query_params_case(case: dict[str, Any]) -> None:
    if case["assets"] != [] or case["observations"] != ["snapshot"]:
        raise ContractError("QueryParams cases use no assets and select the snapshot")
    _validate_query_params_source(case["source"], "QueryParams source")
    comparison = case["comparison"]
    literal_comparison = isinstance(comparison, dict) and comparison.get("kind") == "literal"
    if literal_comparison:
        comparison = _exact(
            comparison,
            {"kind", "value"},
            "QueryParams literal comparison",
        )
        if not isinstance(comparison["value"], str):
            raise ContractError("QueryParams literal comparison value must be a string")
        if case["target_profiles"] != ["python-package-cpython312"]:
            raise ContractError(
                "QueryParams comparisons against non-QueryParams values select the Python package"
            )
    else:
        if case["target_profiles"] != ["rust-native-local", "python-package-cpython312"]:
            raise ContractError("QueryParams parity requires both declared targets")
        if comparison is not None:
            _validate_query_params_source(comparison, "QueryParams comparison")
    probe_keys = case["probe_keys"]
    if not isinstance(probe_keys, list) or any(not isinstance(key, str) for key in probe_keys):
        raise ContractError("QueryParams probe_keys must contain strings")


def _validate_multidict_source(value: Any, context: str) -> dict[str, Any]:
    if not isinstance(value, dict) or not isinstance(value.get("kind"), str):
        raise ContractError(f"{context} must select a MultiDict constructor input")
    kind = value["kind"]
    if kind == "empty":
        return _exact(value, {"kind"}, context)
    if kind not in {"pairs", "mapping", "copy"}:
        raise ContractError(f"{context}.kind is outside the declared MultiDict constructors")
    fields = {"kind", "items", "kwargs"} if kind == "pairs" else {"kind", "items"}
    source = _exact(value, fields, context)
    items = source["items"]
    if not isinstance(items, list):
        raise ContractError(f"{context}.items must be an array")
    seen: set[str] = set()
    duplicate = False
    for index, pair in enumerate(items):
        if not isinstance(pair, list) or len(pair) != 2:
            raise ContractError(f"{context}.items[{index}] must be a two-item array")
        key, item = pair
        if not isinstance(key, str):
            raise ContractError(f"{context}.items[{index}][0] must be a string")
        _multidict_json_scalar(item, f"{context}.items[{index}][1]")
        duplicate = duplicate or key in seen
        seen.add(key)
        if kind == "mapping" and duplicate:
            raise ContractError(f"{context}.items must have unique mapping keys")
    if kind == "pairs":
        kwargs = source["kwargs"]
        if not isinstance(kwargs, list):
            raise ContractError(f"{context}.kwargs must be an array")
        keyword_names: set[str] = set()
        for index, pair in enumerate(kwargs):
            if not isinstance(pair, list) or len(pair) != 2 or not isinstance(pair[0], str):
                raise ContractError(f"{context}.kwargs[{index}] must be a string-keyed pair")
            key, item = pair
            if key in keyword_names:
                raise ContractError(f"{context}.kwargs has duplicate key {key!r}")
            keyword_names.add(key)
            _multidict_json_scalar(item, f"{context}.kwargs[{index}][1]")
    return source


def _multidict_json_scalar(value: Any, context: str) -> None:
    if value is not None and type(value) not in {bool, int, float, str}:
        raise ContractError(f"{context} must be a JSON scalar")


def _validate_multidict_case(case: dict[str, Any]) -> None:
    typing_contract = case.get("typing_contract")
    if typing_contract is None:
        if case["target_profiles"] != ["rust-native-local", "python-package-cpython312"]:
            raise ContractError("MultiDict behavior cases require both declared target profiles")
    elif case["target_profiles"] != ["python-package-cpython312"]:
        raise ContractError("MultiDict typing cases select only the Python-package profile")
    if case["assets"] != [] or case["observations"] != ["mutation-sequence"]:
        raise ContractError("MultiDict cases use no assets and select mutation-sequence")
    if not case["case_id"].startswith("starlette.datastructures.MultiDict.mutation-sequence."):
        raise ContractError("MultiDict case IDs must bind to the public mutation operation")
    source = _validate_multidict_source(case["source"], "MultiDict source")
    comparison = case["comparison"]
    if comparison is not None:
        _validate_multidict_source(comparison, "MultiDict comparison")
    probe_keys = case["probe_keys"]
    if not isinstance(probe_keys, list) or any(not isinstance(key, str) for key in probe_keys):
        raise ContractError("MultiDict probe_keys must contain strings")

    actions = case["actions"]
    if not isinstance(actions, list):
        raise ContractError("MultiDict actions must be an array")
    action_ids: set[str] = set()
    methods: set[str] = set()
    for index, action_value in enumerate(actions):
        context = f"MultiDict actions[{index}]"
        action = _exact(action_value, {"action_id", "method", "args", "kwargs"}, context)
        action_id = _string(action["action_id"], f"{context}.action_id")
        if action_id in action_ids:
            raise ContractError("MultiDict action IDs must be unique")
        action_ids.add(action_id)
        method = _string(action["method"], f"{context}.method")
        if method not in MULTIDICT_METHODS:
            raise ContractError(f"{context}.method is not a declared MultiDict operation")
        methods.add(method)
        args = action["args"]
        kwargs = action["kwargs"]
        if not isinstance(args, list) or not isinstance(kwargs, dict):
            raise ContractError(f"{context}.args and kwargs must be arrays and objects")
        if method in {"__setitem__", "append", "setlist"} and len(args) != 2:
            raise ContractError(f"{context} requires two positional values")
        if method in {"__delitem__", "poplist"} and len(args) != 1:
            raise ContractError(f"{context} requires one positional key")
        if method in {"popitem", "clear"} and (args or kwargs):
            raise ContractError(f"{context} does not accept arguments")
        if method == "pop" and not 1 <= len(args) <= 2:
            raise ContractError(f"{context} requires a key and optional default")
        if method == "setdefault" and not 1 <= len(args) <= 2:
            raise ContractError(f"{context} requires a key and optional default")
        if method == "update" and len(args) > 1:
            raise ContractError(f"{context} accepts at most one positional source")
        if method in {"pop", "setdefault"} and set(kwargs) - {"default"}:
            raise ContractError(f"{context}.kwargs may contain only default")
        if method not in {"pop", "setdefault", "update"} and kwargs:
            raise ContractError(f"{context} does not accept keyword values")
        for argument_index, argument in enumerate(args):
            if method == "setlist" and argument_index == 1:
                if not isinstance(argument, list):
                    raise ContractError(f"{context}.args[1] must be an array")
                for item_index, item in enumerate(argument):
                    _multidict_json_scalar(item, f"{context}.args[1][{item_index}]")
            elif method == "update" and argument_index == 0:
                if isinstance(argument, dict):
                    _exact(argument, {"kind"}, f"{context}.args[0]")
                    if argument["kind"] != "receiver":
                        raise ContractError(
                            f"{context}.args[0].kind must select the current receiver"
                        )
                elif isinstance(argument, list):
                    _validate_multidict_source(
                        {"kind": "pairs", "items": argument, "kwargs": []},
                        f"{context}.args[0]",
                    )
                else:
                    raise ContractError(
                        f"{context}.args[0] must be ordered pairs or the current receiver"
                    )
            elif isinstance(argument, list):
                if method == "setlist":
                    continue
                raise ContractError(f"{context}.args[{argument_index}] must be a scalar")
            else:
                _multidict_json_scalar(argument, f"{context}.args[{argument_index}]")
        for key, value in kwargs.items():
            if not isinstance(key, str):
                raise ContractError(f"{context}.kwargs keys must be strings")
            if method == "update" and key == "default":
                raise ContractError(f"{context}.kwargs cannot use default for update")
            _multidict_json_scalar(value, f"{context}.kwargs[{key!r}]")

    expected_covers = {MULTIDICT_REQUIREMENTS["constructor"]}
    if source["kind"] in {"pairs", "copy"} and any(
        sum(pair[0] == key for pair in source["items"]) > 1 for key, _ in source["items"]
    ):
        expected_covers.add(MULTIDICT_REQUIREMENTS["mapping_views"])
    if {"__setitem__", "__delitem__"} <= methods:
        expected_covers.add(MULTIDICT_REQUIREMENTS["item_mutation"])
    if {"pop", "popitem", "poplist"} <= methods:
        expected_covers.add(MULTIDICT_REQUIREMENTS["pop_family"])
    if {"clear", "setlist"} <= methods:
        expected_covers.add(MULTIDICT_REQUIREMENTS["clear_setlist"])
    if {"setdefault", "append"} <= methods:
        expected_covers.add(MULTIDICT_REQUIREMENTS["setdefault_append"])
    if "update" in methods:
        expected_covers.add(MULTIDICT_REQUIREMENTS["update"])
    if comparison is not None:
        expected_covers.add(MULTIDICT_REQUIREMENTS["repr_equality"])
    if typing_contract is not None:
        contract = _exact(typing_contract, {"probes"}, "MultiDict typing contract")
        probes = contract["probes"]
        if (
            not isinstance(probes, list)
            or not probes
            or any(
                not isinstance(probe, str) or probe not in MULTIDICT_TYPING_PROBES
                for probe in probes
            )
            or len(probes) != len(set(probes))
        ):
            raise ContractError("MultiDict typing probes must be unique declared consumer checks")
        expected_covers.add(MULTIDICT_REQUIREMENTS["generic_typing"])
    covers = case["covers"]
    if (
        not isinstance(covers, list)
        or any(not isinstance(requirement, str) for requirement in covers)
        or len(covers) != len(set(covers))
        or set(covers) != expected_covers
    ):
        raise ContractError(
            "MultiDict covers must be derived from the supplied constructors and actions"
        )


def _validate_comma_separated_strings_case(case: dict[str, Any]) -> None:
    inputs = case["inputs"]
    if not isinstance(inputs, list) or not inputs:
        raise ContractError("CommaSeparatedStrings inputs must be a non-empty array")

    kinds = {
        "string",
        "shlex-edge-string",
        "unicode-repr-string",
        "surrogate-string",
        "malformed-string",
        "sequence",
        "surrogate-sequence",
        "sequence-subclass",
    }
    exercised: set[str] = set()
    has_valid_input = False
    has_sequence_subclass = False
    has_python_error_boundary = False
    has_lone_surrogate = False

    def contains_lone_surrogate(value: str) -> bool:
        return any(0xD800 <= ord(character) <= 0xDFFF for character in value)

    for index, raw_input in enumerate(inputs):
        context = f"CommaSeparatedStrings inputs[{index}]"
        if not isinstance(raw_input, dict) or not isinstance(raw_input.get("kind"), str):
            raise ContractError(f"{context} must select a declared constructor input")
        kind = raw_input["kind"]
        if kind not in kinds:
            raise ContractError(f"{context}.kind is unsupported")
        if kind in {
            "string",
            "shlex-edge-string",
            "unicode-repr-string",
            "surrogate-string",
            "malformed-string",
        }:
            item = _exact(raw_input, {"kind", "value"}, context)
            _string(item["value"], f"{context}.value")
            contains_surrogate = contains_lone_surrogate(item["value"])
            if kind == "surrogate-string":
                if not contains_surrogate:
                    raise ContractError(f"{context}.value must include a lone surrogate")
                has_lone_surrogate = True
            elif contains_surrogate:
                raise ContractError(f"{context} must use the explicit surrogate-string input kind")
            if kind == "malformed-string":
                has_python_error_boundary = True
                exercised.add(COMMA_SEPARATED_STRINGS_REQUIREMENTS["malformed"])
            else:
                has_valid_input = True
                exercised.add(COMMA_SEPARATED_STRINGS_REQUIREMENTS["constructor_string"])
                if kind == "shlex-edge-string":
                    exercised.add(COMMA_SEPARATED_STRINGS_REQUIREMENTS["shlex_edges"])
                elif kind == "unicode-repr-string":
                    unicode_probes = {"\u200b", "\u0378", "\U000e0001"}
                    if not unicode_probes <= set(item["value"]):
                        raise ContractError(
                            f"{context}.value must include the declared format, unassigned, and tag characters"
                        )
                    exercised.add(COMMA_SEPARATED_STRINGS_REQUIREMENTS["unicode_repr"])
        elif kind in {"sequence", "surrogate-sequence"}:
            item = _exact(raw_input, {"kind", "items"}, context)
            sequence_items = item["items"]
            if not isinstance(sequence_items, list) or any(
                not isinstance(value, str) for value in sequence_items
            ):
                raise ContractError(f"{context}.items must be an array of strings")
            contains_surrogate = any(contains_lone_surrogate(value) for value in sequence_items)
            if kind == "surrogate-sequence":
                if not contains_surrogate:
                    raise ContractError(f"{context}.items must include a lone surrogate")
                has_lone_surrogate = True
            elif contains_surrogate:
                raise ContractError(
                    f"{context} must use the explicit surrogate-sequence input kind"
                )
            has_valid_input = True
            exercised.add(COMMA_SEPARATED_STRINGS_REQUIREMENTS["constructor_sequence"])
        else:
            item = _exact(raw_input, {"kind", "items", "repr_suffixes"}, context)
            sequence_items = item["items"]
            repr_suffixes = item["repr_suffixes"]
            if (
                not isinstance(sequence_items, list)
                or not sequence_items
                or any(not isinstance(value, str) for value in sequence_items)
                or not isinstance(repr_suffixes, list)
                or len(repr_suffixes) != len(sequence_items)
                or any(not isinstance(value, str) for value in repr_suffixes)
            ):
                raise ContractError(
                    f"{context} must provide matching non-empty string items and repr suffixes"
                )
            has_valid_input = True
            has_sequence_subclass = True
            exercised.add(COMMA_SEPARATED_STRINGS_REQUIREMENTS["constructor_sequence"])
            exercised.add(COMMA_SEPARATED_STRINGS_REQUIREMENTS["string_subclass"])
            if any(map(contains_lone_surrogate, [*sequence_items, *repr_suffixes])):
                has_lone_surrogate = True

    if has_lone_surrogate:
        exercised.add(COMMA_SEPARATED_STRINGS_REQUIREMENTS["lone_surrogate"])

    index_probes = case["index_probes"]
    if not isinstance(index_probes, list) or any(type(index) is not int for index in index_probes):
        raise ContractError("CommaSeparatedStrings index_probes must contain integers")
    if has_valid_input:
        if not index_probes:
            raise ContractError("valid CommaSeparatedStrings inputs require index probes")
        exercised.add(COMMA_SEPARATED_STRINGS_REQUIREMENTS["sequence_observations"])
        exercised.add(COMMA_SEPARATED_STRINGS_REQUIREMENTS["string_and_repr"])
    elif index_probes:
        raise ContractError("malformed CommaSeparatedStrings inputs do not select index probes")

    if case["assets"] != [] or case["observations"] != ["snapshot"]:
        raise ContractError("CommaSeparatedStrings cases use no assets and select snapshot")
    expected_profiles = (
        ["python-package-cpython312"]
        if has_sequence_subclass or has_python_error_boundary or has_lone_surrogate
        else ["rust-native-local", "python-package-cpython312"]
    )
    if case["target_profiles"] != expected_profiles:
        raise ContractError("CommaSeparatedStrings target profiles must match its input boundary")
    covers = case["covers"]
    if (
        not isinstance(covers, list)
        or any(not isinstance(requirement, str) for requirement in covers)
        or len(covers) != len(set(covers))
        or set(covers) != exercised
    ):
        raise ContractError(
            "CommaSeparatedStrings covers must match its constructor inputs and selected observations"
        )


def _validate_formdata_value(value: Any, context: str) -> None:
    if isinstance(value, str):
        return
    item = _exact(value, {"kind", "filename", "body_base64", "size"}, context)
    if item["kind"] != "upload-file":
        raise ContractError(f"{context}.kind must be upload-file")
    _string(item["filename"], f"{context}.filename")
    body_base64 = _string(item["body_base64"], f"{context}.body_base64")
    try:
        base64.b64decode(body_base64, validate=True)
    except (ValueError, TypeError) as exc:
        raise ContractError(f"{context}.body_base64 must be valid base64") from exc
    if type(item["size"]) is not int or item["size"] < 0:
        raise ContractError(f"{context}.size must be a non-negative integer")


def _validate_formdata_entries(entries: Any, context: str) -> None:
    if not isinstance(entries, list):
        raise ContractError(f"{context} must be an array of key/value pairs")
    for index, raw_entry in enumerate(entries):
        entry_context = f"{context}[{index}]"
        if not isinstance(raw_entry, list) or len(raw_entry) != 2:
            raise ContractError(f"{entry_context} must contain a key and value")
        _string(raw_entry[0], f"{entry_context}[0]")
        _validate_formdata_value(raw_entry[1], f"{entry_context}[1]")


def _validate_formdata_argument(spec: Any, context: str, *, allow_primary: bool) -> None:
    if not isinstance(spec, dict) or not isinstance(spec.get("kind"), str):
        raise ContractError(f"{context} must select a declared FormData input kind")
    kind = spec["kind"]
    if kind in {"pairs", "mapping"}:
        item = _exact(spec, {"kind", "entries"}, context)
        _validate_formdata_entries(item["entries"], f"{context}.entries")
    elif kind == "primary" and allow_primary:
        _exact(spec, {"kind"}, context)
    elif kind == "form-data":
        item = _exact(spec, {"kind", "args", "kwargs"}, context)
        args = item["args"]
        if not isinstance(args, list) or len(args) > 1:
            raise ContractError(f"{context}.args must contain at most one constructor input")
        for index, argument in enumerate(args):
            _validate_formdata_argument(
                argument,
                f"{context}.args[{index}]",
                allow_primary=True,
            )
        _validate_formdata_entries(item["kwargs"], f"{context}.kwargs")
        keyword_names = [entry[0] for entry in item["kwargs"]]
        if len(keyword_names) != len(set(keyword_names)):
            raise ContractError(f"{context}.kwargs keys must be unique")
    else:
        raise ContractError(f"{context}.kind is unsupported")


def _validate_formdata_case(case: dict[str, Any]) -> None:
    if case["assets"] != [] or case["observations"] != ["multidict-lookups"]:
        raise ContractError("FormData cases use no assets and select multidict-lookups")
    if case["target_profiles"] != ["python-package-cpython312"]:
        raise ContractError("FormData constructor parity selects the Python package profile")

    constructor = _exact(case["constructor"], {"args", "kwargs"}, "FormData constructor")
    args = constructor["args"]
    if not isinstance(args, list):
        raise ContractError("FormData constructor args must be an array")
    for index, argument in enumerate(args):
        _validate_formdata_argument(
            argument,
            f"FormData constructor args[{index}]",
            allow_primary=False,
        )
    _validate_formdata_entries(constructor["kwargs"], "FormData constructor kwargs")
    keyword_names = [entry[0] for entry in constructor["kwargs"]]
    if len(keyword_names) != len(set(keyword_names)):
        raise ContractError("FormData constructor kwargs keys must be unique")

    probe_keys = case["probe_keys"]
    if not isinstance(probe_keys, list) or any(not isinstance(key, str) for key in probe_keys):
        raise ContractError("FormData probe_keys must contain strings")
    equalities = case["equalities"]
    if not isinstance(equalities, list):
        raise ContractError("FormData equalities must be an array")
    for index, raw_equality in enumerate(equalities):
        context = f"FormData equalities[{index}]"
        equality = _exact(raw_equality, {"left", "right"}, context)
        _validate_formdata_argument(equality["left"], f"{context}.left", allow_primary=True)
        _validate_formdata_argument(equality["right"], f"{context}.right", allow_primary=True)

    if len(args) > 1:
        if probe_keys or equalities:
            raise ContractError("FormData constructor-error cases cannot select value observations")
    elif not probe_keys or not equalities:
        raise ContractError("successful FormData constructor cases require probes and equalities")

    if case["covers"] != [FORM_DATA_CONSTRUCTOR_REQUIREMENT]:
        raise ContractError("FormData covers must select constructor-input-semantics")


def _validate_authentication_case(case: dict[str, Any]) -> None:
    if case["target_profiles"] != ["python-package-cpython312"]:
        raise ContractError("authentication parity currently targets the Python package profile")
    if case["assets"] != []:
        raise ContractError("authentication cases do not use external assets")

    operation = (case["surface"], case["operation"])
    exercised: set[str] = set()
    if operation == ("starlette.authentication", "value-operations"):
        if case["observations"] != ["actions"]:
            raise ContractError("authentication value operations must select actions")
        actions = case["actions"]
        if not isinstance(actions, list) or not actions:
            raise ContractError("authentication value operations require actions")
        for index, raw_action in enumerate(actions):
            context = f"authentication actions[{index}]"
            if (
                not isinstance(raw_action, dict)
                or not isinstance(raw_action.get("action"), str)
                or raw_action["action"] not in {"credentials", "user-properties"}
            ):
                raise ContractError(f"{context} must select a declared value action")
            action = raw_action["action"]
            if action == "credentials":
                item = _exact(
                    raw_action,
                    {"action", "scopes"}
                    | ({"mutate_source_scopes"} if "mutate_source_scopes" in raw_action else set()),
                    context,
                )
                scopes = item["scopes"]
                if scopes is None:
                    if "mutate_source_scopes" in item:
                        raise ContractError(f"{context} cannot mutate a null source scope sequence")
                    exercised.add("starlette.authentication.AuthCredentials.default-empty-scopes")
                elif isinstance(scopes, list) and all(isinstance(scope, str) for scope in scopes):
                    if "mutate_source_scopes" in item and (
                        not isinstance(item["mutate_source_scopes"], list)
                        or any(not isinstance(scope, str) for scope in item["mutate_source_scopes"])
                    ):
                        raise ContractError(
                            f"{context}.mutate_source_scopes must be a string array"
                        )
                    exercised.add(
                        "starlette.authentication.AuthCredentials.scope-sequence-construction"
                    )
                else:
                    raise ContractError(f"{context}.scopes must be null or a string array")
                continue
            if raw_action.get("user") == "simple":
                item = _exact(raw_action, {"action", "user", "username"}, context)
                _string(item["username"], f"{context}.username")
                exercised.add("starlette.authentication.SimpleUser.properties")
            elif raw_action.get("user") == "unauthenticated":
                _exact(raw_action, {"action", "user"}, context)
                exercised.add("starlette.authentication.UnauthenticatedUser.properties")
            elif raw_action.get("user") == "base":
                _exact(raw_action, {"action", "user"}, context)
                exercised.add("starlette.authentication.BaseUser.abstract-properties")
            elif raw_action.get("user") == "custom":
                item = _exact(
                    raw_action,
                    {"action", "user", "is_authenticated", "display_name", "identity"},
                    context,
                )
                if not isinstance(item["is_authenticated"], bool):
                    raise ContractError(f"{context}.is_authenticated must be a boolean")
                _string(item["display_name"], f"{context}.display_name")
                _string(item["identity"], f"{context}.identity")
                exercised.add("starlette.authentication.BaseUser.custom-subclass-properties")
            else:
                raise ContractError(f"{context}.user is unsupported")
    elif operation == ("starlette.authentication", "scope-check"):
        if case["observations"] != ["checks"]:
            raise ContractError("authentication scope checks must select checks")
        checks = case["checks"]
        if not isinstance(checks, list) or not checks:
            raise ContractError("authentication scope checks require at least one check")
        for index, raw_check in enumerate(checks):
            check = _exact(
                raw_check,
                {"granted_scopes", "required_scopes"},
                f"authentication checks[{index}]",
            )
            for name, scopes in check.items():
                if not isinstance(scopes, list) or any(
                    not isinstance(scope, str) for scope in scopes
                ):
                    raise ContractError(f"authentication check {name} must be a string array")
            if not check["required_scopes"]:
                exercised.add("starlette.authentication.has_required_scope.empty-requirements")
            elif set(check["required_scopes"]) <= set(check["granted_scopes"]):
                exercised.add("starlette.authentication.has_required_scope.all-scopes-present")
            else:
                exercised.add("starlette.authentication.has_required_scope.missing-scope")
    elif operation == ("starlette.authentication", "decorator-dispatch"):
        if case["observations"] != ["scenarios"]:
            raise ContractError("requires decorator cases must select scenarios")
        scenarios = case["scenarios"]
        if not isinstance(scenarios, list) or not scenarios:
            raise ContractError("requires decorator cases need at least one scenario")
        for index, raw_scenario in enumerate(scenarios):
            context = f"requires scenarios[{index}]"
            if not isinstance(raw_scenario, dict):
                raise ContractError(f"{context} must be an object")
            raw_callable = raw_scenario.get("callable")
            if not isinstance(raw_callable, dict):
                raise ContractError(f"{context}.callable must be an object")
            if raw_callable.get("kind") == "invalid-no-connection-parameter":
                scenario = _exact(raw_scenario, {"callable", "required_scopes"}, context)
                callable_spec = _exact(
                    scenario["callable"],
                    {"kind", "display_name"},
                    f"{context}.callable",
                )
                _string(callable_spec["display_name"], f"{context}.callable.display_name")
                required_scopes = scenario["required_scopes"]
                if not isinstance(required_scopes, list) or any(
                    not isinstance(scope, str) for scope in required_scopes
                ):
                    raise ContractError(f"{context}.required_scopes must be a string array")
                exercised.add("starlette.authentication.requires.invalid-decorator-usage")
                continue
            scenario = _exact(
                raw_scenario,
                {"callable", "required_scopes", "connection"}
                | ({"status_code"} if "status_code" in raw_scenario else set())
                | ({"redirect"} if "redirect" in raw_scenario else set()),
                context,
            )
            callable_spec = _exact(
                scenario["callable"],
                {"kind", "mode", "parameter", "result"},
                f"{context}.callable",
            )
            if (
                callable_spec["kind"] != "endpoint"
                or not isinstance(callable_spec["mode"], str)
                or callable_spec["mode"] not in {"sync", "async"}
                or not isinstance(callable_spec["parameter"], str)
                or callable_spec["parameter"] not in {"request", "websocket"}
                or not isinstance(callable_spec["result"], (str, int, float, bool, type(None)))
            ):
                raise ContractError(f"{context}.callable is outside the declared endpoint forms")
            raw_connection = scenario["connection"]
            if not isinstance(raw_connection, dict):
                raise ContractError(f"{context}.connection must be an object")
            connection = _exact(
                raw_connection,
                {"kind", "auth_scopes"}
                | ({"url"} if "url" in scenario["connection"] else set())
                | ({"routes"} if "routes" in scenario["connection"] else set()),
                f"{context}.connection",
            )
            if not isinstance(connection["kind"], str) or connection["kind"] not in {
                "request",
                "websocket",
            }:
                raise ContractError(f"{context}.connection.kind is unsupported")
            if (callable_spec["parameter"] == "websocket") != (connection["kind"] == "websocket"):
                raise ContractError(f"{context} callable and connection kinds must agree")
            if callable_spec["parameter"] == "websocket" and callable_spec["mode"] != "async":
                raise ContractError(f"{context} WebSocket endpoints must be async")
            if not isinstance(connection["auth_scopes"], list) or any(
                not isinstance(scope, str) for scope in connection["auth_scopes"]
            ):
                raise ContractError(f"{context}.connection.auth_scopes must be a string array")
            required_scopes = scenario["required_scopes"]
            if not isinstance(required_scopes, list) or any(
                not isinstance(scope, str) for scope in required_scopes
            ):
                raise ContractError(f"{context}.required_scopes must be a string array")
            if "status_code" in scenario:
                _validate_nonnegative_integer(scenario["status_code"], f"{context}.status_code")
            if "redirect" in scenario:
                _string(scenario["redirect"], f"{context}.redirect")
                routes = connection.get("routes")
                if not isinstance(routes, list) or not routes:
                    raise ContractError(f"{context} redirects require route inputs")
                route_names = set()
                for route_index, raw_route in enumerate(routes):
                    route = _exact(
                        raw_route,
                        {"name", "path"},
                        f"{context}.connection.routes[{route_index}]",
                    )
                    _string(route["name"], f"{context}.connection.routes[{route_index}].name")
                    if not isinstance(route["path"], str) or not route["path"].startswith("/"):
                        raise ContractError(f"{context}.connection route paths must be absolute")
                    route_names.add(route["name"])
                if scenario["redirect"] not in route_names:
                    raise ContractError(f"{context}.redirect must name an input route")
            authorized = set(required_scopes) <= set(connection["auth_scopes"])
            if connection["kind"] == "websocket":
                if not authorized:
                    exercised.add("starlette.authentication.requires.websocket-denied-close")
                    if scenario.get("status_code", 403) != 403:
                        exercised.add(
                            "starlette.authentication.requires.websocket-custom-status-ignored"
                        )
            else:
                if len(required_scopes) > 1:
                    exercised.add("starlette.authentication.requires.multiple-required-scopes")
                if "redirect" in scenario and not authorized:
                    exercised.add("starlette.authentication.requires.redirect-response")
                elif authorized and callable_spec["mode"] == "sync":
                    exercised.add("starlette.authentication.requires.sync-authorized-call")
                elif authorized and callable_spec["mode"] == "async":
                    exercised.add("starlette.authentication.requires.async-authorized-call")
                elif callable_spec["mode"] == "sync":
                    exercised.add("starlette.authentication.requires.sync-denied-error")
                else:
                    exercised.add("starlette.authentication.requires.async-denied-error")
    else:
        if case["observations"] != ["scenarios"]:
            raise ContractError("AuthenticationMiddleware cases must select scenarios")
        scenarios = case["scenarios"]
        if not isinstance(scenarios, list) or not scenarios:
            raise ContractError("AuthenticationMiddleware cases need at least one scenario")
        for index, raw_scenario in enumerate(scenarios):
            context = f"AuthenticationMiddleware scenarios[{index}]"
            scenario_keys = {"scope_type", "backend", "error_handler"}
            if isinstance(raw_scenario, dict) and "error_response" in raw_scenario:
                scenario_keys.add("error_response")
            if isinstance(raw_scenario, dict) and "application_response" in raw_scenario:
                scenario_keys.add("application_response")
            scenario = _exact(raw_scenario, scenario_keys, context)
            if not isinstance(scenario["scope_type"], str) or scenario["scope_type"] not in {
                "http",
                "websocket",
                "lifespan",
            }:
                raise ContractError(f"{context}.scope_type is unsupported")
            if not isinstance(scenario["error_handler"], str) or scenario["error_handler"] not in {
                "default",
                "custom-response",
            }:
                raise ContractError(f"{context}.error_handler is unsupported")
            error_response = scenario.get("error_response")
            if scenario["error_handler"] == "custom-response":
                if error_response is None:
                    raise ContractError(
                        f"{context}.error_response is required for a custom response handler"
                    )
                if not isinstance(error_response, dict) or "kind" not in error_response:
                    raise ContractError(f"{context}.error_response must describe a response")
                if error_response["kind"] == "json-error":
                    response = _exact(
                        error_response,
                        {"kind", "status_code", "error_field"},
                        f"{context}.error_response",
                    )
                    _validate_nonnegative_integer(
                        response["status_code"], f"{context}.error_response.status_code"
                    )
                    if not 100 <= response["status_code"] <= 599:
                        raise ContractError(
                            f"{context}.error_response.status_code must be an HTTP status"
                        )
                    _string(response["error_field"], f"{context}.error_response.error_field")
                elif error_response["kind"] == "plain-text-error":
                    response = _exact(
                        error_response,
                        {"kind", "status_code", "prefix"},
                        f"{context}.error_response",
                    )
                    _validate_nonnegative_integer(
                        response["status_code"], f"{context}.error_response.status_code"
                    )
                    if not 100 <= response["status_code"] <= 599:
                        raise ContractError(
                            f"{context}.error_response.status_code must be an HTTP status"
                        )
                    _string(response["prefix"], f"{context}.error_response.prefix")
                else:
                    raise ContractError(f"{context}.error_response.kind is unsupported")
            elif error_response is not None:
                raise ContractError(f"{context}.error_response requires a custom response handler")
            backend = scenario["backend"]
            if isinstance(backend, dict) and set(backend) == {"error"}:
                error = _exact(backend["error"], {"type", "message"}, f"{context}.backend.error")
                if error["type"] != "AuthenticationError":
                    raise ContractError(f"{context}.backend.error.type is unsupported")
                _string(error["message"], f"{context}.backend.error.message")
                exercised.add(
                    "starlette.middleware.authentication.AuthenticationMiddleware.http-error-handler"
                    if scenario["scope_type"] == "http"
                    else "starlette.middleware.authentication.AuthenticationMiddleware.websocket-error-close"
                )
            elif isinstance(backend, dict) and set(backend) == {"outcome"}:
                outcome = backend["outcome"]
                if isinstance(outcome, dict):
                    result = _exact(outcome, {"credentials", "user"}, f"{context}.backend.outcome")
                    if not isinstance(result["credentials"], list) or any(
                        not isinstance(scope, str) for scope in result["credentials"]
                    ):
                        raise ContractError(f"{context}.backend credentials must be a string array")
                    _string(result["user"], f"{context}.backend user")
                    exercised.add(
                        "starlette.middleware.authentication.AuthenticationMiddleware.scope-user-install"
                    )
                elif isinstance(outcome, str) and outcome in {"none", "must-not-run"}:
                    if outcome == "none":
                        exercised.add(
                            "starlette.middleware.authentication.AuthenticationMiddleware.unauthenticated-default"
                        )
                else:
                    raise ContractError(f"{context}.backend.outcome is unsupported")
            else:
                raise ContractError(f"{context}.backend is outside the declared outcomes")
            application_response = scenario.get("application_response")
            if application_response is not None:
                response = _exact(
                    application_response,
                    {
                        "kind",
                        "status_code",
                        "authenticated_field",
                        "display_name_field",
                    },
                    f"{context}.application_response",
                )
                if response["kind"] != "auth-user-json":
                    raise ContractError(f"{context}.application_response.kind is unsupported")
                _validate_nonnegative_integer(
                    response["status_code"], f"{context}.application_response.status_code"
                )
                if not 100 <= response["status_code"] <= 599:
                    raise ContractError(
                        f"{context}.application_response.status_code must be an HTTP status"
                    )
                _string(
                    response["authenticated_field"],
                    f"{context}.application_response.authenticated_field",
                )
                _string(
                    response["display_name_field"],
                    f"{context}.application_response.display_name_field",
                )
                if response["authenticated_field"] == response["display_name_field"]:
                    raise ContractError(f"{context}.application_response fields must be distinct")
                if not (
                    scenario["scope_type"] == "http"
                    and isinstance(backend, dict)
                    and set(backend) == {"outcome"}
                    and isinstance(backend["outcome"], dict)
                ):
                    raise ContractError(
                        f"{context}.application_response requires an HTTP backend result"
                    )
            if scenario["scope_type"] == "lifespan":
                exercised.add(
                    "starlette.middleware.authentication.AuthenticationMiddleware.non-http-bypass"
                )

    if set(case["covers"]) != exercised:
        raise ContractError(
            "authentication case coverage must match the behaviors selected by its inputs"
        )


def _validate_route_endpoint_spec(spec: Any, context: str) -> str:
    if not isinstance(spec, dict) or not isinstance(spec.get("kind"), str):
        raise ContractError(f"{context} requires an endpoint kind")
    kind = spec["kind"]
    keys_by_kind = {
        "function": {"kind", "name", "async"},
        "bound-method": {"kind", "class_name", "method_name", "async"},
        "class-method": {"kind", "class_name", "method_name", "async"},
        "static-method": {"kind", "class_name", "method_name", "async"},
        "object": {"kind", "class_name"},
        "lambda": {"kind"},
    }
    if kind not in keys_by_kind:
        raise ContractError(f"{context}.kind is not a supported endpoint shape")
    spec = _exact(spec, keys_by_kind[kind], context)
    if kind == "function":
        if not isinstance(spec["name"], str) or not spec["name"].isidentifier():
            raise ContractError(f"{context}.name must be an identifier")
    if kind in {"bound-method", "class-method", "static-method", "object"}:
        if not isinstance(spec["class_name"], str) or not spec["class_name"].isidentifier():
            raise ContractError(f"{context}.class_name must be an identifier")
    if kind in {"bound-method", "class-method", "static-method"} and (
        not isinstance(spec["method_name"], str) or not spec["method_name"].isidentifier()
    ):
        raise ContractError(f"{context}.method_name must be an identifier")
    if "async" in spec and not isinstance(spec["async"], bool):
        raise ContractError(f"{context}.async must be a boolean")
    return kind


def _validate_route_name_case(case: dict[str, Any]) -> None:
    _exact(
        case,
        {
            "case_id",
            "surface",
            "operation",
            "covers",
            "target_profiles",
            "assets",
            "path",
            "methods",
            "name",
            "endpoints",
            "observations",
        },
        "Route endpoint-name case",
    )
    if case["target_profiles"] != ["python-package-cpython312"] or case["assets"] != []:
        raise ContractError("Route endpoint-name parity targets only the Python package profile")
    if case["observations"] != ["constructor_results"]:
        raise ContractError("Route endpoint-name cases select constructor results")
    if not isinstance(case["path"], str) or not case["path"].startswith("/"):
        raise ContractError("Route endpoint-name path must be an absolute route path")
    methods = case["methods"]
    if methods is not None and (
        not isinstance(methods, list)
        or any(not isinstance(method, str) for method in methods)
        or len(methods) != len(set(methods))
    ):
        raise ContractError("Route endpoint-name methods must be null or unique strings")
    if case["name"] is not None and not isinstance(case["name"], str):
        raise ContractError("Route endpoint-name override must be null or a string")
    endpoints = case["endpoints"]
    if not isinstance(endpoints, list) or not endpoints:
        raise ContractError("Route endpoint-name cases require input endpoint shapes")
    exercised: set[str] = set()
    for index, endpoint in enumerate(endpoints):
        kind = _validate_route_endpoint_spec(endpoint, f"Route endpoint-name endpoints[{index}]")
        exercised.add(ROUTE_ENDPOINT_NAME_REQUIREMENTS[kind])
    if set(case["covers"]) != exercised:
        raise ContractError(
            "Route endpoint-name requirements must derive from the supplied callables"
        )


def _validate_route_constructor_error_case(case: dict[str, Any]) -> None:
    _exact(
        case,
        {
            "case_id",
            "surface",
            "operation",
            "covers",
            "target_profiles",
            "assets",
            "attempts",
            "observations",
        },
        "Route constructor-error case",
    )
    if case["target_profiles"] != ["python-package-cpython312"] or case["assets"] != []:
        raise ContractError("Route constructor-error parity targets only the Python package")
    if case["observations"] != ["constructor_results"]:
        raise ContractError("Route constructor-error cases select their declared observation")
    attempts = case["attempts"]
    if not isinstance(attempts, list) or not attempts:
        raise ContractError("Route constructor-error cases require route constructor inputs")

    exercised: set[str] = set()
    for index, attempt in enumerate(attempts):
        _validate_route_value_spec(attempt, f"Route constructor-error attempts[{index}]")
        parameter_names = [name for name, _converter in _route_template_parameters(attempt["path"])]
        counts: dict[str, int] = {}
        for name in parameter_names:
            counts[name] = counts.get(name, 0) + 1
        duplicate_names = [name for name, count in counts.items() if count > 1]
        if not duplicate_names:
            raise ContractError("Route constructor-error inputs must repeat a path parameter name")
        duplicate_kind = "single" if len(duplicate_names) == 1 else "multiple"
        exercised.add(ROUTE_CONSTRUCTOR_ERROR_REQUIREMENTS[duplicate_kind])
    if set(case["covers"]) != exercised:
        raise ContractError("Route constructor-error coverage must derive from repeated path names")


def _validate_route_value_spec(spec: Any, context: str) -> str:
    if not isinstance(spec, dict):
        raise ContractError(f"{context} must be an object")
    spec = _exact(spec, {"path", "endpoint", "methods", "name"}, context)
    if not isinstance(spec["path"], str) or not spec["path"].startswith("/"):
        raise ContractError(f"{context}.path must be an absolute route path")
    endpoint_kind = _validate_route_endpoint_spec(spec["endpoint"], f"{context}.endpoint")
    methods = spec["methods"]
    if methods is not None and (
        not isinstance(methods, list)
        or any(not isinstance(method, str) for method in methods)
        or len(methods) != len(set(methods))
    ):
        raise ContractError(f"{context}.methods must be null or unique strings")
    if spec["name"] is not None and not isinstance(spec["name"], str):
        raise ContractError(f"{context}.name must be null or a string")
    return endpoint_kind


def _validate_route_repr_case(case: dict[str, Any]) -> None:
    surface = case["surface"]
    field = {
        HTTP_ROUTE_SURFACE: "route",
        WEBSOCKET_ROUTE_SURFACE: "route",
        MOUNT_SURFACE: "mount",
        HOST_SURFACE: "host",
    }[surface]
    _exact(
        case,
        {
            "case_id",
            "surface",
            "operation",
            "covers",
            "target_profiles",
            "assets",
            field,
            "observations",
        },
        "routing representation case",
    )
    if case["target_profiles"] != ["python-package-cpython312"] or case["assets"] != []:
        raise ContractError("routing representation parity targets only the Python package profile")
    if case["observations"] != ["representation"]:
        raise ContractError("routing representation cases select their declared observation")

    spec = case[field]
    if surface == HTTP_ROUTE_SURFACE:
        endpoint_kind = _validate_route_value_spec(spec, "Route representation input")
        if endpoint_kind == "function" and spec["methods"] is None:
            requirement = ROUTE_REPRESENTATION_REQUIREMENTS[surface]["inferred-methods"]
        elif endpoint_kind == "object" and spec["methods"] is None:
            requirement = ROUTE_REPRESENTATION_REQUIREMENTS[surface]["class-endpoint-no-methods"]
        else:
            raise ContractError("Route representation inputs must select a pinned endpoint shape")
    elif surface == WEBSOCKET_ROUTE_SURFACE:
        spec = _exact(spec, {"path", "endpoint", "name"}, "WebSocketRoute representation input")
        if not isinstance(spec["path"], str) or not spec["path"].startswith("/"):
            raise ContractError("WebSocketRoute representation path must be absolute")
        endpoint_kind = _validate_route_endpoint_spec(
            spec["endpoint"], "WebSocketRoute representation endpoint"
        )
        if spec["name"] is not None and not isinstance(spec["name"], str):
            raise ContractError("WebSocketRoute representation name must be null or a string")
        if endpoint_kind != "function":
            raise ContractError("WebSocketRoute representation requires an input callable")
        requirement = ROUTE_REPRESENTATION_REQUIREMENTS[surface]["function-endpoint"]
    elif surface == MOUNT_SURFACE:
        spec = _exact(spec, {"path", "name", "routes"}, "Mount representation input")
        if not isinstance(spec["path"], str) or (spec["path"] and not spec["path"].startswith("/")):
            raise ContractError("Mount representation path must be empty or absolute")
        if spec["name"] is not None and not isinstance(spec["name"], str):
            raise ContractError("Mount representation name must be null or a string")
        if not isinstance(spec["routes"], list) or not spec["routes"]:
            raise ContractError("Mount representation requires the supplied child routes")
        for index, route in enumerate(spec["routes"]):
            _validate_route_value_spec(route, f"Mount representation routes[{index}]")
        requirement = ROUTE_REPRESENTATION_REQUIREMENTS[surface][
            "named" if spec["name"] else "unnamed"
        ]
    else:
        spec = _exact(spec, {"host", "name", "routes"}, "Host representation input")
        if not isinstance(spec["host"], str) or not spec["host"]:
            raise ContractError("Host representation host must be a nonempty string")
        if spec["name"] is not None and not isinstance(spec["name"], str):
            raise ContractError("Host representation name must be null or a string")
        if not isinstance(spec["routes"], list) or not spec["routes"]:
            raise ContractError("Host representation requires the supplied child routes")
        for index, route in enumerate(spec["routes"]):
            _validate_route_value_spec(route, f"Host representation routes[{index}]")
        requirement = ROUTE_REPRESENTATION_REQUIREMENTS[surface][
            "named" if spec["name"] else "unnamed"
        ]
    if set(case["covers"]) != {requirement}:
        raise ContractError(
            "routing representation coverage must derive from its constructor input"
        )


def _validate_value_formatting_case(case: dict[str, Any]) -> None:
    if case["target_profiles"] != ["python-package-cpython312"]:
        raise ContractError("value-formatting parity currently targets the Python package profile")
    if case["assets"] != []:
        raise ContractError("value-formatting cases do not use external assets")

    if case["surface"] in ROUTE_REPRESENTATION_REQUIREMENTS:
        _validate_route_repr_case(case)
        return

    if case["surface"] == EXCEPTION_VALUES_SURFACE:
        if case["observations"] != [VALUE_FORMATTING_OPERATION]:
            raise ContractError("exception value-formatting must select its declared observation")
        instances = case["instances"]
        if not isinstance(instances, list) or not instances:
            raise ContractError("exception value-formatting requires at least one input instance")
        exercised: set[str] = set()
        for index, item in enumerate(instances):
            context = f"exception value-formatting instances[{index}]"
            item = _exact(item, {"kind", "subclass_name", "arguments", "mutations"}, context)
            kind = item["kind"]
            subclass_name = item["subclass_name"]
            if subclass_name is not None and (
                not isinstance(subclass_name, str) or not subclass_name.isidentifier()
            ):
                raise ContractError(f"{context}.subclass_name must be null or an identifier")
            mutations = item["mutations"]
            if not isinstance(mutations, list):
                raise ContractError(f"{context}.mutations must be an array")
            arguments = item["arguments"]
            if kind == "http":
                arguments = _exact(
                    arguments,
                    {"status_code", "detail", "headers"},
                    f"{context}.arguments",
                )
                status_code = arguments["status_code"]
                if not isinstance(status_code, int) or isinstance(status_code, bool):
                    raise ContractError(f"{context}.status_code must be an integer")
                headers = arguments["headers"]
                if headers is not None and (
                    not isinstance(headers, dict)
                    or any(
                        not isinstance(name, str) or not isinstance(value, str)
                        for name, value in headers.items()
                    )
                ):
                    raise ContractError(f"{context}.headers must be null or a string mapping")
                try:
                    HTTPStatus(status_code)
                except ValueError:
                    if arguments["detail"] is None:
                        exercised.add("starlette.exception-values.http-invalid-status")
                    else:
                        exercised.add("starlette.exception-values.http-str")
                        exercised.add("starlette.exception-values.http-repr")
                else:
                    if arguments["detail"] is None:
                        exercised.add("starlette.exception-values.http-default-detail")
                    exercised.add("starlette.exception-values.http-str")
                    exercised.add("starlette.exception-values.http-repr")
                allowed_fields = {"status_code", "detail", "headers"}
                if subclass_name is not None and mutations:
                    exercised.add("starlette.exception-values.http-subclass-mutable-fields")
            elif kind == "websocket":
                arguments = _exact(arguments, {"code", "reason"}, f"{context}.arguments")
                code = arguments["code"]
                if not isinstance(code, int) or isinstance(code, bool):
                    raise ContractError(f"{context}.code must be an integer")
                if not arguments["reason"]:
                    exercised.add("starlette.exception-values.websocket-reason-default")
                exercised.add("starlette.exception-values.websocket-str")
                exercised.add("starlette.exception-values.websocket-repr")
                allowed_fields = {"code", "reason"}
                if subclass_name is not None and mutations:
                    exercised.add("starlette.exception-values.websocket-subclass-mutable-fields")
            else:
                raise ContractError(f"{context}.kind must be http or websocket")
            for mutation_index, mutation in enumerate(mutations):
                mutation = _exact(
                    mutation,
                    {"field", "value"},
                    f"{context}.mutations[{mutation_index}]",
                )
                if mutation["field"] not in allowed_fields:
                    raise ContractError(f"{context} mutates an unsupported public field")
                if kind == "http" and mutation["field"] == "status_code":
                    value = mutation["value"]
                    if not isinstance(value, int) or isinstance(value, bool):
                        raise ContractError(f"{context} status_code mutation must be an integer")
                if kind == "http" and mutation["field"] == "headers":
                    value = mutation["value"]
                    if value is not None and (
                        not isinstance(value, dict)
                        or any(
                            not isinstance(name, str) or not isinstance(entry, str)
                            for name, entry in value.items()
                        )
                    ):
                        raise ContractError(
                            f"{context} headers mutation must be null or a string mapping"
                        )
                if kind == "websocket" and mutation["field"] == "code":
                    value = mutation["value"]
                    if not isinstance(value, int) or isinstance(value, bool):
                        raise ContractError(f"{context} code mutation must be an integer")
        if set(case["covers"]) != exercised:
            raise ContractError(
                "exception value-formatting coverage must match the behaviors selected by its inputs"
            )
        return

    if case["surface"] != MIDDLEWARE_CONFIG_SURFACE:
        raise ContractError("value-formatting case uses an undeclared public surface")
    if case["observations"] != ["repr", "__iter__"]:
        raise ContractError("Middleware value-formatting must select repr and __iter__")
    middleware = _exact(
        case["middleware"],
        {"class_name", "args", "kwargs"},
        "Middleware value-formatting input",
    )
    if not isinstance(middleware["class_name"], str) or not middleware["class_name"].isidentifier():
        raise ContractError("Middleware class_name must be an identifier")
    if not isinstance(middleware["args"], list) or not isinstance(middleware["kwargs"], dict):
        raise ContractError("Middleware args and kwargs must be an array and mapping")
    if any(not isinstance(key, str) for key in middleware["kwargs"]):
        raise ContractError("Middleware keyword names must be strings")
    expected = {
        "starlette.middleware.Middleware.repr",
        "starlette.middleware.Middleware.iteration",
    }
    if set(case["covers"]) != expected:
        raise ContractError(
            "Middleware value-formatting coverage must match repr and iteration inputs"
        )


def _validate_body_limit_case_stimulus(case: dict[str, Any]) -> None:
    if case["target_profiles"] != ["python-package-cpython312"]:
        raise ContractError("body-limit parity currently targets the Python package profile")
    if case["assets"] != [] or case["observations"] != ["dispatch"]:
        raise ContractError("body-limit cases must observe dispatch without external assets")
    if case["execution_schedule"] != ["dispatch"] or not isinstance(case["steps"], list):
        raise ContractError("body-limit cases must dispatch one ASGI scope")
    steps = case["steps"]
    if (
        len(steps) != 2
        or [step.get("step_id") for step in steps] != ["middleware", "dispatch"]
        or [step.get("operation") for step in steps] != ["__init__", "__call__"]
        or any(step.get("surface") != BODY_LIMIT_SURFACE for step in steps)
        or steps[0].get("receiver") is not None
        or steps[1].get("receiver") != {"kind": "binding", "step_id": "middleware"}
    ):
        raise ContractError("body-limit cases must construct and call the public middleware")
    constructor_step = _exact(steps[0], STEP_KEYS, "body-limit constructor step")
    dispatch_step = _exact(steps[1], STEP_KEYS, "body-limit dispatch step")
    constructor_args = _exact(
        constructor_step["arguments"], {"app", "max_body_size"}, "body-limit constructor arguments"
    )
    dispatch_args = _exact(
        dispatch_step["arguments"], {"scope", "receive", "send"}, "body-limit dispatch arguments"
    )
    for name, descriptor in constructor_args.items():
        _exact(descriptor, {"kind", "value"}, f"body-limit constructor {name} descriptor")
        if descriptor["kind"] != "literal":
            raise ContractError(f"body-limit constructor {name} must be an input literal")
    app_spec = _exact(
        constructor_args["app"]["value"], {"kind", "actions"}, "body-limit script app"
    )
    max_body_size = constructor_args["max_body_size"]["value"]
    if not isinstance(max_body_size, int) or isinstance(max_body_size, bool) or max_body_size < 0:
        raise ContractError("body-limit max_body_size must be a non-negative integer literal")
    if app_spec["kind"] != "asgi-body-limit-script":
        raise ContractError("body-limit app must use the declared action-script kind")
    _validate_body_limit_action_sequence(app_spec["actions"], "body-limit app actions")

    for name, descriptor in dispatch_args.items():
        _exact(descriptor, {"kind", "value"}, f"body-limit dispatch {name} descriptor")
        if descriptor["kind"] != "literal":
            raise ContractError(f"body-limit dispatch {name} must be an input literal")
    scope_value = dispatch_args["scope"]["value"]
    if not isinstance(scope_value, dict):
        raise ContractError("body-limit scope input must be a record")
    scope_check = dict(scope_value)
    prior_scope_limit = scope_check.pop("preexisting_max_body_size", _BODY_LIMIT_MISSING)
    if prior_scope_limit is not _BODY_LIMIT_MISSING and (
        prior_scope_limit is not None
        and (not isinstance(prior_scope_limit, int) or isinstance(prior_scope_limit, bool))
    ):
        raise ContractError("preexisting body limit must be an integer or null")
    if prior_scope_limit is not _BODY_LIMIT_MISSING and scope_value.get("type") != "http":
        raise ContractError("preexisting body limit input is only valid for HTTP scopes")
    _validate_dispatch_stimulus(
        {
            "scope": scope_check,
            "receive": dispatch_args["receive"]["value"],
            "send": dispatch_args["send"]["value"],
        },
        request_dispatch=True,
        allow_headers=True,
        allow_http_disconnect=True,
    )
    if dispatch_args["send"]["value"] != {"kind": "capture-asgi-send"}:
        raise ContractError("body-limit send must select the fixed ASGI capture collector")
    exercised = _body_limit_semantic_coverage(case)
    covered = set(case["covers"])
    expected_ids = {BODY_LIMIT_REQUIREMENT_CONSTRUCTION} | set(BODY_LIMIT_REQUIREMENTS.values())
    unknown = covered - expected_ids
    if unknown:
        raise ContractError(f"body-limit case covers undeclared requirements: {sorted(unknown)}")
    if covered - exercised:
        raise ContractError(
            "body-limit case claims requirements not exercised by its actions and inputs: "
            f"{sorted(covered - exercised)}"
        )


def _body_limit_semantic_coverage(case: dict[str, Any]) -> set[str]:
    constructor_args = {
        name: descriptor["value"] for name, descriptor in case["steps"][0]["arguments"].items()
    }
    dispatch_args = {
        name: descriptor["value"] for name, descriptor in case["steps"][1]["arguments"].items()
    }
    app_actions = constructor_args["app"]["actions"]
    scope = dispatch_args["scope"]
    coverage = {BODY_LIMIT_REQUIREMENT_CONSTRUCTION, BODY_LIMIT_REQUIREMENTS["scope-restoration"]}
    if scope["type"] != "http":
        coverage.add(BODY_LIMIT_REQUIREMENTS["non-http-pass-through"])
        return coverage

    header_pairs = _gzip_header_pairs(scope["headers_base64_pairs"], "HTTP request headers")
    lengths = [value for name, value in header_pairs if name.lower() == b"content-length"]
    declared_length = None
    invalid_length = False
    if lengths:
        try:
            declared_length = int(lengths[0])
        except ValueError:
            invalid_length = True
    messages = dispatch_args["receive"]
    body_lengths = [
        len(base64.b64decode(item.get("body_base64", ""), validate=True)) for item in messages
    ]
    max_body_size = constructor_args["max_body_size"]

    def flatten(
        actions: list[dict[str, Any]], active_limit: int
    ) -> list[tuple[dict[str, Any], int]]:
        flattened: list[tuple[dict[str, Any], int]] = []
        current_limit = active_limit
        for action in actions:
            if action["action"] == "nested":
                current_limit = action["max_body_size"]
                nested_actions = flatten(action["actions"], current_limit)
                flattened.extend(nested_actions)
                if nested_actions:
                    current_limit = nested_actions[-1][1]
            else:
                flattened.append((action, current_limit))
        return flattened

    actions = flatten(app_actions, max_body_size)
    receive_actions = [action for action, _ in actions if action["action"] == "receive"]
    if declared_length is not None and declared_length > max_body_size and receive_actions:
        coverage.add(BODY_LIMIT_REQUIREMENTS["content-length-precheck"])
    if (
        declared_length is not None
        and declared_length > max_body_size
        and actions
        and actions[0][0]["action"] == "send"
        and actions[0][0]["message"].get("type") == "http.response.start"
    ):
        coverage.add(BODY_LIMIT_REQUIREMENTS["content-length-replacement"])
    received_sizes = body_lengths[: len(receive_actions)]
    received_messages = messages[: len(receive_actions)]
    request_body_total = sum(
        size
        for message, size in zip(received_messages, received_sizes, strict=False)
        if message["type"] == "http.request"
    )
    if any(message["type"] != "http.request" for message in received_messages):
        coverage.add(BODY_LIMIT_REQUIREMENTS["non-request-message-pass-through"])
    if (
        request_body_total == max_body_size
        and any(message["type"] == "http.request" for message in received_messages)
        and any(
            action["action"] == "send" and action["message"].get("type") == "http.response.start"
            for action, _limit in actions
        )
    ):
        coverage.add(BODY_LIMIT_REQUIREMENTS["exact-limit-success"])
    accumulated_size = 0
    exceeded_after_start = False
    response_started = False
    receive_index = 0
    for action, limit in actions:
        if action["action"] == "send" and action["message"].get("type") == "http.response.start":
            response_started = True
        elif action["action"] == "receive" and receive_index < len(received_sizes):
            accumulated_size += received_sizes[receive_index]
            receive_index += 1
            if accumulated_size > limit:
                exceeded_after_start = exceeded_after_start or response_started
                if declared_length is None and not invalid_length:
                    coverage.add(BODY_LIMIT_REQUIREMENTS["streamed-body-count"])
                if declared_length is not None and declared_length <= max_body_size:
                    coverage.add(BODY_LIMIT_REQUIREMENTS["understated-content-length"])
    content_types = [value for name, value in header_pairs if name.lower() == b"content-type"]
    if content_types and declared_length is None and not invalid_length and receive_actions:
        content_type = content_types[0].decode("latin-1")
        if content_type.lower().startswith("multipart/form-data"):
            multipart_body = b"".join(
                base64.b64decode(message["body_base64"], validate=True) for message in messages
            )
            parts = _multipart_parts(content_type, multipart_body)
            payload_size = sum(
                len(payload)
                for part in parts
                if isinstance(payload := part.get_payload(decode=True), bytes)
            )
            if parts and sum(received_sizes) > max_body_size and payload_size <= max_body_size:
                coverage.add(BODY_LIMIT_REQUIREMENTS["multipart-body-counts-encoding-overhead"])
    if invalid_length and receive_actions:
        coverage.add(BODY_LIMIT_REQUIREMENTS["invalid-content-length"])
    if exceeded_after_start:
        coverage.add(BODY_LIMIT_REQUIREMENTS["already-started-propagation"])

    def has_nested(action_sequence: list[dict[str, Any]]) -> bool:
        return any(
            action["action"] == "nested" or has_nested(action["actions"])
            for action in action_sequence
            if action["action"] == "nested"
        )

    if has_nested(app_actions) and receive_actions and any(body_lengths):
        coverage.add(BODY_LIMIT_REQUIREMENTS["nested-limits"])
    return coverage


def _validate_asgi_middleware_constructor(surface: str, args: dict[str, Any]) -> None:
    if surface == WSGI_SURFACE:
        args = _exact(args, {"app"}, "WSGIMiddleware constructor")
        _validate_wsgi_app(args["app"])
        return
    if surface == CORS_SURFACE:
        expected = {
            "app",
            "allow_origins",
            "allow_methods",
            "allow_headers",
            "allow_credentials",
            "allow_origin_regex",
            "allow_private_network",
            "expose_headers",
            "max_age",
        }
        args = _exact(args, expected, "CORSMiddleware constructor")
        for name in ("allow_origins", "allow_methods", "allow_headers", "expose_headers"):
            values = args[name]
            if not isinstance(values, list) or any(not isinstance(value, str) for value in values):
                raise ContractError(f"CORSMiddleware {name} must be a string array")
        for name in ("allow_credentials", "allow_private_network"):
            if type(args[name]) is not bool:
                raise ContractError(f"CORSMiddleware {name} must be boolean")
        if args["allow_origin_regex"] is not None:
            regex = _string(args["allow_origin_regex"], "CORSMiddleware allow_origin_regex")
            try:
                re.compile(regex)
            except re.error as exc:
                raise ContractError(f"CORSMiddleware origin regex is invalid: {exc}") from exc
        if type(args["max_age"]) is not int or args["max_age"] < 0:
            raise ContractError("CORSMiddleware max_age must be a non-negative integer")
    elif surface == HTTPS_REDIRECT_SURFACE:
        _exact(args, {"app"}, "HTTPSRedirectMiddleware constructor")
    elif surface == TRUSTED_HOST_SURFACE:
        if set(args) - {"app", "allowed_hosts", "www_redirect"} or "app" not in args:
            raise ContractError("TrustedHostMiddleware constructor has an invalid argument set")
        if "allowed_hosts" in args and args["allowed_hosts"] is not None:
            hosts = args["allowed_hosts"]
            if not isinstance(hosts, list) or any(not isinstance(host, str) for host in hosts):
                raise ContractError("TrustedHostMiddleware allowed_hosts must be strings or null")
        if "www_redirect" in args and type(args["www_redirect"]) is not bool:
            raise ContractError("TrustedHostMiddleware www_redirect must be boolean")
    else:
        raise ContractError(f"unsupported protocol middleware surface: {surface}")

    _validate_asgi_middleware_app(args["app"])


def _validate_asgi_middleware_constructor_probes(surface: str, probes: Any) -> None:
    if surface != TRUSTED_HOST_SURFACE:
        raise ContractError("constructor attribute probes are not declared for this middleware")
    if not isinstance(probes, list) or not probes:
        raise ContractError("middleware constructor_probes must be a non-empty array")

    probe_ids: set[str] = set()
    supported_attributes = {"allowed_hosts", "allow_any", "www_redirect"}
    for index, raw_probe in enumerate(probes):
        context = f"middleware constructor_probes[{index}]"
        probe = _exact(raw_probe, {"probe_id", "attributes"}, context)
        probe_id = _string(probe["probe_id"], f"{context}.probe_id")
        attributes = probe["attributes"]
        if not probe_id or probe_id in probe_ids:
            raise ContractError(f"{context}.probe_id must be non-empty and unique")
        probe_ids.add(probe_id)
        if (
            not isinstance(attributes, list)
            or not attributes
            or any(
                not isinstance(attribute, str) or attribute not in supported_attributes
                for attribute in attributes
            )
            or len(attributes) != len(set(attributes))
        ):
            raise ContractError(
                f"{context}.attributes must select unique declared TrustedHostMiddleware attributes"
            )


def _validate_asgi_middleware_app(value: Any) -> None:
    app = _exact(value, {"kind", "messages"}, "ASGI middleware app input")
    if app["kind"] != "asgi-response-sequence" or not isinstance(app["messages"], list):
        raise ContractError("ASGI middleware app must be an input-defined message sequence")
    messages = app["messages"]
    if not messages:
        raise ContractError("ASGI middleware app message sequence must not be empty")
    if (
        len(messages) == 1
        and isinstance(messages[0], dict)
        and messages[0].get("type") == "websocket.close"
    ):
        message = _exact(messages[0], {"type", "code"}, "ASGI middleware WebSocket close")
        if message["type"] != "websocket.close" or not isinstance(message["code"], int):
            raise ContractError("ASGI middleware WebSocket close event is invalid")
        return
    start = _exact(
        messages[0],
        {"type", "status", "headers_base64_pairs"},
        "ASGI middleware HTTP response start",
    )
    if (
        start["type"] != "http.response.start"
        or not isinstance(start["status"], int)
        or isinstance(start["status"], bool)
        or not 100 <= start["status"] <= 599
    ):
        raise ContractError("ASGI middleware app must begin with a valid response-start event")
    _gzip_header_pairs(start["headers_base64_pairs"], "ASGI middleware response headers")
    if len(messages) < 2:
        raise ContractError("ASGI middleware HTTP response must include a response body event")
    body_messages = messages[1:]
    for index, raw_message in enumerate(body_messages):
        message = _exact(
            raw_message,
            {"type", "body_base64", "more_body"},
            f"ASGI middleware response body[{index}]",
        )
        if message["type"] != "http.response.body" or not isinstance(message["more_body"], bool):
            raise ContractError("ASGI middleware response body event is invalid")
        try:
            base64.b64decode(message["body_base64"], validate=True)
        except (ValueError, TypeError) as exc:
            raise ContractError("ASGI middleware response body is invalid base64") from exc
    if (
        any(message["more_body"] for message in body_messages[:-1])
        or body_messages[-1]["more_body"]
    ):
        raise ContractError("ASGI middleware response body sequence must end with more_body=false")


def _validate_wsgi_app(value: Any) -> None:
    if not isinstance(value, dict) or value.get("kind") not in {
        "wsgi-response",
        "wsgi-echo-body",
        "wsgi-environ-report",
        "wsgi-raise-before-start",
        "wsgi-exc-info-rethrow",
    }:
        raise ContractError("WSGIMiddleware app must use a declared input-defined WSGI app kind")
    kind = value["kind"]
    fields = {
        "wsgi-response": {"kind", "status", "headers", "chunks_base64"},
        "wsgi-echo-body": {"kind", "status", "headers"},
        "wsgi-environ-report": {
            "kind",
            "status",
            "headers",
            "keys",
            "include_worker_thread",
        },
        "wsgi-raise-before-start": {"kind", "message"},
        "wsgi-exc-info-rethrow": {"kind", "status", "headers", "body_base64", "message"},
    }[kind]
    _exact(value, fields, "WSGIMiddleware WSGI app input")
    if kind == "wsgi-raise-before-start":
        _string(value["message"], "WSGIMiddleware exception message")
        return
    if kind == "wsgi-exc-info-rethrow":
        _string(value["message"], "WSGIMiddleware exception message")
        try:
            base64.b64decode(value["body_base64"], validate=True)
        except (ValueError, TypeError) as exc:
            raise ContractError("WSGIMiddleware exception response body is invalid base64") from exc
    if not isinstance(value["status"], str) or " " not in value["status"]:
        raise ContractError("WSGIMiddleware status must contain a code and reason phrase")
    headers = value["headers"]
    if not isinstance(headers, list):
        raise ContractError("WSGIMiddleware response headers must be an array")
    for index, pair in enumerate(headers):
        if (
            not isinstance(pair, list)
            or len(pair) != 2
            or any(not isinstance(item, str) for item in pair)
        ):
            raise ContractError(f"WSGIMiddleware response header[{index}] must be a string pair")
        try:
            pair[0].encode("ascii")
            pair[1].encode("ascii")
        except UnicodeEncodeError as exc:
            raise ContractError("WSGIMiddleware response headers must be ASCII encodable") from exc
    if kind == "wsgi-response":
        chunks = value["chunks_base64"]
        if not isinstance(chunks, list):
            raise ContractError("WSGIMiddleware response chunks must be a base64 array")
        for chunk in chunks:
            try:
                base64.b64decode(chunk, validate=True)
            except (ValueError, TypeError) as exc:
                raise ContractError("WSGIMiddleware response chunk is invalid base64") from exc
    if kind == "wsgi-environ-report":
        keys = value["keys"]
        if not isinstance(keys, list) or not keys or any(not isinstance(key, str) for key in keys):
            raise ContractError("WSGIMiddleware report keys must be a non-empty string array")
        if len(keys) != len(set(keys)) or type(value["include_worker_thread"]) is not bool:
            raise ContractError("WSGIMiddleware report selectors must be unique and boolean")


def _validate_asgi_middleware_dispatch(surface: str, args: dict[str, Any]) -> None:
    args = _exact(args, {"scope", "receive", "send"}, f"{surface} dispatch")
    scope = args["scope"]
    if surface == WSGI_SURFACE:
        if not isinstance(scope, dict) or scope.get("type") != "http":
            raise ContractError("WSGIMiddleware dispatch must use an HTTP scope")
        _validate_dispatch_stimulus(
            args,
            request_dispatch=False,
            allow_body_stream=True,
            allow_headers=True,
            allow_root_path=True,
            allow_query=True,
            allow_host=True,
            allow_client=True,
        )
        return
    if isinstance(scope, dict) and scope.get("type") == "http":
        _validate_dispatch_stimulus(
            args,
            request_dispatch=True,
            allow_headers=True,
            allow_query=True,
            allow_host=True,
        )
        return
    if not isinstance(scope, dict) or scope.get("type") != "websocket":
        raise ContractError(f"{surface} dispatch must use HTTP or WebSocket scope")
    scope = _exact(
        scope,
        {
            "type",
            "asgi",
            "http_version",
            "scheme",
            "path",
            "raw_path_base64",
            "query_string_base64",
            "root_path",
            "headers_base64_pairs",
            "client",
            "server",
            "subprotocols",
        },
        f"{surface} WebSocket scope",
    )
    if (
        scope["asgi"]
        not in (
            {"version": "3.0", "spec_version": "2.4"},
            {"version": "3.0", "spec_version": "2.5"},
        )
        or scope["scheme"] not in {"ws", "wss"}
        or not isinstance(scope["http_version"], str)
        or not isinstance(scope["root_path"], str)
        or not isinstance(scope["path"], str)
        or scope["raw_path_base64"] != base64.b64encode(scope["path"].encode("ascii")).decode()
    ):
        raise ContractError(f"{surface} WebSocket scope is invalid")
    if args["receive"] != [{"type": "websocket.connect"}] or args["send"] != {
        "kind": "capture-asgi-send"
    }:
        raise ContractError(f"{surface} WebSocket dispatch callbacks are invalid")
    for field in ("raw_path_base64", "query_string_base64"):
        try:
            base64.b64decode(scope[field], validate=True)
        except (ValueError, TypeError) as exc:
            raise ContractError(f"{surface} WebSocket {field} is invalid base64") from exc
    if not isinstance(scope["headers_base64_pairs"], list) or not isinstance(
        scope["subprotocols"], list
    ):
        raise ContractError(f"{surface} WebSocket headers and subprotocols must be arrays")


def _asgi_middleware_semantic_coverage(case: dict[str, Any]) -> set[str]:
    surface = case["surface"]
    is_cors_state_sequence = _is_cors_dispatch_sequence(case)
    constructor = {
        name: descriptor["value"] for name, descriptor in case["steps"][0]["arguments"].items()
    }
    if case["operation"] == "__init__":
        covered = {f"{surface}.construct"}
        hosts = constructor.get("allowed_hosts")
        if hosts and any(
            "*" in host[1:] or (host.startswith("*") and host != "*" and not host.startswith("*."))
            for host in hosts
        ):
            covered.add(f"{surface}.wildcard-validation-error")
        return covered
    dispatch = {
        name: descriptor["value"] for name, descriptor in case["steps"][1]["arguments"].items()
    }
    scope = dispatch["scope"]

    def suffix(value: str) -> str:
        return f"{surface}.{value}"

    covered = {suffix("construct")}

    if surface == WSGI_SURFACE:
        app = constructor["app"]
        kind = app["kind"]
        receive = dispatch["receive"]
        if kind in {"wsgi-environ-report", "wsgi-echo-body"}:
            covered.add(WSGI_REQUIREMENTS["request-body-buffering"])
        if kind == "wsgi-environ-report":
            covered.add(WSGI_REQUIREMENTS["build-environ"])
            if app["include_worker_thread"]:
                covered.add(WSGI_REQUIREMENTS["worker-thread-boundary"])
        if kind in {
            "wsgi-response",
            "wsgi-environ-report",
            "wsgi-echo-body",
            "wsgi-exc-info-rethrow",
        }:
            covered.add(WSGI_REQUIREMENTS["response-order"])
        if kind == "wsgi-raise-before-start":
            covered.add(WSGI_REQUIREMENTS["exception-before-start"])
        if kind == "wsgi-exc-info-rethrow":
            covered.add(WSGI_REQUIREMENTS["exc-info-rethrow"])
        if not receive:
            covered.discard(WSGI_REQUIREMENTS["request-body-buffering"])
        return covered

    def decoded_headers(scope_value: dict[str, Any]) -> dict[str, str]:
        return {
            base64.b64decode(name, validate=True).decode("latin-1").lower(): base64.b64decode(
                value, validate=True
            ).decode("latin-1")
            for name, value in scope_value.get("headers_base64_pairs", [])
        }

    headers = decoded_headers(scope)
    if surface == CORS_SURFACE:
        cors_dispatch_scopes = (
            [
                {name: descriptor["value"] for name, descriptor in step["arguments"].items()}[
                    "scope"
                ]
                for step in case["steps"][1:]
            ]
            if is_cors_state_sequence
            else [scope]
        )
        app_messages = constructor["app"].get("messages", [])
        app_response_start = app_messages[0] if app_messages else {}
        app_response_header_names = {
            base64.b64decode(name, validate=True).decode("latin-1").lower()
            for name, _value in app_response_start.get("headers_base64_pairs", [])
        }
        for cors_scope in cors_dispatch_scopes:
            cors_headers = decoded_headers(cors_scope)
            request_method = cors_headers.get("access-control-request-method")
            request_headers = [
                value.strip().lower()
                for value in cors_headers.get("access-control-request-headers", "").split(",")
                if value.strip()
            ]
            request_origin = cors_headers.get("origin")
            if (
                request_origin is not None
                and "*" not in constructor["allow_origins"]
                and request_origin in constructor["allow_origins"]
            ):
                covered.add(suffix("explicit-origin-match-reflects-and-varies"))
            if (
                cors_scope.get("type") == "http"
                and request_origin is not None
                and request_method is None
                and "*" in constructor["allow_origins"]
                and constructor["allow_credentials"]
                and "cookie" not in cors_headers
            ):
                covered.add(suffix("credentialed-wildcard-origin-reflection-without-cookie"))
            request_origin_allowed = request_origin is not None and (
                "*" in constructor["allow_origins"]
                or request_origin in constructor["allow_origins"]
                or (
                    constructor["allow_origin_regex"] is not None
                    and re.fullmatch(constructor["allow_origin_regex"], request_origin) is not None
                )
            )
            if (
                cors_scope.get("type") == "http"
                and request_origin is not None
                and constructor["allow_origin_regex"] is not None
                and re.fullmatch(constructor["allow_origin_regex"], request_origin) is not None
            ):
                covered.add(suffix("regex-origin-reflection"))
            if (
                cors_scope.get("type") == "http"
                and request_origin is not None
                and constructor["allow_origin_regex"] is not None
                and re.match(constructor["allow_origin_regex"], request_origin) is not None
                and re.fullmatch(constructor["allow_origin_regex"], request_origin) is None
            ):
                covered.add(suffix("regex-fullmatch-origin"))
            allowed_request_headers = {value.lower() for value in constructor["allow_headers"]}
            if (
                cors_scope.get("type") == "http"
                and cors_scope.get("method") == "OPTIONS"
                and request_method is not None
                and request_origin is not None
                and "*" in constructor["allow_origins"]
                and constructor["allow_credentials"]
                and (
                    "*" in constructor["allow_methods"]
                    or request_method in constructor["allow_methods"]
                )
                and (
                    "*" in allowed_request_headers
                    or all(value in allowed_request_headers for value in request_headers)
                )
            ):
                covered.add(suffix("preflight-credentialed-wildcard-origin-reflection"))
            if (
                cors_scope.get("type") == "http"
                and cors_scope.get("method") == "OPTIONS"
                and request_method is not None
                and cors_headers.get("access-control-request-private-network") == "true"
                and not constructor["allow_private_network"]
                and request_origin_allowed
                and (
                    "*" in constructor["allow_methods"]
                    or request_method in constructor["allow_methods"]
                )
                and (
                    "*" in allowed_request_headers
                    or all(value in allowed_request_headers for value in request_headers)
                )
            ):
                covered.add(CORS_PRIVATE_NETWORK_DENIAL_REQUIREMENT)
            if (
                cors_scope.get("type") == "http"
                and cors_scope.get("method") == "OPTIONS"
                and request_method is not None
                and cors_headers.get("access-control-request-private-network") == "true"
                and constructor["allow_private_network"]
                and request_origin_allowed
                and (
                    "*" in constructor["allow_methods"]
                    or request_method in constructor["allow_methods"]
                )
                and (
                    "*" in allowed_request_headers
                    or all(value in allowed_request_headers for value in request_headers)
                )
            ):
                covered.add(suffix("private-network-access-allowed"))
            if (
                cors_scope.get("type") == "http"
                and cors_scope.get("method") != "OPTIONS"
                and request_origin is not None
                and "*" in constructor["allow_origins"]
                and not constructor["allow_credentials"]
                and "cookie" not in cors_headers
                and "vary" in app_response_header_names
            ):
                covered.add(suffix("wildcard-noncredentialed-vary-preserved"))
        has_wildcard_preflight = any(
            cors_scope.get("type") == "http"
            and cors_scope.get("method") == "OPTIONS"
            and decoded_headers(cors_scope).get("access-control-request-method") is not None
            for cors_scope in cors_dispatch_scopes
        )
        has_simple_origin_request = any(
            cors_scope.get("type") == "http"
            and cors_scope.get("method") != "OPTIONS"
            and decoded_headers(cors_scope).get("origin") is not None
            for cors_scope in cors_dispatch_scopes
        )
        if (
            constructor["allow_methods"] == ["*"]
            and has_wildcard_preflight
            and has_simple_origin_request
        ):
            covered.add(suffix("wildcard-method-preflight-and-simple-passthrough"))
        if is_cors_state_sequence:
            sequence_scopes = [
                {name: descriptor["value"] for name, descriptor in step["arguments"].items()}[
                    "scope"
                ]
                for step in case["steps"][1:]
            ]
            sequence_origins = [
                decoded_headers(sequence_scope).get("origin") for sequence_scope in sequence_scopes
            ]
            origin_regex = constructor["allow_origin_regex"]
            regex = re.compile(origin_regex) if origin_regex else None

            def origin_is_allowed(value: str | None) -> bool:
                return value is not None and (
                    "*" in constructor["allow_origins"]
                    or value in constructor["allow_origins"]
                    or (regex is not None and regex.fullmatch(value) is not None)
                )

            if (
                all(sequence_scope["type"] == "http" for sequence_scope in sequence_scopes)
                and len(sequence_origins) == 3
                and sequence_origins[0] == sequence_origins[2]
                and origin_is_allowed(sequence_origins[0])
                and not origin_is_allowed(sequence_origins[1])
            ):
                covered.add(suffix("reused-instance-origin-isolation"))
            sequence_dispatches = [
                {name: descriptor["value"] for name, descriptor in step["arguments"].items()}
                for step in case["steps"][1:]
            ]
            sequence_methods = [sequence_scope.get("method") for sequence_scope in sequence_scopes]
            preflight_headers = (
                decoded_headers(sequence_scopes[0]) if len(sequence_scopes) == 3 else {}
            )
            simple_headers = (
                decoded_headers(sequence_scopes[1]) if len(sequence_scopes) == 3 else {}
            )
            no_origin_headers = (
                decoded_headers(sequence_scopes[2]) if len(sequence_scopes) == 3 else {}
            )
            response_input = constructor["app"]
            response_messages = response_input.get("messages", [])
            response_start = response_messages[0] if response_messages else {}
            response_body = response_messages[1] if len(response_messages) > 1 else {}
            response_headers = {
                base64.b64decode(name, validate=True).decode("latin-1").lower(): base64.b64decode(
                    value, validate=True
                ).decode("latin-1")
                for name, value in response_start.get("headers_base64_pairs", [])
            }
            if (
                constructor["allow_origins"] == ["*"]
                and constructor["allow_methods"] == ["*"]
                and constructor["allow_headers"] == ["*"]
                and constructor["allow_credentials"] is False
                and constructor["allow_origin_regex"] is None
                and constructor["allow_private_network"] is False
                and constructor["expose_headers"] == ["X-Status"]
                and len(sequence_scopes) == 3
                and all(sequence_scope["type"] == "http" for sequence_scope in sequence_scopes)
                and sequence_methods[0] == "OPTIONS"
                and sequence_methods[1] == "GET"
                and sequence_methods[2] == "GET"
                and all(sequence_scope["path"] == "/" for sequence_scope in sequence_scopes)
                and sequence_origins[0] is not None
                and sequence_origins[0] == sequence_origins[1]
                and sequence_origins[2] is None
                and set(preflight_headers)
                == {
                    "origin",
                    "access-control-request-method",
                    "access-control-request-headers",
                }
                and preflight_headers.get("access-control-request-method") == "GET"
                and preflight_headers.get("access-control-request-headers") == "X-Example"
                and set(simple_headers) == {"origin"}
                and not no_origin_headers
                and response_input.get("kind") == "asgi-response-sequence"
                and response_start.get("type") == "http.response.start"
                and response_start.get("status") == 200
                and response_headers
                == {"content-length": "8", "content-type": "text/plain; charset=utf-8"}
                and response_body
                == {
                    "type": "http.response.body",
                    "body_base64": "SG9tZXBhZ2U=",
                    "more_body": False,
                }
                and all(
                    dispatch["receive"]
                    == [{"type": "http.request", "body_base64": "", "more_body": False}]
                    and dispatch["send"] == {"kind": "capture-asgi-send"}
                    for dispatch in sequence_dispatches
                )
            ):
                covered.add(suffix("allow-all-except-credentials"))
        if scope["type"] != "http":
            covered.add(suffix("non-http-passthrough"))
            return covered
        origin = headers.get("origin")
        if origin is None:
            covered.add(suffix("missing-origin-passthrough"))
            return covered
        origins = constructor["allow_origins"]
        origin_regex = constructor["allow_origin_regex"]
        allowed_origin = origin == "*" or "*" in origins or origin in origins
        regex_match = re.compile(origin_regex).match(origin) if origin_regex else None
        full_regex_match = re.compile(origin_regex).fullmatch(origin) if origin_regex else None
        allowed_origin = allowed_origin or full_regex_match is not None
        if origin_regex and regex_match is not None and full_regex_match is None:
            covered.add(suffix("regex-fullmatch-origin"))
        requested_method = headers.get("access-control-request-method")
        if scope["method"] == "OPTIONS" and requested_method is not None:
            requested_headers = [
                value.strip().lower()
                for value in headers.get("access-control-request-headers", "").split(",")
                if value.strip()
            ]
            allowed_methods = constructor["allow_methods"]
            allowed_headers = {value.lower() for value in constructor["allow_headers"]}
            private_network_requested = (
                headers.get("access-control-request-private-network") == "true"
            )
            failures = (
                not allowed_origin,
                "*" not in allowed_methods and requested_method not in allowed_methods,
                "*" not in allowed_headers
                and any(value not in allowed_headers for value in requested_headers),
                private_network_requested and not constructor["allow_private_network"],
            )
            if (
                all(
                    (
                        allowed_origin,
                        "*" in allowed_methods or requested_method in allowed_methods,
                        "*" in allowed_headers
                        or all(value in allowed_headers for value in requested_headers),
                        headers.get("access-control-request-private-network") != "true"
                        or constructor["allow_private_network"],
                    )
                )
                and constructor["allow_private_network"]
            ):
                covered.add(suffix("preflight-wildcard-credential-private-network"))
            elif sum(failures) > 1:
                covered.add(suffix("preflight-denial-failure-order"))
            return covered
        if (
            "*" in origins
            and constructor["allow_credentials"]
            and any(
                base64.b64decode(name, validate=True).lower() == b"vary"
                for name, _value in constructor["app"]["messages"][0]["headers_base64_pairs"]
            )
        ):
            covered.add(suffix("simple-wildcard-credential-reflection-vary-merge"))
        elif origin_regex and regex_match is not None and full_regex_match is None:
            covered.add(suffix("regex-fullmatch-origin"))
        elif not allowed_origin:
            covered.add(suffix("simple-denied-origin-preserves-app-response"))
        return covered

    if surface == HTTPS_REDIRECT_SURFACE:
        scheme = scope.get("scheme")
        if scope["type"] in {"http", "websocket"} and scheme in {"http", "ws"}:
            if scheme == "ws":
                covered.add(suffix("websocket-redirect"))
            elif scope["server"][1] in {80, 443}:
                covered.add(suffix("http-redirect-default-port"))
            elif scope["query_string_base64"]:
                covered.add(suffix("http-redirect-preserves-port-and-query"))
        elif scope["type"] == "websocket" and scheme == "wss":
            covered.add(suffix("secure-websocket-pass-through"))
        else:
            covered.add(suffix("secure-scheme-pass-through"))
        return covered

    if surface == TRUSTED_HOST_SURFACE:
        if scope["type"] != "http":
            covered.add(suffix("non-http-scope-pass-through"))
            return covered
        allowed_hosts = constructor.get("allowed_hosts")
        allowed_hosts = ["*"] if allowed_hosts is None else allowed_hosts
        if "*" in allowed_hosts:
            covered.add(suffix("default-allowed-hosts"))
            return covered
        host = headers.get("host", "").split(":")[0]
        exact_match = host in allowed_hosts
        wildcard_match = any(
            pattern.startswith("*.") and host.endswith(pattern[1:]) for pattern in allowed_hosts
        )
        www_match = "www." + host in allowed_hosts
        if exact_match:
            covered.add(suffix("exact-host-match"))
        elif wildcard_match:
            covered.add(suffix("domain-wildcard-match"))
        elif www_match and constructor.get("www_redirect", True):
            covered.add(suffix("www-redirect"))
        elif www_match:
            covered.add(suffix("www-redirect-disabled"))
        else:
            covered.add(suffix("invalid-host-response"))
        return covered

    return covered


def _validate_gzip_constructor_stimulus(args: dict[str, Any]) -> None:
    allowed_arguments = {
        "app",
        "minimum_size",
        "compresslevel",
        "thread_minimum_size",
        "exclude_content_types",
    }
    if "app" not in args or set(args) - allowed_arguments:
        raise ContractError(
            "GZipMiddleware construction must supply its ASGI app and may omit any "
            "compression setting to exercise the public default"
        )
    app = _exact(args["app"], {"kind", "messages"}, "GZipMiddleware app input")
    if app["kind"] != "asgi-response-sequence":
        raise ContractError("GZipMiddleware app must be an input-defined ASGI response sequence")
    messages = app["messages"]
    if not isinstance(messages, list) or len(messages) < 2:
        raise ContractError("inner ASGI response input must include response start and output")
    start = _exact(
        messages[0],
        {"type", "status", "headers_base64_pairs"},
        "inner ASGI response start",
    )
    if (
        start["type"] != "http.response.start"
        or not isinstance(start["status"], int)
        or isinstance(start["status"], bool)
        or not 100 <= start["status"] <= 599
    ):
        raise ContractError("inner ASGI response must begin with a valid response-start event")
    start_headers = _gzip_header_pairs(start["headers_base64_pairs"], "response start headers")

    output_messages = messages[1:]
    output_types: list[str] = []
    bodies: list[tuple[bytes, bool]] = []
    for index, raw_message in enumerate(output_messages):
        context = f"inner ASGI response message[{index}]"
        if not isinstance(raw_message, dict):
            raise ContractError(f"{context} must be an object")
        message_type = raw_message.get("type")
        output_types.append(message_type)
        if message_type == "http.response.body":
            message = _exact(
                raw_message,
                {"type", "body_base64", "more_body"},
                context,
            )
            if not isinstance(message["more_body"], bool):
                raise ContractError(f"{context}.more_body must be boolean")
            try:
                body = base64.b64decode(message["body_base64"], validate=True)
            except (ValueError, TypeError) as exc:
                raise ContractError(f"{context}.body_base64 is invalid") from exc
            bodies.append((body, message["more_body"]))
        elif message_type == "http.response.pathsend":
            message = _exact(raw_message, {"type", "path"}, context)
            _string(message["path"], f"{context}.path")
        else:
            raise ContractError(f"{context} uses an unsupported ASGI response message type")

    if output_types == ["http.response.pathsend"]:
        pass
    elif all(message_type == "http.response.body" for message_type in output_types):
        if not bodies or any(not more_body for _, more_body in bodies[:-1]) or bodies[-1][1]:
            raise ContractError("inner response body messages must end with more_body=false")
    else:
        raise ContractError("inner response must be body messages or one pathsend event")

    minimum_size = args.get("minimum_size", 500)
    compresslevel = args.get("compresslevel", 9)
    thread_minimum_size = args.get("thread_minimum_size", 128 * 1024)
    if not isinstance(minimum_size, int) or isinstance(minimum_size, bool) or minimum_size < 0:
        raise ContractError("GZipMiddleware minimum_size must be a non-negative integer")
    if (
        not isinstance(compresslevel, int)
        or isinstance(compresslevel, bool)
        or not -1 <= compresslevel <= 9
    ):
        raise ContractError("GZipMiddleware compresslevel must be an integer from -1 through 9")
    if (
        not isinstance(thread_minimum_size, int)
        or isinstance(thread_minimum_size, bool)
        or thread_minimum_size < 0
    ):
        raise ContractError("GZipMiddleware thread_minimum_size must be a non-negative integer")
    if "exclude_content_types" in args:
        exclusions = args["exclude_content_types"]
        if not isinstance(exclusions, list) or any(
            not isinstance(content_type, str) or not content_type for content_type in exclusions
        ):
            raise ContractError("GZipMiddleware exclude_content_types must be a string array")

    content_lengths = [value for name, value in start_headers if name.lower() == b"content-length"]
    if len(content_lengths) > 1:
        raise ContractError("inner response start must not repeat content-length")
    if content_lengths and bodies and not any(more_body for _, more_body in bodies):
        try:
            declared_length = int(content_lengths[0])
        except ValueError as exc:
            raise ContractError("inner content-length must be an integer") from exc
        if declared_length != sum(len(body) for body, _ in bodies):
            raise ContractError("inner content-length must match the supplied response body")


def _gzip_semantic_coverage(case: dict[str, Any]) -> set[str]:
    constructor_args = {
        key: descriptor["value"] for key, descriptor in case["steps"][0]["arguments"].items()
    }
    dispatch_args = {
        key: descriptor["value"] for key, descriptor in case["steps"][1]["arguments"].items()
    }
    app = constructor_args["app"]
    messages = app["messages"]
    response_start = messages[0]
    response_headers = _gzip_header_pairs(
        response_start["headers_base64_pairs"], "response start headers"
    )
    request_headers = _gzip_header_pairs(
        dispatch_args["scope"]["headers_base64_pairs"], "HTTP scope headers"
    )

    def header_value(headers: list[tuple[bytes, bytes]], name: bytes) -> bytes | None:
        return next((value for header_name, value in headers if header_name.lower() == name), None)

    accept_encoding = header_value(request_headers, b"accept-encoding") or b""
    gzip_accepted = b"gzip" in accept_encoding
    content_type_value = header_value(response_headers, b"content-type") or b""
    media_type = content_type_value.partition(b";")[0].strip().lower().decode("latin-1")
    constructor_uses_default_exclusions = "exclude_content_types" not in constructor_args
    excluded_types = {
        content_type.partition(";")[0].strip().lower()
        for content_type in (
            GZIP_DEFAULT_EXCLUDED_CONTENT_TYPES
            if constructor_uses_default_exclusions
            else constructor_args["exclude_content_types"]
        )
    }
    media_family = media_type.partition("/")[0] + "/*"
    default_excluded_media_types = {
        content_type.partition(";")[0].strip().lower()
        for content_type in GZIP_DEFAULT_EXCLUDED_CONTENT_TYPES
    }
    default_excluded_media_type = media_type in default_excluded_media_types or (
        media_family in default_excluded_media_types
    )
    excluded = media_type in excluded_types or media_family in excluded_types
    default_excluded = constructor_uses_default_exclusions and excluded
    configured_excluded = not constructor_uses_default_exclusions and excluded
    content_encoded = header_value(response_headers, b"content-encoding") is not None
    partial_response = response_start["status"] == 206
    output_messages = messages[1:]
    body_messages = [
        message for message in output_messages if message["type"] == "http.response.body"
    ]
    body_lengths = [
        len(base64.b64decode(message["body_base64"], validate=True)) for message in body_messages
    ]
    complete_stream = (
        len(body_messages) >= 2
        and all(message["more_body"] for message in body_messages[:-1])
        and not body_messages[-1]["more_body"]
    )
    minimum_size = constructor_args.get("minimum_size", 500)
    thread_minimum_size = constructor_args.get("thread_minimum_size", 128 * 1024)
    compressible = not content_encoded and not partial_response and not excluded
    coverage = {GZIP_REQUIREMENT_CONSTRUCTION}

    if (
        gzip_accepted
        and compressible
        and any(
            body_length >= thread_minimum_size
            and (index > 0 or message["more_body"] or body_length >= minimum_size)
            for index, (message, body_length) in enumerate(
                zip(body_messages, body_lengths, strict=True)
            )
        )
    ):
        coverage.add(GZIP_REQUIREMENTS["thread-minimum-size"])

    if (
        gzip_accepted
        and len(body_messages) == 1
        and not body_messages[0]["more_body"]
        and body_lengths[0] >= minimum_size
        and compressible
    ):
        coverage.add(GZIP_REQUIREMENTS["gzip-final-response"])
    if (
        accept_encoding.strip().lower() == b"identity"
        and len(body_messages) == 1
        and not body_messages[0]["more_body"]
        and body_lengths[0] >= minimum_size
        and compressible
    ):
        coverage.add(GZIP_REQUIREMENTS["identity-client"])
    if accept_encoding.strip().lower() == b"identity" and complete_stream and compressible:
        coverage.add(GZIP_REQUIREMENTS["identity-streaming-response"])
    if (
        accept_encoding.strip().lower() == b"identity"
        and bool(body_messages)
        and sum(body_lengths) >= minimum_size
        and configured_excluded
        and not content_encoded
        and not partial_response
    ):
        coverage.add(GZIP_REQUIREMENTS["identity-excluded-content-type"])
    if (
        gzip_accepted
        and constructor_args.get("exclude_content_types") == []
        and default_excluded_media_type
        and bool(body_messages)
        and sum(body_lengths) >= minimum_size
        and not content_encoded
        and not partial_response
    ):
        coverage.add(GZIP_REQUIREMENTS["cleared-exclude-content-types"])
    if (
        gzip_accepted
        and len(body_messages) == 1
        and not body_messages[0]["more_body"]
        and body_lengths[0] < minimum_size
        and compressible
    ):
        coverage.add(GZIP_REQUIREMENTS["small-body-bypass"])
    if (
        gzip_accepted
        and bool(body_messages)
        and configured_excluded
        and not content_encoded
        and not partial_response
    ):
        coverage.add(GZIP_REQUIREMENTS["excluded-content-type"])
    if (
        gzip_accepted
        and bool(body_messages)
        and default_excluded
        and not content_encoded
        and not partial_response
    ):
        coverage.add(GZIP_REQUIREMENTS["default-excluded-content-type"])
    if (
        gzip_accepted
        and bool(body_messages)
        and body_lengths[0] >= minimum_size
        and constructor_uses_default_exclusions
        and not excluded
        and not content_encoded
        and not partial_response
    ):
        coverage.add(GZIP_REQUIREMENTS["default-allowed-content-type"])
    if gzip_accepted and complete_stream and compressible:
        coverage.add(GZIP_REQUIREMENTS["streaming-chunks"])
    if (
        gzip_accepted
        and complete_stream
        and compressible
        and len(body_messages) >= 3
        and any(
            not base64.b64decode(message["body_base64"], validate=True) and message["more_body"]
            for message in body_messages
        )
        and any(
            base64.b64decode(message["body_base64"], validate=True) for message in body_messages
        )
    ):
        coverage.add(GZIP_REQUIREMENTS["streaming-empty-chunk"])
    if (
        gzip_accepted
        and complete_stream
        and content_encoded
        and not partial_response
        and not excluded
    ):
        coverage.add(GZIP_REQUIREMENTS["existing-encoding-stream-bypass"])
    if gzip_accepted and partial_response and not content_encoded and not excluded:
        coverage.add(GZIP_REQUIREMENTS["partial-response-stream-bypass"])
    if (
        gzip_accepted
        and len(output_messages) == 1
        and output_messages[0]["type"] == "http.response.pathsend"
    ):
        coverage.add(GZIP_REQUIREMENTS["pathsend"])
    return coverage


def _gzip_responder_semantic_coverage(case: dict[str, Any]) -> set[str]:
    constructor_args = {
        key: descriptor["value"] for key, descriptor in case["steps"][0]["arguments"].items()
    }
    dispatch_args = {
        key: descriptor["value"] for key, descriptor in case["steps"][1]["arguments"].items()
    }
    messages = constructor_args["app"]["messages"]
    response_start = messages[0]
    response_headers = _gzip_header_pairs(
        response_start["headers_base64_pairs"], "GZipResponder response start headers"
    )
    request_headers = _gzip_header_pairs(
        dispatch_args["scope"]["headers_base64_pairs"], "GZipResponder request headers"
    )

    def header_value(headers: list[tuple[bytes, bytes]], name: bytes) -> bytes | None:
        return next((value for header_name, value in headers if header_name.lower() == name), None)

    response_content_type = header_value(response_headers, b"content-type") or b""
    media_type = response_content_type.partition(b";")[0].strip().lower().decode("latin-1")
    configured = constructor_args.get("exclude_content_types")
    normalized_exclusions = {item.partition(";")[0].strip().lower() for item in configured or []}
    media_family = media_type.partition("/")[0] + "/*"
    excluded = media_type in normalized_exclusions or media_family in normalized_exclusions
    content_encoded = header_value(response_headers, b"content-encoding") is not None
    partial_response = response_start["status"] == 206
    body_messages = [message for message in messages[1:] if message["type"] == "http.response.body"]
    body_length = sum(
        len(base64.b64decode(message["body_base64"], validate=True)) for message in body_messages
    )
    minimum_size = constructor_args["minimum_size"]
    coverage = {GZIP_RESPONDER_REQUIREMENTS["construct"]}

    if (
        configured
        and body_messages
        and body_length >= minimum_size
        and excluded
        and not content_encoded
        and not partial_response
    ):
        coverage.add(GZIP_RESPONDER_REQUIREMENTS["excluded-content-type"])
    if (
        body_messages
        and body_length >= minimum_size
        and not excluded
        and not content_encoded
        and not partial_response
        and header_value(request_headers, b"accept-encoding") is None
    ):
        coverage.add(GZIP_RESPONDER_REQUIREMENTS["direct-compression"])
    return coverage


def _route_path_matches(route_path: str, request_path: str) -> bool:
    return _route_template_matches(route_path, request_path)


def _starlette_add_route_semantic_coverage(case: dict[str, Any]) -> set[str]:
    registration = case["steps"][1]
    route_arguments = {key: item["value"] for key, item in registration["arguments"].items()}
    route_path = route_arguments["path"]
    methods = set(route_arguments["methods"])
    effective_methods = methods | ({"HEAD"} if "GET" in methods else set())
    dispatches = {
        step["step_id"]: {key: item["value"] for key, item in step["arguments"].items()}
        for step in case["steps"][2:]
    }
    coverage: set[str] = set()
    successful_dispatches = [
        dispatch["scope"]
        for dispatch in dispatches.values()
        if dispatch["scope"]["path"] == route_path
        and dispatch["scope"]["method"] in effective_methods
    ]
    if {scope["method"] for scope in successful_dispatches} >= {"GET"}:
        coverage.add(STARLETTE_ADD_ROUTE_WORKFLOW_REQUIREMENTS["success"])
    wrong_method = dispatches.get("dispatch-wrong-method", {}).get("scope", {})
    if (
        wrong_method.get("path") == route_path
        and wrong_method.get("method") not in effective_methods
    ):
        coverage.add(STARLETTE_ADD_ROUTE_WORKFLOW_REQUIREMENTS["method_miss"])
    return coverage


def _semantic_coverage(case: dict[str, Any]) -> set[str]:
    if case["surface"] == GZIP_SURFACE:
        return _gzip_semantic_coverage(case)
    if case["surface"] == GZIP_RESPONDER_SURFACE:
        return _gzip_responder_semantic_coverage(case)
    if any(step.get("operation") == "add_exception_handler" for step in case["steps"]):
        return _starlette_add_exception_handler_semantic_coverage(case)
    if any(step.get("operation") == "add_middleware" for step in case["steps"]):
        return _starlette_add_middleware_semantic_coverage(case)
    if _is_route_body_limit_workflow(case):
        requirement = _route_body_limit_requirement_from_input(case)
        return set() if requirement is None else {requirement}
    if _is_route_middleware_workflow(case):
        app_arguments = {
            key: descriptor["value"] for key, descriptor in case["steps"][0]["arguments"].items()
        }
        topology = _route_middleware_topology(app_arguments["routes"])
        requirement_key = {
            "route": "route",
            "mount_routes": "mount_routes",
            "mount_app": "mount_app",
            "mount_exception": "mount_exception",
            "mounted_app_exception_propagation": "mounted_app_exception_propagation",
        }.get(topology)
        return (
            {STARLETTE_ROUTE_MIDDLEWARE_REQUIREMENTS[requirement_key]}
            if requirement_key is not None
            else set()
        )
    if any(step.get("operation") == "add_route" for step in case["steps"]):
        return _starlette_add_route_semantic_coverage(case)
    app_arguments = {
        key: descriptor["value"] for key, descriptor in case["steps"][0]["arguments"].items()
    }
    if case["execution_schedule"] == ["lifespan.startup", "lifespan.shutdown"]:
        lifecycle_args = {
            key: descriptor["value"] for key, descriptor in case["steps"][1]["arguments"].items()
        }
        return {_lifespan_case_requirement(app_arguments["lifespan"], lifecycle_args)}
    route = app_arguments["routes"][0]
    endpoint = route["endpoint"]
    dispatch_arguments = {
        key: descriptor["value"] for key, descriptor in case["steps"][-1]["arguments"].items()
    }
    scope = dispatch_arguments["scope"]
    path = scope["path"]
    if case["operation"] == "__call__" and route["kind"] == "websocket-route":
        if scope.get("type") != "websocket" or path != route["path"]:
            return set()
        endpoint = route["endpoint"]
        if endpoint["kind"] == "authentication-required-websocket":
            if case["target_profiles"] != ["python-package-cpython312"]:
                return set()
            outcome = _authentication_middleware_outcome(scope)
            access = {
                "missing": "denied",
                "valid": "authorized",
                "invalid": "invalid-basic-credentials",
            }[outcome]
            return {AUTHENTICATION_REQUIRED_WEBSOCKET_REQUIREMENTS[f"{endpoint['form']}-{access}"]}
        if endpoint["kind"] == "http-exception":
            return {"starlette.asgi.websocket-exception.http-denial-response"}
        action = endpoint["actions"][-1]
        if action["action"] == "raise-websocket-exception":
            handlers = app_arguments["exception_handlers"]
            if any(
                entry["key"] == {"kind": "exception-class", "name": "WebSocketException"}
                and entry["handler"]["kind"] == "websocket-exception-close-handler"
                for entry in handlers
            ):
                return {"starlette.asgi.websocket-exception.websocket-class-handler"}
            return {"starlette.asgi.websocket-exception.default-handler"}
        return {"starlette.asgi.websocket-exception.custom-handler"}
    method = scope["method"]
    path_matches = _route_path_matches(route["path"], path)
    methods = {"GET"} if route["methods"] is None else set(route["methods"])
    if "GET" in methods:
        methods.add("HEAD")
    method_matches = method in methods
    coverage: set[str] = set()
    if endpoint["kind"] == "authentication-login-next-redirect":
        if (
            case["operation"] == "__call__"
            and case["target_profiles"] == ["python-package-cpython312"]
            and route["kind"] == "http-route"
            and path_matches
            and method_matches
            and scope.get("type") == "http"
            and _authentication_middleware_outcome(scope) == "valid"
        ):
            query_string = base64.b64decode(scope["query_string_base64"], validate=True).decode(
                "ascii"
            )
            if any(
                name == endpoint["query_parameter"] and value
                for name, value in parse_qsl(query_string, keep_blank_values=True)
            ):
                return {AUTHENTICATION_LOGIN_NEXT_REDIRECT_REQUIREMENT}
        return coverage
    if endpoint["kind"] == "authentication-user-interface":
        if (
            case["operation"] == "__call__"
            and path_matches
            and method_matches
            and scope.get("type") == "http"
        ):
            requirement = _authentication_user_interface_requirement(scope)
            if requirement is not None:
                coverage.add(requirement)
                if requirement in {
                    AUTH_USER_INTERFACE_REQUIREMENTS["unauthenticated"],
                    AUTH_USER_INTERFACE_REQUIREMENTS["basic"],
                    AUTH_USER_INTERFACE_REQUIREMENTS["wrong-scheme"],
                }:
                    coverage.add(AUTH_USER_INTERFACE_REQUIREMENTS["auth-state"])
        return coverage
    if endpoint["kind"] == "authentication-required-route":
        if (
            case["operation"] != "__call__"
            or case["target_profiles"] != ["python-package-cpython312"]
            or route["kind"] != "http-route"
            or not path_matches
            or not method_matches
            or scope.get("type") != "http"
        ):
            return coverage
        outcome = _authentication_middleware_outcome(scope)
        if outcome == "invalid":
            return {AUTHENTICATION_REQUIRED_ROUTE_REQUIREMENTS["invalid-basic-credentials"]}
        form = endpoint["form"]
        access = "authorized" if outcome == "valid" else "denied"
        return {AUTHENTICATION_REQUIRED_ROUTE_REQUIREMENTS[f"{form}-{access}"]}
    if (
        case["operation"] == "__call__"
        and case["target_profiles"] == ["python-package-cpython312"]
        and route["kind"] == "http-route"
        and endpoint["kind"] == "plain-text-response"
        and path_matches
        and method_matches
    ):
        coverage.add("starlette.applications.Starlette.__call__.async-route-return-response")
    if (
        case["operation"] == "__call__"
        and case["target_profiles"] == ["python-package-cpython312"]
        and route["kind"] == "http-route"
        and endpoint["kind"] == "sync-plain-text-response"
        and route["methods"] is None
        and path_matches
    ):
        observed_methods = set()
        for step in case["steps"]:
            if step.get("operation") != "__call__":
                continue
            step_arguments = {
                key: descriptor["value"] for key, descriptor in step["arguments"].items()
            }
            step_scope = step_arguments["scope"]
            if (
                step_scope.get("type") == "http"
                and _route_path_matches(route["path"], step_scope["path"])
                and step_scope["method"] in methods
            ):
                observed_methods.add(step_scope["method"])
        if {"GET", "HEAD"} <= observed_methods:
            coverage.add("starlette.applications.Starlette.__call__.sync-route-return-response")

    if case["operation"] == "__call__":
        handlers = app_arguments["exception_handlers"]
        if _is_server_error_stimulus(app_arguments):
            key_specs = [entry["key"] for entry in handlers]
            has_status_500 = {"kind": "status-code", "status_code": 500} in key_specs
            has_exception = {"kind": "exception-class", "name": "Exception"} in key_specs
            if path_matches and method_matches:
                if endpoint["kind"] == "raise-runtime-error":
                    if not handlers and not app_arguments["debug"]:
                        coverage.add("starlette.asgi.server-error.default-response")
                    if has_status_500:
                        coverage.add("starlette.asgi.server-error.status-500-handler")
                    if has_exception:
                        coverage.add("starlette.asgi.server-error.exception-handler")
                    if has_status_500 and has_exception:
                        coverage.add("starlette.asgi.server-error.special-key-order")
                    if app_arguments["debug"]:
                        coverage.add("starlette.asgi.server-error.debug-traceback")
                elif endpoint["kind"] == "asgi-callable-action-sequence":
                    if any(
                        action["action"] == "raise-runtime-error" for action in endpoint["actions"]
                    ):
                        coverage.add("starlette.asgi.server-error.response-started")
                elif endpoint["kind"] == "response-background-task-error":
                    if has_exception:
                        coverage.add("starlette.asgi.server-error.background-task-failure")
                elif endpoint["kind"] == "http-exception" and endpoint["status_code"] == 500:
                    if has_status_500 and any(
                        key == {"kind": "exception-class", "name": "HTTPException"}
                        for key in key_specs
                    ):
                        coverage.add("starlette.asgi.server-error.handled-http-exception-500")
            return coverage
        if handlers:
            entries_by_key = {
                (
                    entry["key"]["kind"],
                    entry["key"].get("name", entry["key"].get("status_code")),
                ): entry
                for entry in handlers
            }
            if _is_router_miss_http_exception_handler_workflow(app_arguments, dispatch_arguments):
                coverage.update(
                    {
                        ROUTER_MISS_EXCEPTION_HANDLER_REQUIREMENT,
                        "starlette.asgi.exception-handler.async-callback",
                    }
                )
            elif endpoint["kind"] == "http-exception-after-body":
                subclass_key = ("exception-class", endpoint["exception_class"])
                handler_entry = entries_by_key.get(subclass_key)
                if path_matches and method_matches and handler_entry is not None:
                    coverage.update(
                        {
                            "starlette.asgi.exception-handler.exception-class",
                            "starlette.asgi.exception-handler.async-callback",
                        }
                    )
                    if handler_entry["handler"]["kind"] == "request-body-json-response":
                        messages = dispatch_arguments["receive"]
                        chunks = [
                            base64.b64decode(message["body_base64"], validate=True)
                            for message in messages
                        ]
                        if (
                            len(chunks) > 1
                            and all(message["more_body"] for message in messages[:-1])
                            and not messages[-1]["more_body"]
                            and b"".join(chunks)
                        ):
                            coverage.add(
                                "starlette.asgi.exception-handler.request-body-cache-reuse"
                            )
            elif endpoint["kind"] == "http-exception":
                handler_entry = entries_by_key.get(("exception-class", "HTTPException"))
                if (
                    path_matches
                    and method_matches
                    and endpoint["headers"]
                    and handler_entry is not None
                    and handler_entry["handler"]["kind"] == "json-exception-detail-headers-response"
                ):
                    coverage.update(
                        {
                            "starlette.asgi.exception-handler.exception-class",
                            "starlette.asgi.exception-handler.async-callback",
                            "starlette.asgi.exception-handler.headers-forwarding",
                        }
                    )
            elif path_matches and not method_matches:
                if ("status-code", 405) in entries_by_key:
                    coverage.add("starlette.asgi.exception-handler.status-code")
                if ("exception-class", "HTTPException") in entries_by_key:
                    coverage.add("starlette.asgi.exception-handler.exception-class")
                if handlers and all(
                    entry["handler"]["kind"]
                    in {"json-exception-detail-response", "json-literal-response"}
                    for entry in handlers
                ):
                    coverage.add("starlette.asgi.exception-handler.async-callback")
            return coverage
        if endpoint["kind"] == "http-exception":
            if path_matches and method_matches:
                status_code = endpoint["status_code"]
                detail = endpoint["detail"]
                headers = endpoint["headers"]
                if status_code == 406 and detail is None:
                    coverage.add("starlette.asgi.http-exception.default-406-detail")
                elif status_code == 406 and isinstance(detail, str):
                    coverage.add("starlette.asgi.http-exception.explicit-detail")
                elif status_code == 204 and detail is None:
                    coverage.add("starlette.asgi.http-exception.no-content-204")
                elif status_code == 304 and detail is None:
                    coverage.add("starlette.asgi.http-exception.not-modified-304")
                elif status_code == 200 and detail is None and headers:
                    coverage.add("starlette.asgi.http-exception.headers-200")
            return coverage
        if path_matches and method_matches:
            coverage.update(
                {
                    "starlette.asgi.get-hello.application-construction",
                    "starlette.asgi.get-hello.dispatch",
                }
            )
        elif not path_matches and _application_has_slash_redirect(
            app_arguments["routes"], path, scope.get("root_path", "")
        ):
            coverage.add("starlette.asgi.get-hello.slash-redirect")
        elif not path_matches:
            coverage.add("starlette.asgi.get-hello.route-miss-404")
        else:
            coverage.add("starlette.asgi.get-hello.wrong-method-405")
        if case["execution_schedule"] == [
            "lifespan.startup",
            "dispatch",
            "lifespan.shutdown",
        ]:
            coverage.add("starlette.asgi.get-hello.lifespan")
        return coverage

    coverage.update(
        {
            "starlette.routing.request-scope-values",
            "starlette.asgi.request-dispatch-events",
        }
    )
    if not path_matches:
        coverage.add("starlette.routing.items-route-miss-404")
        return coverage
    if not method_matches:
        coverage.add("starlette.routing.items-wrong-method-405")
        return coverage

    path_parameters = dict(_route_template_parameters(route["path"]))
    path_parameter = endpoint.get("path_parameter")
    if path_parameter is not None:
        converter = path_parameters.get(path_parameter)
        requirement = {
            "str": "starlette.request.path-param-string",
            "int": "starlette.request.path-param-int",
            "float": "starlette.request.path-param-float",
            "uuid": "starlette.request.path-param-uuid",
            "path": "starlette.request.path-param-path",
        }.get(converter)
        if requirement is not None:
            coverage.add(requirement)
        if converter == "int":
            captured = _route_template_capture(route["path"], path)
            raw_value = captured.get(path_parameter) if captured is not None else None
            integer_limit = sys.get_int_max_str_digits()
            if integer_limit > 0 and raw_value is not None and len(raw_value) > integer_limit:
                coverage.add("starlette.request.path-param-int-digit-limit")

    if endpoint["kind"] == "request-observer":
        query = base64.b64decode(scope["query_string_base64"], validate=True).decode("ascii")
        query_values = [
            value
            for name, value in parse_qsl(query, keep_blank_values=True)
            if name == endpoint["query_parameter"]
        ]
        if len(query_values) > 1:
            coverage.add("starlette.request.query-params-getlist-scalar")

        headers = [
            (
                base64.b64decode(name, validate=True).decode("latin-1").casefold(),
                base64.b64decode(value, validate=True).decode("latin-1"),
            )
            for name, value in scope["headers_base64_pairs"]
        ]
        primary_header = endpoint["header_primary_case"]
        alternate_header = endpoint["header_alternate_case"]
        if (
            primary_header != alternate_header
            and primary_header.casefold() == alternate_header.casefold()
            and any(name == primary_header.casefold() for name, _ in headers)
        ):
            coverage.add("starlette.request.headers-case-insensitive")

        cookie_name = endpoint["cookie_name"]
        cookies = [
            cookie.strip().partition("=")
            for name, value in headers
            if name == "cookie"
            for cookie in value.split(";")
        ]
        if any(name == cookie_name and separator for name, separator, _ in cookies):
            coverage.add("starlette.request.cookies")

        messages = dispatch_arguments["receive"]
        chunks = [base64.b64decode(message["body_base64"], validate=True) for message in messages]
        has_complete_chunking = (
            len(messages) > 1
            and all(message["more_body"] for message in messages[:-1])
            and not messages[-1]["more_body"]
        )
        if has_complete_chunking:
            try:
                json.loads(b"".join(chunks))
            except (json.JSONDecodeError, UnicodeDecodeError):
                pass
            else:
                coverage.add("starlette.request.json-chunked-body")
    elif endpoint["kind"] == "request-cookies-observer":
        cookie_values = _request_cookie_header_values(scope)
        if cookie_values and any(cookie_values):
            if endpoint["probe"]["kind"] == "items":
                coverage.add(REQUEST_COOKIES_LENIENT_REQUIREMENT)
            elif endpoint["probe"]["kind"] == "mapping-actions":
                coverage.add(REQUEST_COOKIES_DICT_REQUIREMENT)
    elif endpoint["kind"] == "request-connection-property":
        property_name = endpoint["property"]
        if property_name == "app":
            coverage.add(REQUEST_CONNECTION_PROPERTY_REQUIREMENTS[property_name])
        elif property_name not in scope:
            coverage.add(REQUEST_CONNECTION_PROPERTY_REQUIREMENTS[property_name])
    elif endpoint["kind"] == "request-state-observer":
        coverage.add(REQUEST_STATE_LAZY_INITIALIZATION_REQUIREMENT)
    elif endpoint["kind"] == "request-stream-observer":
        operations = {action["operation"] for action in endpoint["actions"]}
        coverage.update(
            requirement
            for operation, requirement in REQUEST_STREAM_REQUIREMENTS.items()
            if operation in operations
        )
    elif endpoint["kind"] == "sync-request-runtime-observer":
        coverage.update(
            SYNC_REQUEST_RUNTIME_REQUIREMENTS[action["property"]]
            if action["operation"] == "callable-property"
            else SYNC_REQUEST_RUNTIME_REQUIREMENTS[
                action["method"] if action["operation"] == "construct-awaitable" else "stream"
            ]
            for action in endpoint["actions"]
        )
        coverage.update(
            SYNC_ENDPOINT_REQUIREMENTS[key]
            for key in ("contextvar", "worker_thread", "single_invocation")
        )
    elif endpoint["kind"] == "sync-request-observer":
        coverage.update(
            SYNC_ENDPOINT_REQUIREMENTS[key]
            for key in ("contextvar", "worker_thread", "single_invocation")
        )
        if endpoint["callable_kind"] in {"bound_method", "partial"}:
            coverage.add(SYNC_ENDPOINT_REQUIREMENTS["callable_form"])
        if "error_message" in endpoint:
            coverage.add("starlette.asgi.server-error.default-response")
    elif endpoint["kind"] == "async-request-callable-observer":
        coverage.add(ASYNC_ENDPOINT_CALLABLE_REQUIREMENT)
        if "error_message" in endpoint:
            coverage.add("starlette.asgi.server-error.default-response")
    elif endpoint["kind"] == "sync-request-cancellation-observer":
        coverage.update(
            SYNC_ENDPOINT_REQUIREMENTS[key]
            for key in ("worker_thread", "single_invocation", "worker_cancellation")
        )
    elif endpoint["kind"] == "asgi-callable-instance-observer":
        coverage.add(ASGI_CALLABLE_INSTANCE_REQUIREMENT)
    elif endpoint == ASYNC_CALL_BOUNDARY_ENDPOINT:
        if case["execution_schedule"] == ["dispatch", "cancel-server-task"]:
            coverage.update(ASYNC_CALL_BOUNDARY_REQUIREMENTS)
    elif endpoint["kind"] == "asgi-callable-action-sequence":
        coverage.add(ASGI_CALLABLE_INSTANCE_REQUIREMENT)
        sent_response = any(action["action"] == "send" for action in endpoint["actions"])
        action_kinds = {action["action"] for action in endpoint["actions"]}
        if "raise-http-exception" in action_kinds:
            coverage.add(
                "starlette.routing.asgi-callable-http-exception-after-start"
                if sent_response
                else "starlette.routing.asgi-callable-http-exception-before-start"
            )
        if "raise-runtime-error" in action_kinds:
            coverage.add(
                "starlette.asgi.server-error.response-started"
                if sent_response
                else "starlette.asgi.server-error.default-response"
            )
    return coverage


def validate_input_document(document: Any, manifest: dict[str, Any]) -> list[dict[str, Any]]:
    _exact(document, {"schema", "cases"}, "parity input")
    if document["schema"] != INPUT_SCHEMA:
        raise ContractError(f"unsupported parity input schema: {document['schema']!r}")
    if not isinstance(document["cases"], list) or not document["cases"]:
        raise ContractError("parity input must select at least one case")
    cases = [validate_case(case, manifest) for case in document["cases"]]
    ids = [case["case_id"] for case in cases]
    if len(ids) != len(set(ids)):
        raise ContractError("parity input case IDs must be globally unique")
    return cases


def validate_benchmark_document(
    document: Any, cases: list[dict[str, Any]], manifest: dict[str, Any]
) -> dict[str, Any]:
    _exact(document, {"schema", "workloads", "suites"}, "benchmark input")
    if document["schema"] != BENCHMARK_INPUT_SCHEMA:
        raise ContractError(f"unsupported benchmark input schema: {document['schema']!r}")
    if not isinstance(document["workloads"], list) or len(document["workloads"]) != 1:
        raise ContractError("the slice benchmark must declare exactly one explicit workload")
    workload = _exact(
        document["workloads"][0],
        {"workload_id", "covers", "subjects", "input", "measurement"},
        "benchmark workload",
    )
    if workload["workload_id"] != "starlette.asgi.get-hello.direct-dispatch":
        raise ContractError(
            "benchmark workload ID differs from the declared direct-ASGI smoke workload"
        )
    if workload["covers"] != ["starlette.asgi.get-hello.latency"]:
        raise ContractError("benchmark workload must cover the declared latency requirement")
    expected_subjects = [
        {"kind": "oracle", "id": "starlette-python"},
        {"kind": "target_profile", "id": "rust-native-local"},
        {"kind": "target_profile", "id": "python-package-cpython312"},
    ]
    if workload["subjects"] != expected_subjects:
        raise ContractError(
            "benchmark subjects must include the pinned oracle and both declared targets in order"
        )
    for subject in workload["subjects"]:
        _exact(subject, {"kind", "id"}, "benchmark subject")
    _exact(workload["input"], {"kind", "case_id"}, "benchmark workload input")
    expected_case_id = "starlette.applications.Starlette.__call__.get-hello"
    if workload["input"] != {"kind": "parity_case", "case_id": expected_case_id}:
        raise ContractError("benchmark must reference the public GET /hello parity case")
    if expected_case_id not in {case["case_id"] for case in cases}:
        raise ContractError("benchmark references a parity case outside the active input set")
    measurement = _exact(
        workload["measurement"],
        {
            "boundary",
            "step_ids",
            "metrics",
            "warmup_iterations",
            "measurement_iterations",
            "samples",
            "concurrency",
            "cache_state",
            "correctness_gate",
        },
        "benchmark measurement",
    )
    if measurement != {
        "boundary": "observed_steps",
        "step_ids": ["dispatch"],
        "metrics": ["latency"],
        "warmup_iterations": 20,
        "measurement_iterations": 100,
        "samples": 30,
        "concurrency": 1,
        "cache_state": "warm",
        "correctness_gate": "parity_pass",
    }:
        raise ContractError(
            "benchmark measurement policy differs from the declared deterministic smoke policy"
        )
    if not isinstance(document["suites"], list) or len(document["suites"]) != 1:
        raise ContractError("the smoke benchmark must declare exactly one suite")
    suite = _exact(document["suites"][0], {"suite_id", "description", "members"}, "benchmark suite")
    if (
        suite["suite_id"] != "direct-asgi-smoke"
        or not isinstance(suite["description"], str)
        or not suite["description"]
    ):
        raise ContractError("benchmark suite ID/description is invalid")
    if suite["members"] != [{"workload_id": workload["workload_id"], "weight": 1}]:
        raise ContractError(
            "benchmark suite must include the direct ASGI workload with unit weight"
        )
    _exact(suite["members"][0], {"workload_id", "weight"}, "benchmark suite member")
    requirement_rows = [
        requirement
        for surface in manifest["surfaces"]
        for operation in surface["operations"]
        for requirement in operation["requirements"]
        if requirement["id"] == workload["covers"][0]
    ]
    if len(requirement_rows) != 1 or requirement_rows[0]["lanes"] != ["benchmark"]:
        raise ContractError(
            "benchmark requirement must resolve to exactly one benchmark-only requirement"
        )
    return document


def validate_benchmark_inputs(
    root: Path, manifest: dict[str, Any], cases: list[dict[str, Any]]
) -> list[tuple[Path, dict[str, Any]]]:
    lane_root = root / GENERATED_INPUT_ROOT / "benchmark"
    indexed: set[str] = set()
    documents: list[tuple[Path, dict[str, Any]]] = []
    for relative in manifest["input_index"]["benchmark"]:
        path = root / relative
        try:
            path.resolve().relative_to(lane_root.resolve())
        except ValueError as exc:
            raise ContractError(f"benchmark input escapes its lane root: {relative}") from exc
        document = load_json(path)
        if not isinstance(document, dict):
            raise ContractError(f"benchmark input must be an object: {relative}")
        if document.get("schema") == BENCHMARK_INPUT_SCHEMA:
            validate_benchmark_document(document, cases, manifest)
        elif document.get("schema") == UPSTREAM_BENCHMARK_INPUT_SCHEMA:
            from .upstream_benchmark_contract import validate_upstream_workloads

            validate_upstream_workloads(document)
        else:
            raise ContractError(f"unsupported benchmark input schema: {document.get('schema')!r}")
        indexed.add(path.resolve().as_posix())
        documents.append((path, document))
    discovered = (
        {path.resolve().as_posix() for path in lane_root.rglob("*.json")}
        if lane_root.exists()
        else set()
    )
    if indexed != discovered:
        raise ContractError(
            f"benchmark input index mismatch: missing={sorted(discovered - indexed)}, stale={sorted(indexed - discovered)}"
        )
    return documents


def validate_inputs(
    root: Path, manifest: dict[str, Any]
) -> tuple[list[tuple[Path, dict[str, Any]]], list[dict[str, Any]]]:
    index = manifest["input_index"]
    active: set[str] = set()
    loaded: list[tuple[Path, dict[str, Any]]] = []
    all_cases: list[dict[str, Any]] = []
    for relative in index["parity"]:
        path = root / relative
        try:
            path.resolve().relative_to((root / GENERATED_INPUT_ROOT / "parity").resolve())
        except ValueError as exc:
            raise ContractError(f"parity input escapes its lane root: {relative}") from exc
        active.add(path.resolve().as_posix())
        document = load_json(path)
        cases = validate_input_document(document, manifest)
        loaded.append((path, document))
        all_cases.extend(cases)
    parity_root = root / GENERATED_INPUT_ROOT / "parity"
    discovered = (
        {path.resolve().as_posix() for path in parity_root.rglob("*.json")}
        if parity_root.exists()
        else set()
    )
    if active != discovered:
        raise ContractError(
            f"parity input index mismatch: missing={sorted(discovered - active)}, stale={sorted(active - discovered)}"
        )
    case_ids = [case["case_id"] for case in all_cases]
    if len(case_ids) != len(set(case_ids)):
        raise ContractError("case IDs must be unique across all indexed parity inputs")
    parity_requirements = {
        requirement["id"]
        for surface in manifest["surfaces"]
        for operation in surface["operations"]
        for requirement in operation["requirements"]
        if "parity" in requirement["lanes"]
    }
    covered_requirements = {requirement for case in all_cases for requirement in case["covers"]}
    missing_requirements = parity_requirements - covered_requirements
    if missing_requirements:
        raise ContractError(
            f"indexed parity inputs do not cover declared parity requirements: {sorted(missing_requirements)}"
        )
    required_profiles_by_requirement = {
        requirement["id"]: set(requirement["target_profiles"])
        for surface in manifest["surfaces"]
        for operation in surface["operations"]
        for requirement in operation["requirements"]
        if "parity" in requirement["lanes"]
    }
    covered_profiles_by_requirement: dict[str, set[str]] = {
        requirement_id: set() for requirement_id in required_profiles_by_requirement
    }
    for case in all_cases:
        for requirement_id in case["covers"]:
            covered_profiles_by_requirement[requirement_id].update(case["target_profiles"])
    missing_requirement_profiles = {
        requirement_id: sorted(required_profiles - covered_profiles_by_requirement[requirement_id])
        for requirement_id, required_profiles in required_profiles_by_requirement.items()
        if required_profiles - covered_profiles_by_requirement[requirement_id]
    }
    if missing_requirement_profiles:
        missing_pairs = [
            (requirement_id, profile_id)
            for requirement_id, profile_ids in sorted(missing_requirement_profiles.items())
            for profile_id in profile_ids
        ]
        raise ContractError(
            "indexed parity inputs do not cover declared parity requirement/profile pairs: "
            f"{missing_pairs}"
        )
    if index["coverage"]:
        raise ContractError(
            "coverage inputs are outside this slice; full replacement coverage remains required"
        )
    coverage_root = root / GENERATED_INPUT_ROOT / "coverage"
    if coverage_root.exists() and any(coverage_root.rglob("*.json")):
        raise ContractError("unindexed coverage inputs are not allowed")
    validate_benchmark_inputs(root, manifest, all_cases)
    return loaded, all_cases


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def validate_workflow_result(value: Any, expected_case_id: str, context: str) -> dict[str, Any]:
    _exact(value, {"case_id", "status", "observations"}, context)
    if value["case_id"] != expected_case_id:
        raise ContractError(f"{context}.case_id mismatch")
    if value["status"] not in PARITY_TERMINAL_STATUSES:
        raise ContractError(f"{context}.status is invalid")
    observations = value["observations"]
    if not isinstance(observations, list):
        raise ContractError(f"{context}.observations must be an array")
    for index, item in enumerate(observations):
        item_context = f"{context}.observations[{index}]"
        if not isinstance(item, dict):
            raise ContractError(f"{item_context} must be an object")
        status = item.get("status")
        if status == "ok":
            _exact(item, {"step_id", "status", "value"}, item_context)
        elif status == "error":
            _exact(item, {"step_id", "status", "error", "partial_value"}, item_context)
            _exact(
                item["error"],
                {
                    "class",
                    "kind",
                    "message",
                    "stage",
                    "code",
                    "cause",
                    "suppress_context",
                },
                f"{item_context}.error",
            )
            for name in ("class", "kind", "message", "stage"):
                if item["error"][name] is not None and not isinstance(item["error"][name], str):
                    raise ContractError(f"{item_context}.error.{name} must be a string or null")
            code = item["error"]["code"]
            if code is not None and (not isinstance(code, (str, int)) or isinstance(code, bool)):
                raise ContractError(f"{item_context}.error.code must be a string, integer, or null")
            cause = item["error"]["cause"]
            if cause is not None:
                _exact(cause, {"class", "message", "attributes"}, f"{item_context}.error.cause")
                for name in ("class", "message"):
                    if cause[name] is not None and not isinstance(cause[name], str):
                        raise ContractError(
                            f"{item_context}.error.cause.{name} must be a string or null"
                        )
                if not isinstance(cause["attributes"], dict):
                    raise ContractError(f"{item_context}.error.cause.attributes must be an object")
            if not isinstance(item["error"]["suppress_context"], bool):
                raise ContractError(f"{item_context}.error.suppress_context must be boolean")
            if not isinstance(item["partial_value"], dict):
                raise ContractError(f"{item_context}.partial_value must be an object")
        elif status in {"skipped", "unsupported"}:
            _exact(item, {"step_id", "status", "reason"}, item_context)
            _string(item["reason"], f"{item_context}.reason")
        else:
            raise ContractError(f"{item_context}.status is invalid or unsupported")
    if value["status"] in {"skipped", "unsupported"} and not value["observations"]:
        return value
    if value["status"] == "completed" and not value["observations"]:
        raise ContractError(f"{context} completed with no observation evidence")
    return value


def _validate_session_workflow_result(
    case: dict[str, Any], result: dict[str, Any], context: str
) -> None:
    if result["status"] != "completed":
        return
    observations = [
        item for item in result["observations"] if item.get("step_id") == SESSION_WORKFLOW_OPERATION
    ]
    if len(observations) != 1 or observations[0]["status"] != "ok":
        raise ContractError(f"{context} must contain one completed Session workflow value")
    value = _exact(
        observations[0]["value"],
        {"secret_key_observation", "requests"},
        f"{context}.value",
    )
    rows = value["requests"]
    if not isinstance(rows, list) or len(rows) != len(case["requests"]):
        raise ContractError(f"{context}.requests must match the input request count")
    request_fields = {
        "request_id",
        "action",
        "outcome",
        "error",
        "session",
        "accessed",
        "modified",
        "mutation_result",
        "response_status",
        "response_headers",
        "response_bytes",
        "asgi_event_order",
        "asgi_events",
    }
    for index, (row, request) in enumerate(zip(rows, case["requests"], strict=True)):
        row_context = f"{context}.requests[{index}]"
        _exact(row, request_fields, row_context)
        if row["request_id"] != request["request_id"]:
            raise ContractError(f"{row_context}.request_id differs from its input")
        if row["action"] != request["action"]["kind"]:
            raise ContractError(f"{row_context}.action differs from its input")
        if row["outcome"] not in {"ok", "error"}:
            raise ContractError(f"{row_context}.outcome is invalid")
        error = row["error"]
        if error is not None:
            _exact(error, {"class", "message"}, f"{row_context}.error")
            _string(error["class"], f"{row_context}.error.class")
            _string(error["message"], f"{row_context}.error.message")
        if (row["outcome"] == "error") != (error is not None):
            raise ContractError(f"{row_context}.outcome and error do not agree")
        if row["outcome"] == "error":
            if request["action"]["kind"] != "session-operation":
                raise ContractError(f"{row_context} records an error outside Session operations")
            if (
                row["response_status"] is not None
                or row["response_headers"]
                or row["response_bytes"] != {"encoding": "base64", "data": ""}
                or row["asgi_event_order"]
                or row["asgi_events"]
            ):
                raise ContractError(f"{row_context} emitted response data after an escaped error")
        if row["accessed"] is not None and not isinstance(row["accessed"], bool):
            raise ContractError(f"{row_context}.accessed must be boolean or null")
        if row["modified"] is not None and not isinstance(row["modified"], bool):
            raise ContractError(f"{row_context}.modified must be boolean or null")
        if (
            not isinstance(row["response_headers"], list)
            or not isinstance(row["asgi_event_order"], list)
            or not isinstance(row["asgi_events"], list)
        ):
            raise ContractError(f"{row_context} response observations must be arrays")
        if not isinstance(row["response_bytes"], dict):
            raise ContractError(f"{row_context}.response_bytes must be an object")
        _exact(row["response_bytes"], {"encoding", "data"}, f"{row_context}.response_bytes")
        if row["response_bytes"]["encoding"] != "base64" or not isinstance(
            row["response_bytes"]["data"], str
        ):
            raise ContractError(f"{row_context}.response_bytes is malformed")


def _validate_sha256(value: Any, context: str) -> None:
    if (
        not isinstance(value, str)
        or len(value) != 64
        or any(character not in "0123456789abcdef" for character in value)
    ):
        raise ContractError(f"{context} must be a lowercase SHA-256 digest")


def _validate_nonnegative_integer(value: Any, context: str) -> None:
    if not isinstance(value, int) or isinstance(value, bool) or value < 0:
        raise ContractError(f"{context} must be a non-negative integer")


def _sample_quantile(values: list[float], percentile: float) -> float:
    ordered = sorted(values)
    index = max(0, min(len(ordered) - 1, int((percentile * len(ordered) + 0.999999999) - 1)))
    return ordered[index]


def _validate_not_run_subject_identity(identity: Any, subject_id: str, context: str) -> None:
    if identity is None:
        return
    if subject_id == "starlette-python":
        oracle = _exact(
            identity,
            {
                "oracle_id",
                "name",
                "version",
                "revision",
                "runtime",
                "module_path",
                "dependency_lock_sha256",
                "os",
                "architecture",
                "environment_sha256",
                "runtime_lock_sha256",
            },
            context,
        )
        if (
            oracle["oracle_id"] != subject_id
            or oracle["version"] != "1.6.0"
            or oracle["revision"] != ORACLE_COMMIT
        ):
            raise ContractError(f"{context} differs from the pinned Starlette oracle identity")
        for name in ("name", "version", "revision", "runtime", "module_path", "os", "architecture"):
            _string(oracle[name], f"{context}.{name}")
        for name in ("dependency_lock_sha256", "environment_sha256", "runtime_lock_sha256"):
            _validate_sha256(oracle[name], f"{context}.{name}")
        return

    expected_target_ids = {
        "rust-native-local": "rust-native",
        "python-package-cpython312": "python-package",
    }
    target = _exact(
        identity,
        {
            "target_profile",
            "target_id",
            "revision",
            "dirty",
            "runtime",
            "backend",
            "features",
            "package_version",
            "target_tree_sha256",
            "dependency_lock_sha256",
            "os",
            "architecture",
            "environment_sha256",
        },
        context,
    )
    if target["target_profile"] != subject_id or target["target_id"] != expected_target_ids.get(
        subject_id
    ):
        raise ContractError(f"{context} does not match its not_run target subject")
    for name in ("revision", "runtime", "backend", "os", "architecture"):
        _string(target[name], f"{context}.{name}")
    if not isinstance(target["dirty"], bool):
        raise ContractError(f"{context}.dirty must be boolean")
    if not isinstance(target["features"], list) or any(
        not isinstance(feature, str) for feature in target["features"]
    ):
        raise ContractError(f"{context}.features must be an array of strings")
    if target["package_version"] is not None:
        _string(target["package_version"], f"{context}.package_version")
    if target["target_tree_sha256"] is not None:
        _validate_sha256(target["target_tree_sha256"], f"{context}.target_tree_sha256")
    _validate_sha256(target["dependency_lock_sha256"], f"{context}.dependency_lock_sha256")
    if target["environment_sha256"] is not None:
        _validate_sha256(target["environment_sha256"], f"{context}.environment_sha256")


def _validate_worker_identity(identity: Any, subject_id: str, context: str) -> None:
    worker = _exact(
        identity,
        {
            "subject_id",
            "starlette_version",
            "package_version",
            "module_path",
            "core_extension_path",
            "python_executable",
            "environment_prefix",
            "runtime",
            "os",
            "architecture",
            "source_revision",
            "target_tree_sha256",
            "wheel_sha256",
        },
        context,
    )
    if worker["subject_id"] != subject_id:
        raise ContractError(f"{context}.subject_id differs from the measured subject")
    for name in (
        "starlette_version",
        "module_path",
        "python_executable",
        "environment_prefix",
        "runtime",
        "os",
        "architecture",
    ):
        _string(worker[name], f"{context}.{name}")

    if subject_id == "starlette-python":
        if (
            worker["starlette_version"] != "1.6.0"
            or worker["package_version"] is not None
            or worker["core_extension_path"] is not None
            or worker["source_revision"] != ORACLE_COMMIT
            or worker["target_tree_sha256"] is not None
            or worker["wheel_sha256"] is not None
        ):
            raise ContractError(f"{context} does not identify the pinned Starlette source")
        return

    if subject_id != "python-package-cpython312":
        raise ContractError(f"{context} has an unsupported measured worker subject")
    if (
        worker["starlette_version"] != "0.1.0"
        or worker["package_version"] != "0.1.0"
        or worker["source_revision"] is not None
    ):
        raise ContractError(f"{context} does not identify the installed Python package")
    _string(worker["core_extension_path"], f"{context}.core_extension_path")
    _validate_sha256(worker["target_tree_sha256"], f"{context}.target_tree_sha256")
    _validate_sha256(worker["wheel_sha256"], f"{context}.wheel_sha256")


def _artifact_path(root: Path, relative_path: str, context: str) -> Path:
    relative = Path(relative_path)
    if relative.is_absolute() or ".." in relative.parts:
        raise ContractError(f"{context} path must remain repository-relative")
    active_root = root.resolve()
    path = (active_root / relative).resolve()
    try:
        path.relative_to(active_root)
    except ValueError as exc:
        raise ContractError(f"{context} path escapes the active repository") from exc
    if not path.is_file():
        raise ContractError(f"{context} file is missing: {relative_path}")
    return path


def _active_result_inputs(
    root: Path, manifest_path: Path | None
) -> tuple[
    Path,
    dict[str, Any],
    list[tuple[Path, dict[str, Any]]],
    list[tuple[Path, dict[str, Any]]],
]:
    root = root.resolve()
    active_manifest_path = manifest_path or (root / "tests/fixtures/manifest.yaml")
    if not active_manifest_path.is_absolute():
        active_manifest_path = root / active_manifest_path
    active_manifest_path = active_manifest_path.resolve()
    try:
        active_manifest_path.relative_to(root)
    except ValueError as exc:
        raise ContractError("active parity manifest must be inside the repository root") from exc
    manifest = load_manifest(active_manifest_path)
    validate_manifest(manifest)
    from .generate_inputs import _check_generated, _validate_sources

    _check_generated(root, _validate_sources(root, manifest))
    indexed_inputs, cases = validate_inputs(root, manifest)
    benchmark_inputs = validate_benchmark_inputs(root, manifest, cases)
    return active_manifest_path, manifest, indexed_inputs, benchmark_inputs


def _canonical_json_sha256(value: Any) -> str:
    encoded = json.dumps(
        value,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        allow_nan=False,
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _load_referenced_parity_result(
    root: Path,
    relative_path: str,
    expected_sha256: str,
    manifest_path: Path,
    context: str,
) -> tuple[dict[str, Any], str]:
    path = _artifact_path(root, relative_path, context)
    actual_sha256 = sha256_file(path)
    if actual_sha256 != expected_sha256:
        raise ContractError(f"{context} digest differs from its referenced parity result")
    result = load_json(path)
    result = _validate_parity_result_artifact(result, root=root, manifest_path=manifest_path)
    if result["identity"]["command"]["command_id"] != "parity":
        raise ContractError(f"{context} must reference a live parity run")
    return result, actual_sha256


def _pinned_upstream_root(root: Path) -> Path:
    configured = os.environ.get("STARLETTE_ORACLE_ROOT")
    upstream = Path(configured).resolve() if configured else (root.resolve().parent / "starlette")
    if not upstream.is_dir():
        raise ContractError(
            "validating upstream benchmark evidence requires the pinned Starlette checkout "
            "(set STARLETTE_ORACLE_ROOT)"
        )
    try:
        revision = subprocess.run(
            ["git", "-C", str(upstream), "rev-parse", "HEAD"],
            check=True,
            capture_output=True,
            text=True,
            timeout=10,
        ).stdout.strip()
    except (OSError, subprocess.SubprocessError) as exc:
        raise ContractError(f"cannot inspect pinned Starlette checkout: {exc}") from exc
    if revision != ORACLE_COMMIT:
        raise ContractError(f"expected pinned Starlette checkout {ORACLE_COMMIT}, found {revision}")
    return upstream


def _pinned_source_file_sha256(upstream: Path, relative_path: str) -> str:
    try:
        result = subprocess.run(
            ["git", "-C", str(upstream), "show", f"{ORACLE_COMMIT}:{relative_path}"],
            check=True,
            capture_output=True,
            timeout=15,
        )
    except (OSError, subprocess.SubprocessError) as exc:
        raise ContractError(
            f"cannot read pinned Starlette source file {relative_path}: {exc}"
        ) from exc
    return hashlib.sha256(result.stdout).hexdigest()


def _smoke_parity_gate_passed(
    result_status: str,
    comparisons: list[dict[str, Any]],
    profiles: list[str],
) -> bool:
    expected_profiles = set(profiles)
    observed_profiles = {row["target_profile"] for row in comparisons}
    return not (
        result_status in {"cancelled", "invalid"}
        or len(comparisons) != len(expected_profiles)
        or observed_profiles != expected_profiles
        or any(row["outcome"] != "pass" for row in comparisons)
    )


def _validate_smoke_parity_gate(
    root: Path,
    workload: dict[str, Any],
    gate: dict[str, Any],
    manifest_path: Path,
) -> None:
    case_id = workload["input"]["case_id"]
    profiles = sorted(
        subject["id"] for subject in workload["subjects"] if subject["kind"] == "target_profile"
    )
    parity_result, digest = _load_referenced_parity_result(
        root,
        gate["parity_result_path"],
        gate["parity_result_sha256"],
        manifest_path,
        "smoke benchmark correctness gate",
    )
    if (
        parity_result["identity"]["run_id"] != gate["parity_run_id"]
        or parity_result["summary"] != gate["summary"]
    ):
        raise ContractError("smoke benchmark gate identity differs from its parity result")
    comparisons = [
        row
        for row in parity_result["comparisons"]
        if row["case_id"] == case_id and row["target_profile"] in profiles
    ]
    passed = _smoke_parity_gate_passed(parity_result["status"], comparisons, profiles)
    expected_gate = {
        "status": "pass" if passed else "failed",
        "case_id": case_id,
        "parity_run_id": parity_result["identity"]["run_id"],
        "parity_result_path": gate["parity_result_path"],
        "parity_result_sha256": digest,
        "profiles": profiles,
        "summary": parity_result["summary"],
        "oracles": parity_result["identity"]["oracles"],
        "targets": parity_result["identity"]["targets"],
        "comparison_outcomes": [
            {"target_profile": row["target_profile"], "outcome": row["outcome"]}
            for row in comparisons
        ],
        "infrastructure_errors": parity_result["infrastructure_errors"],
    }
    if gate != expected_gate:
        raise ContractError("smoke benchmark correctness gate differs from its live parity result")


def _validate_benchmark_result_artifact(
    value: Any, root: Path | None = None, manifest_path: Path | None = None
) -> dict[str, Any]:
    _exact(
        value,
        {"schema", "identity", "status", "summary", "workloads", "upstream_suite"},
        "benchmark result",
    )
    if value["schema"] != BENCHMARK_RESULT_SCHEMA:
        raise ContractError("unsupported benchmark result schema")
    if value["status"] not in {"completed", "not_proven"}:
        raise ContractError("benchmark result status is invalid")

    identity = _exact(
        value["identity"],
        {
            "run_id",
            "started_at",
            "finished_at",
            "manifest",
            "benchmark_inputs",
            "parity_case_input",
            "source_validation",
            "parity_gate",
            "native_parity_adapter",
            "prepared_environments",
            "machine",
            "command",
        },
        "benchmark result.identity",
    )
    if root is None:
        command = identity.get("command")
        command_cwd = command.get("cwd") if isinstance(command, dict) else None
        if not isinstance(command_cwd, str) or not Path(command_cwd).is_absolute():
            raise ContractError(
                "benchmark result integrity validation requires the active repository root"
            )
        root = Path(command_cwd)
    root = root.resolve()
    for name in ("run_id", "started_at", "finished_at"):
        _string(identity[name], f"benchmark result.identity.{name}")
    manifest_identity = _exact(
        identity["manifest"], {"path", "schema", "sha256"}, "benchmark identity.manifest"
    )
    if (
        manifest_identity["path"] != "tests/fixtures/manifest.yaml"
        or manifest_identity["schema"] != MANIFEST_SCHEMA
    ):
        raise ContractError("benchmark result manifest identity differs from the active contract")
    _validate_sha256(manifest_identity["sha256"], "benchmark identity.manifest.sha256")

    (
        active_manifest_path,
        active_manifest,
        indexed_inputs,
        active_benchmark_inputs,
    ) = _active_result_inputs(root, manifest_path)
    if (
        manifest_identity["path"] != active_manifest_path.relative_to(root).as_posix()
        or manifest_identity["schema"] != active_manifest["schema"]
        or manifest_identity["sha256"] != sha256_file(active_manifest_path)
    ):
        raise ContractError("benchmark result manifest differs from the active manifest")

    benchmark_inputs = identity["benchmark_inputs"]
    if not isinstance(benchmark_inputs, list) or len(benchmark_inputs) != 1:
        raise ContractError("benchmark result must bind exactly one benchmark input file")
    benchmark_input = _exact(
        benchmark_inputs[0],
        {"path", "schema", "sha256"},
        "benchmark result.identity.benchmark_inputs[0]",
    )
    if (
        not isinstance(benchmark_input["path"], str)
        or benchmark_input["path"] != "build/parity/inputs/benchmark/asgi-get-hello.json"
        or benchmark_input["schema"] != BENCHMARK_INPUT_SCHEMA
    ):
        raise ContractError("benchmark result input identity is outside the indexed benchmark lane")
    _validate_sha256(benchmark_input["sha256"], "benchmark identity.benchmark_inputs[0].sha256")
    benchmark_input_path = _artifact_path(root, benchmark_input["path"], "benchmark input")
    indexed_benchmark_by_path = {
        path.resolve(): document for path, document in active_benchmark_inputs
    }
    if benchmark_input_path not in indexed_benchmark_by_path:
        raise ContractError("benchmark result input is not indexed by the active manifest")
    if sha256_file(benchmark_input_path) != benchmark_input["sha256"]:
        raise ContractError("benchmark result input digest differs from the active input")
    active_benchmark_document = indexed_benchmark_by_path[benchmark_input_path]
    if active_benchmark_document.get("schema") != BENCHMARK_INPUT_SCHEMA:
        raise ContractError("smoke benchmark result references a non-smoke benchmark input")
    if len(active_benchmark_document.get("workloads", [])) != 1:
        raise ContractError("active smoke benchmark input must contain exactly one workload")
    active_workload = active_benchmark_document["workloads"][0]

    parity_case_input = _exact(
        identity["parity_case_input"],
        {"case_id", "path", "sha256", "case_sha256"},
        "benchmark result.identity.parity_case_input",
    )
    _string(parity_case_input["case_id"], "benchmark identity.parity_case_input.case_id")
    if parity_case_input["case_id"] != "starlette.applications.Starlette.__call__.get-hello":
        raise ContractError("benchmark result is not bound to the declared GET /hello parity case")
    if not isinstance(parity_case_input["path"], str) or not parity_case_input["path"].startswith(
        "build/parity/inputs/parity/"
    ):
        raise ContractError("benchmark parity case identity is outside the parity input lane")
    _validate_sha256(parity_case_input["sha256"], "benchmark parity input.sha256")
    _validate_sha256(parity_case_input["case_sha256"], "benchmark parity input.case_sha256")
    parity_case_path = _artifact_path(
        root, parity_case_input["path"], "benchmark parity case input"
    )
    indexed_parity_by_path = {path.resolve(): document for path, document in indexed_inputs}
    if parity_case_path not in indexed_parity_by_path:
        raise ContractError("benchmark parity case input is not indexed by the active manifest")
    if sha256_file(parity_case_path) != parity_case_input["sha256"]:
        raise ContractError("benchmark parity input digest differs from the active input")
    matching_active_cases = [
        case
        for case in indexed_parity_by_path[parity_case_path]["cases"]
        if case.get("case_id") == parity_case_input["case_id"]
    ]
    if len(matching_active_cases) != 1:
        raise ContractError("benchmark parity case ID does not resolve in its active input")
    if _canonical_json_sha256(matching_active_cases[0]) != parity_case_input["case_sha256"]:
        raise ContractError("benchmark parity case digest differs from the active case")
    if active_workload["input"] != {"kind": "parity_case", "case_id": parity_case_input["case_id"]}:
        raise ContractError("benchmark workload does not reference the active parity case")

    source_validation = _exact(
        identity["source_validation"],
        {
            "schema",
            "scope_mode",
            "scope_id",
            "oracle_commit",
            "oracle_package",
            "runtime_dependency_lock_sha256",
            "indexed_input_files",
            "cases",
            "target_profiles",
            "operations",
            "parity_tooling_sources_compiled",
            "parity_passes_claimed",
        },
        "benchmark result.identity.source_validation",
    )
    if (
        source_validation["schema"] != MANIFEST_SCHEMA
        or source_validation["oracle_commit"] != ORACLE_COMMIT
        or source_validation["parity_passes_claimed"] != 0
    ):
        raise ContractError("benchmark source validation identity differs from the pinned contract")
    for name in ("scope_mode", "scope_id", "oracle_package"):
        _string(source_validation[name], f"benchmark source_validation.{name}")
    _validate_sha256(
        source_validation["runtime_dependency_lock_sha256"],
        "benchmark source_validation.runtime_dependency_lock_sha256",
    )
    for name in (
        "indexed_input_files",
        "cases",
        "target_profiles",
        "operations",
        "parity_tooling_sources_compiled",
    ):
        _validate_nonnegative_integer(
            source_validation[name], f"benchmark source_validation.{name}"
        )

    gate = _exact(
        identity["parity_gate"],
        {
            "status",
            "case_id",
            "parity_run_id",
            "parity_result_path",
            "parity_result_sha256",
            "profiles",
            "summary",
            "oracles",
            "targets",
            "comparison_outcomes",
            "infrastructure_errors",
        },
        "benchmark result.identity.parity_gate",
    )
    if gate["status"] not in {"pass", "failed"}:
        raise ContractError("benchmark correctness gate status is invalid")
    if (
        gate["case_id"] != parity_case_input["case_id"]
        or gate["parity_result_path"] != "build/parity/benchmark-correctness-result.json"
    ):
        raise ContractError("benchmark correctness gate does not identify its resolved input")
    _string(gate["parity_run_id"], "benchmark correctness gate.parity_run_id")
    _validate_sha256(gate["parity_result_sha256"], "benchmark correctness gate result hash")
    if gate["profiles"] != ["python-package-cpython312", "rust-native-local"]:
        raise ContractError("benchmark correctness gate must include both declared target profiles")
    gate_summary = _exact(
        gate["summary"],
        {"selected", "executed", "passed", "failed", "not_run", "infrastructure_errors"},
        "benchmark correctness gate.summary",
    )
    for name, count in gate_summary.items():
        _validate_nonnegative_integer(count, f"benchmark correctness gate.summary.{name}")
    if not isinstance(gate["oracles"], list) or not isinstance(gate["targets"], list):
        raise ContractError("benchmark correctness gate identities must be arrays")
    oracle_ids: set[str] = set()
    for index, oracle in enumerate(gate["oracles"]):
        oracle = _exact(
            oracle,
            {
                "oracle_id",
                "name",
                "version",
                "revision",
                "runtime",
                "module_path",
                "dependency_lock_sha256",
                "os",
                "architecture",
                "environment_sha256",
                "runtime_lock_sha256",
            },
            f"benchmark correctness gate.oracles[{index}]",
        )
        if oracle["oracle_id"] != "starlette-python" or oracle["revision"] != ORACLE_COMMIT:
            raise ContractError("benchmark correctness gate oracle identity differs")
        if oracle["oracle_id"] in oracle_ids:
            raise ContractError("benchmark correctness gate repeats an oracle identity")
        oracle_ids.add(oracle["oracle_id"])
        for name in (
            "name",
            "version",
            "runtime",
            "module_path",
            "os",
            "architecture",
        ):
            _string(oracle[name], f"benchmark correctness gate oracle.{name}")
        for name in (
            "dependency_lock_sha256",
            "environment_sha256",
            "runtime_lock_sha256",
        ):
            _validate_sha256(oracle[name], f"benchmark correctness gate oracle.{name}")
    target_profiles: set[str] = set()
    for index, target in enumerate(gate["targets"]):
        target = _exact(
            target,
            {
                "target_profile",
                "target_id",
                "revision",
                "dirty",
                "runtime",
                "backend",
                "features",
                "package_version",
                "target_tree_sha256",
                "dependency_lock_sha256",
                "os",
                "architecture",
                "environment_sha256",
            },
            f"benchmark correctness gate.targets[{index}]",
        )
        if target["target_profile"] not in {"rust-native-local", "python-package-cpython312"}:
            raise ContractError("benchmark correctness gate contains an unknown target profile")
        if target["target_profile"] in target_profiles:
            raise ContractError("benchmark correctness gate repeats a target profile")
        target_profiles.add(target["target_profile"])
        for name in ("target_id", "revision", "runtime", "backend", "os", "architecture"):
            _string(target[name], f"benchmark correctness gate target.{name}")
        if not isinstance(target["dirty"], bool):
            raise ContractError("benchmark correctness gate target dirty state must be boolean")
        if not isinstance(target["features"], list) or any(
            not isinstance(feature, str) for feature in target["features"]
        ):
            raise ContractError("benchmark correctness gate target features must be strings")
        if target["package_version"] is not None:
            _string(target["package_version"], "benchmark correctness gate target.package_version")
        if target["target_tree_sha256"] is not None:
            _validate_sha256(
                target["target_tree_sha256"], "benchmark correctness gate target.target_tree_sha256"
            )
        _validate_sha256(
            target["dependency_lock_sha256"],
            "benchmark correctness gate target.dependency_lock_sha256",
        )
        if target["environment_sha256"] is not None:
            _validate_sha256(
                target["environment_sha256"], "benchmark correctness gate target.environment_sha256"
            )
    if oracle_ids not in ({"starlette-python"}, set()) or (
        gate["status"] == "pass" and oracle_ids != {"starlette-python"}
    ):
        raise ContractError("benchmark correctness gate contains an unknown oracle inventory")
    expected_profiles = {"rust-native-local", "python-package-cpython312"}
    if (gate["status"] == "pass" and target_profiles != expected_profiles) or (
        gate["status"] == "failed" and not target_profiles <= expected_profiles
    ):
        raise ContractError(
            "benchmark correctness gate must identify both declared target profiles"
        )
    outcomes = gate["comparison_outcomes"]
    if not isinstance(outcomes, list):
        raise ContractError("benchmark correctness gate comparison outcomes must be an array")
    outcome_profiles: set[str] = set()
    for index, outcome in enumerate(outcomes):
        outcome = _exact(
            outcome,
            {"target_profile", "outcome"},
            f"benchmark correctness gate.comparison_outcomes[{index}]",
        )
        if (
            outcome["target_profile"] not in {"rust-native-local", "python-package-cpython312"}
            or outcome["target_profile"] in outcome_profiles
            or outcome["outcome"] not in {"pass", "fail", "not_run"}
        ):
            raise ContractError("benchmark correctness gate has invalid or duplicate outcomes")
        outcome_profiles.add(outcome["target_profile"])
    if not isinstance(gate["infrastructure_errors"], list):
        raise ContractError("benchmark correctness gate infrastructure errors must be an array")
    for index, error in enumerate(gate["infrastructure_errors"]):
        error = _exact(
            error,
            {"scope", "id", "kind", "message"},
            f"benchmark correctness gate.infrastructure_errors[{index}]",
        )
        _string(error["scope"], f"benchmark correctness gate.infrastructure_errors[{index}].scope")
        _string(error["kind"], f"benchmark correctness gate.infrastructure_errors[{index}].kind")
        _string(
            error["message"], f"benchmark correctness gate.infrastructure_errors[{index}].message"
        )
        if error["id"] is not None:
            _string(error["id"], f"benchmark correctness gate.infrastructure_errors[{index}].id")
    if gate["status"] == "pass" and (
        outcome_profiles != expected_profiles
        or len(outcomes) != len(expected_profiles)
        or any(item["outcome"] != "pass" for item in outcomes)
    ):
        raise ContractError("passing benchmark correctness gate requires both exact target passes")
    _validate_smoke_parity_gate(root, active_workload, gate, active_manifest_path)

    adapter = _exact(
        identity["native_parity_adapter"],
        {"argv", "path", "sha256"},
        "benchmark result.identity.native_parity_adapter",
    )
    if (
        not isinstance(adapter["argv"], list)
        or not adapter["argv"]
        or any(not isinstance(part, str) for part in adapter["argv"])
        or not isinstance(adapter["path"], str)
        or Path(adapter["path"]).is_absolute()
    ):
        raise ContractError("benchmark native adapter identity is malformed")
    _validate_sha256(adapter["sha256"], "benchmark native adapter.sha256")

    environments = identity["prepared_environments"]
    expected_environment_ids = {"starlette-oracle-cpython312", "starlette-rs-py-cpython312"}
    if not isinstance(environments, list) or len(environments) != 2:
        raise ContractError("benchmark result must identify both prepared Python environments")
    environment_ids: set[str] = set()
    for index, environment in enumerate(environments):
        environment = _exact(
            environment,
            {
                "id",
                "python",
                "runtime",
                "os",
                "architecture",
                "dependency_lock_path",
                "dependency_lock_sha256",
                "installed_lock_sha256",
                "artifact_sha256",
                "environment_sha256",
            },
            f"benchmark result.identity.prepared_environments[{index}]",
        )
        if (
            environment["id"] not in expected_environment_ids
            or environment["id"] in environment_ids
        ):
            raise ContractError("benchmark result contains unknown or duplicate environments")
        environment_ids.add(environment["id"])
        for name in ("python", "runtime", "os", "architecture", "dependency_lock_path"):
            _string(environment[name], f"benchmark environment.{name}")
        expected_lock_path = (
            "scripts/parity/locks/starlette-oracle-cpython312.txt"
            if environment["id"] == "starlette-oracle-cpython312"
            else "scripts/parity/locks/asgi-runtime-cpython312.txt"
        )
        if environment["dependency_lock_path"] != expected_lock_path:
            raise ContractError(
                "benchmark environment dependency_lock_path differs from its isolated runtime lock"
            )
        for name in (
            "dependency_lock_sha256",
            "installed_lock_sha256",
            "environment_sha256",
        ):
            _validate_sha256(environment[name], f"benchmark environment.{name}")
        if environment["artifact_sha256"] is not None:
            _validate_sha256(
                environment["artifact_sha256"], "benchmark environment.artifact_sha256"
            )

    machine = _exact(
        identity["machine"],
        {
            "platform",
            "architecture",
            "processor",
            "logical_cpu_count",
            "python",
            "python_executable",
            "rustc",
            "cargo",
        },
        "benchmark result.identity.machine",
    )
    for name in ("platform", "architecture", "processor", "python", "python_executable"):
        if name == "processor":
            if not isinstance(machine[name], str):
                raise ContractError("benchmark machine.processor must be a string")
        elif machine[name] is not None:
            _string(machine[name], f"benchmark machine.{name}")
    if machine["logical_cpu_count"] is not None:
        _validate_nonnegative_integer(
            machine["logical_cpu_count"], "benchmark machine.logical_cpu_count"
        )
    for name in ("rustc", "cargo"):
        if machine[name] is not None:
            _string(machine[name], f"benchmark machine.{name}")
    command = _exact(identity["command"], {"argv", "cwd"}, "benchmark result.identity.command")
    if (
        not isinstance(command["argv"], list)
        or not command["argv"]
        or any(not isinstance(part, str) for part in command["argv"])
    ):
        raise ContractError("benchmark command argv must be a non-empty string array")
    command_cwd = _string(command["cwd"], "benchmark command.cwd")
    if not Path(command_cwd).is_absolute() or Path(command_cwd).resolve() != root:
        raise ContractError("benchmark command cwd differs from the active repository root")

    workloads = value["workloads"]
    if not isinstance(workloads, list) or len(workloads) != 1:
        raise ContractError("benchmark result must include exactly one declared workload")
    workload = _exact(
        workloads[0],
        {
            "workload_id",
            "covers",
            "input",
            "correctness_gate",
            "measurement_policy",
            "subjects",
            "comparison",
        },
        "benchmark result.workloads[0]",
    )
    _string(workload["workload_id"], "benchmark workload.workload_id")
    if workload["workload_id"] != "starlette.asgi.get-hello.direct-dispatch":
        raise ContractError("benchmark result identifies an unknown workload")
    if not isinstance(workload["covers"], list) or not workload["covers"]:
        raise ContractError("benchmark workload covers must be a non-empty array")
    if workload["covers"] != ["starlette.asgi.get-hello.latency"]:
        raise ContractError("benchmark result coverage differs from the declared workload")
    workload_input = _exact(workload["input"], {"kind", "case_id"}, "benchmark workload.input")
    if (
        workload_input["kind"] != "parity_case"
        or workload_input["case_id"] != parity_case_input["case_id"]
    ):
        raise ContractError("benchmark workload input does not match the hashed parity case")
    gate_evidence = workload["correctness_gate"]
    if gate["status"] == "pass":
        gate_evidence = _exact(
            gate_evidence,
            {
                "status",
                "case_id",
                "parity_run_id",
                "parity_result_path",
                "parity_result_sha256",
                "profiles",
                "summary",
                "oracles",
                "targets",
                "comparison_outcomes",
                "infrastructure_errors",
                "observation_sha256",
                "exact_source_package_observations",
            },
            "benchmark workload.correctness_gate",
        )
        _validate_sha256(gate_evidence["observation_sha256"], "benchmark exact probe hash")
        if gate_evidence["exact_source_package_observations"] != "pass":
            raise ContractError("benchmark source/package probe must pass exact comparison")
    else:
        _exact(
            gate_evidence,
            {
                "status",
                "case_id",
                "parity_run_id",
                "parity_result_path",
                "parity_result_sha256",
                "profiles",
                "summary",
                "oracles",
                "targets",
                "comparison_outcomes",
                "infrastructure_errors",
            },
            "benchmark workload.correctness_gate",
        )
    if (
        gate_evidence["status"] != gate["status"]
        or gate_evidence["case_id"] != parity_case_input["case_id"]
    ):
        raise ContractError("workload correctness gate differs from benchmark identity")
    gate_identity = {key: gate_evidence[key] for key in gate}
    if gate_identity != gate:
        raise ContractError("workload correctness gate evidence differs from the run identity")

    policy = _exact(
        workload["measurement_policy"],
        {
            "boundary",
            "step_ids",
            "metrics",
            "warmup_iterations",
            "measurement_iterations",
            "samples",
            "concurrency",
            "cache_state",
            "correctness_gate",
        },
        "benchmark workload.measurement_policy",
    )
    if (
        policy["boundary"] != "observed_steps"
        or policy["step_ids"] != ["dispatch"]
        or policy["metrics"] != ["latency"]
        or policy["cache_state"] != "warm"
        or policy["concurrency"] != 1
        or policy["correctness_gate"] != "parity_pass"
    ):
        raise ContractError(
            "benchmark result measurement policy differs from the declared smoke lane"
        )
    for name in ("warmup_iterations", "measurement_iterations", "samples"):
        if not isinstance(policy[name], int) or isinstance(policy[name], bool) or policy[name] <= 0:
            raise ContractError(f"benchmark measurement_policy.{name} must be a positive integer")
    if (policy["warmup_iterations"], policy["measurement_iterations"], policy["samples"]) != (
        20,
        100,
        30,
    ):
        raise ContractError(
            "benchmark measurement counts differ from the indexed deterministic policy"
        )

    subjects = workload["subjects"]
    expected_subjects = ["starlette-python", "rust-native-local", "python-package-cpython312"]
    if not isinstance(subjects, list) or len(subjects) != len(expected_subjects):
        raise ContractError("benchmark workload must include all declared runtime subjects")
    subject_statuses: dict[str, str] = {}
    for index, subject in enumerate(subjects):
        if not isinstance(subject, dict) or subject.get("subject_id") != expected_subjects[index]:
            raise ContractError("benchmark workload subjects differ from the manifest order")
        subject_id = subject["subject_id"]
        if subject.get("status") == "not_run":
            _exact(
                subject,
                {"subject_id", "status", "identity", "reason"},
                f"benchmark workload.subjects[{index}]",
            )
            _string(subject["reason"], f"benchmark workload.subjects[{index}].reason")
            _validate_not_run_subject_identity(
                subject["identity"],
                subject_id,
                f"benchmark workload.subjects[{index}].identity",
            )
        elif subject.get("status") == "measured":
            _exact(
                subject,
                {"subject_id", "status", "identity", "capabilities", "measurement"},
                f"benchmark workload.subjects[{index}]",
            )
            if subject_id == "rust-native-local" or not isinstance(subject["identity"], dict):
                raise ContractError("only Python subjects can have measured worker identities")
            _validate_worker_identity(
                subject["identity"], subject_id, f"benchmark workload.subjects[{index}].identity"
            )
            capabilities = _exact(
                subject["capabilities"],
                {"router_instance_is_asgi_callable", "gzip_middleware_module_available"},
                f"benchmark workload.subjects[{index}].capabilities",
            )
            if any(not isinstance(item, bool) for item in capabilities.values()):
                raise ContractError("benchmark capability results must be booleans")
            measurement = _exact(
                subject["measurement"],
                {
                    "unit",
                    "warmup_iterations",
                    "measurement_iterations_per_sample",
                    "samples",
                    "statistics",
                },
                f"benchmark workload.subjects[{index}].measurement",
            )
            if measurement["unit"] != "nanoseconds_per_dispatch":
                raise ContractError("benchmark measurement unit is invalid")
            if (
                measurement["warmup_iterations"] != policy["warmup_iterations"]
                or measurement["measurement_iterations_per_sample"]
                != policy["measurement_iterations"]
            ):
                raise ContractError("benchmark worker counts differ from the declared policy")
            samples = measurement["samples"]
            if not isinstance(samples, list) or len(samples) != policy["samples"]:
                raise ContractError(
                    "benchmark worker samples differ from the declared sample count"
                )
            if any(
                not isinstance(sample, (int, float))
                or isinstance(sample, bool)
                or not math.isfinite(sample)
                or sample <= 0
                for sample in samples
            ):
                raise ContractError("benchmark samples must be positive finite numbers")
            stats = _exact(
                measurement["statistics"],
                {"median", "mean", "stdev", "min", "max", "p50", "p95", "p99"},
                f"benchmark workload.subjects[{index}].measurement.statistics",
            )
            if any(
                not isinstance(number, (int, float))
                or isinstance(number, bool)
                or not math.isfinite(number)
                for number in stats.values()
            ):
                raise ContractError("benchmark statistics must be numeric")
            expected_statistics = {
                "median": statistics.median(samples),
                "mean": statistics.fmean(samples),
                "stdev": statistics.stdev(samples) if len(samples) > 1 else 0.0,
                "min": min(samples),
                "max": max(samples),
                "p50": _sample_quantile(samples, 0.50),
                "p95": _sample_quantile(samples, 0.95),
                "p99": _sample_quantile(samples, 0.99),
            }
            if any(
                not math.isclose(stats[name], expected, rel_tol=1e-12, abs_tol=1e-9)
                for name, expected in expected_statistics.items()
            ):
                raise ContractError("benchmark statistics differ from their sample distribution")
        else:
            raise ContractError(f"benchmark workload.subjects[{index}].status is invalid")
        subject_statuses[subject_id] = subject["status"]

    comparison = workload["comparison"]
    if comparison.get("status") == "not_run":
        comparison = _exact(comparison, {"status", "reason"}, "benchmark workload.comparison")
        _string(comparison["reason"], "benchmark workload.comparison.reason")
    elif comparison.get("status") == "measured":
        comparison = _exact(
            comparison,
            {
                "status",
                "source_subject_id",
                "target_subject_id",
                "latency_unit",
                "source_median",
                "target_median",
                "target_over_source_median_ratio",
                "source_over_target_median_speedup",
                "sample_count",
                "measurement_iterations_per_sample",
            },
            "benchmark workload.comparison",
        )
        if (
            comparison["source_subject_id"] != "starlette-python"
            or comparison["target_subject_id"] != "python-package-cpython312"
            or comparison["latency_unit"] != "nanoseconds_per_dispatch"
        ):
            raise ContractError("benchmark comparison subjects or units are invalid")
        for name in (
            "source_median",
            "target_median",
            "target_over_source_median_ratio",
            "source_over_target_median_speedup",
        ):
            number = comparison[name]
            if not isinstance(number, (int, float)) or isinstance(number, bool) or number <= 0:
                raise ContractError(f"benchmark comparison.{name} must be positive")
        if (
            comparison["sample_count"] != policy["samples"]
            or comparison["measurement_iterations_per_sample"] != policy["measurement_iterations"]
        ):
            raise ContractError("benchmark comparison counts differ from the declared policy")
        source_measurement = next(
            subject["measurement"]
            for subject in subjects
            if subject["subject_id"] == "starlette-python"
        )
        target_measurement = next(
            subject["measurement"]
            for subject in subjects
            if subject["subject_id"] == "python-package-cpython312"
        )
        source_median = source_measurement["statistics"]["median"]
        target_median = target_measurement["statistics"]["median"]
        if (
            comparison["source_median"] != source_median
            or comparison["target_median"] != target_median
            or not math.isclose(
                comparison["target_over_source_median_ratio"],
                target_median / source_median,
                rel_tol=1e-12,
            )
            or not math.isclose(
                comparison["source_over_target_median_speedup"],
                source_median / target_median,
                rel_tol=1e-12,
            )
        ):
            raise ContractError("benchmark comparison differs from the measured medians")
    else:
        raise ContractError("benchmark comparison status is invalid")

    upstream = value["upstream_suite"]
    if gate["status"] == "failed":
        upstream = _exact(
            upstream,
            {
                "status",
                "source_revision",
                "documented_workload_count",
                "matched_workload_count",
                "not_run_workload_count",
                "reason",
                "workloads",
            },
            "benchmark upstream_suite",
        )
        if "source_supported" in upstream or "target_supported" in upstream:
            raise ContractError("unprobed capability claims are forbidden after gate failure")
        _string(upstream["reason"], "benchmark upstream_suite.reason")
    else:
        upstream = _exact(
            upstream,
            {
                "status",
                "source_revision",
                "documented_workload_count",
                "matched_workload_count",
                "not_run_workload_count",
                "source_files",
                "source_workload_categories",
                "workloads",
            },
            "benchmark upstream_suite",
        )
        source_files = upstream["source_files"]
        if not isinstance(source_files, list) or len(source_files) != 3:
            raise ContractError("benchmark result must identify all three pinned benchmark sources")
        for index, source_file in enumerate(source_files):
            source_file = _exact(
                source_file,
                {"path", "sha256"},
                f"benchmark upstream_suite.source_files[{index}]",
            )
            expected_source_paths = {
                "benchmarks/README.md",
                "benchmarks/routing_benchmark.py",
                "benchmarks/gzip_benchmark.py",
            }
            if source_file["path"] not in expected_source_paths:
                raise ContractError("benchmark result names an unknown pinned source file")
            _validate_sha256(source_file["sha256"], f"benchmark source_file[{index}].sha256")
        if {item["path"] for item in source_files} != expected_source_paths:
            raise ContractError(
                "benchmark source identity must include the complete pinned source set"
            )
        categories = upstream["source_workload_categories"]
        if not isinstance(categories, list) or len(categories) != 2:
            raise ContractError("benchmark upstream suite must report router and gzip categories")
        for index, category in enumerate(categories):
            category = _exact(
                category,
                {
                    "name",
                    "count",
                    "source_supported",
                    "target_supported",
                    "target_status",
                    "not_run_count",
                },
                f"benchmark upstream_suite.source_workload_categories[{index}]",
            )
            expected_name, expected_count = (("router", 6), ("gzip", 68))[index]
            if (
                category["name"] != expected_name
                or category["count"] != expected_count
                or not isinstance(category["source_supported"], bool)
                or not isinstance(category["target_supported"], bool)
                or category["target_status"] not in {"blocked", "not_implemented"}
                or category["target_status"]
                != ("not_implemented" if category["target_supported"] else "blocked")
                or category["not_run_count"] != expected_count
            ):
                raise ContractError("benchmark upstream workload category evidence is inconsistent")

    if (
        upstream["status"] != "not_run"
        or upstream["source_revision"] != ORACLE_COMMIT
        or upstream["documented_workload_count"] != 74
        or upstream["matched_workload_count"] != 0
        or upstream["not_run_workload_count"] != 74
    ):
        raise ContractError("the 74 source-documented workloads must remain visible as not_run")
    upstream_rows = upstream["workloads"]
    if not isinstance(upstream_rows, list) or len(upstream_rows) != 74:
        raise ContractError("benchmark upstream workload inventory must contain 74 rows")
    upstream_ids: set[str] = set()
    upstream_categories = {"router": 0, "gzip": 0}
    for index, row in enumerate(upstream_rows):
        row = _exact(
            row,
            {"workload_id", "category", "status", "reason"},
            f"benchmark upstream_suite.workloads[{index}]",
        )
        _string(row["workload_id"], f"benchmark upstream workload[{index}].workload_id")
        if (
            row["workload_id"] in upstream_ids
            or row["category"] not in upstream_categories
            or row["status"] != "not_run"
        ):
            raise ContractError("benchmark upstream workload rows have duplicate or invalid status")
        upstream_ids.add(row["workload_id"])
        upstream_categories[row["category"]] += 1
        _string(row["reason"], f"benchmark upstream workload[{index}].reason")
    if upstream_categories != {"router": 6, "gzip": 68}:
        raise ContractError("benchmark upstream workload category counts differ from the source")

    summary = _exact(
        value["summary"],
        {
            "declared_workloads",
            "measured_workloads",
            "measured_subjects",
            "not_run_subjects",
            "source_documented_workloads",
            "source_documented_workloads_matched",
            "source_documented_workloads_not_run",
        },
        "benchmark result.summary",
    )
    for name, count in summary.items():
        _validate_nonnegative_integer(count, f"benchmark result.summary.{name}")
    measured_subject_count = sum(status == "measured" for status in subject_statuses.values())
    expected_summary = {
        "declared_workloads": 1,
        "measured_workloads": int(
            subject_statuses.get("starlette-python") == "measured"
            and subject_statuses.get("python-package-cpython312") == "measured"
        ),
        "measured_subjects": measured_subject_count,
        "not_run_subjects": len(subject_statuses) - measured_subject_count,
        "source_documented_workloads": 74,
        "source_documented_workloads_matched": 0,
        "source_documented_workloads_not_run": 74,
    }
    if summary != expected_summary:
        raise ContractError("benchmark result summary does not equal its subject evidence counts")
    if value["status"] != "not_proven":
        raise ContractError(
            "benchmark cannot be completed while Rust-native or source workloads are not_run"
        )
    if gate["status"] == "failed" and any(
        status != "not_run" for status in subject_statuses.values()
    ):
        raise ContractError("benchmark gate failure cannot produce measured subjects")
    if gate["status"] == "pass" and subject_statuses.get("rust-native-local") != "not_run":
        raise ContractError(
            "Rust-native must remain not_run until its dispatch boundary is equivalent"
        )
    if (comparison.get("status") == "measured") != (expected_summary["measured_workloads"] == 1):
        raise ContractError("benchmark comparison status differs from measured workload evidence")
    return value


def _validate_positive_finite_number(value: Any, context: str, *, allow_zero: bool = False) -> None:
    if (
        not isinstance(value, (int, float))
        or isinstance(value, bool)
        or not math.isfinite(value)
        or value < 0
        or (value == 0 and not allow_zero)
    ):
        qualifier = "non-negative" if allow_zero else "positive"
        raise ContractError(f"{context} must be a finite {qualifier} number")


def _validate_upstream_measurement_policy(value: Any, context: str) -> dict[str, Any]:
    policy = _exact(
        value,
        {
            "setup_outside_timer",
            "timed_call",
            "post_timer_checks",
            "source_harness",
            "runner_policy",
        },
        context,
    )
    for name in ("setup_outside_timer", "post_timer_checks"):
        rows = policy[name]
        if not isinstance(rows, list) or not rows:
            raise ContractError(f"{context}.{name} must be a non-empty string array")
        for index, row in enumerate(rows):
            _string(row, f"{context}.{name}[{index}]")
    timed_call = _exact(
        policy["timed_call"],
        {"boundary_id", "includes"},
        f"{context}.timed_call",
    )
    _string(timed_call["boundary_id"], f"{context}.timed_call.boundary_id")
    if not isinstance(timed_call["includes"], list) or not timed_call["includes"]:
        raise ContractError(f"{context}.timed_call.includes must be a non-empty string array")
    for index, item in enumerate(timed_call["includes"]):
        _string(item, f"{context}.timed_call.includes[{index}]")

    harness = _exact(
        policy["source_harness"],
        {"package", "method", "marker", "rounds"},
        f"{context}.source_harness",
    )
    _string(harness["package"], f"{context}.source_harness.package")
    if harness["package"] != "pytest-codspeed":
        raise ContractError(f"{context}.source_harness.package differs from the pinned benchmark")
    if harness["method"] not in {"benchmark", "benchmark.pedantic"}:
        raise ContractError(f"{context}.source_harness.method is unsupported")
    marker = harness["marker"]
    if marker is not None:
        marker = _exact(
            marker,
            {"max_time_seconds", "max_rounds"},
            f"{context}.source_harness.marker",
        )
        _validate_positive_finite_number(
            marker["max_time_seconds"], f"{context}.source_harness.marker.max_time_seconds"
        )
        if not isinstance(marker["max_rounds"], int) or isinstance(marker["max_rounds"], bool):
            raise ContractError(f"{context}.source_harness.marker.max_rounds must be an integer")
        _validate_nonnegative_integer(
            marker["max_rounds"], f"{context}.source_harness.marker.max_rounds"
        )
        if marker["max_rounds"] == 0:
            raise ContractError(f"{context}.source_harness.marker.max_rounds must be positive")
    if harness["rounds"] is not None:
        if not isinstance(harness["rounds"], int) or isinstance(harness["rounds"], bool):
            raise ContractError(f"{context}.source_harness.rounds must be an integer or null")
        if harness["rounds"] <= 0:
            raise ContractError(f"{context}.source_harness.rounds must be positive")

    runner_policy = _exact(
        policy["runner_policy"],
        {"warmup_iterations", "samples", "iterations_per_sample", "sample_statistic"},
        f"{context}.runner_policy",
    )
    for name in ("warmup_iterations", "samples", "iterations_per_sample"):
        number = runner_policy[name]
        if not isinstance(number, int) or isinstance(number, bool):
            raise ContractError(f"{context}.runner_policy.{name} must be an integer")
        if number < (0 if name == "warmup_iterations" else 1):
            raise ContractError(f"{context}.runner_policy.{name} is out of range")
    if runner_policy["sample_statistic"] != "mean_call_duration":
        raise ContractError(f"{context}.runner_policy.sample_statistic is unsupported")
    return policy


def _validate_upstream_measurement(value: Any, context: str) -> dict[str, Any]:
    measurement = _exact(
        value,
        {
            "unit",
            "runner_policy",
            "warmup_iterations",
            "samples",
            "iterations_per_sample",
            "statistics",
        },
        context,
    )
    if measurement["unit"] != "nanoseconds_per_operation":
        raise ContractError(f"{context}.unit is invalid")
    runner_policy = _exact(
        measurement["runner_policy"],
        {"warmup_iterations", "samples", "iterations_per_sample", "sample_statistic"},
        f"{context}.runner_policy",
    )
    for name in ("warmup_iterations", "samples", "iterations_per_sample"):
        number = runner_policy[name]
        if not isinstance(number, int) or isinstance(number, bool):
            raise ContractError(f"{context}.runner_policy.{name} must be an integer")
        if number < (0 if name == "warmup_iterations" else 1):
            raise ContractError(f"{context}.runner_policy.{name} is out of range")
    if runner_policy["sample_statistic"] != "mean_call_duration":
        raise ContractError(f"{context}.runner_policy.sample_statistic is unsupported")
    if (
        measurement["warmup_iterations"] != runner_policy["warmup_iterations"]
        or measurement["iterations_per_sample"] != runner_policy["iterations_per_sample"]
    ):
        raise ContractError(f"{context} counts differ from runner_policy")
    samples = measurement["samples"]
    if not isinstance(samples, list) or len(samples) != runner_policy["samples"]:
        raise ContractError(f"{context}.samples differs from runner_policy.samples")
    for index, sample in enumerate(samples):
        _validate_positive_finite_number(sample, f"{context}.samples[{index}]")
    statistics_row = _exact(
        measurement["statistics"],
        {"median", "mean", "stdev", "min", "max", "p50", "p95", "p99"},
        f"{context}.statistics",
    )
    for name, number in statistics_row.items():
        _validate_positive_finite_number(
            number, f"{context}.statistics.{name}", allow_zero=name == "stdev"
        )
    expected_statistics = {
        "median": statistics.median(samples),
        "mean": statistics.fmean(samples),
        "stdev": statistics.stdev(samples) if len(samples) > 1 else 0.0,
        "min": min(samples),
        "max": max(samples),
        "p50": _sample_quantile(samples, 0.50),
        "p95": _sample_quantile(samples, 0.95),
        "p99": _sample_quantile(samples, 0.99),
    }
    if any(
        not math.isclose(statistics_row[name], expected, rel_tol=1e-12, abs_tol=1e-9)
        for name, expected in expected_statistics.items()
    ):
        raise ContractError(f"{context}.statistics differ from the sample distribution")
    return measurement


def _validate_upstream_worker_identity(value: Any, subject_id: str, context: str) -> dict[str, Any]:
    capabilities = {
        "router_instance_is_asgi_callable",
        "gzip_middleware_available",
    }
    if subject_id == "starlette-python":
        identity = _exact(
            value,
            {
                "subject_id",
                "starlette_version",
                "source_revision",
                "module_path",
                "python_executable",
                "environment_prefix",
                "runtime",
                "os",
                "architecture",
                "capabilities",
            },
            context,
        )
        if (
            identity["subject_id"] != subject_id
            or identity["starlette_version"] != "1.6.0"
            or identity["source_revision"] != ORACLE_COMMIT
        ):
            raise ContractError(f"{context} does not identify the pinned Starlette source")
    else:
        identity = _exact(
            value,
            {
                "subject_id",
                "starlette_version",
                "package_version",
                "module_path",
                "core_extension_path",
                "python_executable",
                "environment_prefix",
                "runtime",
                "os",
                "architecture",
                "target_tree_sha256",
                "wheel_sha256",
                "capabilities",
            },
            context,
        )
        if (
            identity["subject_id"] != subject_id
            or identity["starlette_version"] != "0.1.0"
            or identity["package_version"] != "0.1.0"
        ):
            raise ContractError(f"{context} does not identify the installed Python package")
        _validate_sha256(identity["target_tree_sha256"], f"{context}.target_tree_sha256")
        _validate_sha256(identity["wheel_sha256"], f"{context}.wheel_sha256")
    for name in (
        "module_path",
        "python_executable",
        "environment_prefix",
        "runtime",
        "os",
        "architecture",
    ):
        _string(identity[name], f"{context}.{name}")
    if subject_id == "python-package-cpython312":
        _string(identity["core_extension_path"], f"{context}.core_extension_path")
    capability_row = _exact(identity["capabilities"], capabilities, f"{context}.capabilities")
    if any(not isinstance(capability, bool) for capability in capability_row.values()):
        raise ContractError(f"{context}.capabilities must contain booleans")
    return identity


def _validate_upstream_target_identity(value: Any, context: str) -> dict[str, Any]:
    identity = _exact(
        value,
        {
            "target_profile",
            "target_id",
            "revision",
            "dirty",
            "runtime",
            "backend",
            "features",
            "package_version",
            "target_tree_sha256",
            "dependency_lock_sha256",
            "os",
            "architecture",
            "environment_sha256",
        },
        context,
    )
    if identity["target_profile"] not in {"rust-native-local", "python-package-cpython312"}:
        raise ContractError(f"{context}.target_profile is unsupported")
    if not isinstance(identity["dirty"], bool):
        raise ContractError(f"{context}.dirty must be boolean")
    for name in ("target_id", "revision", "runtime", "backend", "os", "architecture"):
        _string(identity[name], f"{context}.{name}")
    if not isinstance(identity["features"], list) or any(
        not isinstance(feature, str) for feature in identity["features"]
    ):
        raise ContractError(f"{context}.features must be a string array")
    if identity["package_version"] is not None:
        _string(identity["package_version"], f"{context}.package_version")
    for name in ("target_tree_sha256", "environment_sha256"):
        if identity[name] is not None:
            _validate_sha256(identity[name], f"{context}.{name}")
    _validate_sha256(identity["dependency_lock_sha256"], f"{context}.dependency_lock_sha256")
    return identity


def _validate_upstream_subject(value: Any, subject_id: str, context: str) -> dict[str, Any]:
    if not isinstance(value, dict) or value.get("subject_id") != subject_id:
        raise ContractError(f"{context} subject identity differs from the declared order")
    status = value.get("status")
    if status == "not_run":
        subject = _exact(value, {"subject_id", "status", "identity", "reason"}, context)
        if subject["identity"] is not None:
            raise ContractError(f"{context}.identity must be null before a successful probe")
        _string(subject["reason"], f"{context}.reason")
    elif status == "probed":
        subject = _exact(
            value,
            {"subject_id", "status", "identity", "input_relations"},
            context,
        )
        _validate_upstream_worker_identity(subject["identity"], subject_id, f"{context}.identity")
        _validate_upstream_relations(subject["input_relations"], f"{context}.input_relations")
    elif status == "measured":
        subject = _exact(
            value,
            {"subject_id", "status", "identity", "input_relations", "measurement"},
            context,
        )
        _validate_upstream_worker_identity(subject["identity"], subject_id, f"{context}.identity")
        _validate_upstream_relations(subject["input_relations"], f"{context}.input_relations")
        _validate_upstream_measurement(subject["measurement"], f"{context}.measurement")
    else:
        raise ContractError(f"{context}.status is invalid")
    return subject


def _validate_upstream_relations(value: Any, context: str) -> None:
    if not isinstance(value, list):
        raise ContractError(f"{context} must be an array")
    for index, relation in enumerate(value):
        relation = _exact(relation, {"relation", "status"}, f"{context}[{index}]")
        _string(relation["relation"], f"{context}[{index}].relation")
        if relation["status"] != "pass":
            raise ContractError(f"{context}[{index}].status must be pass")


def _validate_upstream_first_difference(value: Any, context: str) -> None:
    if not isinstance(value, dict):
        raise ContractError(f"{context} must be an object")
    _string(value.get("path"), f"{context}.path")
    keys = set(value)
    if keys == {"path", "source_type", "target_type"}:
        _string(value["source_type"], f"{context}.source_type")
        _string(value["target_type"], f"{context}.target_type")
    elif keys == {"path", "source_keys", "target_keys"}:
        for name in ("source_keys", "target_keys"):
            if not isinstance(value[name], list) or any(
                not isinstance(item, str) for item in value[name]
            ):
                raise ContractError(f"{context}.{name} must be a string array")
    elif keys in (
        {"path", "source_length", "target_length"},
        {"path", "source_length", "target_length", "source_sha256", "target_sha256"},
    ):
        for name in ("source_length", "target_length"):
            _validate_nonnegative_integer(value[name], f"{context}.{name}")
        for name in ("source_sha256", "target_sha256"):
            if name in value:
                _validate_sha256(value[name], f"{context}.{name}")
    elif keys == {"path", "source", "target"}:
        # The first difference leaf contains values observed live from the two
        # workers, so these fields intentionally admit any JSON value.
        return
    else:
        raise ContractError(f"{context} has an unsupported difference shape")


def _validate_upstream_benchmark_result_artifact(value: Any, root: Path) -> dict[str, Any]:
    from .upstream_benchmark_contract import (
        INPUT_KIND_CATEGORIES,
        UPSTREAM_WORKLOAD_IDS,
        validate_upstream_workloads,
    )

    result = _exact(
        value,
        {"schema", "completion_scope", "identity", "status", "summary", "workloads"},
        "upstream benchmark result",
    )
    if result["schema"] != UPSTREAM_BENCHMARK_RESULT_SCHEMA:
        raise ContractError("unsupported upstream benchmark result schema")
    if result["completion_scope"] != "pinned source versus installed Python package":
        raise ContractError("upstream benchmark result completion scope is invalid")
    if result["status"] not in {"completed", "not_proven"}:
        raise ContractError("upstream benchmark result status is invalid")

    base_identity_keys = {
        "run_id",
        "started_at",
        "finished_at",
        "input",
        "manifest",
        "source_revision",
        "source_files",
        "parity_gate",
        "prepared_environments",
        "machine",
        "command",
    }
    raw_identity = result["identity"]
    if not isinstance(raw_identity, dict):
        raise ContractError("upstream benchmark result.identity must be an object")
    identity_keys = set(raw_identity)
    if identity_keys not in (base_identity_keys, base_identity_keys | {"target_checkout"}):
        raise ContractError("upstream benchmark result.identity has missing or unknown fields")
    identity = _exact(
        raw_identity,
        identity_keys,
        "upstream benchmark result.identity",
    )
    for name in ("run_id", "started_at", "finished_at"):
        _string(identity[name], f"upstream benchmark identity.{name}")
    if "target_checkout" in identity:
        target_checkout = _exact(
            identity["target_checkout"],
            {"revision", "dirty", "working_tree_sha256"},
            "upstream benchmark identity.target_checkout",
        )
        revision = _string(
            target_checkout["revision"],
            "upstream benchmark identity.target_checkout.revision",
        )
        if re.fullmatch(r"(?:[a-f0-9]{40}|[a-f0-9]{64})", revision) is None:
            raise ContractError(
                "upstream benchmark target checkout revision must be a full lowercase Git object ID"
            )
        if type(target_checkout["dirty"]) is not bool:
            raise ContractError("upstream benchmark target checkout dirty must be a boolean")
        _validate_sha256(
            target_checkout["working_tree_sha256"],
            "upstream benchmark identity.target_checkout.working_tree_sha256",
        )
    input_identity = _exact(
        identity["input"], {"path", "schema", "sha256"}, "upstream benchmark identity.input"
    )
    if (
        input_identity["path"] != "build/parity/inputs/benchmark/starlette-upstream-workloads.json"
        or input_identity["schema"] != UPSTREAM_BENCHMARK_INPUT_SCHEMA
    ):
        raise ContractError(
            "upstream benchmark result input differs from the active indexed catalog"
        )
    _validate_sha256(input_identity["sha256"], "upstream benchmark identity.input.sha256")
    active_root = root.resolve()
    active_input_path = (active_root / input_identity["path"]).resolve()
    try:
        active_input_path.relative_to(active_root)
    except ValueError as exc:
        raise ContractError(
            "upstream benchmark input path must remain inside the active root"
        ) from exc
    if not active_input_path.is_file():
        raise ContractError("active upstream benchmark input catalog is missing")
    if sha256_file(active_input_path) != input_identity["sha256"]:
        raise ContractError(
            "upstream benchmark result input digest differs from the active catalog"
        )
    active_input_catalog = load_json(active_input_path)
    validate_upstream_workloads(active_input_catalog)
    active_workloads = active_input_catalog["workloads"]
    manifest = _exact(
        identity["manifest"],
        {"path", "schema", "sha256"},
        "upstream benchmark identity.manifest",
    )
    if manifest["path"] != "tests/fixtures/manifest.yaml" or manifest["schema"] != MANIFEST_SCHEMA:
        raise ContractError("upstream benchmark result manifest differs from the active contract")
    _validate_sha256(manifest["sha256"], "upstream benchmark identity.manifest.sha256")
    active_manifest_path = (active_root / manifest["path"]).resolve()
    try:
        active_manifest_path.relative_to(active_root)
    except ValueError as exc:
        raise ContractError(
            "upstream benchmark manifest path must remain inside the active root"
        ) from exc
    if not active_manifest_path.is_file():
        raise ContractError("active upstream benchmark manifest is missing")
    if sha256_file(active_manifest_path) != manifest["sha256"]:
        raise ContractError(
            "upstream benchmark result manifest digest differs from the active manifest"
        )
    active_manifest = load_manifest(active_manifest_path)
    validate_manifest(active_manifest)
    if input_identity["path"] not in active_manifest["input_index"]["benchmark"]:
        raise ContractError(
            "upstream benchmark result catalog is not indexed by the active manifest"
        )
    if identity["source_revision"] != ORACLE_COMMIT:
        raise ContractError("upstream benchmark result source revision differs from the pin")

    source_files = identity["source_files"]
    expected_source_files = [
        "benchmarks/routing_benchmark.py",
        "benchmarks/gzip_benchmark.py",
    ]
    if not isinstance(source_files, list) or len(source_files) != len(expected_source_files):
        raise ContractError("upstream benchmark result must identify both pinned source files")
    observed_source_files: list[str] = []
    for index, row in enumerate(source_files):
        row = _exact(row, {"path", "sha256"}, f"upstream benchmark identity.source_files[{index}]")
        observed_source_files.append(
            _string(row["path"], f"upstream benchmark source_files[{index}].path")
        )
        _validate_sha256(row["sha256"], f"upstream benchmark source_files[{index}].sha256")
    if observed_source_files != expected_source_files:
        raise ContractError("upstream benchmark source-file identity differs from the pinned suite")

    upstream_root = _pinned_upstream_root(active_root)
    for index, row in enumerate(source_files):
        relative_path = expected_source_files[index]
        pinned_sha256 = _pinned_source_file_sha256(upstream_root, relative_path)
        source_path = _artifact_path(upstream_root, relative_path, "pinned benchmark source")
        if sha256_file(source_path) != pinned_sha256:
            raise ContractError(
                f"pinned benchmark source differs from commit {ORACLE_COMMIT}: {relative_path}"
            )
        if row["sha256"] != pinned_sha256:
            raise ContractError(
                f"upstream benchmark result source hash differs from pinned commit: {relative_path}"
            )

    gate = _exact(
        identity["parity_gate"],
        {"path", "run_id", "sha256", "summary"},
        "upstream benchmark identity.parity_gate",
    )
    if gate["path"] != "build/parity/upstream-benchmark-correctness-result.json":
        raise ContractError("upstream benchmark parity gate path is invalid")
    if gate["run_id"] is not None:
        _string(gate["run_id"], "upstream benchmark parity_gate.run_id")
    _validate_sha256(gate["sha256"], "upstream benchmark parity_gate.sha256")
    gate_summary = _exact(
        gate["summary"],
        {"selected", "executed", "passed", "failed", "not_run", "infrastructure_errors"},
        "upstream benchmark parity_gate.summary",
    )
    for name, count in gate_summary.items():
        _validate_nonnegative_integer(count, f"upstream benchmark parity_gate.summary.{name}")
    if gate["run_id"] is None:
        raise ContractError("upstream benchmark correctness gate must identify its parity run")
    parity_gate_result, gate_sha256 = _load_referenced_parity_result(
        active_root,
        gate["path"],
        gate["sha256"],
        active_manifest_path,
        "upstream benchmark correctness gate",
    )
    if (
        parity_gate_result["identity"]["run_id"] != gate["run_id"]
        or parity_gate_result["summary"] != gate["summary"]
        or gate_sha256 != gate["sha256"]
    ):
        raise ContractError("upstream benchmark gate identity differs from its live parity result")

    environments = identity["prepared_environments"]
    environment_ids = ["starlette-oracle-cpython312", "starlette-rs-py-cpython312"]
    if not isinstance(environments, list) or len(environments) != len(environment_ids):
        raise ContractError("upstream benchmark result must identify both prepared environments")
    for index, environment in enumerate(environments):
        context = f"upstream benchmark identity.prepared_environments[{index}]"
        environment = _exact(
            environment,
            {
                "id",
                "python",
                "runtime",
                "os",
                "architecture",
                "dependency_lock_path",
                "dependency_lock_sha256",
                "installed_lock_sha256",
                "artifact_sha256",
                "environment_sha256",
            },
            context,
        )
        if environment["id"] != environment_ids[index]:
            raise ContractError("upstream benchmark prepared environment order differs")
        for name in ("python", "runtime", "os", "architecture"):
            _string(environment[name], f"{context}.{name}")
        expected_lock_path = (
            "scripts/parity/locks/starlette-oracle-cpython312.txt"
            if environment["id"] == "starlette-oracle-cpython312"
            else "scripts/parity/locks/asgi-runtime-cpython312.txt"
        )
        if environment["dependency_lock_path"] != expected_lock_path:
            raise ContractError(
                f"{context}.dependency_lock_path differs from the active runtime lock"
            )
        for name in ("dependency_lock_sha256", "installed_lock_sha256", "environment_sha256"):
            _validate_sha256(environment[name], f"{context}.{name}")
        if index == 0:
            if environment["artifact_sha256"] is not None:
                raise ContractError(
                    f"{context}.artifact_sha256 must be null for the source environment"
                )
        else:
            _validate_sha256(environment["artifact_sha256"], f"{context}.artifact_sha256")

    machine = _exact(
        identity["machine"],
        {
            "platform",
            "architecture",
            "processor",
            "logical_cpu_count",
            "python",
            "python_executable",
        },
        "upstream benchmark identity.machine",
    )
    for name in ("platform", "architecture", "python", "python_executable"):
        _string(machine[name], f"upstream benchmark identity.machine.{name}")
    if not isinstance(machine["processor"], str):
        raise ContractError("upstream benchmark identity.machine.processor must be a string")
    if machine["logical_cpu_count"] is not None:
        _validate_nonnegative_integer(
            machine["logical_cpu_count"], "upstream benchmark identity.machine.logical_cpu_count"
        )
    command = _exact(identity["command"], {"argv", "cwd"}, "upstream benchmark identity.command")
    argv = command["argv"]
    if (
        not isinstance(argv, list)
        or not argv
        or any(not isinstance(part, str) or not part for part in argv)
    ):
        raise ContractError("upstream benchmark identity.command.argv must be non-empty strings")
    # The executable path is machine-specific; the module and command suffix is
    # fixed by the result interface.
    if len(argv) < 4 or argv[-3:] != ["-m", "scripts.parity.cli", "benchmark-upstream"]:
        raise ContractError("upstream benchmark command identity does not name its CLI")
    command_cwd = _string(command["cwd"], "upstream benchmark identity.command.cwd")
    if not Path(command_cwd).is_absolute() or Path(command_cwd).resolve() != active_root:
        raise ContractError(
            "upstream benchmark command cwd differs from the active repository root"
        )

    rows = result["workloads"]
    if not isinstance(rows, list) or len(rows) != len(UPSTREAM_WORKLOAD_IDS):
        raise ContractError("upstream benchmark result must account for all 74 pinned workloads")
    if [row.get("workload_id") if isinstance(row, dict) else None for row in rows] != list(
        UPSTREAM_WORKLOAD_IDS
    ):
        raise ContractError("upstream benchmark result IDs/order differ from the pinned catalog")

    counts = {"measured": 0, "not_run": 0, "failed": 0, "router_measured": 0, "gzip_measured": 0}
    worker_identities: dict[str, dict[str, Any]] = {}
    for index, row_value in enumerate(rows):
        context = f"upstream benchmark workloads[{index}]"
        if not isinstance(row_value, dict):
            raise ContractError(f"{context} must be an object")
        workload_id = UPSTREAM_WORKLOAD_IDS[index]
        catalog_row = active_workloads[index]
        if catalog_row["workload_id"] != workload_id:
            raise ContractError(f"{context} workload ID differs from its active catalog row")
        input_kind = catalog_row["input"]["kind"]
        category = INPUT_KIND_CATEGORIES[input_kind]
        status = row_value.get("status")
        if status == "measured":
            row = _exact(
                row_value,
                {
                    "workload_id",
                    "category",
                    "status",
                    "correctness_gate",
                    "measurement_policy",
                    "comparison",
                    "subjects",
                },
                context,
            )
        elif status == "not_run":
            row = _exact(
                row_value,
                {
                    "workload_id",
                    "category",
                    "status",
                    "correctness_gate",
                    "measurement_policy",
                    "subjects",
                    "reason",
                },
                context,
            )
        elif status == "failed":
            gate_value = row_value.get("correctness_gate")
            if isinstance(gate_value, dict) and set(gate_value) == {
                "status",
                "source_observation_sha256",
                "target_observation_sha256",
                "normalized_source_observation_sha256",
                "normalized_target_observation_sha256",
                "normalization",
            }:
                row = _exact(
                    row_value,
                    {
                        "workload_id",
                        "category",
                        "status",
                        "correctness_gate",
                        "comparison",
                        "subjects",
                        "reason",
                    },
                    context,
                )
            else:
                row = _exact(
                    row_value,
                    {
                        "workload_id",
                        "category",
                        "status",
                        "correctness_gate",
                        "measurement_policy",
                        "subjects",
                        "reason",
                    },
                    context,
                )
        else:
            raise ContractError(f"{context}.status is invalid")
        if row["workload_id"] != workload_id or row["category"] != category:
            raise ContractError(f"{context} workload category differs from the active input")
        counts[status] += 1

        if "measurement_policy" in row:
            _validate_upstream_measurement_policy(
                row["measurement_policy"], f"{context}.measurement_policy"
            )
        if "reason" in row:
            _string(row["reason"], f"{context}.reason")

        correctness_gate = row["correctness_gate"]
        if status == "measured":
            correctness_gate = _exact(
                correctness_gate,
                {
                    "status",
                    "source_observation_sha256",
                    "target_observation_sha256",
                    "normalized_source_observation_sha256",
                    "normalized_target_observation_sha256",
                    "normalization",
                },
                f"{context}.correctness_gate",
            )
            if correctness_gate["status"] != "pass":
                raise ContractError(f"{context}.correctness_gate must pass for measured rows")
            for name in (
                "source_observation_sha256",
                "target_observation_sha256",
                "normalized_source_observation_sha256",
                "normalized_target_observation_sha256",
            ):
                _validate_sha256(correctness_gate[name], f"{context}.correctness_gate.{name}")
            if (
                correctness_gate["normalized_source_observation_sha256"]
                != correctness_gate["normalized_target_observation_sha256"]
            ):
                raise ContractError(
                    f"{context}.correctness_gate normalized observations must match"
                )
            _string(correctness_gate["normalization"], f"{context}.correctness_gate.normalization")
            comparison = _exact(
                row["comparison"],
                {
                    "status",
                    "metric",
                    "source_median",
                    "package_median",
                    "source_over_package_speedup",
                    "measurement_order",
                },
                f"{context}.comparison",
            )
            if (
                comparison["status"] != "measured"
                or comparison["metric"] != "median_nanoseconds_per_operation"
            ):
                raise ContractError(f"{context}.comparison metric/status is invalid")
            for name in ("source_median", "package_median", "source_over_package_speedup"):
                _validate_positive_finite_number(comparison[name], f"{context}.comparison.{name}")
            expected_measurement_order = (
                ["starlette-python", "python-package-cpython312"]
                if index % 2 == 0
                else ["python-package-cpython312", "starlette-python"]
            )
            if comparison["measurement_order"] != expected_measurement_order:
                raise ContractError(
                    f"{context}.comparison.measurement_order does not follow the declared counterbalanced order"
                )
        elif status == "not_run":
            correctness_gate = _exact(correctness_gate, {"status"}, f"{context}.correctness_gate")
            if correctness_gate["status"] != "not_run":
                raise ContractError(f"{context}.correctness_gate must be not_run")
        elif "comparison" in row:
            correctness_gate = _exact(
                correctness_gate,
                {
                    "status",
                    "source_observation_sha256",
                    "target_observation_sha256",
                    "normalized_source_observation_sha256",
                    "normalized_target_observation_sha256",
                    "normalization",
                },
                f"{context}.correctness_gate",
            )
            if correctness_gate["status"] != "failed":
                raise ContractError(
                    f"{context}.correctness_gate must fail for observation differences"
                )
            for name in (
                "source_observation_sha256",
                "target_observation_sha256",
                "normalized_source_observation_sha256",
                "normalized_target_observation_sha256",
            ):
                _validate_sha256(correctness_gate[name], f"{context}.correctness_gate.{name}")
            if (
                correctness_gate["normalized_source_observation_sha256"]
                == correctness_gate["normalized_target_observation_sha256"]
            ):
                raise ContractError(
                    f"{context}.correctness_gate normalized observations must differ on failure"
                )
            _string(correctness_gate["normalization"], f"{context}.correctness_gate.normalization")
            comparison = _exact(
                row["comparison"], {"status", "first_difference"}, f"{context}.comparison"
            )
            if comparison["status"] != "fail":
                raise ContractError(f"{context}.comparison must fail for observation differences")
            _validate_upstream_first_difference(
                comparison["first_difference"], f"{context}.comparison.first_difference"
            )
        else:
            correctness_gate = _exact(correctness_gate, {"status"}, f"{context}.correctness_gate")
            if correctness_gate["status"] != "failed":
                raise ContractError(f"{context}.correctness_gate must be failed")

        subjects = row["subjects"]
        if not isinstance(subjects, list) or len(subjects) != 3:
            raise ContractError(f"{context}.subjects must account for three runtime subjects")
        source_subject = _validate_upstream_subject(
            subjects[0], "starlette-python", f"{context}.subjects[0]"
        )
        package_subject = _validate_upstream_subject(
            subjects[1], "python-package-cpython312", f"{context}.subjects[1]"
        )
        for subject in (source_subject, package_subject):
            observed_identity = subject.get("identity")
            if observed_identity is None:
                continue
            subject_id = subject["subject_id"]
            previous_identity = worker_identities.setdefault(subject_id, observed_identity)
            if previous_identity != observed_identity:
                raise ContractError(f"{context}.{subject_id} identity changed across workload rows")
        native = _exact(
            subjects[2],
            {"subject_id", "status", "identity", "reason"},
            f"{context}.subjects[2]",
        )
        if native["subject_id"] != "rust-native-local" or native["status"] != "not_run":
            raise ContractError(
                f"{context}.subjects[2] must preserve the Rust-native not_run boundary"
            )
        if native["identity"] is not None:
            _validate_upstream_target_identity(
                native["identity"], f"{context}.subjects[2].identity"
            )
            if native["identity"]["target_profile"] != "rust-native-local":
                raise ContractError(f"{context}.subjects[2].identity must identify Rust-native")
        _string(native["reason"], f"{context}.subjects[2].reason")

        if status == "measured":
            if [source_subject["status"], package_subject["status"]] != ["measured", "measured"]:
                raise ContractError(f"{context} measured status requires both Python measurements")
            declared_runner_policy = row["measurement_policy"]["runner_policy"]
            if any(
                subject["measurement"]["runner_policy"] != declared_runner_policy
                for subject in (source_subject, package_subject)
            ):
                raise ContractError(
                    f"{context} measurements differ from the declared runner policy"
                )
            source_median = source_subject["measurement"]["statistics"]["median"]
            package_median = package_subject["measurement"]["statistics"]["median"]
            comparison = row["comparison"]
            if (
                comparison["source_median"] != source_median
                or comparison["package_median"] != package_median
                or not math.isclose(
                    comparison["source_over_package_speedup"],
                    source_median / package_median,
                    rel_tol=1e-12,
                )
            ):
                raise ContractError(f"{context}.comparison differs from subject measurements")
            counts[f"{category}_measured"] += 1
        elif "comparison" in row:
            if [source_subject["status"], package_subject["status"]] != ["probed", "probed"]:
                raise ContractError(f"{context} correctness mismatch requires both live probes")
        elif any(subject["status"] == "measured" for subject in (source_subject, package_subject)):
            raise ContractError(f"{context} incomplete rows cannot claim an individual measurement")

    summary = _exact(
        result["summary"],
        {
            "declared",
            "measured",
            "not_run",
            "failed",
            "native_not_run_workloads",
            "router_measured",
            "gzip_measured",
        },
        "upstream benchmark result.summary",
    )
    for name, count in summary.items():
        _validate_nonnegative_integer(count, f"upstream benchmark result.summary.{name}")
    expected_summary = {
        "declared": 74,
        "measured": counts["measured"],
        "not_run": counts["not_run"],
        "failed": counts["failed"],
        "native_not_run_workloads": 74,
        "router_measured": counts["router_measured"],
        "gzip_measured": counts["gzip_measured"],
    }
    if summary != expected_summary:
        raise ContractError("upstream benchmark summary does not reconcile with workload rows")
    if result["status"] == "completed":
        if counts["measured"] != 74 or counts["not_run"] or counts["failed"]:
            raise ContractError("completed upstream benchmark must measure all 74 workloads")
    elif counts["measured"] == 74 and counts["not_run"] == 0 and counts["failed"] == 0:
        raise ContractError("fully measured upstream benchmark must be marked completed")
    return result


def _validate_parity_result_against_active_contract(
    value: dict[str, Any], root: Path, manifest_path: Path | None
) -> None:
    """Bind parity evidence to the active inputs and recompute its comparison rows."""
    root = root.resolve()
    active_manifest_path = manifest_path or (root / "tests/fixtures/manifest.yaml")
    if not active_manifest_path.is_absolute():
        active_manifest_path = root / active_manifest_path
    active_manifest_path = active_manifest_path.resolve()
    try:
        manifest_relative = active_manifest_path.relative_to(root).as_posix()
    except ValueError as exc:
        raise ContractError("active parity manifest must be inside the repository root") from exc

    manifest = load_manifest(active_manifest_path)
    validate_manifest(manifest)
    from .api_sources import load_api_metadata

    package_path = Path(load_api_metadata(root)["authority"]["package_path"])
    from .generate_inputs import _check_generated, _validate_sources

    generated_inputs = _validate_sources(root, manifest)
    _check_generated(root, generated_inputs)
    indexed_inputs, cases = validate_inputs(root, manifest)
    expected_manifest_identity = {
        "path": manifest_relative,
        "schema": manifest["schema"],
        "sha256": sha256_file(active_manifest_path),
    }
    if value["identity"]["manifest"] != expected_manifest_identity:
        raise ContractError("parity result manifest identity differs from the active manifest")

    expected_input_identity = [
        {
            "path": path.resolve().relative_to(root).as_posix(),
            "schema": document["schema"],
            "sha256": sha256_file(path),
        }
        for path, document in indexed_inputs
    ]
    if value["identity"]["inputs"] != expected_input_identity:
        raise ContractError("parity result inputs differ from the active indexed input digests")
    if value["identity"]["assets"] != []:
        raise ContractError("parity result assets differ from the active input contract")

    command_id = _string(
        value["identity"]["command"]["command_id"], "result.identity.command.command_id"
    )
    commands = {command["id"]: command for command in manifest["commands"]}
    if command_id not in {"parity", "oracle-only"} or command_id not in commands:
        raise ContractError("parity result command is not a declared parity execution mode")
    command = commands[command_id]
    expected_command = {
        "command_id": command_id,
        "argv": command["argv"],
        "cwd": command["cwd"],
        "timeout_seconds": command["timeout_seconds"],
    }
    if value["identity"]["command"] != expected_command:
        raise ContractError("parity result command identity differs from the active manifest")

    identity = value["identity"]
    if not all(isinstance(identity[name], list) for name in ("oracles", "targets", "environments")):
        raise ContractError("parity result identity inventories must be arrays")
    errors = value["infrastructure_errors"]
    failed_runner_environment = any(
        error["scope"] == "runner" and error["id"] == "python-environments" for error in errors
    )

    expected_oracles = {oracle["id"]: oracle for oracle in manifest["oracles"]}
    oracle_records: dict[str, dict[str, Any]] = {}
    for index, oracle in enumerate(identity["oracles"]):
        oracle_id = _string(oracle["oracle_id"], f"result.identity.oracles[{index}].oracle_id")
        if oracle_id not in expected_oracles or oracle_id in oracle_records:
            raise ContractError("parity result oracle identity inventory differs from the manifest")
        declared = expected_oracles[oracle_id]
        if (
            oracle["name"] != declared["name"]
            or oracle["version"] != declared["version"]
            or oracle["revision"] != manifest["scope"]["inventory"]["revision"]
        ):
            raise ContractError(f"parity result oracle identity {oracle_id} differs from the pin")
        for field in ("runtime", "module_path", "os", "architecture"):
            _string(oracle[field], f"result.identity.oracles[{index}].{field}")
        module_path = Path(oracle["module_path"])
        if (
            not module_path.is_absolute()
            or module_path.name != "__init__.py"
            or module_path.parent.name != package_path.parts[-1]
        ):
            raise ContractError(
                f"parity result oracle identity {oracle_id} has an invalid module path"
            )
        for field in (
            "dependency_lock_sha256",
            "environment_sha256",
            "runtime_lock_sha256",
        ):
            _validate_sha256(oracle[field], f"result.identity.oracles[{index}].{field}")
        oracle_records[oracle_id] = oracle

    if set(oracle_records) != set(expected_oracles) and not (
        failed_runner_environment
        or any(error["scope"] == "oracle" and error["id"] in expected_oracles for error in errors)
    ):
        raise ContractError(
            "parity result omits a source oracle identity without an identity error"
        )

    expected_profiles = {profile["id"]: profile for profile in manifest["target_profiles"]}
    targets = {target["id"]: target for target in manifest["targets"]}
    profile_records: dict[str, dict[str, Any]] = {}
    for index, target in enumerate(identity["targets"]):
        profile_id = _string(
            target["target_profile"], f"result.identity.targets[{index}].target_profile"
        )
        if profile_id not in expected_profiles or profile_id in profile_records:
            raise ContractError("parity result target identity inventory differs from the manifest")
        declared_profile = expected_profiles[profile_id]
        target_id = declared_profile["target_id"]
        if (
            target["target_id"] != target_id
            or target["backend"] != declared_profile["backend"]
            or target["features"] != declared_profile["features"]
        ):
            raise ContractError(
                f"parity result target identity {profile_id} differs from its profile"
            )
        if target_id not in targets:
            raise ContractError(
                f"parity result target identity {profile_id} names an unknown target"
            )
        for field in ("revision", "runtime", "backend", "os", "architecture"):
            _string(target[field], f"result.identity.targets[{index}].{field}")
        if not isinstance(target["dirty"], bool) or not isinstance(target["features"], list):
            raise ContractError(f"parity result target identity {profile_id} is malformed")
        if target["package_version"] is not None:
            _string(target["package_version"], f"result.identity.targets[{index}].package_version")
        if target["target_tree_sha256"] is not None:
            _validate_sha256(
                target["target_tree_sha256"],
                f"result.identity.targets[{index}].target_tree_sha256",
            )
        _validate_sha256(
            target["dependency_lock_sha256"],
            f"result.identity.targets[{index}].dependency_lock_sha256",
        )
        if target["environment_sha256"] is not None:
            _validate_sha256(
                target["environment_sha256"],
                f"result.identity.targets[{index}].environment_sha256",
            )
        profile_records[profile_id] = target

    if command_id == "oracle-only" and profile_records:
        raise ContractError("oracle-only result must not include target identities")
    if command_id == "parity":
        missing_profiles = set(expected_profiles) - set(profile_records)
        for profile_id in missing_profiles:
            target_id = expected_profiles[profile_id]["target_id"]
            if not (
                failed_runner_environment
                or any(error["scope"] == "target" and error["id"] == target_id for error in errors)
            ):
                raise ContractError(
                    f"parity result omits target identity {profile_id} without an identity error"
                )

    environment_records: dict[str, dict[str, Any]] = {}
    for index, environment in enumerate(identity["environments"]):
        environment_id = _string(environment["id"], f"result.identity.environments[{index}].id")
        if environment_id in environment_records:
            raise ContractError("parity result repeats a prepared environment identity")
        for field in ("runtime", "os", "architecture"):
            _string(environment[field], f"result.identity.environments[{index}].{field}")
        _validate_sha256(
            environment["dependency_lock_sha256"],
            f"result.identity.environments[{index}].dependency_lock_sha256",
        )
        _validate_sha256(
            environment["environment_sha256"],
            f"result.identity.environments[{index}].environment_sha256",
        )
        if environment_id == "rust-native-local":
            lock_path = root / "Cargo.lock"
            if not lock_path.is_file() or environment["dependency_lock_sha256"] != sha256_file(
                lock_path
            ):
                raise ContractError("native environment lock digest differs from active Cargo.lock")
        elif environment_id in {
            "starlette-oracle-cpython312",
            "starlette-rs-py-cpython312",
        }:
            expected_lock = (
                "scripts/parity/locks/starlette-oracle-cpython312.txt"
                if environment_id == "starlette-oracle-cpython312"
                else "scripts/parity/locks/asgi-runtime-cpython312.txt"
            )
            if environment["dependency_lock_path"] != expected_lock:
                raise ContractError(f"{environment_id} is bound to an unexpected runtime lock")
            lock_path = root / expected_lock
            if not lock_path.is_file() or environment["dependency_lock_sha256"] != sha256_file(
                lock_path
            ):
                raise ContractError(f"{environment_id} lock digest differs from the active lock")
            _validate_sha256(
                environment["installed_lock_sha256"],
                f"result.identity.environments[{index}].installed_lock_sha256",
            )
            artifact_digest = environment["artifact_sha256"]
            if environment_id == "starlette-oracle-cpython312":
                if artifact_digest is not None:
                    raise ContractError(
                        "source oracle environment cannot identify a target artifact"
                    )
            elif artifact_digest is not None:
                _validate_sha256(
                    artifact_digest,
                    f"result.identity.environments[{index}].artifact_sha256",
                )
        else:
            raise ContractError(f"parity result has unknown environment identity {environment_id}")
        environment_records[environment_id] = environment

    expected_environment_ids = {"starlette-oracle-cpython312", "starlette-rs-py-cpython312"}
    if command_id == "parity":
        expected_environment_ids.add("rust-native-local")
    if not failed_runner_environment and set(environment_records) != expected_environment_ids:
        raise ContractError("parity result prepared environment inventory differs from the command")
    if command_id == "oracle-only" and "rust-native-local" in environment_records:
        raise ContractError("oracle-only result must not include a native target environment")

    oracle_environment = environment_records.get("starlette-oracle-cpython312")
    if oracle_environment is not None:
        for oracle in oracle_records.values():
            if oracle["runtime_lock_sha256"] != oracle_environment["dependency_lock_sha256"]:
                raise ContractError(
                    "source oracle runtime lock differs from its prepared environment"
                )
            if oracle["environment_sha256"] != oracle_environment["environment_sha256"]:
                raise ContractError("source oracle identity differs from its prepared environment")
    python_environment = environment_records.get("starlette-rs-py-cpython312")
    native_environment = environment_records.get("rust-native-local")
    for profile_id, target in profile_records.items():
        if target["target_id"] == "rust-native":
            if native_environment is None or (
                target["dependency_lock_sha256"] != native_environment["dependency_lock_sha256"]
                or target["environment_sha256"] != native_environment["environment_sha256"]
            ):
                raise ContractError(
                    f"native target identity {profile_id} differs from its environment"
                )
        elif target["target_id"] == "python-package":
            if python_environment is None or (
                target["dependency_lock_sha256"] != python_environment["dependency_lock_sha256"]
                or target["environment_sha256"] != python_environment["environment_sha256"]
            ):
                raise ContractError(
                    f"Python target identity {profile_id} differs from its environment"
                )

    expected_rows = [
        (case["case_id"], profile_id) for case in cases for profile_id in case["target_profiles"]
    ]
    comparisons = value["comparisons"]
    for index, row in enumerate(comparisons):
        _string(row["case_id"], f"result.comparisons[{index}].case_id")
        _string(row["target_profile"], f"result.comparisons[{index}].target_profile")
    actual_rows = [(row["case_id"], row["target_profile"]) for row in comparisons]
    if len(actual_rows) != len(set(actual_rows)):
        raise ContractError("parity result contains duplicate case/target-profile rows")
    expected_set = set(expected_rows)
    actual_set = set(actual_rows)
    if actual_set != expected_set:
        raise ContractError(
            "parity result comparison rows differ from active cases and target profiles: "
            f"missing={sorted(expected_set - actual_set)}, extra={sorted(actual_set - expected_set)}"
        )

    from .comparator import compare_workflows

    operations = {
        (surface["id"], operation["id"]): operation
        for surface in manifest["surfaces"]
        for operation in surface["operations"]
    }
    case_by_id = {case["case_id"]: case for case in cases}
    for index, comparison in enumerate(comparisons):
        context = f"result.comparisons[{index}]"
        case = case_by_id[comparison["case_id"]]
        if comparison["requirements"] != case["covers"]:
            raise ContractError(f"{context}.requirements differ from the active case")

        source = comparison["source"]
        target = comparison["target"]
        if (
            case["surface"] == SESSION_MIDDLEWARE_SURFACE
            and case["operation"] == SESSION_WORKFLOW_OPERATION
        ):
            _validate_session_workflow_result(case, source, f"{context}.source")
            _validate_session_workflow_result(case, target, f"{context}.target")
        both_completed = source["status"] == target["status"] == "completed"
        if command_id == "oracle-only":
            if target["status"] != "skipped":
                raise ContractError(f"{context}: oracle-only evidence must omit target execution")
            if source["status"] == "completed":
                expected_target = {
                    "case_id": case["case_id"],
                    "status": "skipped",
                    "observations": [
                        {
                            "step_id": step_id,
                            "status": "skipped",
                            "reason": (
                                "not run: target intentionally omitted by the explicit "
                                "oracle-only command"
                            ),
                        }
                        for step_id in case["observations"]
                    ],
                }
                if target != expected_target:
                    raise ContractError(f"{context}: oracle-only target omission reason is invalid")
        if both_completed:
            expected_outcome, expected_diffs = compare_workflows(
                case,
                operations[(case["surface"], case["operation"])],
                source,
                target,
            )
        else:
            expected_outcome, expected_diffs = "not_run", []
        if comparison["outcome"] != expected_outcome or comparison["diffs"] != expected_diffs:
            raise ContractError(
                f"{context}: outcome/diffs do not match canonical comparison of workflow evidence"
            )


def _validate_parity_result_artifact(
    value: Any,
    *,
    root: Path | None = None,
    manifest_path: Path | None = None,
) -> dict[str, Any]:
    _exact(
        value,
        {"schema", "identity", "status", "summary", "comparisons", "infrastructure_errors"},
        "parity result",
    )
    if value["schema"] != RESULT_SCHEMA:
        raise ContractError("unsupported parity result schema")
    if value["status"] not in {"completed", "infrastructure_failed", "cancelled", "invalid"}:
        raise ContractError("parity result status is invalid")
    identity = _exact(
        value["identity"],
        {
            "run_id",
            "started_at",
            "finished_at",
            "manifest",
            "inputs",
            "assets",
            "oracles",
            "targets",
            "environments",
            "command",
        },
        "result.identity",
    )
    _string(identity["run_id"], "result.identity.run_id")
    _exact(identity["manifest"], {"path", "schema", "sha256"}, "result.identity.manifest")
    if identity["manifest"]["schema"] != MANIFEST_SCHEMA:
        raise ContractError("result manifest schema mismatch")
    for index, item in enumerate(identity["inputs"]):
        _exact(item, {"path", "schema", "sha256"}, f"result.identity.inputs[{index}]")
        if item["schema"] != INPUT_SCHEMA:
            raise ContractError(f"result.identity.inputs[{index}].schema is incompatible")
    for index, item in enumerate(identity["oracles"]):
        _exact(
            item,
            {
                "oracle_id",
                "name",
                "version",
                "revision",
                "runtime",
                "module_path",
                "dependency_lock_sha256",
                "os",
                "architecture",
                "environment_sha256",
                "runtime_lock_sha256",
            },
            f"result.identity.oracles[{index}]",
        )
    for index, item in enumerate(identity["targets"]):
        _exact(
            item,
            {
                "target_profile",
                "target_id",
                "revision",
                "dirty",
                "runtime",
                "backend",
                "features",
                "package_version",
                "target_tree_sha256",
                "dependency_lock_sha256",
                "os",
                "architecture",
                "environment_sha256",
            },
            f"result.identity.targets[{index}]",
        )
    for index, item in enumerate(identity["environments"]):
        if not isinstance(item, dict):
            raise ContractError(f"result.identity.environments[{index}] must be an object")
        if item.get("id") == "rust-native-local":
            _exact(
                item,
                {
                    "id",
                    "runtime",
                    "os",
                    "architecture",
                    "rustc",
                    "cargo",
                    "dependency_lock_path",
                    "dependency_lock_sha256",
                    "environment_sha256",
                },
                f"result.identity.environments[{index}]",
            )
            if item["dependency_lock_path"] != "Cargo.lock":
                raise ContractError("native environment must bind to Cargo.lock")
        elif item.get("id") in {"starlette-oracle-cpython312", "starlette-rs-py-cpython312"}:
            _exact(
                item,
                {
                    "id",
                    "python",
                    "runtime",
                    "os",
                    "architecture",
                    "dependency_lock_path",
                    "dependency_lock_sha256",
                    "installed_lock_sha256",
                    "artifact_sha256",
                    "environment_sha256",
                },
                f"result.identity.environments[{index}]",
            )
            expected_lock_path = (
                "scripts/parity/locks/starlette-oracle-cpython312.txt"
                if item["id"] == "starlette-oracle-cpython312"
                else "scripts/parity/locks/asgi-runtime-cpython312.txt"
            )
            if item["dependency_lock_path"] != expected_lock_path:
                raise ContractError(
                    "Python environment must bind to its committed isolated dependency lock"
                )
        else:
            raise ContractError(
                f"result.identity.environments[{index}] has an unknown environment ID"
            )
    _exact(
        identity["command"],
        {"command_id", "argv", "cwd", "timeout_seconds"},
        "result.identity.command",
    )
    _exact(
        value["summary"],
        {"selected", "executed", "passed", "failed", "not_run", "infrastructure_errors"},
        "result.summary",
    )
    for name, count in value["summary"].items():
        _validate_nonnegative_integer(count, f"result.summary.{name}")
    comparisons = value["comparisons"]
    if not isinstance(comparisons, list):
        raise ContractError("result.comparisons must be an array")
    for index, comparison in enumerate(comparisons):
        context = f"result.comparisons[{index}]"
        _exact(
            comparison,
            {"case_id", "target_profile", "requirements", "source", "target", "outcome", "diffs"},
            context,
        )
        if comparison["outcome"] not in {"pass", "fail", "not_run"}:
            raise ContractError(f"{context}.outcome is invalid")
        validate_workflow_result(comparison["source"], comparison["case_id"], f"{context}.source")
        validate_workflow_result(comparison["target"], comparison["case_id"], f"{context}.target")
        for diff_index, diff in enumerate(comparison["diffs"]):
            _exact(
                diff,
                {"step_id", "path", "kind", "source", "target", "message"},
                f"{context}.diffs[{diff_index}]",
            )
        both_completed = (
            comparison["source"]["status"] == comparison["target"]["status"] == "completed"
        )
        if comparison["outcome"] == "pass" and (not both_completed or comparison["diffs"]):
            raise ContractError(f"{context}: pass requires completed, equal observations")
        if comparison["outcome"] == "fail" and (not both_completed or not comparison["diffs"]):
            raise ContractError(
                f"{context}: fail requires two completed results and at least one exact difference"
            )
        if comparison["outcome"] == "not_run" and both_completed:
            raise ContractError(f"{context}: completed results cannot be labeled not_run")
    for index, error in enumerate(value["infrastructure_errors"]):
        _exact(error, {"scope", "id", "kind", "message"}, f"result.infrastructure_errors[{index}]")
    expected_summary = {
        "selected": len(comparisons),
        "executed": sum(
            1
            for item in comparisons
            if item["source"]["status"] == "completed" and item["target"]["status"] == "completed"
        ),
        "passed": sum(1 for item in comparisons if item["outcome"] == "pass"),
        "failed": sum(1 for item in comparisons if item["outcome"] == "fail"),
        "not_run": sum(1 for item in comparisons if item["outcome"] == "not_run"),
        "infrastructure_errors": len(value["infrastructure_errors"]),
    }
    if value["summary"] != expected_summary:
        raise ContractError("result summary does not equal its comparison/evidence counts")
    if value["status"] == "completed" and value["infrastructure_errors"]:
        raise ContractError("completed result cannot contain infrastructure errors")
    if value["status"] == "infrastructure_failed" and not value["infrastructure_errors"]:
        raise ContractError("infrastructure_failed result requires an infrastructure error")
    if any(
        item["outcome"] == "pass"
        and (item["source"]["status"] != "completed" or item["target"]["status"] != "completed")
        for item in comparisons
    ):
        raise ContractError("a pass requires completed source and target evidence")
    if root is None:
        raise ContractError(
            "parity result integrity validation requires the active repository root"
        )
    _validate_parity_result_against_active_contract(value, root, manifest_path)
    return value


def validate_result_artifact(
    value: Any,
    *,
    root: Path | None = None,
    manifest_path: Path | None = None,
) -> dict[str, Any]:
    if isinstance(value, dict) and value.get("schema") == UPSTREAM_BENCHMARK_RESULT_SCHEMA:
        if root is None:
            raise ContractError(
                "validating an upstream benchmark result requires the active repository root"
            )
        return _validate_upstream_benchmark_result_artifact(value, root)
    if isinstance(value, dict) and value.get("schema") == BENCHMARK_RESULT_SCHEMA:
        return _validate_benchmark_result_artifact(value, root, manifest_path)
    return _validate_parity_result_artifact(value, root=root, manifest_path=manifest_path)
